  // 质控 API：仪器/项目列表用 DataView，结果数据用 DataInputNew（与录入页一致）
  // 8.9.0: 旧「驱动质控页 UI」遗留的 qeGetJQ/qeIsQCPage 已删除（无调用方，getJQ/isQCDataInputPage 即本尊）
  function qeQCApiUrl() {
    return BASE + '/qc/ashx/ashQCDataView.ashx';
  }
  function qeQCDataApiUrl() {
    return BASE + '/qc/ashx/ashQCDataInputNew.ashx';
  }

  function qeMonthEndDate(year, month) {
    const last = new Date(year, month, 0).getDate();
    return year + '-' + String(month).padStart(2, '0') + '-' + String(last).padStart(2, '0');
  }

  // 通过 API 查询某台仪器的测试项目列表（与录入页一致用 DataInputNew）
  async function qeApiTestCodes(machineDR, startDate, endDate, matDR, machName) {
    const api = qeQCDataApiUrl();
    const sd = startDate || '2024-01-01';
    const ed = endDate || today();
    const url =
      api +
      '?Method=QryMachineTestCode&MachineParameterDR=' +
      encodeURIComponent(machineDR) +
      '&MatDR=' +
      encodeURIComponent(matDR || '') +
      '&MatLotDR=&StartDate=' +
      encodeURIComponent(sd) +
      '&EndDate=' +
      encodeURIComponent(ed);
    try {
      const data = await fetchJ(url, 15000, _qeSignal());
      return data && data.rows ? data.rows : Array.isArray(data) ? data : [];
    } catch (e) {
      dbg('[LIS-QE] qeApiTestCodes error:', e);
      // 8.9.0: 查询失败 ≠ 该机器没有项目。吞成空数组会让相关项目显示「未映射/无数据」，
      // 表面像本月没做质控，实际是网络故障 → 登记后导出结束统一提示（用户主动停止除外）
      if (!(_qeAbortCtrl && _qeAbortCtrl.signal.aborted)) {_qeQueryFailures.push(`机器「${machName || machineDR}」测试项目列表`);}
      return [];
    }
  }

  // 通过 API 查询某项目各浓度的质控结果（对齐 DataInputNew.QueryData）
  let _qeLevelFailures = []; // 8.5.82: 本轮导出中拉取失败的水平（项目名+水平号），导出完成时统一提示，不再静默丢数据
  let _qeQueryFailures = []; // 8.9.0: 本轮导出/检测中查询失败的基础接口（项目列表/机器参数/质控物列表），与 _qeLevelFailures 一起在导出结束提示
  async function qeApiQCData(machineDR, testCodeDR, matDR, startDate, endDate, projName) {
    const api = qeQCDataApiUrl();
    const levels = [];
    try {
      const leaveUrl =
        api +
        '?Method=QueryQCLeaveData&MachineParameterDR=' +
        encodeURIComponent(machineDR) +
        '&TestCodeDR=' +
        encodeURIComponent(testCodeDR) +
        '&StartDate=' +
        encodeURIComponent(startDate) +
        '&EndDate=' +
        encodeURIComponent(endDate) +
        '&MaterialCode=' +
        encodeURIComponent(matDR || '') +
        '&BatchCode=';
      // 8.5.82: 改用重试（超时是瞬时故障）——此前一次超时该水平整月数据就静默缺失
      // 8.9.0: 贯传导出停止信号，停止后不再空等在途请求
      const leaveData = await fetchJRetry(leaveUrl, 15000, _qeSignal(), 2);
      const leaveRows = Array.isArray(leaveData) ? leaveData : (leaveData && leaveData.rows) || [];
      leaveRows.forEach(r => {
        if (r.LevelNo != null && r.LevelNo !== '') {
          levels.push({ levelNo: String(r.LevelNo), matLotDR: r.MatLotDR || '' });
        }
      });
    } catch (e) {
      dbg('[LIS-QE] QueryQCLeaveData failed:', e.message);
      // 8.9.0: 失败登记——质控物/水平列表拉不到会退回默认 L1/L2，若实际有 L3 会静默丢失
      if (!(_qeAbortCtrl && _qeAbortCtrl.signal.aborted)) {_qeLevelFailures.push((projName || testCodeDR) + ' 质控物水平列表');}
    }
    if (!levels.length) {levels.push({ levelNo: '1', matLotDR: '' }, { levelNo: '2', matLotDR: '' });}

    const allRows = [];
    const seen = new Set();
    for (const lv of levels) {
      try {
        const url =
          api +
          '?Method=QueryTestResultData&StartDate=' +
          encodeURIComponent(startDate) +
          '&EndDate=' +
          encodeURIComponent(endDate) +
          '&InstrumentCode=' +
          encodeURIComponent(machineDR) +
          '&Leavel=' +
          encodeURIComponent(lv.levelNo) +
          '&TCCode=' +
          encodeURIComponent(testCodeDR) +
          '&QcRule=&MatDR=' +
          encodeURIComponent(matDR || '') +
          '&BatchCode=';
        // 8.5.82: 每水平重试 2 次——单水平失败会让 Excel 少一整水平的数据
        // 8.9.0: 贯传导出停止信号
        const data = await fetchJRetry(url, 25000, _qeSignal(), 2);
        const rows = Array.isArray(data) ? data : (data && data.rows) || [];
        rows.forEach(r => {
          const levelNo = r.LevelNo || lv.levelNo;
          const date = r.TestDate || r.AddDate || r.QCDate || '';
          // 去重 key 包含运行序号/时间戳，避免同日多次检测结果被丢弃
          const seq = r.SeqNo || r.RunSeq || r.AddTime || '';
          // 8.5.56: 序号全缺时退化为「结果值」参与 key，否则同日同水平多次检测会被折叠成一条
          const seqKey = seq || 'v' + (r.Result1 != null ? r.Result1 : r.Result != null ? r.Result : allRows.length);
          const key = date + '|' + levelNo + '|' + (r.TestCodeDR || testCodeDR) + '|' + seqKey;
          if (seen.has(key)) {return;}
          seen.add(key);
          // 不修改原 API 响应对象，避免副作用；LevelNo 无条件补全：
          // 若 API 行带 SeqNo 但缺 LevelNo，旧逻辑不补全，下游会把所有水平归到 Level 1
          const row = r.LevelNo != null ? r : { ...r, LevelNo: levelNo };
          if (date || row.Result1 != null || row.DayAve != null || row.Result != null) {allRows.push(row);}
        });
      } catch (e) {
        dbg('[LIS-QE] QueryTestResultData L' + lv.levelNo + ' failed:', e.message);
        // 8.5.82: 失败登记（导出结束统一提示），不再只写调试日志让文件静默缺数据
        if (!(_qeAbortCtrl && _qeAbortCtrl.signal.aborted)) {_qeLevelFailures.push((projName || testCodeDR) + ' L' + lv.levelNo);}
      }
    }
    return allRows;
  }

  // 通过 QC API 查询工作组的仪器参数列表
  async function qeApiMachineParameters(wgDR) {
    const url = qeQCApiUrl() + '?Method=QryMachineParameter&WorkGroupDR=' + wgDR;
    try {
      const data = await fetchJ(url, 15000, _qeSignal());
      return data && data.rows ? data.rows : Array.isArray(data) ? data : [];
    } catch (e) {
      dbg('[LIS-QE] qeApiMachineParameters error:', e);
      // 8.9.0: 该工作组机器列表查询失败会静默少一整组仪器（其项目全部「未映射」），登记提示
      if (!(_qeAbortCtrl && _qeAbortCtrl.signal.aborted)) {_qeQueryFailures.push(`工作组 ${wgDR} 机器参数列表`);}
      return [];
    }
  }

  // 遍历所有工作组获取全部仪器（使用 QC API 查询 MachineParameter）
  // 8.9.0: 3 个工作组并行查询
  async function qeGetAllMachines() {
    const allMachines = [];
    const wgs = [
      { dr: '1', name: '临检' },
      { dr: '3', name: '生化' },
      { dr: '4', name: '免疫' }
    ];
    await Promise.all(wgs.map(async w => {
      try {
        const rows = await qeApiMachineParameters(w.dr);
        dbg(`[LIS-QE] 工作组 ${w.name}(${w.dr}): ${rows.length} 台仪器`);
        rows.forEach(m => {
          allMachines.push({
            id: String(m.RowID || ''),
            text: String(m.CName || m.Name || m.RowID || ''),
            wgDR: w.dr,
            wgName: w.name,
            raw: m
          });
        });
      } catch (e) {
        dbg(`[LIS-QE] 加载工作组 ${w.name} 失败:`, e);
        // 8.9.0: qeApiMachineParameters 内部已吞错返回 []，这里补一层数量校验兜底
        if (!(_qeAbortCtrl && _qeAbortCtrl.signal.aborted)) {_qeQueryFailures.push(`工作组 ${w.name} 机器参数列表`);}
      }
    }));
    dbg(`[LIS-QE] 共找到 ${allMachines.length} 台仪器`);
    return allMachines;
  }

  // 设置仪器选择（通过 loadData 注入数据再 setValue）
  // 8.9.0: 旧「驱动质控页 UI」方案遗留的 qeSelectMachine/qeGetTestCodes/qeSelectTestCode/qeReadData
  // 已删除（全文件无调用方，改走 API 方案）——防止后人改匹配逻辑时改漏副本

  // 计算质控结果值——8.9.0 起与 QC 模块 qcAverageValue 合一（此前两份逐字重复实现）
  function qeCalcValue(row) {
    return qcAverageValue(row);
  }

  // 从日期字符串提取日
  function qeExtractDay(dateStr) {
    const s = String(dateStr || '').trim();
    const m = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
    if (m) {return parseInt(m[3], 10);}
    if (/^\d{8}$/.test(s)) {return parseInt(s.slice(6, 8), 10);}
    const d = new Date(s.replace(/-/g, '/'));
    return Number.isNaN(d.getTime()) ? 0 : d.getDate();
  }

  // 从日期字符串提取月
  function qeExtractMonth(dateStr) {
    const s = String(dateStr || '').trim();
    const m = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
    if (m) {return parseInt(m[2], 10);}
    if (/^\d{8}$/.test(s)) {return parseInt(s.slice(4, 6), 10);}
    const d = new Date(s.replace(/-/g, '/'));
    return Number.isNaN(d.getTime()) ? 0 : d.getMonth() + 1;
  }

  // 8.10.0: 年份提取——此前 inMonth 只比月不比年，LIS 若返回范围外的往年同月
  // 质控数据会混入导出 Excel
  function qeExtractYear(dateStr) {
    const s = String(dateStr || '').trim();
    const m = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
    if (m) {return parseInt(m[1], 10);}
    if (/^\d{8}$/.test(s)) {return parseInt(s.slice(0, 4), 10);}
    const d = new Date(s.replace(/-/g, '/'));
    return Number.isNaN(d.getTime()) ? 0 : d.getFullYear();
  }

  function qeCountMonthQCRows(dataRows, month, year) {
    let n = 0;
    (dataRows || []).forEach(r => {
      const val = qeCalcValue(r);
      if (val === null || Number.isNaN(val)) {return;}
      const date = r.TestDate || r.AddDate || r.QCDate || '';
      const m = qeExtractMonth(date);
      const d = qeExtractDay(date);
      const y = qeExtractYear(date); // 8.10.0: 补年份比较
      const inMonth =
        (y === year && m === month && d > 0) || (String(date).indexOf(year + '-' + String(month).padStart(2, '0')) === 0 && d > 0);
      if (inMonth) {n++;}
    });
    return n;
  }

  // 同月多质控物时（如血常规 202602/202604），自动选有数据的 MatDR
  async function qeFetchProjectQCData(group, proj, map, cfg) {
    const month = cfg._month || new Date().getMonth() + 1;
    const year = cfg._year || new Date().getFullYear();
    const startDate = year + '-' + String(month).padStart(2, '0') + '-01';
    const endDate = qeMonthEndDate(year, month);
    const matCandidates = [];
    const addMat = (md, name) => {
      const id = String(md || '');
      if (matCandidates.some(c => c.matDR === id)) {return;}
      matCandidates.push({ matDR: id, materialName: name || '' });
    };
    addMat(map.matDR, map.materialName);

    if (group.id === 'blood' || group.id === 'urine') {
      const testCodes = await qeApiTestCodes(map.machineDR, startDate, endDate, '', map.machineName);
      testCodes.forEach(tc => {
        if (!qeMatchProject(group, proj, tc, map.machineName)) {return;}
        addMat(tc.MatDR, tc.MaterialName);
      });
    }

    let bestRows = [],
      bestMat = map.matDR || '',
      bestName = map.materialName || '',
      bestCount = 0;
    // 8.9.0: 多质控物并行拉取（此前串行 × 15-25s 超时链路）；选择逻辑仍按候选顺序，结果与旧版一致
    const _matRows = await qePool(matCandidates, 3, c =>
      qeApiQCData(map.machineDR, map.testCodeDR, c.matDR, startDate, endDate, proj.name)
    );
    matCandidates.forEach((c, idx) => {
      const rows = _matRows[idx] || [];
      const cnt = qeCountMonthQCRows(rows, month, year);
      if (cnt > bestCount) {
        bestCount = cnt;
        bestRows = rows;
        bestMat = c.matDR;
        bestName = c.materialName || bestName;
      }
    });
    if (bestCount > 0 && bestMat !== map.matDR) {
      dbg('[LIS-QE] ' + proj.name + ' 质控物切换: ' + (map.materialName || map.matDR) + ' -> ' + (bestName || bestMat));
      map.matDR = bestMat;
      map.materialName = bestName;
    }
    return bestRows;
  }

  function qeMappingCount(mappings) {
    return Object.keys(mappings || {}).filter(k => !k.startsWith('_')).length;
  }

  // CS5100 仪器列表常为空，用质控物 MatDR 补查 + 院内稳定 DR 兜底
  async function qeCoagFallbackMappings(mappings, machines, startDate, endDate, statusCb) {
    const coagGroup = QE_GROUPS.find(g => g.id === 'coag');
    if (!coagGroup) {return;}
    const missing = coagGroup.projects.filter(p => !mappings[p.code]);
    if (!missing.length) {return;}
    const coagMach = machines.find(m => /CS.?5100|凝血|血凝/i.test(m.text));
    if (!coagMach) {return;}
    if (statusCb) {statusCb('凝血组：尝试质控物补查...', 'info');}

    const matDRs = ['167', '169', '151', '98'];
    const tcByRowID = {}; // 8.5.82: RowID→CName 实测表，供硬编码兜底核对
    for (const matDR of matDRs) {
      const testCodes = await qeApiTestCodes(coagMach.id, startDate, endDate, matDR, coagMach.text);
      for (const tc of testCodes) {
        const rowID = String(tc.RowID || '');
        if (rowID) {tcByRowID[rowID] = qeNormName(tc.CName);}
        const mat = String(tc.MatDR || matDR || '');
        const cname = qeNormName(tc.CName);
        // 与主循环一致：每个 tc 只分配给匹配分最高的 proj
        let bestProj = null, bestScore = -1;
        for (const proj of coagGroup.projects) {
          if (mappings[proj.code]) {continue;}
          const score = qeMatchScore(coagGroup, proj, tc, coagMach.text);
          if (score < 0) {continue;}
          if (score > bestScore) {bestScore = score; bestProj = proj;}
        }
        if (bestProj) {
          mappings[bestProj.code] = {
            machineDR: coagMach.id,
            machineName: coagMach.text,
            testCodeDR: rowID,
            testName: cname || bestProj.name,
            matDR: mat,
            matLotDR: String(tc.MatLotRowID || ''),
            wgDR: coagMach.wgDR,
            wgName: coagMach.wgName,
            groupId: coagGroup.id
          };
        }
      }
    }

    const stillMissing = coagGroup.projects.filter(p => !mappings[p.code]);
    if (!stillMissing.length) {return;}
    const hardcoded = [
      { code: '1101', testCodeDR: '29', matDR: '167', names: ['凝血酶原时间', 'PT'] },
      { code: '1102', testCodeDR: '282', matDR: '167', names: ['国际标准化比值', 'INR'] },
      { code: '1103', testCodeDR: '27', matDR: '167', names: ['活化部分凝血活酶时间', 'APTT'] },
      { code: '1104', testCodeDR: '30', matDR: '167', names: ['纤维蛋白原', 'FIB'] }
    ];
    hardcoded.forEach(h => {
      if (mappings[h.code]) {return;}
      const proj = coagGroup.projects.find(p => p.code === h.code);
      if (!proj) {return;}
      // 8.5.82: 有实测数据时校验硬编码 RowID 实际指向的项目名——LIS 重建库后 RowID 会漂移，
      // 拿着正确项目名装错误数据不如不映射（不匹配则跳过，走「未映射」告警）
      const actualName = tcByRowID[h.testCodeDR];
      if (actualName !== undefined && actualName !== '' && !h.names.some(n => actualName.includes(n) || n.includes(actualName))) {
        dbg('[LIS-QE] 硬编码映射校验失败: code', h.code, 'RowID', h.testCodeDR, '实际指向「' + actualName + '」，跳过');
        if (statusCb) {statusCb(`凝血组：硬编码 DR ${h.testCodeDR} 与实际项目「${actualName}」不符，已跳过`, 'error');}
        return;
      }
      mappings[h.code] = {
        machineDR: coagMach.id,
        machineName: coagMach.text,
        testCodeDR: h.testCodeDR,
        testName: h.names[0],
        matDR: h.matDR,
        matLotDR: '',
        wgDR: coagMach.wgDR,
        wgName: coagMach.wgName,
        groupId: coagGroup.id
      };
    });
    const coagFound = coagGroup.projects.filter(p => mappings[p.code]).length;
    if (statusCb && coagFound) {statusCb(`凝血组：${coagFound}/${coagGroup.projects.length} 已映射`, 'info');}
  }

  // --- 自动检测项目映射 ---
  // 遍历所有工作组的仪器，通过 API 查询测试项目并匹配
  async function qeDetectMappings(statusCb) {
    const mappings = {}; // { projectCode: { machineDR, testCodeDR, testName, machineName, matDR, matLotDR, wgDR, wgName } }
    _qeQueryFailures = []; // 8.9.0: 每轮检测重新登记，避免「单独检测」留下的旧失败记录混进后续导出提示
    const machines = await qeGetAllMachines();
    const now = today();
    // 计算当月日期范围
    const cfg = qeCollectConfig();
    const year = cfg._year || new Date().getFullYear();
    const month = cfg._month || new Date().getMonth() + 1;
    const startDate = year + '-' + String(month).padStart(2, '0') + '-01';
    const endDate = qeMonthEndDate(year, month);

    if (statusCb) {statusCb(`正在检测项目映射... 共 ${machines.length} 台仪器`, 'info');}

    // 8.9.0: 两阶段——阶段1 仪器间 4 路并发抓取测试项目列表（网络耗时大头）；
    // 阶段2 仍按原机器顺序串行分配映射（tc 抢占 unmapped 项目的顺序必须与旧版一致，
    // 否则多台仪器都能匹配同名项目时分配结果会漂移）
    const _machTestCodes = await qePool(machines, 4, async (mach, mi) => {
      if (qeAbortFlag) {return [];}
      if (statusCb) {statusCb(`检测 ${mi + 1}/${machines.length}: ${mach.text}（${mach.wgName}）`, 'info');}
      const testCodes = await qeApiTestCodes(mach.id, startDate, endDate, '', mach.text);
      dbg(`[LIS-QE] ${mach.text}: ${testCodes.length} 个测试项目`);
      if (testCodes.length > 0) {
        dbg(
          '[LIS-QE] 示例:',
          testCodes
            .slice(0, 3)
            .map(
              tc => `Code=${tc.Code} CName=${tc.CName} MatName=${tc.MaterialName} RowID=${tc.RowID} MatDR=${tc.MatDR}`
            )
            .join(' | ')
        );
      }
      return testCodes;
    });

    for (let mi = 0; mi < machines.length; mi++) {
      if (qeAbortFlag) {break;}
      const mach = machines[mi];
      const testCodes = _machTestCodes[mi] || [];
      for (let ti = 0; ti < testCodes.length; ti++) {
        const tc = testCodes[ti];
        const rowID = String(tc.RowID || '');
        const matDR = String(tc.MatDR || '');
        const matLotDR = String(tc.MatLotRowID || '');
        const cname = qeNormName(tc.CName);
        // 每个 tc 只分配给匹配分最高的 proj，避免成对项目(FT3/TT3 等)
        // 因子串别名被同一数据抢占、导致导出结果相同
        let bestProj = null, bestGroup = null, bestScore = -1;
        for (const group of QE_GROUPS) {
          for (const proj of group.projects) {
            if (mappings[proj.code]) {continue;}
            const score = qeMatchScore(group, proj, tc, mach.text);
            if (score < 0) {continue;}
            if (score > bestScore) {
              bestScore = score; bestProj = proj; bestGroup = group;
            }
          }
        }
        if (bestProj) {
          mappings[bestProj.code] = {
            machineDR: mach.id,
            machineName: mach.text,
            testCodeDR: rowID,
            testName: cname || bestProj.name,
            matDR: matDR,
            matLotDR: matLotDR,
            materialName: String(tc.MaterialName || ''),
            wgDR: mach.wgDR,
            wgName: mach.wgName,
            groupId: bestGroup.id
          };
        }
      }
    }

    await qeCoagFallbackMappings(mappings, machines, startDate, endDate, statusCb);

    mappings._meta = { year: year, month: month, at: Date.now(), logicVersion: QE_MAP_LOGIC_VERSION };
    const found = qeMappingCount(mappings);
    const total = QE_GROUPS.reduce((s, g) => s + g.projects.length, 0);
    if (statusCb)
    {statusCb(
      `映射检测完成: ${found}/${total} 个项目已匹配（${year}-${String(month).padStart(2, '0')}）`,
      found === total ? 'ok' : 'info'
    );}
    return mappings;
  }

  // ============================================================
  // ⚠️ 映射缓存版本（8.4.7 事故教训：改匹配逻辑忘 bump，旧缓存让修复不生效）
  // 改以下任意匹配逻辑，必须同步：QE_MAP_KEY 的 v9 升 v10，且 QE_MAP_LOGIC_VERSION +1：
  //   - QE_ALIASES 别名表 / QE_LIS_ABBR 缩写表
  //   - qeMatchScore / qeAbbrHit / qeDetectMappings / qeCoagFallbackMappings
  //   - QE_GROUPS 的机器正则 / materialHint / lisName / 硬编码 DR
  // 导出前会校验 logicVersion，不符自动重新检测并保存；key 升版是双保险（旧缓存物理不可达）。
  // 只改数据获取 / Excel 生成等非匹配逻辑时无需 bump，但建议顺手 bump。
  // ============================================================
  const QE_MAP_KEY = 'lis-qe-mappings-v9';
  // 映射逻辑版本：qeMatchScore 最佳匹配 = 2。版本不符时导出前自动重新检测，
  // 防止旧缓存(如 v8 子串抢占导致的错误 testCodeDR)被复用、使脚本修复不生效
  const QE_MAP_LOGIC_VERSION = 2;
  function qeLoadMappings() {
    try {
      return JSON.parse(localStorage.getItem(QE_MAP_KEY) || '{}');
    } catch (e) {
      return {};
    }
  }
  function qeSaveMappings(m) {
    try {
      localStorage.setItem(QE_MAP_KEY, JSON.stringify(m));
    } catch (e) {}
  }

  // --- 核心：获取某组的质控数据 ---
  async function qeFetchGroupData(group, cfg, mappings, statusCb) {
    const rows = []; // 最终输出行
    const groupViolations = []; // 8.10.31: 本组质控出控记录
    const month = cfg._month || new Date().getMonth() + 1;
    const year = cfg._year || new Date().getFullYear();
    const operator = qeGetOperator(cfg, group);
    const startDate = year + '-' + String(month).padStart(2, '0') + '-01';
    const endDate = qeMonthEndDate(year, month);

    // 8.9.0: 项目间 4 路并发拉数据（此前逐项目串行是导出慢的主因）；
    // 各项目相互独立、无跨项分配，行生成仍按原项目顺序串行执行，输出行序与旧版一致
    const _projData = await qePool(group.projects, 4, async (proj, pi) => {
      if (qeAbortFlag) {return null;}
      const map = mappings[proj.code];
      if (!map) {
        if (statusCb) {statusCb(`  跳过 ${proj.name}（未找到映射）`, 'error');}
        return null;
      }

      if (statusCb) {statusCb(`  加载 ${proj.name} (${pi + 1}/${group.projects.length})...`, 'info');}

      // 通过 API 查询质控数据（血常规/尿常规等同月多质控物时自动选有数据的）
      const dataRows = await qeFetchProjectQCData(group, proj, map, cfg);
      if (!dataRows.length) {
        const matHint = map.materialName ? '（质控物 ' + map.materialName + '）' : '';
        if (statusCb) {statusCb(`  ${proj.name}: 无数据${matHint}`, 'info');}
        return null;
      }
      return { proj, map, dataRows };
    });

    for (const _pd of _projData) {
      if (!_pd) {continue;}
      const proj = _pd.proj;
      const map = _pd.map;
      const dataRows = _pd.dataRows;

      // 按浓度分组
      const levels = {};
      dataRows.forEach(r => {
        const lv = String(r.LevelNo || '1');
        if (!levels[lv]) {levels[lv] = [];}
        const val = qeCalcValue(r);
        if (val !== null && !Number.isNaN(val)) {
          const date = r.TestDate || r.AddDate || r.QCDate || '';
          const m = qeExtractMonth(date);
          const d = qeExtractDay(date);
          const y = qeExtractYear(date); // 8.10.0: 补年份比较
          const inMonth =
            (y === year && m === month && d > 0) ||
            (String(date).indexOf(year + '-' + String(month).padStart(2, '0')) === 0 && d > 0);
          if (inMonth) {
            levels[lv].push({
              day: d,
              value: val,
              date: date,
              time: r.TestTime || r.AddTime || '',
              target: parseFloat(r.SetUpX),
              sd: parseFloat(r.SetUpSD),
              rawTarget: r.SetUpX,
              rawSd: r.SetUpSD
            });
          }
        }
      });

      // 8.11.9: 配置浓度数（group.concentrations）与仪器实际回传的水平号可能不一致。
      // 下方输出与 Westgard 核查都只遍历 1..concentrations，超出配置的水平会被静默丢弃
      // （既不出 Excel 也不进核查），用户完全无感知。这里显式提示，避免「数据少了没人知道」。
      const _extraLv = Object.keys(levels)
        .filter(k => /^\d+$/.test(k) && Number(k) > (group.concentrations || 1))
        .sort((a, b) => Number(a) - Number(b));
      if (_extraLv.length && statusCb) {
        statusCb(
          `  ⚠ ${proj.name}：仪器回传了超出配置的浓度水平 L${_extraLv.join('/L')}，本次导出已跳过；若确为实际水平请调高该组「浓度数」`,
          'error'
        );
      }

      // 生成输出行
      const conc = group.concentrations || 1;
      for (let li = 0; li < conc; li++) {
        const lvNo = String(li + 1);
        const lvData = levels[lvNo] || [];
        let lot = '';
        if (group.lotMode === 'suffix') {
          const base = qeGetLot(cfg, group);
          lot = base + (li === 0 ? 'N' : 'H');
        } else if (group.lotMode === 'dual') {
          const lots = qeGetLot(cfg, group);
          lot = Array.isArray(lots) ? lots[li] || '' : '';
        } else if (group.lotMode === 'single') {
          lot = qeGetLot(cfg, group);
        } else if (group.lotMode === 'perProject' || group.lotMode === 'immune') {
          const lots = qeGetLot(cfg, group);
          lot = lots[proj.code] || '';
        } else if (group.lotMode === 'coag') {
          const lots = qeGetLot(cfg, group);
          lot = proj.isDDimer ? lots._dimer : lots._main;
        }
        lvData.sort((a, b) => (a.day - b.day) || String(a.time || '').localeCompare(String(b.time || '')));
        const daySeq = {};
        lvData.forEach(pt => {
          pt.lot = lot;
          const seq = (daySeq[pt.day] = (daySeq[pt.day] || 0) + 1);
          pt.seq = seq;
          rows.push([proj.code, month, pt.day, seq, lot, pt.value, proj.name, operator]);
        });
      }

      // 8.10.31: 智能核查该项目的 Westgard 质控规则（结合当月靶值与标准差）
      try {
        const pViolations = qeEvaluateWestgardRules(group, proj, levels, conc, year, month);
        if (pViolations && pViolations.length) {
          groupViolations.push(...pViolations);
        }
      } catch (err) {
        dbg('[LIS-QE] Westgard 核查异常:', proj.name, err);
      }
    }

    rows.rows = rows;
    rows.violations = groupViolations;
    return rows;
  }

  // ============================================================
  //  模块 QE 增强：Westgard 室内质控多规则智能核查引擎 (8.10.32)
  //  支持规则：
  //    1-3s (严重失控，单点超 3SD)
  //    2-2s (连续失控，同水平连续两点同侧超 2SD 或同日跨水平同侧超 2SD)
  //    R-4s (极差失控，同水平连续两点反向极差超 4SD 或同日跨水平极差超 4SD)
  //    10-x (漂移失控，连续 10 点均值同侧)
  //    1-2s (质控预警，单点 2 < |Z| <= 3，未触发拒收规则)
  // ============================================================
  function qeEvaluateWestgardRules(group, proj, levels, conc, year, month) {
    const violations = [];
    const levelPoints = {}; // { lvNo: [ptWithZ, ...] }

    for (let li = 0; li < conc; li++) {
      const lvNo = String(li + 1);
      const pts = (levels[lvNo] || []).slice();
      if (!pts.length) {continue;}

      // 寻找该水平的有效靶值与 SD（优先用行自带，行缺漏时用同水平其它行靶值/SD 兜底）
      const fallbackTargetPt = pts.find(p => !Number.isNaN(p.target) && !Number.isNaN(p.sd) && p.sd > 0);
      const defaultTarget = fallbackTargetPt ? fallbackTargetPt.target : NaN;
      const defaultSd = fallbackTargetPt ? fallbackTargetPt.sd : NaN;

      // 按日期与时间升序排序
      pts.sort((a, b) => (a.day - b.day) || String(a.time || '').localeCompare(String(b.time || '')));

      // 为每个测定点解析有效靶值、SD 并计算 Z-Score
      const evaluatedPts = [];
      pts.forEach(pt => {
        const target = !Number.isNaN(pt.target) ? pt.target : defaultTarget;
        const sd = (!Number.isNaN(pt.sd) && pt.sd > 0) ? pt.sd : defaultSd;
        if (Number.isNaN(target) || Number.isNaN(sd) || sd <= 0) {
          return;
        }
        const diff = pt.value - target;
        const z = diff / sd;
        evaluatedPts.push({
          ...pt,
          target,
          sd,
          diff,
          z,
          levelNo: lvNo
        });
      });

      levelPoints[lvNo] = evaluatedPts;

      // --- 单水平时序规则检查 ---
      let streak10x = 0;
      let sign10x = 0;

      for (let i = 0; i < evaluatedPts.length; i++) {
        const curr = evaluatedPts[i];
        const prev = i > 0 ? evaluatedPts[i - 1] : null;
        const z = curr.z;
        const absZ = Math.abs(z);
        const ptViolations = [];

        // 1. 1-3s (严重失控，单点超过 3SD)
        if (absZ > 3) {
          ptViolations.push({
            rule: '1-3s',
            ruleName: '1-3s (严重失控)',
            severity: 'loss',
            detail: `测定值 ${curr.value} 偏离靶值 ${curr.target.toFixed(2)} 达 ${absZ.toFixed(2)} SD（超 3SD 限值）`
          });
        }

        // 2. 2-2s (同水平连续两点同侧超 2SD)
        if (prev) {
          const prevZ = prev.z;
          if ((z > 2 && prevZ > 2) || (z < -2 && prevZ < -2)) {
            ptViolations.push({
              rule: '2-2s',
              ruleName: '2-2s (连续失控)',
              severity: 'loss',
              detail: `同水平连续 2 点同侧超 2SD（前值 Z=${prevZ > 0 ? '+' : ''}${prevZ.toFixed(2)}, 现值 Z=${z > 0 ? '+' : ''}${z.toFixed(2)}）`
            });
          }
        }

        // 3. R-4s (同水平连续两点反向极差超 4SD)
        if (prev) {
          const prevZ = prev.z;
          const rangeZ = Math.abs(z - prevZ);
          if (rangeZ >= 4 && ((z > 0 && prevZ < 0) || (z < 0 && prevZ > 0))) {
            ptViolations.push({
              rule: 'R-4s',
              ruleName: 'R-4s (极差失控)',
              severity: 'loss',
              detail: `同水平连续 2 点反向极差达 ${rangeZ.toFixed(2)} SD（前值 Z=${prevZ > 0 ? '+' : ''}${prevZ.toFixed(2)}, 现值 Z=${z > 0 ? '+' : ''}${z.toFixed(2)}）`
            });
          }
        }

        // 4. 10-x (连续 10 点均位于均值同一侧)
        if (z !== 0) {
          const curSign = z > 0 ? 1 : -1;
          if (curSign === sign10x) {
            streak10x++;
          } else {
            sign10x = curSign;
            streak10x = 1;
          }
          if (streak10x >= 10) {
            ptViolations.push({
              rule: '10-x',
              ruleName: '10-x (均值漂移)',
              severity: 'loss',
              detail: `同水平连续 ${streak10x} 点均位于均值同一侧（${sign10x > 0 ? '正向' : '负向'}均值漂移）`
            });
          }
        } else {
          streak10x = 0;
          sign10x = 0;
        }

        // 5. 1-2s (单点超 2SD 质控预警，未达拒收条件)
        if (absZ > 2 && absZ <= 3) {
          const hasLoss = ptViolations.some(v => v.severity === 'loss');
          if (!hasLoss) {
            ptViolations.push({
              rule: '1-2s',
              ruleName: '1-2s (质控预警)',
              severity: 'warn',
              detail: `单点测定值偏离靶值达 ${absZ.toFixed(2)} SD（超 2SD 预警线，未达 3SD）`
            });
          }
        }

        // 记录违规项
        if (ptViolations.length > 0) {
          const isLoss = ptViolations.some(v => v.severity === 'loss');
          const dateStr = curr.date || `${year}-${String(month).padStart(2, '0')}-${String(curr.day).padStart(2, '0')}`;
          violations.push({
            groupId: group.id,
            groupName: group.name,
            file: group.file,
            projectCode: proj.code,
            projectName: proj.name,
            levelNo: lvNo,
            lot: curr.lot || '',
            date: dateStr,
            day: curr.day,
            value: curr.value,
            target: curr.target,
            sd: curr.sd,
            z: curr.z,
            severity: isLoss ? 'loss' : 'warn',
            rules: ptViolations.map(v => v.rule),
            ruleNames: ptViolations.map(v => v.ruleName),
            details: ptViolations.map(v => v.detail)
          });
        }
      }
    }

    // --- 跨水平同日规则检查 (R-4s 跨水平 与 2-2s 跨水平) ---
    if (conc >= 2 && levelPoints['1'] && levelPoints['2']) {
      // 8.11.9: 同日 L1 可能有多条测定（重测/多次上机/多批号），此前 `dayMap1[p.day] = p`
      // 只保留当天最后一条 L1，跨水平 R-4s / 2-2s 仅与那一条比较，
      // 同日其它 L1 与 L2 的组合被永久漏检（真实失控可能只出现在被覆盖掉的那条上）。
      // 改为按日收集全部 L1 测点，逐条与同日 L2 比较。
      const dayMap1 = {};
      levelPoints['1'].forEach(p => {
        if (!dayMap1[p.day]) {dayMap1[p.day] = [];}
        dayMap1[p.day].push(p);
      });
      levelPoints['2'].forEach(p2 => {
        const p1list = dayMap1[p2.day];
        if (!p1list) {return;}
        p1list.forEach(p1 => {
        const z1 = p1.z;
        const z2 = p2.z;
        const crossViolations = [];

        // 跨水平 R-4s: 同日双水平极差 >= 4SD
        const rangeZ = Math.abs(z1 - z2);
        if (rangeZ >= 4) {
          crossViolations.push({
            rule: 'R-4s',
            ruleName: 'R-4s (跨水平极差)',
            severity: 'loss',
            detail: `同日双水平测定值极差达 ${rangeZ.toFixed(2)} SD（L1: ${z1 > 0 ? '+' : ''}${z1.toFixed(2)}SD, L2: ${z2 > 0 ? '+' : ''}${z2.toFixed(2)}SD）`
          });
        }

        // 跨水平 2-2s: 同日双水平同时同侧超 2SD
        if ((z1 > 2 && z2 > 2) || (z1 < -2 && z2 < -2)) {
          crossViolations.push({
            rule: '2-2s',
            ruleName: '2-2s (跨水平连续)',
            severity: 'loss',
            detail: `同日双水平测定值同时同侧超 2SD（L1: ${z1 > 0 ? '+' : ''}${z1.toFixed(2)}SD, L2: ${z2 > 0 ? '+' : ''}${z2.toFixed(2)}SD）`
          });
        }

        if (crossViolations.length > 0) {
          const dateStr = p2.date || `${year}-${String(month).padStart(2, '0')}-${String(p2.day).padStart(2, '0')}`;
          const existing = violations.find(v => v.projectCode === proj.code && v.day === p2.day);
          if (existing) {
            crossViolations.forEach(cv => {
              if (!existing.rules.includes(cv.rule)) {
                existing.rules.push(cv.rule);
                existing.ruleNames.push(cv.ruleName);
                existing.details.push(cv.detail);
                if (cv.severity === 'loss') {existing.severity = 'loss';}
              }
            });
          } else {
            violations.push({
              groupId: group.id,
              groupName: group.name,
              file: group.file,
              projectCode: proj.code,
              projectName: proj.name,
              levelNo: 'L1+L2',
              lot: (p1.lot || '') + (p2.lot ? '/' + p2.lot : ''),
              date: dateStr,
              day: p2.day,
              value: p2.value,
              target: p2.target,
              sd: p2.sd,
              z: p2.z,
              severity: 'loss',
              rules: crossViolations.map(v => v.rule),
              ruleNames: crossViolations.map(v => v.ruleName),
              details: crossViolations.map(v => v.detail)
            });
          }
        }
        });
      });
    }

    return violations;
  }

  // 渲染质控出控排查报告卡片 (8.10.31)
  function qeRenderQCAuditReport(violations, year, month, totalGroups, exportedCount) {
    const host = document.getElementById('lis-qe-audit-section');
    if (!host) {return;}

    if (!violations || !violations.length) {
      host.innerHTML = `
        <div class="qe-qc-audit-box clean">
            <div class="qe-qc-audit-title">
                <span style="font-size:16px">🛡️</span>
                <span style="font-weight:800;color:#059669;font-size:12px">质控规则核查：所有已导出项目在控</span>
            </div>
            <div class="qe-qc-audit-sub">
                已结合 ${year} 年 ${String(month).padStart(2, '0')} 月各项目靶值与 SD，核查 1-3s、2-2s、R-4s、10-x 及 1-2s 规则，未发现失控或预警结果。
            </div>
        </div>`;
      return;
    }

    const lossItems = violations.filter(v => v.severity === 'loss');
    const warnItems = violations.filter(v => v.severity === 'warn');
    const uniqueProjects = new Set(violations.map(v => v.projectName)).size;

    let filterMode = 'all';

    function renderTableRows(items) {
      if (!items.length) {
        return '<tr><td colspan="9" style="text-align:center;color:#94a3b8;padding:16px">当前筛选模式下无匹配记录</td></tr>';
      }
      return items.map(v => {
        const isLoss = v.severity === 'loss';
        const rowCls = isLoss ? 'row-loss' : 'row-warn';
        const zStr = v.z != null ? (v.z > 0 ? '+' : '') + v.z.toFixed(2) : '-';
        const targetSdStr = (v.target != null && v.sd != null) ? `${v.target} ± ${v.sd}` : '-';
        const dateShort = v.date && v.date.length >= 10 ? v.date.slice(5) : (v.date || String(v.day) + '日');
        const ruleBadges = (v.ruleNames || []).map(r => `<span class="qe-qc-rule-badge ${isLoss ? 'loss' : 'warn'}">${esc(r)}</span>`).join(' ');
        const detailsStr = (v.details || []).join('<br>');
        return `
          <tr class="${rowCls}">
              <td style="font-weight:700;color:#334155">${esc(v.groupName)}</td>
              <td style="font-weight:700;color:var(--lis-primary)">${esc(v.projectName)}</td>
              <td>Level ${esc(v.levelNo)}</td>
              <td>${esc(dateShort)}</td>
              <td style="font-weight:800;color:${isLoss ? '#b91c1c' : '#b45309'}">${esc(String(v.value))}</td>
              <td style="color:#64748b">${esc(targetSdStr)}</td>
              <td style="font-weight:700;color:${isLoss ? '#b91c1c' : '#b45309'}">${esc(zStr)} SD</td>
              <td>${ruleBadges}</td>
              <td style="color:#475569;line-height:1.4">${detailsStr}</td>
          </tr>`;
      }).join('');
    }

    function updateView() {
      const displayItems = filterMode === 'loss' ? lossItems : filterMode === 'warn' ? warnItems : violations;
      const tbody = host.querySelector('.qe-qc-table tbody');
      if (tbody) {
        tbody.innerHTML = renderTableRows(displayItems);
      }
      host.querySelectorAll('.qe-qc-tab').forEach(t => {
        t.classList.toggle('active', t.getAttribute('data-filter') === filterMode);
      });
    }

    host.innerHTML = `
      <div class="qe-qc-audit-box alert">
          <div class="qe-qc-audit-header">
              <div class="qe-qc-audit-title">
                  <span style="font-size:16px">⚠️</span>
                  <span style="font-weight:800;font-size:13px;color:#b91c1c">质控出控排查通报</span>
                  <span class="qe-qc-summary-tag">（共 ${violations.length} 项异常：${lossItems.length > 0 ? `<b style="color:#b91c1c">🔴 ${lossItems.length} 项失控</b>` : ''}${lossItems.length > 0 && warnItems.length > 0 ? '，' : ''}${warnItems.length > 0 ? `<b style="color:#b45309">🟡 ${warnItems.length} 项预警</b>` : ''}，涉及 ${uniqueProjects} 个项目）</span>
              </div>
              <div class="qe-qc-audit-actions">
                  <button id="lis-qe-audit-copy" type="button" class="qe-qc-btn copy" title="复制文本通报，方便微信/钉钉交班">📋 复制出控清单</button>
                  <button id="lis-qe-audit-export-xlsx" type="button" class="qe-qc-btn export" title="导出专属出控排查明细 Excel">📥 导出出控明细 Excel</button>
              </div>
          </div>
          <div class="qe-qc-tabs">
              <button type="button" class="qe-qc-tab active" data-filter="all">全部 (${violations.length})</button>
              <button type="button" class="qe-qc-tab" data-filter="loss">仅看失控 (${lossItems.length})</button>
              <button type="button" class="qe-qc-tab" data-filter="warn">仅看预警 (${warnItems.length})</button>
          </div>
          <div class="qe-qc-table-wrap">
              <table class="qe-qc-table">
                  <thead>
                      <tr>
                          <th>专业组</th>
                          <th>项目名称</th>
                          <th>水平</th>
                          <th>测定日期</th>
                          <th>测定值</th>
                          <th>靶值 ± SD</th>
                          <th>偏离度 (Z)</th>
                          <th>触发规则</th>
                          <th>规则判定说明</th>
                      </tr>
                  </thead>
                  <tbody>
                      ${renderTableRows(violations)}
                  </tbody>
              </table>
          </div>
      </div>`;

    // 绑定 Tabs 筛选切换
    host.querySelectorAll('.qe-qc-tab').forEach(tab => {
      tab.addEventListener('click', () => {
        filterMode = tab.getAttribute('data-filter') || 'all';
        updateView();
      });
    });

    // 绑定一键复制通报按钮
    const copyBtn = host.querySelector('#lis-qe-audit-copy');
    if (copyBtn) {
      copyBtn.addEventListener('click', () => {
        qeCopyQCReportText(violations, year, month);
      });
    }

    // 绑定导出专属 Excel 按钮
    const exportXlsxBtn = host.querySelector('#lis-qe-audit-export-xlsx');
    if (exportXlsxBtn) {
      exportXlsxBtn.addEventListener('click', () => {
        qeDownloadQCViolationsXlsx(violations, year, month);
      });
    }
  }

  // 复制出控通报纯文本 (8.10.31)
  function qeCopyQCReportText(violations, year, month) {
    if (!violations || !violations.length) {
      toast('暂无出控记录可复制', 'i');
      return;
    }
    const lossCount = violations.filter(v => v.severity === 'loss').length;
    const warnCount = violations.filter(v => v.severity === 'warn').length;

    const grouped = {};
    violations.forEach(v => {
      const k = `${v.groupName} - ${v.projectName}`;
      if (!grouped[k]) {grouped[k] = [];}
      grouped[k].push(v);
    });

    let text = `【室内质控出控排查通报】${year}年${String(month).padStart(2, '0')}月\n`;
    text += `共发现 ${violations.length} 项质控异常（${lossCount} 项失控，${warnCount} 项预警）：\n\n`;

    let idx = 1;
    for (const [projKey, items] of Object.entries(grouped)) {
      text += `${idx++}. 【${projKey}】\n`;
      items.forEach(it => {
        const icon = it.severity === 'loss' ? '🔴' : '🟡';
        const rules = (it.ruleNames || []).join('、');
        const zStr = it.z != null ? (it.z > 0 ? '+' : '') + it.z.toFixed(2) : '';
        const targetStr = (it.target != null && it.sd != null) ? `靶值 ${it.target}±${it.sd}` : '';
        const dateStr = it.date && it.date.length >= 10 ? it.date.slice(5) : it.date;
        text += `   - ${dateStr} (Level ${it.levelNo}): 测定值 ${it.value} (${targetStr}, Z=${zStr} SD) [${icon} ${rules}]\n`;
        (it.details || []).forEach(d => {
          text += `     说明: ${d}\n`;
        });
      });
      text += '\n';
    }

    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(() => {
        toast('已复制质控出控通报清单到剪贴板！', 's');
      }).catch(() => {
        qeFallbackCopy(text);
      });
    } else {
      qeFallbackCopy(text);
    }
  }

  function qeFallbackCopy(text) {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.left = '-9999px';
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    try {
      document.execCommand('copy');
      toast('已复制质控出控通报清单到剪贴板！', 's');
    } catch (e) {
      toast('复制失败，请手动选中复制', 'e');
    }
    document.body.removeChild(ta);
  }

  // 导出专属出控明细 Excel 表格 (8.10.31)
  function qeDownloadQCViolationsXlsx(violations, year, month) {
    const X = qeXlsxLib || qeGetGlobal('XLSX');
    if (!X || !X.utils) {
      toast('SheetJS 未就绪，无法导出 Excel', 'e');
      return;
    }
    const wb = X.utils.book_new();
    const header = [
      '专业组', '项目编码', '项目名称', '浓度水平', '质控批号', '测定日期',
      '测定值', '靶值', '标准差', 'Z偏离得分', '异常级别', '触发规则', '规则判定说明'
    ];
    const data = [
      header,
      ...violations.map(v => [
        v.groupName,
        v.projectCode,
        v.projectName,
        'Level ' + v.levelNo,
        v.lot || '',
        v.date,
        v.value,
        v.target != null ? v.target : '',
        v.sd != null ? v.sd : '',
        v.z != null ? Number(v.z.toFixed(2)) : '',
        v.severity === 'loss' ? '失控' : '预警',
        (v.ruleNames || []).join('; '),
        (v.details || []).join('; ')
      ])
    ];
    const ws = X.utils.aoa_to_sheet(data);
    ws['!cols'] = [
      { wch: 10 }, { wch: 10 }, { wch: 22 }, { wch: 10 }, { wch: 16 }, { wch: 12 },
      { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 12 }, { wch: 10 }, { wch: 22 }, { wch: 45 }
    ];
    X.utils.book_append_sheet(wb, ws, '质控出控明细');
    const xlsxData = X.write(wb, { bookType: 'xlsx', type: 'array' });
    const blob = new Blob([xlsxData], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    });
    const filename = `质控出控排查明细_${year}年${String(month).padStart(2, '0')}月.xlsx`;
    qeDownloadBlob(blob, filename);
    toast(`已导出出控排查明细: ${filename}`, 's');
  }

  // 油猴沙箱里 vendor 库可能挂在 window/unsafeWindow，不一定是自由变量
  function qeGetGlobal(name) {
    try {
      if (typeof globalThis !== 'undefined' && globalThis[name]) {return globalThis[name];}
    } catch (e) {}
    try {
      if (typeof window !== 'undefined' && window[name]) {return window[name];}
    } catch (e) {}
    try {
      if (typeof unsafeWindow !== 'undefined' && unsafeWindow[name]) {return unsafeWindow[name];}
    } catch (e) {}
    try {
      // 自由变量（@require 进沙箱时常在此）
      // eslint-disable-next-line no-eval
      const v = (0, eval)('typeof ' + name + '!=="undefined"?' + name + ':null');
      if (v) {return v;}
    } catch (e) {}
    return null;
  }

  // 8.9.0: vendor 文件 SHA-256（与仓库/同步到 nginx 的副本对应）。内网是 HTTP 明文，
  // 兜底拉 JS 直接执行 = 供应链劫持面；先校验哈希再执行，不匹配一律拒绝（fail-closed）。
  // ⚠️ 更换 vendor 文件时必须同步更新这里（本地 shasum -a 256 vendor/xxx 计算），
  //    并用 同步脚本到nginx.command 一起推送。
  const VENDOR_SHA256 = {
    'xlsx.full.min.js': 'cc015130aa8521e7f088f88898eba949ccdcbfb38df0bd129b44b7273c3a6f41',
    'jszip.min.js': 'acc7e41455a80765b5fd9c7ee1b8078a6d160bbbca455aeae854de65c947d59e'
  };
  // 紧凑同步 SHA-256（HTTP 内网无 WebCrypto，只能纯 JS 实现）
  // 标准 K 常量表（前 64 个素数立方根小数部分前 32 位）
  const _SHA256_K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
  ];
  function sha256Hex(ascii) {
    function rotr(x, n) {return (x >>> n) | (x << (32 - n));}
    const K = _SHA256_K;
    const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
    const l = ascii.length;
    const words = [];
    for (let i = 0; i < l; i++) {words[i >> 2] = (words[i >> 2] || 0) | (ascii.charCodeAt(i) << (24 - (i % 4) * 8));}
    words[l >> 2] = (words[l >> 2] || 0) | (0x80 << (24 - (l % 4) * 8));
    const bitLen = l * 8;
    // 总字数须为 16 的倍数：数据 + 0x80 + 补零 + 8 字节长度（大端 64 位）
    const wc = (((l + 9) + 63) >> 6) << 4;
    words[wc - 1] = bitLen % 4294967296;
    words[wc - 2] = Math.floor(bitLen / 4294967296);
    for (let i = 0; i < wc; i += 16) {
      const w = new Array(64);
      for (let t = 0; t < 16; t++) {w[t] = words[i + t] || 0;}
      for (let t = 16; t < 64; t++) {
        const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
        const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
        w[t] = (w[t - 16] + s0 + w[t - 7] + s1) | 0;
      }
      let [a, b, c, d, e, f, g, h] = H;
      for (let t = 0; t < 64; t++) {
        const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
        const ch = (e & f) ^ (~e & g);
        const t1 = (h + S1 + ch + K[t] + w[t]) | 0;
        const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
        const mj = (a & b) ^ (a & c) ^ (b & c);
        const t2 = (S0 + mj) | 0;
        h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
      }
      H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
      H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
    }
    return H.map(x => ('00000000' + (x >>> 0).toString(16)).slice(-8)).join('');
  }

  // 从 vendor 源拉取脚本并校验 SHA-256 后执行（@require 失败时的兜底）。8.8.35: 先试科室 nginx 源，再试本机 serve
  async function qeLoadVendorScript(fileName, globalName) {
    if (qeGetGlobal(globalName)) {return true;}
    const expect = VENDOR_SHA256[fileName];
    if (!expect) {
      dbg('[LIS-QE] 未登记哈希，拒绝兜底加载', fileName);
      return false;
    }
    const urls = [VENDOR_BASE + '/' + fileName, 'http://127.0.0.1:8765/vendor/' + fileName];
    for (const url of urls) {
      // 8.10.0: 兜底 fetch 补上超时 + 停止信号——此前无 AbortController，vendor 源
      // 「半死」（接受连接不响应）时导出永远卡在「正在加载 Excel 组件…」，
      // 「停止」按钮无效（信号没接进来），导出按钮永久禁用，只能刷新页面
      const ctrl = new AbortController();
      const toId = setTimeout(() => ctrl.abort(), 15000);
      const extSig = _qeSignal();
      const onExtAbort = () => ctrl.abort();
      if (extSig) {
        if (extSig.aborted) {ctrl.abort();}
        else {extSig.addEventListener('abort', onExtAbort, { once: true });}
      }
      try {
        const r = await fetch(url, { cache: 'no-cache', mode: 'cors', signal: ctrl.signal });
        if (!r.ok) {continue;}
        const buf = await r.arrayBuffer();
        const bytes = new Uint8Array(buf);
        if (!bytes.length) {continue;}
        // 8.9.0: 哈希按「原始字节」算——vendor（如 xlsx）含大量非 ASCII 字节，
        // text() 的 UTF-16 码元与文件字节不一致会把完好文件误判成篡改
        let bin = '';
        for (let i = 0; i < bytes.length; i += 8192) {bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 8192));}
        let code = bin;
        try {code = new TextDecoder('utf-8').decode(bytes);} catch (e) {}
        if (!code || code.length < 100) {continue;}
        const got = await qeExecVendorCode(fileName, code, expect, globalName, bin);
        if (got) {return true;}
      } catch (e) {
        dbg('[LIS-QE] 加载失败', url, e.message);
        // 用户停止信号到达时不再尝试下一个源，直接结束兜底
        if (extSig && extSig.aborted) {return !!qeGetGlobal(globalName);}
      } finally {
        clearTimeout(toId);
        if (extSig) {extSig.removeEventListener('abort', onExtAbort);}
      }
    }
    return !!qeGetGlobal(globalName);
  }

  async function qeExecVendorCode(fileName, code, expect, globalName, byteStr) {
    // 8.9.0: 哈希不匹配 = 源被篡改或版本错位，拒绝执行（fail-closed，不回退明文执行）
    const digest = await new Promise(res => {
      try {res(sha256Hex(byteStr || code));} catch (e) {res('');}
    });
    if (digest !== expect) {
      dbg('[LIS-QE] SHA-256 校验失败，拒绝执行', fileName, digest);
      return null;
    }
    // 绑定到本脚本可访问的对象（JSZip UMD 写 window.JSZip；须屏蔽 node 的 module）
    const root = typeof globalThis !== 'undefined' ? globalThis : typeof window !== 'undefined' ? window : {};
    // module/exports/define 显式 undefined，避免 UMD 走 module.exports 而不挂全局
    const runner = new Function(
      'root',
      'window',
      'globalThis',
      'self',
      'module',
      'exports',
      'define',
      code +
        '\n;return (typeof ' +
        globalName +
        '!=="undefined"?' +
        globalName +
        ':null)||window.' +
        globalName +
        '||root.' +
        globalName +
        '||globalThis.' +
        globalName +
        ';'
    );
    let got = null;
    try {
      got = runner(root, root, root, root, undefined, undefined, undefined);
    } catch (e1) {
      dbg('[LIS-QE] Function 执行失败', fileName, e1.message);
      try {
        // eslint-disable-next-line no-eval -- 哈希已校验的 vendor 兜底执行，仅此一处
        (0, eval)(code);
      } catch (e2) {}
      got = qeGetGlobal(globalName);
    }
    if (!got) {got = qeGetGlobal(globalName) || root[globalName];}
    if (got) {
      try {
        root[globalName] = got;
      } catch (e) {}
      if (globalName === 'XLSX') {qeXlsxLib = got;}
      if (globalName === 'JSZip') {qeJSZipLib = got;}
      dbg('[LIS-QE] 已加载（SHA-256 校验通过）', fileName);
    }
    return got;
  }

  let qeXlsxLib = null;
  let qeJSZipLib = null;

  async function qeEnsureXlsx() {
    if (qeXlsxLib && qeXlsxLib.utils) {return true;}
    const g = qeGetGlobal('XLSX');
    if (g && g.utils) {
      qeXlsxLib = g;
      return true;
    }
    const ok = await qeLoadVendorScript('xlsx.full.min.js', 'XLSX');
    qeXlsxLib = qeGetGlobal('XLSX') || qeXlsxLib;
    return !!(qeXlsxLib && qeXlsxLib.utils);
  }

  async function qeEnsureJSZip() {
    if (qeJSZipLib) {return true;}
    const g = qeGetGlobal('JSZip');
    if (g) {
      qeJSZipLib = g;
      return true;
    }
    const ok = await qeLoadVendorScript('jszip.min.js', 'JSZip');
    qeJSZipLib = qeGetGlobal('JSZip') || qeJSZipLib;
    return !!qeJSZipLib;
  }

  // --- Excel 生成 ---
  function qeBuildXlsx(groupName, rows) {
    const X = qeXlsxLib || qeGetGlobal('XLSX');
    if (!X || !X.utils) {
      throw new Error('SheetJS 未加载：请先运行 python3 ~/脚本/serve.py，再刷新页面后重试');
    }
    const wb = X.utils.book_new();
    const header = ['项目编码', '月', '日', '次', '批号', '数值', '备注', '操作者'];
    const data = [header, ...rows];
    const ws = X.utils.aoa_to_sheet(data);
    // 设置列宽
    ws['!cols'] = [{ wch: 10 }, { wch: 5 }, { wch: 5 }, { wch: 4 }, { wch: 18 }, { wch: 10 }, { wch: 20 }, { wch: 10 }];
    X.utils.book_append_sheet(wb, ws, 'Sheet1');
    return X.write(wb, { bookType: 'xlsx', type: 'array' });
  }

  function qeDownloadBlob(blob, filename) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 5000);
  }

  // 从内存或结果列表 DOM 收集可打包文件（单独下载按钮上挂着 _blob）
  function qeCollectPackableFiles() {
    let files = (qeLastExportFiles || []).filter(f => f && f.blob && f.name);
    if (files.length) {return files;}
    const list = document.getElementById('lis-qe-results');
    if (!list) {return [];}
    files = [];
    list.querySelectorAll('button[data-fn]').forEach(btn => {
      if (btn._blob) {files.push({ name: btn.getAttribute('data-fn') || 'export.xlsx', blob: btn._blob });}
    });
    return files;
  }

  function qeUpdateZipButton() {
    const btn = document.getElementById('lis-qe-zip');
    if (!btn) {return;}
    const n = qeCollectPackableFiles().length;
    // 始终可点：无文件时点一下给提示，避免「灰色没反应」
    btn.disabled = false;
    btn.style.opacity = n > 0 ? '1' : '0.65';
    btn.style.cursor = 'pointer';
    btn.textContent = n > 0 ? `📦 打包下载 ZIP (${n})` : '📦 打包下载 ZIP';
  }

  // CRC32 表（ZIP 本地实现用，不依赖 JSZip，避免油猴沙箱卡住）
  let _qeCrcTable = null;
  function qeCrc32(u8) {
    if (!_qeCrcTable) {
      _qeCrcTable = new Uint32Array(256);
      for (let n = 0; n < 256; n++) {
        let c = n;
        for (let k = 0; k < 8; k++) {c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;}
        _qeCrcTable[n] = c >>> 0;
      }
    }
    let crc = 0xffffffff;
    for (let i = 0; i < u8.length; i++) {crc = _qeCrcTable[(crc ^ u8[i]) & 0xff] ^ (crc >>> 8);}
    return (crc ^ 0xffffffff) >>> 0;
  }

  function qeU16(n) {
    return new Uint8Array([n & 0xff, (n >>> 8) & 0xff]);
  }
  function qeU32(n) {
    return new Uint8Array([n & 0xff, (n >>> 8) & 0xff, (n >>> 16) & 0xff, (n >>> 24) & 0xff]);
  }
  function qeConcatBytes(parts) {
    let len = 0;
    parts.forEach(p => {
      len += p.length;
    });
    const out = new Uint8Array(len);
    let off = 0;
    parts.forEach(p => {
      out.set(p, off);
      off += p.length;
    });
    return out;
  }

  // 纯 JS 生成 ZIP（仅 STORE 存储，xlsx 本身已压缩，体积几乎无差）
  function qeBuildZipBlobSync(entries) {
    // entries: [{ name: string, data: Uint8Array }]
    const enc = typeof TextEncoder !== 'undefined' ? new TextEncoder() : null;
    const localParts = [];
    const centralParts = [];
    let offset = 0;
    entries.forEach(ent => {
      const nameBytes = enc
        ? enc.encode(ent.name)
        : (() => {
          const a = new Uint8Array(ent.name.length);
          for (let i = 0; i < ent.name.length; i++) {a[i] = ent.name.charCodeAt(i) & 0xff;}
          return a;
        })();
      const data = ent.data;
      const crc = qeCrc32(data);
      const size = data.length >>> 0;
      // Local file header（flags bit11 = UTF-8 文件名，避免中文乱码）
      const flags = 0x0800;
      const local = qeConcatBytes([
        qeU32(0x04034b50),
        qeU16(20), // version needed
        qeU16(flags),
        qeU16(0), // method STORE
        qeU16(0),
        qeU16(0), // time/date
        qeU32(crc),
        qeU32(size),
        qeU32(size),
        qeU16(nameBytes.length),
        qeU16(0), // extra len
        nameBytes,
        data
      ]);
      localParts.push(local);
      // Central directory header
      const central = qeConcatBytes([
        qeU32(0x02014b50),
        qeU16(20),
        qeU16(20),
        qeU16(flags),
        qeU16(0),
        qeU16(0),
        qeU16(0),
        qeU32(crc),
        qeU32(size),
        qeU32(size),
        qeU16(nameBytes.length),
        qeU16(0),
        qeU16(0), // extra, comment
        qeU16(0),
        qeU16(0), // disk, int attr
        qeU32(0), // ext attr
        qeU32(offset),
        nameBytes
      ]);
      centralParts.push(central);
      offset += local.length;
    });
    const centralDir = qeConcatBytes(centralParts);
    const end = qeConcatBytes([
      qeU32(0x06054b50),
      qeU16(0),
      qeU16(0),
      qeU16(entries.length),
      qeU16(entries.length),
      qeU32(centralDir.length),
      qeU32(offset),
      qeU16(0)
    ]);
    const all = qeConcatBytes(localParts.concat([centralDir, end]));
    return new Blob([all], { type: 'application/zip' });
  }

  async function qeBlobToU8(blob) {
    if (!blob) {return new Uint8Array(0);}
    if (blob.arrayBuffer) {
      const ab = await blob.arrayBuffer();
      return new Uint8Array(ab);
    }
    // 极旧环境
    return new Promise((resolve, reject) => {
      const fr = new FileReader();
      fr.onload = () => resolve(new Uint8Array(fr.result));
      fr.onerror = () => reject(fr.error || new Error('FileReader failed'));
      fr.readAsArrayBuffer(blob);
    });
  }

  // 一键 ZIP：纯本地实现，不依赖 JSZip（避免「打包中…」卡住）
  async function qeDownloadAllZip() {
    const files = qeCollectPackableFiles();
    if (!files.length) {
      qeSetStatus('没有可打包的文件：请先点「开始导出」生成表格。', 'error');
      return;
    }
    const zipBtn = document.getElementById('lis-qe-zip');
    if (zipBtn) {
      zipBtn.disabled = true;
      zipBtn.textContent = '打包中…';
    }
    try {
      qeSetStatus(`正在打包 ${files.length} 个 Excel…`, 'info');
      const entries = [];
      for (let i = 0; i < files.length; i++) {
        qeSetStatus(`读取文件 ${i + 1}/${files.length}：${files[i].name}`, 'info');
        // 让出主线程，刷新 UI
        await sleep(0);
        const u8 = await qeBlobToU8(files[i].blob);
        entries.push({ name: files[i].name, data: u8 });
      }
      qeSetStatus('正在生成 ZIP…', 'info');
      await sleep(0);
      const zipBlob = qeBuildZipBlobSync(entries);
      const cfg = qeCollectConfig();
      const ym =
        cfg._year && cfg._month
          ? `${cfg._year}${String(cfg._month).padStart(2, '0')}`
          : today().replace(/-/g, '').slice(0, 6);
      qeDownloadBlob(zipBlob, `质控数据_${ym}.zip`);
      qeSetStatus(`✅ ZIP 已下载（${files.length} 个表格，约 ${Math.round(zipBlob.size / 1024)} KB）。`, 'ok');
    } catch (e) {
      dbg('[LIS-QE] ZIP 失败:', e && e.message);
      qeSetStatus('ZIP 失败: ' + (e && e.message ? e.message : e) + '，改为逐个下载…', 'error');
      try {
        for (let i = 0; i < files.length; i++) {
          qeDownloadBlob(files[i].blob, files[i].name);
          await sleep(350);
        }
        qeSetStatus(`已触发 ${files.length} 个文件逐个下载。`, 'ok');
      } catch (e2) {
        qeSetStatus('逐个下载也失败: ' + (e2 && e2.message ? e2.message : e2), 'error');
      }
    } finally {
      qeUpdateZipButton();
    }
  }

  // --- UI 创建 ---
  function qeCreateFab() {
    if (document.getElementById('lis-qe-fab')) {return;}
    const fab = document.createElement('button');
    fab.id = 'lis-qe-fab';
    fab.textContent = 'QC导';
    fab.title = '质控数据导出\n拖动移动 | 点击打开';
    document.body.appendChild(fab);

    // 恢复位置
    const FAB_POS_KEY = 'lis-qe-fab-pos';
    try {
      const fp = JSON.parse(localStorage.getItem(FAB_POS_KEY) || 'null');
      if (fp && typeof fp.l === 'number') {
        fab.style.left = fp.l + 'px';
        fab.style.top = fp.t + 'px';
        fab.style.right = 'auto';
        fab.style.bottom = 'auto';
        fab.style.position = 'fixed';
      }
    } catch (e) {}

    // 拖动 + 点击
    let fabDx = 0,
      fabDy = 0,
      fabDownX = 0,
      fabDownY = 0;
    fab.addEventListener('mousedown', e => {
      fabDx = e.clientX - fab.offsetLeft;
      fabDy = e.clientY - fab.offsetTop;
      fabDownX = e.clientX;
      fabDownY = e.clientY;
      const onMove = ev => {
        fab.style.left = ev.clientX - fabDx + 'px';
        fab.style.top = ev.clientY - fabDy + 'px';
        fab.style.right = 'auto';
        fab.style.bottom = 'auto';
        fab.style.position = 'fixed';
      };
      const onUp = ev => {
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
        const dist = Math.abs(ev.clientX - fabDownX) + Math.abs(ev.clientY - fabDownY);
        if (dist < 5) {
          const panel = document.getElementById('lis-qe-panel');
          if (panel) {
            const willShow = !panel.classList.contains('show');
            panel.classList.toggle('show');
            if (willShow) {
              qeSyncFromGatewayOnOpen();
            }
          }
        } else {
          try {
            localStorage.setItem(FAB_POS_KEY, JSON.stringify({ l: fab.offsetLeft, t: fab.offsetTop }));
          } catch (e) {}
        }
      };
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
      e.preventDefault();
    });
  }

  function qeCreatePanel() {
    if (document.getElementById('lis-qe-panel')) {return;}
    const panel = document.createElement('div');
    panel.id = 'lis-qe-panel';

    const cfg = qeLoadConfig();
    const now = new Date();
    const defaultMonth = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');

    // --- 项目勾选 HTML ---
    let groupsHtml = '';
    QE_GROUPS.forEach(g => {
      groupsHtml += `<label><input type="checkbox" class="qe-gcheck" value="${g.id}" checked>${g.name} (${g.projects.length}项)</label>`;
    });

    // --- 批号设置 HTML ---
    let lotsHtml = '';
    QE_GROUPS.forEach(g => {
      const gc = (cfg.lots && cfg.lots[g.id]) || {};
      if (g.lotMode === 'suffix') {
        const base = gc.baseLot || g.baseLot;
        lotsHtml += `<div class="qe-lot-item"><span>${g.name} 基础批号</span><input type="text" class="qe-lot-input" data-group="${g.id}" data-type="baseLot" value="${esc(base)}" placeholder="自动+N/H后缀"></div>`;
      } else if (g.lotMode === 'dual') {
        const l1 = (gc.lots && gc.lots[0]) || (g.defaultLots && g.defaultLots[0]) || '';
        const l2 = (gc.lots && gc.lots[1]) || (g.defaultLots && g.defaultLots[1]) || '';
        lotsHtml += `<div class="qe-lot-item"><span>${g.name} Level1</span><input type="text" class="qe-lot-input" data-group="${g.id}" data-type="lot0" value="${esc(l1)}"></div>`;
        lotsHtml += `<div class="qe-lot-item"><span>${g.name} Level2</span><input type="text" class="qe-lot-input" data-group="${g.id}" data-type="lot1" value="${esc(l2)}"></div>`;
      } else if (g.lotMode === 'single') {
        const lot = gc.lot || g.defaultLot || '';
        lotsHtml += `<div class="qe-lot-item"><span>${g.name}</span><input type="text" class="qe-lot-input" data-group="${g.id}" data-type="lot" value="${esc(lot)}"></div>`;
      } else if (g.lotMode === 'perProject') {
        g.projects.forEach(p => {
          const lot = gc[p.code] || p.defaultLot || '';
          lotsHtml += `<div class="qe-lot-item"><span>${p.name}</span><input type="text" class="qe-lot-input" data-group="${g.id}" data-type="proj" data-code="${p.code}" value="${esc(lot)}"></div>`;
        });
      } else if (g.lotMode === 'coag') {
        const mainLot = gc._main || g.defaultLot || '';
        const dimerLot = gc._dimer || g.dDimLot || '';
        lotsHtml += `<div class="qe-lot-item"><span>凝血四项(INR/APTT/PT/FIB)</span><input type="text" class="qe-lot-input" data-group="${g.id}" data-type="coag_main" value="${esc(mainLot)}"></div>`;
        lotsHtml += `<div class="qe-lot-item"><span>D-二聚体</span><input type="text" class="qe-lot-input" data-group="${g.id}" data-type="coag_dimer" value="${esc(dimerLot)}"></div>`;
      } else if (g.lotMode === 'immune') {
        let projLotsHtml = '';
        g.projects.forEach(p => {
          const lot = gc[p.code] || p.defaultLot || g.defaultLot || '';
          projLotsHtml += `<div class="qe-lot-item"><span>${p.name}</span><input type="text" class="qe-lot-input" data-group="${g.id}" data-type="proj" data-code="${p.code}" value="${esc(lot)}"></div>`;
        });
        lotsHtml += `<div class="qe-lot-item" style="flex:1 0 100%"><span style="min-width:auto">${g.name}</span><span class="qe-immune-toggle" data-target="qe-imm-${g.id}">展开设置 ▾</span></div>`;
        lotsHtml += `<div id="qe-imm-${g.id}" class="qe-immune-lots" style="flex:1 0 100%"><div class="qe-lot-grid">${projLotsHtml}</div></div>`;
      }
    });

    // --- 操作者设置 HTML ---
    // 8.16.18: 不再内置任何操作者姓名（公开仓库不带个人信息）。
    // 三组输入框留空并给提示：用户填一次 → qeSaveConfig 存 localStorage → 同步科室网关机，
    // 全程不落仓库文件、不经过 GitHub。
    const operatorGroups = [
      { ids: ['blood', 'coag', 'urine'], label: '临检（血常规/凝血/尿常规）' },
      { ids: ['biochem', 'lipid'], label: '生化（含血脂）' },
      { ids: ['endocrine', 'tumor', 'cardiac', 'infection'], label: '免疫组' }
    ];
    let operatorHtml = '';
    operatorGroups.forEach(og => {
      const val = (cfg.operators && cfg.operators[og.ids[0]]) || '';
      operatorHtml += `<div class="qe-lot-item"><span>${og.label}</span><input type="text" class="qe-op-input" data-ids="${og.ids.join(',')}" value="${esc(val)}" placeholder="填写操作者姓名" title="填一次并「保存并同步网关」后自动带入；存本机与科室网关机，不会进入代码仓库" style="flex:1;min-width:0"></div>`;
    });

    panel.innerHTML = `
            <div id="lis-qe-hd">
                <h3>📊 质控数据导出</h3>
                <span class="qe-spacer"></span>
                <button id="lis-qe-mini" title="隐藏">_</button>
                <button class="qe-close" id="lis-qe-close" title="关闭">×</button>
            </div>
            <div id="lis-qe-body">
                <!-- Step 1: 选择月份和项目 -->
                <div class="qe-step">
                    <div class="qe-step-hd">
                        <span class="qe-step-num">1</span>
                        <span class="qe-step-title">选择月份和导出项目</span>
                        <button id="lis-qe-toggle-all" style="height:22px;font-size:10px;border:1px solid #b8ddd3;background:#f0faf7;color:#0d6655;border-radius:3px;padding:0 8px;cursor:pointer;font-weight:700">全选/反选</button>
                    </div>
                    <div class="qe-step-body">
                        <div class="qe-date-row" style="margin-bottom:6px">
                            <input type="month" id="lis-qe-month" value="${defaultMonth}">
                        </div>
                        <div class="qe-row">${groupsHtml}</div>
                    </div>
                </div>

                <!-- Step 2: 批号和操作者设置 -->
                <div class="qe-step">
                    <div class="qe-step-hd">
                        <span class="qe-step-num">2</span>
                        <span class="qe-step-title">批号和操作者设置</span>
                        <span class="qe-step-desc" id="lis-qe-sync-desc">修改后点击右侧保存并同步</span>
                        <button class="qe-save-btn" id="lis-qe-pull" style="margin-right:6px;background:#f0f9ff;color:#0284c7;border:1px solid #bae6fd" title="从网关机强制重新读取最新批号与操作者配置">☁️ 从网关读取</button>
                        <button class="qe-save-btn" id="lis-qe-save" title="保存当前设置并实时同步共享到科室网关机">💾 保存并同步网关</button>
                    </div>
                    <div class="qe-step-body">
                        <div class="qe-lot-grid">${lotsHtml}</div>
                        <div style="margin-top:8px;border-top:1px solid #edf1f5;padding-top:8px">
                            <div style="font-size:11px;font-weight:700;color:#526575;margin-bottom:4px">操作者</div>
                            <div class="qe-lot-grid">${operatorHtml}</div>
                        </div>
                    </div>
                </div>

                <!-- Step 3: 检测和导出 -->
                <div class="qe-step">
                    <div class="qe-step-hd">
                        <span class="qe-step-num">3</span>
                        <span class="qe-step-title">检测映射 → 导出</span>
                    </div>
                    <div class="qe-step-body">
                        <div class="qe-actions">
                            <button id="lis-qe-detect" title="自动检测质控系统中的项目映射">🔍 检测映射</button>
                            <button id="lis-qe-export" class="primary" title="开始导出">▶ 开始导出</button>
                            <button id="lis-qe-cancel" style="display:none;background:#fff3e0;color:#e65100;border-color:#ff9800">⏹ 停止</button>
                        </div>
                        <div id="lis-qe-status" style="margin-top:6px">选择月份和项目后，点击"检测映射"。</div>
                        <div class="qe-progress" id="lis-qe-progress"><div class="qe-progress-bar" id="lis-qe-pbar"></div><div class="qe-progress-text" id="lis-qe-ptext"></div></div>
                        <div class="qe-mapping-info" id="lis-qe-mapinfo"></div>
                    </div>
                </div>

                <!-- 导出结果 -->
                <div class="qe-step" id="lis-qe-result-section" style="display:none">
                    <div class="qe-step-hd">
                        <span class="qe-step-num">✓</span>
                        <span class="qe-step-title">导出结果</span>
                        <button id="lis-qe-zip" type="button" title="将本次导出的全部表格打成一个 ZIP">📦 打包下载 ZIP</button>
                    </div>
                    <div class="qe-step-body">
                        <div class="qe-result-list" id="lis-qe-results"></div>
                        <div id="lis-qe-audit-section"></div>
                    </div>
                </div>
            </div>`;
    document.body.appendChild(panel);

    // --- 事件绑定 ---
    document.getElementById('lis-qe-mini').addEventListener('click', () => panel.classList.remove('show'));
    document.getElementById('lis-qe-close').addEventListener('click', () => panel.classList.remove('show'));
    const zipBtn0 = document.getElementById('lis-qe-zip');
    if (zipBtn0) {
      zipBtn0.addEventListener('click', e => {
        e.preventDefault();
        e.stopPropagation();
        qeSetStatus('正在处理打包…', 'info');
        qeDownloadAllZip().catch(err => {
          qeSetStatus('ZIP 异常: ' + (err && err.message ? err.message : err), 'error');
          qeUpdateZipButton();
        });
      });
    }

    // 全选/反选
    document.getElementById('lis-qe-toggle-all').addEventListener('click', () => {
      const checks = panel.querySelectorAll('.qe-gcheck');
      const allChecked = Array.from(checks).every(c => c.checked);
      checks.forEach(c => (c.checked = !allChecked));
    });

    // 免疫组展开/折叠
    panel.querySelectorAll('.qe-immune-toggle').forEach(el => {
      el.addEventListener('click', () => {
        const target = document.getElementById(el.dataset.target);
        if (target) {
          target.classList.toggle('show');
          el.textContent = target.classList.contains('show') ? '收起 ▴' : '展开设置 ▾';
        }
      });
    });

    // 保存设置并同步到网关机（全科室电脑共享）
    document.getElementById('lis-qe-save').addEventListener('click', async () => {
      const cfg = qeCollectConfig();
      cfg._updated_at = Date.now();
      qeSaveConfig(cfg);
      const btn = document.getElementById('lis-qe-save');
      const desc = document.getElementById('lis-qe-sync-desc');
      btn.textContent = '⏳ 同步中...';
      btn.disabled = true;
      const res = await qePushGatewayConfig({ config: cfg });
      btn.disabled = false;
      if (res && res.ok) {
        btn.textContent = '✅ 已同步网关';
        btn.classList.add('saved');
        if (desc) {
          const timeStr = new Date().toTimeString().substring(0, 5);
          desc.innerHTML = `<span style="color:#059669;font-weight:700">☁️ 已同步网关机（${timeStr} 全科室已共享）</span>`;
        }
        toast('质控批号与操作者已保存至网关机，科室所有电脑已同步共享！', 's', 3000);
      } else {
        btn.textContent = '💾 已保存在本机';
        btn.classList.add('saved');
        if (desc) {
          desc.innerHTML = `<span style="color:#d97706">⚠️ 网关离线，已保存在本机</span>`;
        }
        toast('网关机未响应，配置已暂存本机。网关恢复后可重新保存同步。', 'w', 3500);
      }
      setTimeout(() => {
        btn.textContent = '💾 保存并同步网关';
        btn.classList.remove('saved');
      }, 2500);
    });

    // 从网关读取最新配置
    const pullBtn = document.getElementById('lis-qe-pull');
    if (pullBtn) {
      pullBtn.addEventListener('click', async () => {
        pullBtn.textContent = '⏳ 读取中...';
        pullBtn.disabled = true;
        const data = await qeFetchGatewayConfig();
        pullBtn.disabled = false;
        pullBtn.textContent = '☁️ 从网关读取';
        const desc = document.getElementById('lis-qe-sync-desc');
        if (data && data.config) {
          qePopulateInputs(data.config);
          qeSaveConfig({ ...data.config, _updated_at: data.updated_at || Date.now() });
          if (data.mappings) {
            qeSaveMappings(data.mappings);
            qeShowMappingInfo(data.mappings);
          }
          const ts = data.updated_at ? new Date(data.updated_at) : new Date();
          const timeStr = `${String(ts.getMonth() + 1).padStart(2, '0')}-${String(ts.getDate()).padStart(2, '0')} ${String(ts.getHours()).padStart(2, '0')}:${String(ts.getMinutes()).padStart(2, '0')}`;
          if (desc) {
            desc.innerHTML = `<span style="color:#0284c7;font-weight:700">☁️ 已从网关加载配置（更新于 ${timeStr}）</span>`;
          }
          toast('已成功从网关机拉取最新质控配置！', 's', 2500);
        } else {
          toast('网关机暂无共享配置或未连接', 'i', 2500);
        }
      });
    }

    // 检测映射
    document.getElementById('lis-qe-detect').addEventListener('click', async () => {
      qeSetStatus('正在检测项目映射...', 'info');
      document.getElementById('lis-qe-detect').disabled = true;
      qeAbortFlag = false;
      _qeAbortCtrl = new AbortController(); // 8.9.0: 独立检测也要能被「停止」中断在途请求
      const _detectCtrl = _qeAbortCtrl; // 8.10.0: 记住本次操作自己的控制器
      try {
        const mappings = await qeDetectMappings(qeSetStatus);
        qeSaveMappings(mappings);
        qeShowMappingInfo(mappings);
        qePushGatewayConfig({ mappings }).catch(() => {});
      } catch (e) {
        qeSetStatus('检测失败: ' + e.message, 'error');
      }
      // 8.10.0: 仅当仍是本次操作的控制器才置空——检测进行中启动导出时，
      // 导出新建的控制器不能被检测收尾误清（否则导出的「停止」失效、在途请求不可中断）
      if (_qeAbortCtrl === _detectCtrl) {_qeAbortCtrl = null;}
      document.getElementById('lis-qe-detect').disabled = false;
    });

    // 开始导出
    document.getElementById('lis-qe-export').addEventListener('click', () => qeStartExport());
    document.getElementById('lis-qe-cancel').addEventListener('click', () => {
      qeAbortFlag = true;
      if (_qeAbortCtrl) {_qeAbortCtrl.abort();} // 8.9.0: 同时 abort 在途请求，不再等超时
      qeSetStatus('正在停止...', 'info');
    });

    // ESC 关闭
    panel.addEventListener('keydown', e => {
      if (e.key === 'Escape') {
        e.stopPropagation();
        e.stopImmediatePropagation();
        panel.classList.remove('show');
      }
    });

    // 加载已有映射信息
    const savedMap = qeLoadMappings();
    if (Object.keys(savedMap).length > 1) {qeShowMappingInfo(savedMap);}

    // 8.10.24: 初次创建面板时，异步从网关机拉取最新质控配置并自动填充
    qeSyncFromGatewayOnOpen();
  }

  function qeSetStatus(text, type) {
    const el = document.getElementById('lis-qe-status');
    if (!el) {return;}
    el.textContent = text || '';
    el.classList.remove('ok', 'error', 'info');
    if (type) {el.classList.add(type);}
  }

  function qeShowMappingInfo(mappings) {
    const el = document.getElementById('lis-qe-mapinfo');
    if (!el) {return;}
    const total = QE_GROUPS.reduce((s, g) => s + g.projects.length, 0);
    const found = qeMappingCount(mappings);
    const meta = mappings._meta;
    const groupStats = QE_GROUPS.map(g => {
      const n = g.projects.filter(p => mappings[p.code]).length;
      return `${g.name} ${n}/${g.projects.length}`;
    }).join('　');
    const missing = [];
    QE_GROUPS.forEach(g => {
      g.projects.forEach(p => {
        if (!mappings[p.code]) {missing.push(g.name + '/' + p.name);}
      });
    });
    const metaHint =
      meta && meta.year && meta.month
        ? `<br><span style="font-size:10px;color:#607d8b">映射月份: ${meta.year}-${String(meta.month).padStart(2, '0')}</span>`
        : '';
    el.innerHTML =
      `已匹配 <b>${found}/${total}</b> 个项目${metaHint}<br><span style="font-size:10px;color:#607d8b">${groupStats}</span>` +
      (missing.length ? `<br>未匹配: ${missing.join('、')}` : '<br>✅ 全部匹配');
  }

  // 从 UI 收集配置
  function qeCollectConfig() {
    const panel = document.getElementById('lis-qe-panel');
    if (!panel) {return {};}
    const cfg = {};

    // 月份
    const monthInput = document.getElementById('lis-qe-month');
    if (monthInput && monthInput.value) {
      const parts = monthInput.value.split('-');
      cfg._year = parseInt(parts[0], 10);
      cfg._month = parseInt(parts[1], 10);
      if (isNaN(cfg._year) || isNaN(cfg._month) || cfg._month < 1 || cfg._month > 12) {
        cfg._year = 0;
        cfg._month = 0;
      }
    }

    // 选中的组
    cfg.selectedGroups = Array.from(panel.querySelectorAll('.qe-gcheck:checked')).map(c => c.value);

    // 批号
    cfg.lots = {};
    panel.querySelectorAll('.qe-lot-input').forEach(input => {
      const gid = input.dataset.group;
      const type = input.dataset.type;
      const code = input.dataset.code;
      const val = input.value.trim();
      if (!cfg.lots[gid]) {cfg.lots[gid] = {};}
      if (type === 'baseLot') {cfg.lots[gid].baseLot = val;}
      else if (type === 'lot0') {
        if (!cfg.lots[gid].lots) {cfg.lots[gid].lots = [];}
        cfg.lots[gid].lots[0] = val;
      } else if (type === 'lot1') {
        if (!cfg.lots[gid].lots) {cfg.lots[gid].lots = [];}
        cfg.lots[gid].lots[1] = val;
      } else if (type === 'lot') {cfg.lots[gid].lot = val;}
      else if (type === 'coag_main') {cfg.lots[gid]._main = val;}
      else if (type === 'coag_dimer') {cfg.lots[gid]._dimer = val;}
      else if (type === 'proj' && code) {cfg.lots[gid][code] = val;}
    });

    // 操作者
    cfg.operators = {};
    panel.querySelectorAll('.qe-op-input').forEach(input => {
      const ids = (input.dataset.ids || '').split(',');
      ids.forEach(id => {
        if (id) {cfg.operators[id] = input.value.trim();}
      });
    });

    return cfg;
  }

  // 显示进度
  function qeShowProgress(current, total, text) {
    const prog = document.getElementById('lis-qe-progress');
    const bar = document.getElementById('lis-qe-pbar');
    const ptxt = document.getElementById('lis-qe-ptext');
    if (prog) {prog.classList.add('show');}
    if (bar) {bar.style.width = (total > 0 ? (current / total) * 100 : 0) + '%';}
    if (ptxt) {ptxt.textContent = text || `${current}/${total}`;}
  }
  function qeHideProgress() {
    const prog = document.getElementById('lis-qe-progress');
    if (prog) {prog.classList.remove('show');}
  }

  // 主导出流程
  async function qeStartExport() {
    if (qeExporting) {return;}

    const cfg = qeCollectConfig();
    if (!cfg._year || !cfg._month) {
      qeSetStatus('请选择有效的导出月份。', 'error');
      return;
    }
    if (!cfg.selectedGroups || !cfg.selectedGroups.length) {
      qeSetStatus('请至少选择一个导出项目。', 'error');
      return;
    }
    // 8.16.18: 操作者必填校验——各组不再内置默认姓名（公开仓库不带个人信息），
    // 改由用户在「批号和操作者设置」里填写。只校验本次要导出的组，避免生成一列空白的操作者。
    const _missOp = QE_GROUPS.filter(g => cfg.selectedGroups.includes(g.id) && !qeGetOperator(cfg, g));
    if (_missOp.length) {
      qeSetStatus('请先在「批号和操作者设置」里填写操作者：' + _missOp.map(g => g.name).join('、'), 'error');
      const _firstOp = document.querySelector('.qe-op-input');
      if (_firstOp) {
        try {_firstOp.scrollIntoView({ block: 'center' });} catch (e) {}
        try {_firstOp.focus();} catch (e) {}
      }
      return;
    }

    // 8.5.82: 守卫与按钮禁用前移到任何 await 之前——此前「重新检测映射」的长 await 窗口内
    // 再次点击可并发启动第二路导出、检测按钮也未禁用；先结束的一方 finally 复位守卫后守卫彻底失效
    qeExporting = true;
    qeAbortFlag = false;
    _qeAbortCtrl = new AbortController(); // 8.9.0
    const _exportCtrl = _qeAbortCtrl; // 8.10.0: 与检测收尾对称——只清自己的控制器
    _qeLevelFailures = []; // 8.5.82
    _qeQueryFailures = []; // 8.9.0
    const exportBtn = document.getElementById('lis-qe-export');
    const cancelBtn = document.getElementById('lis-qe-cancel');
    const detectBtn = document.getElementById('lis-qe-detect');
    if (exportBtn) {exportBtn.disabled = true;}
    if (cancelBtn) {cancelBtn.style.display = '';}
    if (detectBtn) {detectBtn.disabled = true;}

    try {
      // 保存配置并后台同步到网关机
      qeSaveConfig(cfg);
      qePushGatewayConfig({ config: cfg }).catch(() => {});

      let mappings = qeLoadMappings();
      // 映射逻辑版本不符(或缓存为空)时自动重新检测，确保用最新的 qeMatchScore 匹配，
      // 避免旧缓存里错误的 testCodeDR(如 FT3/TT3 指向同一条)被复用导致导出数据错乱
      if (!qeMappingCount(mappings) || !mappings._meta || mappings._meta.logicVersion !== QE_MAP_LOGIC_VERSION) {
        qeSetStatus('质控项目映射已更新，正在重新检测（仅需一次）...', 'info');
        try {
          mappings = await qeDetectMappings(qeSetStatus);
          qeSaveMappings(mappings);
          qeShowMappingInfo(mappings);
          qePushGatewayConfig({ mappings }).catch(() => {});
        } catch (e) {
          qeSetStatus('重新检测映射失败: ' + e.message + '（可手动点"检测映射"）', 'error');
          return;
        }
        if (!qeMappingCount(mappings)) {
          qeSetStatus('未检测到任何质控项目映射，请检查仪器配置后点"检测映射"。', 'error');
          return;
        }
      }
      const mapMeta = mappings._meta;
      if (mapMeta && cfg._year && cfg._month && (mapMeta.year !== cfg._year || mapMeta.month !== cfg._month)) {
        qeSetStatus(
          `⚠️ 映射为 ${mapMeta.year}-${String(mapMeta.month).padStart(2, '0')} 月检测，导出 ${cfg._year}-${String(cfg._month).padStart(2, '0')} 月；血常规/尿常规会自动切换有数据的质控物，其他组若当月项目编码有变可能导出空数据，建议先点「检测映射」`,
          'error'
        );
      }

      qeLastExportFiles = [];
      qeUpdateZipButton();

      const resultSection = document.getElementById('lis-qe-result-section');
      const resultList = document.getElementById('lis-qe-results');
      const auditSection = document.getElementById('lis-qe-audit-section');
      if (resultSection) {resultSection.style.display = '';}
      if (resultList) {resultList.innerHTML = '';}
      if (auditSection) {auditSection.innerHTML = '';}

      const groupsToExport = QE_GROUPS.filter(g => cfg.selectedGroups.includes(g.id));
      const totalGroups = groupsToExport.length;
      const results = [];
      const allExportViolations = []; // 8.10.31: 质控出控全局汇总

      // SheetJS：@require 可能失败，导出前兜底补拉（8.8.35 起主源科室 nginx，兜底本机 serve）
      qeSetStatus('正在加载 Excel 组件…', 'info');
      if (!(await qeEnsureXlsx())) {
        qeSetStatus(
          'SheetJS 未加载：请先确认科室 nginx 在线（192.168.31.111:9111），或在 Mac 上运行  python3 ~/脚本/serve.py  / Windows 双击 start_serve.bat，再刷新本页重试。',
          'error'
        );
        return;
      }

      for (let gi = 0; gi < totalGroups; gi++) {
        if (qeAbortFlag) {break;}
        const group = groupsToExport[gi];
        qeSetStatus(`正在导出 ${group.name} (${gi + 1}/${totalGroups})...`, 'info');
        qeShowProgress(gi, totalGroups, `${group.name} (${gi + 1}/${totalGroups})`);

        try {
          const groupRes = await qeFetchGroupData(group, cfg, mappings, qeSetStatus);
          const rows = groupRes.rows || groupRes;
          const groupViolations = groupRes.violations || [];
          if (groupViolations.length > 0) {
            allExportViolations.push(...groupViolations);
          }

          if (rows.length > 0) {
            const xlsxData = qeBuildXlsx(group.name, rows);
            const blob = new Blob([xlsxData], {
              type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
            });
            results.push({ name: group.file, blob, rows: rows.length, violations: groupViolations });
            qeAddResultItem(group.file, rows.length, blob, null, groupViolations);
            const lossCnt = groupViolations.filter(v => v.severity === 'loss').length;
            const lossHint = lossCnt > 0 ? ` (🔴 ${lossCnt}项失控)` : '';
            qeSetStatus(`${group.name}: 导出完成，${rows.length} 行数据${lossHint}`, lossCnt > 0 ? 'error' : 'ok');
          } else {
            qeSetStatus(`${group.name}: 无数据`, 'info');
            qeAddResultItem(group.file, 0, null, null, groupViolations);
          }
        } catch (e) {
          qeSetStatus(`${group.name}: 导出失败 - ${e.message}`, 'error');
          qeAddResultItem(group.file, 0, null, e.message);
        }
      }

      qeLastExportFiles = results.slice();
      qeUpdateZipButton();
      qeShowProgress(totalGroups, totalGroups, '完成');

      // 8.10.31: 渲染 Westgard 质控出控智能核查报告
      const curYear = cfg._year || new Date().getFullYear();
      const curMonth = cfg._month || new Date().getMonth() + 1;
      qeRenderQCAuditReport(allExportViolations, curYear, curMonth, totalGroups, results.length);

      if (!qeAbortFlag) {
        const zipHint = results.length ? ' 可点右上角「打包下载 ZIP」。' : '';
        // 8.5.82: 拉取失败的水平统一提示——此前单水平超时整月数据静默缺失，文件却显示「导出完成」
        // 8.9.0: 基础查询失败（项目列表/机器参数/质控物列表）一并提示——吞成空数组会让整组项目
        // 假装「本月没做质控」，实际是网络故障
        const _allQeFails = _qeLevelFailures.concat(_qeQueryFailures);
        const failHint = _allQeFails.length
          ? ` ⚠️ 有 ${_allQeFails.length} 项查询失败（${_allQeFails.slice(0, 5).join('、')}${_allQeFails.length > 5 ? ' 等' : ''}），对应数据可能不完整，建议重导`
          : '';
        const lossTotal = allExportViolations.filter(v => v.severity === 'loss').length;
        const warnTotal = allExportViolations.filter(v => v.severity === 'warn').length;
        const auditHint = lossTotal > 0
          ? ` ⚠️ 发现 ${lossTotal} 项失控（详见下方排查报告）`
          : (warnTotal > 0 ? ` ⚠️ 发现 ${warnTotal} 项预警（详见下方排查报告）` : ' 🛡️ 质控均在控');
        qeSetStatus(`导出完成！共 ${results.length}/${totalGroups} 个文件。${auditHint}${failHint}${zipHint}`, (lossTotal > 0 || _allQeFails.length) ? 'error' : 'ok');
      } else {
        qeSetStatus('导出已停止。', 'info');
      }
    } finally {
      qeExporting = false;
      qeAbortFlag = false;
      if (_qeAbortCtrl === _exportCtrl) {_qeAbortCtrl = null;} // 8.10.0: 防止误清其它操作的控制器
      try {
        qeHideProgress();
      } catch (e) {}
      if (exportBtn) {exportBtn.disabled = false;}
      if (cancelBtn) {cancelBtn.style.display = 'none';}
      if (detectBtn) {detectBtn.disabled = false;}
    }
  }

  function qeAddResultItem(filename, rowCount, blob, error, groupViolations) {
    const list = document.getElementById('lis-qe-results');
    if (!list) {return;}
    const div = document.createElement('div');
    div.className = 'qe-result-item';
    let statusHtml = '';
    let btnHtml = '';
    let violationHtml = '';
    if (error) {
      statusHtml = `<span class="qe-ri-status err">❌ ${esc(error)}</span>`;
    } else if (rowCount > 0) {
      statusHtml = `<span class="qe-ri-status ok">✅ ${rowCount} 行</span>`;
      if (blob) {
        btnHtml = `<button data-fn="${esc(filename)}">下载</button>`;
      }
      if (groupViolations && groupViolations.length > 0) {
        const lossCnt = groupViolations.filter(v => v.severity === 'loss').length;
        const warnCnt = groupViolations.filter(v => v.severity === 'warn').length;
        if (lossCnt > 0) {
          violationHtml = `<span class="qe-violation-badge err" title="包含 ${lossCnt} 项失控结果">🔴 ${lossCnt} 项失控</span>`;
        } else if (warnCnt > 0) {
          violationHtml = `<span class="qe-violation-badge warn" title="包含 ${warnCnt} 项预警结果">🟡 ${warnCnt} 项预警</span>`;
        }
      } else {
        violationHtml = '<span class="qe-violation-badge ok" title="质控在控">🟢 在控</span>';
      }
    } else {
      statusHtml = '<span class="qe-ri-status" style="color:#9e9e9e">无数据</span>';
    }
    div.innerHTML = `<span class="qe-ri-name">${esc(filename)}</span>${violationHtml}${statusHtml}${btnHtml}`;
    if (btnHtml) {
      const dlBtn = div.querySelector('button');
      dlBtn._blob = blob;
      dlBtn.addEventListener('click', () => {
        qeDownloadBlob(blob, filename);
      });
    }
    list.appendChild(div);
  }

  // --- 初始化 ---
  function initQEExport() {
    if (qeInited) {return;}
    qeInited = true;
    qeCreateFab();
    qeCreatePanel();
    dbg('[LIS-QE] 质控数据导出模块已加载');
  }

  let qeProbeTimer = null;
  function startQEProbe() {
    if (qeProbeTimer) {return;}
    const probe = () => {
      const fab = document.getElementById('lis-qe-fab');
      if (!qeInited) {initQEExport();}
      if (fab) {fab.style.display = 'flex';}
    };
    probe();
    qeProbeTimer = setInterval(probe, 2000);
  }

  // ============================================================
  //  模块 C：一体化工作台（核心）
  // ============================================================
  let wsData = []; // 加载的标本数据
  // 8.9.0: 本地已审核移除、但可能仍出现在在途旧快照里的 ReportDR。
  // 30s tick/阶段2 请求发出后才审核成功 → applyResults 用 T0 快照整体覆盖 wsData 会把
  // 已审标本“复活”（幽灵卡，甚至被自动审核二次复审）。applyResults 据此过滤；
  // 条目在全量快照确认服务端也不再返回后才清除。
  const _wsLocalRemoved = new Set();

  // 8.9.4: 批审成功后同步内存行状态为已审——批审期间 WS 周期刷新已停止，条目 requeue 重试时
  // 「Status=3 跳过」检查读的是批审开始时的旧 wsData，拦不住对已审标本的再次 ReportSave
  function markSpecimenAuditedInMem(reportDR) {
    try {
      const r = wsData.find(x => String(x.ReportDR) === String(reportDR));
      if (r) {
        r.Status = '3';
        r.ReportStatus = '3';
        // 8.10.0: 改数据必失效缓存（8.9.0 epoch 机制）——此前只改内存行，
        // _filteredCache/_countsCache 键未变，批审期间任何走缓存的渲染/计数
        // 仍会把该标本算进待审
        invalidateCaches();
      }
    } catch (e) {}
  }
  let wsMachines = []; // 当前加载的仪器列表
  let wsActiveMachine = ''; // 当前选中的仪器 DR, ''=全部
  let wsActiveWG = ''; // 当前选中的工作组 DR, ''=全部工作组
  let wsSelectedMachinesByWG = {}; // {工作组DR: [仪器DR]}，空数组/无记录=该工作组全部仪器
  let wsCategory = 'audit'; // 当前分类: 'audit'(待审,融合正常+异常)/'incomplete'/'pending'/'collected'/'all'
  let wsClassifiedCache = {}; // 分类缓存 {[reportDR]: {status, items, row, reportDR}}
  const _CLASSIFIED_CACHE_MAX = 1000;
  let wsClassifying = false; // 分类进行中标记
  let wsAbnormalIndex = -1; // 异常视图当前焦点索引
  const wsChecked = new Set(); // 选中的 ReportDR 集合
  const wsSort = { field: 'AcceptDT', asc: false };
  let wsTimer = null;
  let _authTimer = null;
  let _batchScanTimer = null;
  let wsSearchQuery = '';
  let wsLoading = false;
  let wsMachineCounts = {}; // { machineDR: {total, normalReady, abnormalReady, incomplete} }
  // 8.11.8: 详情抽屉打开期间被推迟的整表重建（关闭抽屉时补渲染，避免列表长期停在旧数据快照）
  let _wsRenderDeferred = false;
  // 8.11.8: 右栏实时检视器（Live Inspector）专用状态——
  // 检视器与详情抽屉是两个并行渲染目标，此前共用 _detailLoadSeq 会互相作废对方的加载
  //（详情抽屉永久卡在「正在加载结果...」的根因）。此处拆出独立序号。
  let _inspLoadSeq = 0;
  // 右栏当前已渲染出结果的分类代数（配合 #lis-insp-body[data-rdr] 判断可否跳过重建）
  let _inspShownVersion = -1;
  // 整表重建（renderWSTable 会 body.innerHTML 清空右栏）前承接的右栏内容。
  // 30s 自动刷新走的就是整表重建路径，若不承接，右栏每半分钟闪回「正在加载结果...」
  // 并丢失滚动位置，审阅长结果集（生化几十项）时被反复打断。
  let _inspCarry = null;
  // 正在审核中的标本 ReportDR（精确到条，替代以前「有任一审核在跑」的粗判）
  let _abnormalAuditingDR = '';

  // --- 性能优化：缓存 ---
  const _detailLRU = new Map(); // 详情结果 LRU 缓存，最多 50 条
  const _DETAIL_LRU_MAX = 50;
  let _filteredCache = null; // filteredData() 结果缓存
  let _filteredCacheKey = ''; // 缓存键
  let _countsCache = null; // 统一计数缓存
  let _wsDataEpoch = 0; // 8.9.0: 数据代数，invalidateCaches 时递增，作统一计数缓存键
  let _countsCacheKey = ''; // 计数缓存键
  let _classifyRawCache = {}; // 分类时的原始 API 响应缓存，供详情面板复用
  let _classifyVersion = 0; // 分类结果版本，驱动过滤缓存失效
  let _wsLoadSeq = 0; // 工作台加载序号，防止旧请求覆盖新刷新
  let _classifyRunSeq = 0; // 分类运行序号，防止旧分类任务影响新刷新
  let _classifyPendingRerun = false; // 分类进行中又有新数据时，结束后再跑一轮
  let _lastWSNonEmptyAt = 0; // 最近一次成功加载到标本的时间，用于强制刷新兜底
  let _wsLoadedDate = ''; // 8.5.42: 工作台数据对应的日期（查询窗口结束日），跨天时允许清空重载
  let wsActiveDate = ''; // 8.7.0: 工作台查看日期（''=今天，'YYYY-MM-DD'=历史日期），支持查看/审核过去日期的标本
  let _wsDataHealth = { lastFullSuccessAt: 0, failed: false, partial: false }; // 自动审核数据健康状态
  let _wsFullLoadFailStreak = 0; // 8.6.3: 全量加载连续失败/返回空的次数（成功应用后清零）
  // 8.6.3: 连续失败升级提醒——失败时只有左上角小字一闪而过（30s 一轮），会话过期挂一整晚没人注意；
  // 连续 10 次（约 5 分钟）toast 一次提示旧数据 + 重新登录，成功后自动清零（toast 只弹一次不刷屏）
  function _noteWSLoadFailure() {
    _wsFullLoadFailStreak++;
    if (_wsFullLoadFailStreak === 10) {
      showToast('工作台已连续约 5 分钟刷新失败（当前显示的是旧数据）。可能 LIS 登录会话已过期，请重新登录或刷新页面', 'warning');
    }
  }
  let _normalKeyHandler = null; // 普通视图键盘监听
  let _abnormalFocusDR = '';
  let _wsSearchTimer = null;
  const _tabId = 'tab_' + Date.now() + '_' + Math.random().toString(36).slice(2, 10);

  function specimenFingerprint(row) {
    if (!row) {return '';}
    return [
      row.ReportDR,
      row.Status || row.ReportStatus,
      row.IsComplete,
      row.NoResRows,
      row.AcceptDT,
      row.TransmitDate,
      row._mdr,
      row._pending ? '1' : '0'
    ]
      .map(v => String(v || ''))
      .join('|');
  }

  function isClassificationStale(row) {
    if (!row || !row.ReportDR) {return true;}
    const cached = wsClassifiedCache[row.ReportDR];
    if (!cached) {return true;}
    const fp = specimenFingerprint(row);
    if (cached.fingerprint !== fp) {return true;}
    const age = Date.now() - (cached._classifiedAt || cached._accessTs || 0);
    // 8.10.23: 手工录入标本若尚未录入完整（缺项或未录入），缓存有效期缩短为 20 秒，
    // 以便检验人员在 LIS 保存录入结果后，点击刷新或定时刷新能迅速拉取最新明细并升入「待审」
    if (cached.isManual && !cached.isManualComplete) {
      return age > 20000;
    }
    return age > CLASSIFY_STALE_MS;
  }

  function pruneStaleClassificationCache(newData) {
    const newMap = new Map((newData || []).map(r => [String(r.ReportDR), specimenFingerprint(r)]));
    let changed = false;
    for (const dr of Object.keys(wsClassifiedCache)) {
      if (!newMap.has(dr)) {
        delete wsClassifiedCache[dr];
        changed = true;
        continue;
      }
      const cached = wsClassifiedCache[dr];
      const fp = newMap.get(dr);
      if (cached.fingerprint !== fp) {
        delete wsClassifiedCache[dr];
        changed = true;
      }
    }
    if (changed) {_classifyVersion++;}
    return changed;
  }

  function attachClassificationMeta(result, row) {
    if (!result || !row) {return result;}
    result.fingerprint = specimenFingerprint(row);
    result._classifiedAt = Date.now();
    result.row = row;
    return result;
  }

  function invalidateCaches(options = {}) {
    _filteredCache = null;
    _filteredCacheKey = '';
    _countsCache = null;
    _countsCacheKey = '';
    _wsDataEpoch++; // 8.9.0: 数据/忽略状态代数——统一计数缓存键的一部分
    if (options.detail) {_detailLRU.clear();}
    if (options.raw) {_classifyRawCache = {};}
  }

  function normalizeWSMachineFilterState(raw) {
    const out = {};
    if (!raw || typeof raw !== 'object') {return out;}
    Object.keys(raw).forEach(wg => {
      const arr = Array.isArray(raw[wg]) ? raw[wg] : [];
      const selected = [...new Set(arr.map(v => String(v || '')).filter(Boolean))];
      if (selected.length) {out[String(wg)] = selected;}
    });
    return out;
  }

  function getWSSelectedMachineSet(wg) {
    const key = String(wg || '');
    if (!key) {return new Set();}
    return new Set((wsSelectedMachinesByWG[key] || []).map(String).filter(Boolean));
  }

  function setWSSelectedMachineSet(wg, set) {
    const key = String(wg || '');
    if (!key) {return;}
    const arr = [...set].map(String).filter(Boolean);
    if (arr.length) {wsSelectedMachinesByWG[key] = arr;}
    else {delete wsSelectedMachinesByWG[key];}
  }

  function wsMachineFilterSetForActiveWG() {
    return wsActiveWG ? getWSSelectedMachineSet(wsActiveWG) : new Set();
  }

  // 8.7.0: 当前查看日期（''=今天）
  function wsViewDate() {
    return wsActiveDate || today();
  }

  // 8.7.0: 工作台查询日期窗口 [起始日, 结束日]
  //  - 历史日期查看（wsActiveDate）：严格单日查询 [wsActiveDate, wsActiveDate]，绝不混入今天或其它日期
  //  - 今天（默认）：单日 [today(), today()]；若自动审核在运行且开启日早于今天，回溯到开启日（跨午夜未审标本）
  function getWSQueryRange() {
    const end = today();
    // 8.8.10: 用户主动查看历史日期时，严格按该单日查询，决不向后扩展到今天
    if (wsActiveDate && wsActiveDate !== end) {
      return [wsActiveDate, wsActiveDate];
    }
    let start = wsViewDate();
    if (start > end) {start = end;} // 未来日期钳制为今天
    if (autoAuditEnabled()) {
      const sd = String((_autoAudit && _autoAudit.startDate) || '');
      // 仅当查看今天、且自动审核「开启日」比今天早时，才向回扩展查询窗口以覆盖跨午夜未审标本
      if (sd && sd < start) {
        const minStart = addDays(end, -7);
        start = sd < minStart ? minStart : sd;
      }
      return [start, end];
    }
    return [start, start];
  }

  // 8.7.0: 头部日期控件标签
  function wsDateLabel(dateStr) {
    const td = today();
    if (!dateStr || dateStr === td) {return '今天';}
    if (dateStr === addDays(td, -1)) {return '昨天';}
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
    if (m) {return m[2] + '-' + m[3];}
    return dateStr;
  }

  // 8.8.0: 只更新头部日期胶囊显示（不重建整个头部，避免搜索框内容丢失）
  function updateWSDateControls() {
    const pill = document.getElementById('lis-ws-date-pill');
    if (!pill) {return;}
    const v = wsViewDate();
    const td = today();
    const label = document.getElementById('lis-ws-date-label');
    if (label) {label.textContent = wsDateLabel(v);}
    pill.classList.toggle('past', !!wsActiveDate);
    const mainBtn = document.getElementById('lis-ws-date-btn');
    if (mainBtn) {
      mainBtn.title = wsActiveDate
        ? '正在查看历史日期 ' + wsActiveDate + '，点击弹出日历改选日期'
        : '点击弹出日历选择日期（可查看/审核历史标本）';
    }
    const nextBtn = document.getElementById('lis-ws-date-next');
    if (nextBtn) {nextBtn.disabled = v >= td;}
    // 8.8.3: 「今」按钮——查看历史日期时显示（回到今天后隐藏，因为已经是今天）；
    // 8.8.4: 并入胶囊内区段，胶囊自身 .past 琥珀高亮即可，按钮不再单独加类
    const todayBtn = document.getElementById('lis-ws-date-today');
    if (todayBtn) {todayBtn.style.display = wsActiveDate ? '' : 'none';}
    // 日历弹层开着时同步：前一天/后一天步进后选中态与月份跟随
    if (document.getElementById('lis-ws-date-picker')) {wsDatePickerRender();}
  }

  // 8.7.0: 切换工作台查看日期（''=今天）；作废在飞请求与缓存后按新日期强制重载。
  // 空结果保护对「主动切日期」不适用：先清空 wsData，让新日期的空数据如实显示（不留旧日期假数据）。
  async function setWSActiveDate(dateStr) {
    let d = String(dateStr || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) {d = '';}
    if (d > today()) {d = '';} // 不允许未来日期，回今天
    if (d === wsActiveDate) {updateWSDateControls(); return;}
    wsActiveDate = d;
    // 8.8.5: 同步日历弹层年/月状态，保证跨月步进时日历跟随后续月份渲染
    const curV = wsViewDate();
    const curM = /^(\d{4})-(\d{2})/.exec(curV);
    if (curM && _wsDatePickerState) {
      _wsDatePickerState.y = Number(curM[1]);
      _wsDatePickerState.m = Number(curM[2]);
    }
    saveWSState();
    _wsLoadSeq++;
    wsLoading = false;
    wsClassifying = false;
    _classifyPendingRerun = false;
    _classifyRunSeq++;
    wsClassifiedCache = {};
    _classifyVersion++;
    wsChecked.clear();
    wsAbnormalIndex = -1;
    invalidateCaches({ detail: true, raw: true });
    wsData = [];
    updateWSDateControls();
    // 8.8.11: 从历史视图切回今天时，把被审核切走的原生日期框一并恢复今天（与查看日保持一致）；
    // 切到历史日期时 restoreNativeDateboxToday 内部守卫会跳过（原生页停在查看日是符合预期的）
    restoreNativeDateboxToday();
    renderWSTable();
    renderWSCategoryBar();
    setWSStatusNote('加载 ' + wsViewDate() + ' 数据中...');
    try {
      await loadWSData({ force: true });
      showToast('已切换到 ' + (wsActiveDate ? wsActiveDate : '今天') + '：共 ' + wsData.length + ' 条', 'info');
    } catch (e) {
      dbg('切换日期加载数据失败:', e);
    }
  }

  // 8.8.0: 工作台日历弹层（自绘，Safari 无 showPicker 也能稳定弹日历）
  let _wsDatePickerState = null; // 弹层当前展示的年月 {y, m}
  let _wsDatePickerCleanup = null;

  function wsCloseDatePicker() {
    const p = document.getElementById('lis-ws-date-picker');
    if (p) {p.remove();}
    if (_wsDatePickerCleanup) {
      _wsDatePickerCleanup();
      _wsDatePickerCleanup = null;
    }
    _wsDatePickerState = null;
  }

  // 重建弹层内容并重新绑定事件；由月份切换 / 前一天·后一天步进后调用
  function wsDatePickerRender() {
    const picker = document.getElementById('lis-ws-date-picker');
    if (!picker || !_wsDatePickerState) {return;}
    const st = _wsDatePickerState;
    const viewYear = st.y;
    const viewMonth = st.m;
    const sel = wsViewDate();
    const td = today();
    const minYear = Math.min(2020, new Date().getFullYear() - 5, viewYear - 2);
    const maxYear = Math.max(new Date().getFullYear() + 1, viewYear + 2);
    const years = [];
    for (let y = minYear; y <= maxYear; y += 1) {
      years.push(`<option value="${y}"${y === viewYear ? ' selected' : ''}>${y}年</option>`);
    }
    const months = [];
    for (let m = 1; m <= 12; m += 1) {
      months.push(`<option value="${m}"${m === viewMonth ? ' selected' : ''}>${m}月</option>`);
    }
    const firstDay = new Date(viewYear, viewMonth - 1, 1).getDay();
    const count = new Date(viewYear, viewMonth, 0).getDate();
    const days = [];
    for (let i = 0; i < firstDay; i += 1) {days.push('<button type="button" class="blank" tabindex="-1"></button>');}
    for (let d = 1; d <= count; d += 1) {
      const value = viewYear + '-' + String(viewMonth).padStart(2, '0') + '-' + String(d).padStart(2, '0');
      let cls = '';
      if (value === sel) {cls += ' on';}
      if (value === td) {cls += ' today';}
      const isFuture = value > td;
      if (isFuture) {cls += ' future';}
      days.push(`<button type="button" data-date="${value}" class="${cls.trim()}"${isFuture ? ' disabled' : ''}>${d}</button>`);
    }
    picker.innerHTML = `
      <div class="ws-dp-head">
        <select class="ws-dp-year">${years.join('')}</select>
        <select class="ws-dp-month">${months.join('')}</select>
        <button type="button" class="ws-dp-today">今天</button>
      </div>
      <div class="ws-dp-week"><span>日</span><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span></div>
      <div class="ws-dp-days">${days.join('')}</div>
      <div class="ws-dp-foot">
        <button type="button" id="ws-dp-prevday">◀ 前一天</button>
        <button type="button" id="ws-dp-nextday"${wsViewDate() >= td ? ' disabled' : ''}>后一天 ▶</button>
      </div>`;
    picker.querySelector('.ws-dp-year').addEventListener('change', e => {
      st.y = Number(e.target.value);
      wsDatePickerRender();
    });
    picker.querySelector('.ws-dp-month').addEventListener('change', e => {
      st.m = Number(e.target.value);
      wsDatePickerRender();
    });
    picker.querySelector('.ws-dp-today').addEventListener('click', e => {
      e.stopPropagation();
      wsCloseDatePicker();
      setWSActiveDate('');
    });
    picker.querySelectorAll('.ws-dp-days button[data-date]').forEach(btn => {
      btn.addEventListener('click', e => {
        e.stopPropagation();
        const d = btn.dataset.date;
        if (d > td) {return;}
        wsCloseDatePicker();
        setWSActiveDate(d);
      });
    });
    picker.querySelector('#ws-dp-prevday').addEventListener('click', e => {
      e.stopPropagation();
      setWSActiveDate(addDays(wsViewDate(), -1)); // 弹层保持打开，选中态/月份由 updateWSDateControls 同步
    });
    picker.querySelector('#ws-dp-nextday').addEventListener('click', e => {
      e.stopPropagation();
      if (wsViewDate() >= td) {return;}
      setWSActiveDate(addDays(wsViewDate(), 1)); // 未来日期会被钳制回今天
    });
  }

  function wsOpenDatePicker() {
    wsCloseDatePicker();
    const base = wsViewDate();
    const m = /^(\d{4})-(\d{2})/.exec(base);
    const now = new Date();
    _wsDatePickerState = {
      y: m ? Number(m[1]) : now.getFullYear(),
      m: m ? Number(m[2]) : now.getMonth() + 1
    };
    const picker = document.createElement('div');
    picker.id = 'lis-ws-date-picker';
    document.body.appendChild(picker);
    wsDatePickerRender();
    const anchor = document.getElementById('lis-ws-date-pill');
    const rect = anchor ? anchor.getBoundingClientRect() : { left: 0, bottom: 0 };
    picker.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - picker.offsetWidth - 8)) + 'px';
    picker.style.top = Math.max(8, Math.min(rect.bottom + 4, window.innerHeight - picker.offsetHeight - 8)) + 'px';
    const closeOnOutside = e => {
      const t = e.target;
      if (t && t.closest && t.closest('#lis-ws-date-picker, #lis-ws-date-pill')) {return;}
      wsCloseDatePicker();
    };
    const closeOnEsc = e => {
      if (e.key === 'Escape') {wsCloseDatePicker();}
    };
    _wsDatePickerCleanup = () => {
      document.removeEventListener('mousedown', closeOnOutside, true);
      document.removeEventListener('keydown', closeOnEsc, true);
    };
    // 打开瞬间的 mousedown 已发生在注册之前，直接挂监听即可
    document.addEventListener('mousedown', closeOnOutside, true);
    document.addEventListener('keydown', closeOnEsc, true);
  }

  function rowPassWSMachineFilter(row) {
    if (!row) {return false;}
    if (wsActiveWG && row._wg !== wsActiveWG) {return false;}
    if (wsActiveWG) {
      // 单工作组模式：检查该组的多选仪器
      const selected = getWSSelectedMachineSet(wsActiveWG);
      if (selected.size > 0) {return selected.has(String(row._mdr || prWorkGroupMachineDR(row) || ''));}
    } else {
      // 全部工作组模式：只要有任何组勾选了仪器，就只显示被勾选的（含外送组）
      const anySelected = WS_WG.some(w => getWSSelectedMachineSet(w.dr).size > 0);
      if (anySelected) {
        const wgSelected = getWSSelectedMachineSet(row._wg || '');
        return wgSelected.size > 0 && wgSelected.has(String(row._mdr || prWorkGroupMachineDR(row) || ''));
      }
      // 所有组都没勾选 = 全部仪器通过
    }
    if (wsActiveMachine) {return String(row._mdr || prWorkGroupMachineDR(row) || '') === String(wsActiveMachine);}
    return true;
  }

  // 8.5.67: 自动审核范围快照 —— 开启自动审核那一刻固定工作组+勾选仪器，之后勾选变化不影响
  function captureAuditScopeSnapshot() {
    const byWG = {};
    Object.keys(wsSelectedMachinesByWG).forEach(k => {
      const arr = (wsSelectedMachinesByWG[k] || []).map(String).filter(Boolean);
      if (arr.length) {byWG[String(k)] = arr;}
    });
    const machines = wsMachines.map(m => ({ wg: String(m._wg || ''), dr: String(m.RowID || ''), name: m.CName || m.Name || '' }));
    return { wg: wsActiveWG || '', machine: wsActiveMachine || '', byWG, machines, capturedAt: Date.now(), user: uname() || uid() };
  }
  // 快照过滤：语义与 rowPassWSMachineFilter 一致，但读开启时固定的快照（无快照回退动态，兼容旧数据）
  function rowPassAuditSnapshot(row) {
    if (!row) {return false;}
    const scope = _autoAudit && _autoAudit.scope;
    if (!scope) {return rowPassWSMachineFilter(row);}
    const mdr = String(row._mdr || prWorkGroupMachineDR(row) || '');
    if (scope.wg) {
      // 单工作组：非该组 → 否；该组勾选为空 = 该组全选
      if (row._wg !== scope.wg) {return false;}
      const sel = new Set((scope.byWG && scope.byWG[scope.wg]) || []);
      return sel.size > 0 ? sel.has(mdr) : true;
    }
    // 全部工作组模式（含外送组）
    const anySelected = WS_WG.some(w => ((scope.byWG && scope.byWG[w.dr]) || []).length > 0);
    if (anySelected) {
      const wgSel = new Set((scope.byWG && scope.byWG[row._wg || '']) || []);
      return wgSel.size > 0 && wgSel.has(mdr);
    }
    if (scope.machine) {return mdr === String(scope.machine);}
    return true;
  }

  // 8.10.23: 手工录入标本识别与完整性判断（H900 电解质分析仪、手工杂项等）：
  // 这类仪器无双向通信程序将 LIS 的 IsComplete 置为 1，结果靠检验人员在界面手工填写并保存。
  const MANUAL_ENTRY_MACHINE_REGEX = /h[-_]?900|电解质|手工|杂项|manual/i;
  const AUTOMATED_MACHINE_REGEX = /生化分析仪|全自动|血细胞|血球|血常规|凝血|化学发光|dxi|maglumi|getein|wan200|sysmex|mindray/i;

  function isManualEntrySpecimen(row) {
    if (!row) {return false;}
    let name = String(row._mn || row.MachineName || row.machineName || '').trim();
    if (!name) {
      const mdr = String(row._mdr || prWorkGroupMachineDR(row) || '');
      if (mdr) {
        const m = (wsMachines || []).find(x => String(x.RowID) === mdr);
        if (m) {name = String(m.CName || m.Name || '').trim();}
      }
    }
    // 8.10.25: H900 明确属于手工录入仪器（即使注册设备名含「全自动」也无双向通讯置IsComplete=1，优先判定）
    if (name && /h[-_]?900/i.test(name)) {return true;}
    // 明确属于全自动仪器时，即使项目叫电解质也不是手工录入（如生化仪做电解质）
    if (name && AUTOMATED_MACHINE_REGEX.test(name)) {return false;}
    if (name && MANUAL_ENTRY_MACHINE_REGEX.test(name)) {return true;}
    const ts = String(row.TestSetDesc || row.ItemDesc || '').trim();
    if (ts && /手工|杂项/.test(ts)) {return true;}
    if (ts && /电解质|血锂|锂/.test(ts) && (!name || /h[-_]?900|电解质/i.test(name))) {return true;}
    return false;
  }

  function isSpecimenActuallyComplete(row, cached = null) {
    if (!row) {return false;}
    const complete = String(row.IsComplete || '');
    if (complete === '1') {return true;}
    if (isManualEntrySpecimen(row)) {
      const c = cached || wsClassifiedCache[row.ReportDR];
      if (c && c.isManualComplete) {return true;}
    }
    return false;
  }

  // 8.17.9: 结果完整度判定——**所有「能不能审」的完整度闸门都必须走这里**，返回 {ok, missing, reason}。
  // 为什么单独抽出来：此前完整度判定散在四处（getWSAuditBucket / continueAuditQueue 逐条复核 /
  // auditAbnormalSpecimen / 详情面板），而且**只返回布尔**——拦下之后现场只看到「结果不完整」四个字，
  // 不知道缺几项、也不知道是哪一种不完整，没法判断该不该人工补审（现场「缺了三个项目竟然审掉了」
  // 这条反馈里，最缺的就是这个可诊断性）。
  // LIS 字段口径（用 cache/ 里真实 QryWorkList 响应核过：IsComplete='1' 81 条 / '0' 32 条 / '2' 27 条）：
  //   IsComplete='1' → 完整（NoResRows 为空）
  //   IsComplete='2' → 部分结果，NoResRows = **还缺几项**
  //   IsComplete='0' → 无结果，   NoResRows = **该组合项目的项目总数**
  // 手工录入仪器（H900/手工杂项）LIS 不置 IsComplete=1，走项级判定（8.10.23）。
  function specimenCompleteness(row, cached = null) {
    if (!row) {return {ok: false, missing: 0, reason: '标本已不在工作台数据中（可能已审核/已取消/超出查询范围）'};}
    if (isSpecimenActuallyComplete(row, cached)) {return {ok: true, missing: 0, reason: ''};}
    const ic = String(row.IsComplete === undefined || row.IsComplete === null ? '' : row.IsComplete);
    const n = parseInt(String(row.NoResRows || ''), 10);
    const missing = Number.isFinite(n) && n > 0 ? n : 0;
    if (isManualEntrySpecimen(row)) {return {ok: false, missing, reason: '手工录入项目未录全'};}
    if (ic === '2') {return {ok: false, missing, reason: '结果不完整（缺 ' + (missing || '若干') + ' 项）'};}
    if (ic === '0') {return {ok: false, missing, reason: '无结果（应做 ' + (missing || '若干') + ' 项）'};}
    return {ok: false, missing, reason: '完整度未知（IsComplete=' + (ic || '空') + '）'};
  }

  // 8.17.11: 「组合项目 → 应有项数」——**观察模式**（只记不拦）。
  // 为什么需要：8.17.9 那类「LIS 自己把 IsComplete 说成 1、实际缺 3 项」的情况，脚本侧唯一能查的信号
  // 就是「这个组合项目该有几项，现在只有几项」。而 LIS 恰好会告诉我们这个数：
  //   IsComplete='0'（无结果）时，NoResRows = **该组合项目的项目总数**（已用 cache/ 真实响应核过：
  //   血常规 24 / 血细胞分析+网织红 31 / 短疗巡诊肿标一体检 3 …）。
  // 所以：从这类行里学出应有项数（取历史最大值 + 记观测次数），审核时把「应有/实测/差几项」一起写进
  // 审核留痕。**先只记录、只提示，不拦截**——「减项开单」的组合项目会造成误拦，等攒够现场数据
  // （留痕里能看到它到底能不能抓到真问题、会不会误报）再决定是否升级成硬拦。
  function expectedItemsLoad() {
    try {
      const o = JSON.parse(localStorage.getItem(K.expectedItems) || '{}');
      return o && typeof o === 'object' && !Array.isArray(o) ? o : {};
    } catch (e) {
      return {};
    }
  }
  // 从一批工作列表行里学「组合项目 → 应有项数」（只认 IsComplete='0' 且 NoResRows 为正整数）
  function expectedItemsLearn(rows) {
    try {
      if (!Array.isArray(rows) || !rows.length) {return;}
      const map = expectedItemsLoad();
      let changed = false;
      rows.forEach(r => {
        if (!r) {return;}
        if (String(r.IsComplete === undefined || r.IsComplete === null ? '' : r.IsComplete) !== '0') {return;}
        const desc = String(r.TestSetDesc || '').trim();
        if (!desc) {return;}
        const n = parseInt(String(r.NoResRows || ''), 10);
        if (!Number.isFinite(n) || n <= 0) {return;}
        const cur = map[desc] && typeof map[desc] === 'object' ? map[desc] : {n: 0, k: 0};
        const nextN = Math.max(Number(cur.n) || 0, n);
        const nextK = (Number(cur.k) || 0) + 1;
        if (nextN !== cur.n || nextK !== cur.k) {
          map[desc] = {n: nextN, k: nextK};
          changed = true;
        }
      });
      if (changed) {localStorage.setItem(K.expectedItems, JSON.stringify(map));}
    } catch (e) {}
  }
  // 观察模式判定：{exp 应有, act 实测, short 差几项, seen 观测次数}；拿不到实测或没学到过 → 全 0
  function expectedItemsCheck(row) {
    const out = {exp: 0, act: 0, short: 0, seen: 0};
    try {
      if (!row) {return out;}
      const desc = String(row.TestSetDesc || '').trim();
      if (!desc) {return out;}
      const e = expectedItemsLoad()[desc];
      if (!e) {return out;}
      out.exp = Number(e.n) > 0 ? Number(e.n) : 0;
      out.seen = Number(e.k) || 0;
      const c = wsClassifiedCache[row.ReportDR];
      out.act = c && Array.isArray(c.items) ? c.items.length : 0;
      if (out.exp > 0 && out.act > 0 && out.act < out.exp) {out.short = out.exp - out.act;}
    } catch (e) {}
    return out;
  }
  try {
    if (typeof unsafeWindow !== 'undefined') {
      unsafeWindow.lisExpectedItems = () => {
        try {
          const m = expectedItemsLoad();
          const rows = Object.keys(m).map(k => ({组合项目: k, 应有项数: m[k].n, 观测次数: m[k].k}));
          if (console.table) {console.table(rows);} else {console.log(rows);}
          return rows;
        } catch (e) {
          return [];
        }
      };
    }
  } catch (e) {}

  // 8.17.10: 审核留痕——每次「脚本真的把标本审掉了」都记一条：**审核那一刻**看到的完整度快照 + 走的哪条路径。
  // 为什么必须记：8.17.9 现场那条（检验号 26091800246）的结果补全后就永远看不出当时的状态了——
  // Mac 上没有 LIS 数据、脚本当时也没留痕，只能靠回忆。有了这条留痕，下次同类问题能直接回答
  // 「审核那一刻 LIS 说它完整吗」：
  //   ic='1'（LIS 说完整）+ 事后不完整  → **LIS 侧把完整度判错了**（脚本无信号可查，需要「应有项数」对照）
  //   ic='2'/'0' 或 verdict 非空       → **闸门被绕过 / 用的是过期数据**（脚本侧的问题）
  const AUDIT_TRACE_MAX = 800;
  function auditTraceAdd(entry) {
    try {
      const e = entry || {};
      const dr = String(e.dr || '');
      if (!dr) {return;}
      const now = new Date();
      const day =
        now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0') + '-' + String(now.getDate()).padStart(2, '0');
      let log = [];
      try {log = JSON.parse(localStorage.getItem(K.auditTrace) || '[]');} catch (err) {log = [];}
      if (!Array.isArray(log)) {log = [];}
      log.push({
        day,
        t: now.toTimeString().slice(0, 8),
        dr,
        labno: String(e.labno || ''),
        pat: String(e.pat || ''),
        mn: String(e.mn || ''),
        path: String(e.path || ''),
        ic: e.ic === undefined || e.ic === null ? '' : String(e.ic),
        nrr: e.nrr === undefined || e.nrr === null ? '' : String(e.nrr),
        verdict: String(e.verdict || ''),
        // 8.17.11: 观察模式字段（应有项数 / 实测项数 / 差几项 / 观测次数）
        exp: Number(e.exp) || 0,
        act: Number(e.act) || 0,
        short: Number(e.short) || 0,
        seen: Number(e.seen) || 0
      });
      if (log.length > AUDIT_TRACE_MAX) {log = log.slice(log.length - AUDIT_TRACE_MAX);}
      try {localStorage.setItem(K.auditTrace, JSON.stringify(log));} catch (err) {}
    } catch (e) {}
  }
  // 8.17.10: 审核那一刻的完整度快照（写进留痕、也挂到队列条目上供「审核后自检」定性）
  function auditTraceSnapshot(row) {
    const ic = row ? String(row.IsComplete === undefined || row.IsComplete === null ? '' : row.IsComplete) : '';
    const nrr = row ? String(row.NoResRows || '') : '';
    let verdict = '';
    try {
      verdict = specimenCompleteness(row, row ? wsClassifiedCache[row.ReportDR] : null).reason || '';
    } catch (e) {}
    // 8.17.11: 观察模式——把「应有/实测/差几项」也记进留痕。
    // 这样下次再出现「事后才发现缺项」时，留痕能直接回答：审核那一刻项数对得上吗？
    // 对得上 → LIS 侧把完整度判错了；对不上 → 应有项数核对本来就能抓到（该升级成硬拦）。
    let expItems = {exp: 0, act: 0, short: 0, seen: 0};
    try {expItems = expectedItemsCheck(row);} catch (e) {}
    return {ic, nrr, verdict, exp: expItems.exp, act: expItems.act, short: expItems.short, seen: expItems.seen};
  }
  // 8.17.10: 现场诊断入口——F12 控制台执行 lisAuditTrace()（全部）或 lisAuditTrace('26091800246')（按检验号）
  function auditTraceRead(filter) {
    let rows = [];
    try {
      const log = JSON.parse(localStorage.getItem(K.auditTrace) || '[]');
      const f = String(filter || '');
      rows = Array.isArray(log)
        ? log.filter(
            r =>
              !f ||
              String(r.labno || '').includes(f) ||
              String(r.dr || '') === f ||
              String(r.pat || '').includes(f)
          )
        : [];
    } catch (e) {}
    try {
      if (console.table) {console.table(rows);} else {console.log(rows);}
    } catch (e) {}
    return rows;
  }
  try {
    if (typeof unsafeWindow !== 'undefined') {
      unsafeWindow.lisAuditTrace = auditTraceRead;
      unsafeWindow.lisAuditTraceRaw = () => {
        try {return JSON.parse(localStorage.getItem(K.auditTrace) || '[]');} catch (e) {return [];}
      };
    }
  } catch (e) {}

  // 8.10.2: 自动审核仪器黑名单——「手工杂项」与手工录入仪器（H900等）永不自动审核。
  // 理由：这类仪器下的标本靠人填写，LIS 不置 IsComplete=1 的居多，
  // 即使录入完整也绝不该由无人值守机器人代签。与勾选范围无关：即使快照是「全部工作组全部仪器」也一律排除。
  // 判定优先用行上的仪器名 _mn（loadWSData 已附加），缺失时回退 wsMachines 里按 _mdr 查名字。
  function rowAutoAuditMachineAllowed(row) {
    if (!row) {return false;}
    if (isManualEntrySpecimen(row)) {return false;}
    let name = String(row._mn || row.MachineName || row.machineName || '').trim();
    if (!name) {
      const mdr = String(row._mdr || prWorkGroupMachineDR(row) || '');
      if (mdr) {
        const m = (wsMachines || []).find(x => String(x.RowID) === mdr);
        if (m) {name = String(m.CName || m.Name || '').trim();}
      }
    }
    if (!name) {return true;} // 名字取不到不误杀（漏排一台好过整组不审）
    return !AUTO_AUDIT_EXCLUDE_MACHINE_NAMES.test(name);
  }
  // 8.10.2: 自动审核候选统一闸门——忽略列表 + 范围快照 + 手工杂项黑名单，三处候选过滤共用
  function rowIsAutoAuditCandidate(row) {
    if (!row) {return false;}
    if (isWSIgnored(row.ReportDR)) {return false;}
    if (!rowPassAuditSnapshot(row)) {return false;}
    return rowAutoAuditMachineAllowed(row);
  }

  const DETAIL_LRU_TTL = 5 * 60 * 1000; // 8.5.82: 详情缓存有效期——标本结果被仪器重传/复检修正后，重开详情不能再看旧 HTML
  function detailLRUGet(key) {
    if (_detailLRU.has(key)) {
      const v = _detailLRU.get(key);
      _detailLRU.delete(key);
      // 8.5.82: 过期即弃（此前 ts 写了从不校验，会话级永久有效）
      if (v && v.ts && Date.now() - v.ts > DETAIL_LRU_TTL) {
        return null;
      }
      _detailLRU.set(key, v);
      return v;
    }
    return null;
  }
  function detailLRUHas(key) {
    return _detailLRU.has(key);
  }

  function detailLRUSet(key, val) {
    if (_detailLRU.has(key)) {_detailLRU.delete(key);}
    if (_detailLRU.size >= _DETAIL_LRU_MAX) {
      const first = _detailLRU.keys().next().value;
      _detailLRU.delete(first);
    }
    _detailLRU.set(key, val);
  }
  // 8.15.10: 整表作废——放行范围改动后必须调用。详情 HTML 里含「该项能否批审」的配色与结论，
  // 缓存命中会直接注入旧 HTML（loadDetailResults 的 LRU 快路径），不清理就永远显示旧规则的结果。
  function detailLRUClear() {_detailLRU.clear();}

  const WS_CATEGORIES = ['audit', 'incomplete', 'pending', 'collected', 'all'];

  function saveWSState() {
    try {
      localStorage.setItem(
        K.wsState,
        JSON.stringify({
          wg: wsActiveWG,
          cat: wsCategory,
          mdr: wsActiveMachine,
          multiMdr: wsSelectedMachinesByWG,
          date: wsActiveDate // 8.7.0: 记住查看日期（刷新页面后接着看历史视图）
        })
      );
    } catch (e) { dbg('saveWSState 失败:', e.message); }
  }

  function loadWSState() {
    const fallback = { wg: wgDR() || '', cat: 'audit', mdr: '' };
    try {
      const saved = JSON.parse(localStorage.getItem(K.wsState) || '{}');
      const wg = Object.prototype.hasOwnProperty.call(saved, 'wg') ? String(saved.wg) : fallback.wg;
      // 旧版 normal/abnormal 分类已合并为 audit（待审），老状态自动归一
      const cat = WS_CATEGORIES.includes(saved.cat)
        ? saved.cat
        : saved.cat === 'normal' || saved.cat === 'abnormal'
          ? 'audit'
          : fallback.cat;
      const mdr = Object.prototype.hasOwnProperty.call(saved, 'mdr') ? String(saved.mdr) : fallback.mdr;
      const multiMdr = saved.multiMdr && typeof saved.multiMdr === 'object' ? saved.multiMdr : {};
      // 8.7.0: 恢复查看日期——只接受合法的过去日期，未来/非法一律回今天
      let date = /^\d{4}-\d{2}-\d{2}$/.test(String(saved.date || '')) ? String(saved.date) : '';
      if (date > today()) {date = '';}
      return { wg, cat, mdr, multiMdr, date };
    } catch (e) {
      return fallback;
    }
  }

  function applyWSState(state) {
    wsActiveWG = state.wg;
    wsCategory = state.cat;
    wsActiveMachine = state.mdr;
    wsSelectedMachinesByWG = normalizeWSMachineFilterState(state.multiMdr || {});
    wsActiveDate = state.date || ''; // 8.7.0: 恢复查看日期
    // 8.17.0: 恢复出的「外送组 + 待审/不完整」组合是死路（外送恒为空）——归一到「待排」，
    // 避免重开工作台停在一个永远空白的分类上（与工作组标签点击时的归一逻辑一致）
    if (isExternalWSWorkGroup(wsActiveWG) && (wsCategory === 'audit' || wsCategory === 'incomplete')) {
      wsCategory = 'pending';
    }
    if (wsActiveWG && wsActiveMachine && !getWSSelectedMachineSet(wsActiveWG).size) {
      setWSSelectedMachineSet(wsActiveWG, new Set([String(wsActiveMachine)]));
      wsActiveMachine = '';
    }
  }

  function normalizeWSMachineSelection(loadedWGs) {
    const byWG = {};
    Object.keys(wsSelectedMachinesByWG || {}).forEach(wg => {
      // 该组机器列表没成功加载（网络瞬断返回空）时不清理，保留原勾选等下一轮再验
      if (loadedWGs && loadedWGs.size && !loadedWGs.has(String(wg))) {
        byWG[wg] = wsSelectedMachinesByWG[wg];
        return;
      }
      const valid = new Set(wsMachines.filter(m => String(m._wg || '') === String(wg)).map(m => String(m.RowID || '')));
      const selected = (wsSelectedMachinesByWG[wg] || []).map(String).filter(mdr => valid.has(mdr));
      if (selected.length) {byWG[wg] = [...new Set(selected)];}
    });
    wsSelectedMachinesByWG = byWG;
    if (wsActiveMachine) {
      const ok = wsMachines.some(
        m => String(m.RowID) === String(wsActiveMachine) && (!wsActiveWG || m._wg === wsActiveWG)
      );
      if (!ok) {wsActiveMachine = '';}
    }
  }

  // 打开工作台
  function openWS() {
    // 防重入：如果已打开，不做任何操作
    const wsEl = $('#lis-ws');
    if (!wsEl) {return;}
    if (wsEl.classList.contains('show')) {
      dbg('[WS] openWS 被调用但已打开，跳过');
      return;
    }
    dbg('[WS] openWS 被调用');
    if (DEBUG) {console.trace('[WS] openWS 调用栈');}
    wsMarkUserClosed(false); // 8.16.11: 用户（或用户发起的流程）主动打开 → 解除「别再自动拉回来」标记

    applyWSState(loadWSState());
    _abnormalPrewarmDR = '';
    _abnormalNativeReadyDR = '';
    wsClassifiedCache = {};
    _classifyVersion++;
    wsClassifying = false;
    wsLoading = false; // 重置加载状态，防止上次 closeWS 时 loadWSData 还在运行
    _wsLoadSeq++; // 作废关闭前可能仍在飞行的 loadWSData
    wsAbnormalIndex = -1;
    wsChecked.clear();
    wsData = [];
    wsMachines = [];
    wsMachineCounts = {};
    _tabsBuilt = false;
    _catBarBuilt = false;
    _wsRenderDeferred = false; // 8.11.8: 重开工作台时清掉可能残留的延迟渲染标记
    invalidateCaches({ detail: true, raw: true });
    wsEl.classList.add('show');
    // 强制 flex 布局（LIS 系统 CSS 会覆盖）
    wsEl.style.cssText =
      'display:flex!important;flex-direction:column!important;height:100vh!important;overflow:hidden!important;position:fixed!important;inset:0!important;z-index:100000!important';
    document.body.style.overflow = 'hidden';
    resetWSSearch(); // 8.11.10: 头部 build-once 后搜索词不再随重建消失，重开时显式清空
    renderWSHeader();
    renderWSTabs();
    renderWSCategoryBar();
    renderWSTable();
    updateWSFooter();
    _installF4Bridge(); // 常驻 F4 桥，独立于异常视图处理器生命周期
    loadWSData().then(() => {
      if (wsCategory === 'audit') {prefetchAbnormalAuditContext();}
    });
    startWSRefresh();
    if (wsCategory === 'audit') {prefetchReportPageForWS();}
    resumeAutoAuditIfActive(); // 8.5.58: 自动审核状态持久化，重开工作台自动恢复
  }

  function closeWS() {
    const wsEl = $('#lis-ws');
    if (!wsEl) {return;}
    if (!wsEl.classList.contains('show')) {
      dbg('[WS] closeWS 被调用但未打开，跳过');
      return;
    }
    saveWSState();
    dbg('[WS] closeWS 被调用');
    if (DEBUG) {console.trace('[WS] closeWS 调用栈');}
    // 8.16.11: 记下「是用户主动离开工作台」。自动审核的保活（keepWorkbenchOnTop）会看这个标记，
    // 不再把正在看原始 LIS 的用户强行拉回工作台；用户自己再点开（openWS）即解除。
    wsMarkUserClosed(true);
    wsEl.classList.remove('show');
    wsEl.style.cssText = 'display:none!important';
    document.body.style.overflow = '';
    stopWSRefresh();
    closeDetailPanel(true); // 关闭详情面板，避免工作台关闭后详情面板残留
    restoreNativeDateboxToday(); // 8.8.2: 工作台关闭兜底——原生日期框若被历史审核切走过，恢复今天
    wsCloseDatePicker(); // 8.8.11: 日历弹层挂在 body 上，关工作台必须一并收起，否则悬浮残留
    closeWSMachPopovers(); // 收起仪器下拉浮层
    updateAbnormalEnterBridge();
    // 清理键盘监听器
    _removeAbnormalKeyHandler();
    _removeF4BridgeHandler(); // 清理 F4 桥，防止事件监听器泄漏
    if (_normalKeyHandler) {
      document.removeEventListener('keydown', _normalKeyHandler);
      _normalKeyHandler = null;
    }
    _removeDetailKeyHandler();
    clearTimeout(_abnormalPrewarmTimer);
    _abnormalPrewarmTimer = null;
    if (_detailPrewarmTimer) {
      clearTimeout(_detailPrewarmTimer);
      _detailPrewarmTimer = null;
    }
    clearMachineCache(); // 关闭工作台时清理仪器缓存，避免内存只增不减
    wsLoading = false; // 重置加载状态，防止下次 openWS 被阻塞
    _wsLoadSeq++; // 作废关闭时仍在飞行的 loadWSData
  }

  function findWSSpecimenByReportDR(reportDR) {
    const target = String(reportDR || '');
    if (!target) {return null;}
    const fromFiltered = filteredData().find(r => String(r.ReportDR || '') === target);
    if (fromFiltered) {return fromFiltered;}
    return wsData.find(r => String(r.ReportDR || '') === target) || null;
  }

  let _wsDataRowMap = null;
  let _wsDataRowMapEpoch = -1;
  function getWSDataRowMap() {
    if (!_wsDataRowMap || _wsDataRowMapEpoch !== _wsDataEpoch) {
      _wsDataRowMap = new Map();
      (wsData || []).forEach(r => {
        if (r && r.ReportDR) {_wsDataRowMap.set(String(r.ReportDR), r);}
      });
      _wsDataRowMapEpoch = _wsDataEpoch;
    }
    return _wsDataRowMap;
  }

  function resolveQueueItemRow(item) {
    if (!item || !item.reportDR) {return null;}
    const map = getWSDataRowMap();
    return map.get(String(item.reportDR)) || null;
  }

  let _queueLockToken = ''; // 8.5.82: 本队列实例的锁 token——refresh/release 必须校验，防同标签旧循环误续期/误删新循环的锁
  // 8.16.31: 成功时返回**本次获取的 token**（失败返回 ''，空串为假值，`if (!token)` 判定语义不变）。
  // 调用方必须把 token 传给 releaseQueueLock —— 否则两轮循环共用同一个模块变量时，
  // 旧循环的 finally 会拿被新循环覆盖过的 token 去比，代际保护形同虚设。
  function acquireQueueLock() {
    try {
      const raw = localStorage.getItem(K.auditQueueLock);
      if (raw) {
        const lock = JSON.parse(raw);
        if (lock.owner !== _tabId && Date.now() - (lock.ts || 0) < AUDIT_QUEUE_LOCK_TTL) {return '';}
      }
      const token = Math.random().toString(36).slice(2);
      localStorage.setItem(K.auditQueueLock, JSON.stringify({ owner: _tabId, token, ts: Date.now() }));
      const check = JSON.parse(localStorage.getItem(K.auditQueueLock) || '{}');
      if (check.owner === _tabId && check.token === token) {_queueLockToken = token; return token;}
      return '';
    } catch (e) {
      // 无法可靠读写锁时宁可不自动审核，避免双标签页并发审核
      return '';
    }
  }

  function refreshQueueLock() {
    try {
      // 8.5.82: 只续期自己 token 的锁——同标签旧循环（已被代际强停但仍卡在 CA 等待）不得覆盖新循环的锁
      const lock = JSON.parse(localStorage.getItem(K.auditQueueLock) || 'null');
      if (lock && lock.owner === _tabId && (lock.token === undefined || lock.token === _queueLockToken)) {
        lock.ts = Date.now();
        localStorage.setItem(K.auditQueueLock, JSON.stringify(lock));
      }
    } catch (e) {}
  }

  // token 可选：传入 = 释放本次循环持有的那一代锁（推荐，代际保护完整）；
  // 不传 = 沿用模块内当前 token（仅 pagehide 这类「本页持有的锁一律释放」的场景使用）。
  function releaseQueueLock(token) {
    const myToken = token !== undefined ? String(token || '') : _queueLockToken;
    try {
      const raw = localStorage.getItem(K.auditQueueLock);
      if (raw) {
        const lock = JSON.parse(raw);
        // 8.5.82: 校验 token——旧循环的 finally 不得删掉新循环刚获得的锁（token 缺失视为旧版锁，owner 匹配即删）
        if (lock.owner === _tabId && lock.token !== undefined && myToken && lock.token !== myToken) {
          // 锁已换代（新循环持有）→ 既不动锁，也不动 token
        } else if (lock.owner === _tabId && (lock.token === undefined || lock.token === myToken)) {
          localStorage.removeItem(K.auditQueueLock);
        }
      }
    } catch (e) {}
    // 8.16.31: **必须**作废本次持有的 token。此前不清 → `_queueLockToken` 一直是上次批审的旧值：
    //   ① isScriptOwnedNativeSelection()（18070）恒为真 → canScriptSelectNativeRow 的
    //      「用户手动选行保护」永久失效，用户正在原生页查看的标本会被脚本抢走；
    //   ② 残留 token 与共享变量叠加，会让旧循环误判自己仍持锁，从而删掉/续期新循环的锁。
    // 只有确认没被新循环换代时才清，代际保护不丢。
    if (_queueLockToken && _queueLockToken === myToken) {_queueLockToken = '';}
  }

  // 8.10.5: 自动审核主循环跨标签页主互斥锁（覆盖正常批量+异常逐条全周期，防止双标签页抢选行与审核按钮）
  const AUTO_AUDIT_TICK_LOCK_TTL = 45000;
  let _aaTickLockToken = '';
  function acquireAutoAuditTickLock() {
    try {
      const raw = localStorage.getItem(K.autoAuditTickLock);
      if (raw) {
        const lock = JSON.parse(raw);
        if (lock.owner !== _tabId && Date.now() - (lock.ts || 0) < AUTO_AUDIT_TICK_LOCK_TTL) {return false;}
      }
      const token = Math.random().toString(36).slice(2);
      localStorage.setItem(K.autoAuditTickLock, JSON.stringify({ owner: _tabId, token, ts: Date.now() }));
      const check = JSON.parse(localStorage.getItem(K.autoAuditTickLock) || '{}');
      if (check.owner === _tabId && check.token === token) {_aaTickLockToken = token; return true;}
      return false;
    } catch (e) {return false;}
  }
  function refreshAutoAuditTickLock() {
    try {
      const lock = JSON.parse(localStorage.getItem(K.autoAuditTickLock) || 'null');
      if (lock && lock.owner === _tabId && (lock.token === undefined || lock.token === _aaTickLockToken)) {
        lock.ts = Date.now();
        localStorage.setItem(K.autoAuditTickLock, JSON.stringify(lock));
      }
    } catch (e) {}
  }
  function releaseAutoAuditTickLock() {
    try {
      const raw = localStorage.getItem(K.autoAuditTickLock);
      if (!raw) {return;}
      const lock = JSON.parse(raw);
      if (lock.owner === _tabId && (lock.token === undefined || lock.token === _aaTickLockToken)) {
        localStorage.removeItem(K.autoAuditTickLock);
      }
    } catch (e) {}
  }

  // ==================== 8.16.11: 「用户主动离开工作台」标记 ====================
  // 现场：开着自动审核时，回原始 LIS 看东西会被**强行切回工作台**（很烦）。
  // 原因是自动审核每轮都跑 keepWorkbenchOnTop('自动审核') 保活，还有整页刷新后的自动重开。
  // 现在：closeWS() 落这个标记 → 保活/自动重开一律让路；用户自己点开工作台（openWS）即清除。
  // 用 sessionStorage：原始 LIS 内部跳转/刷新后仍然尊重用户「我要待在原始界面」的意愿；
  // 仅本标签页有效，不影响其它标签页。
  const WS_USER_CLOSED_KEY = 'LIS_WS_UserClosed';
  function wsUserClosedWS() {
    try {return sessionStorage.getItem(WS_USER_CLOSED_KEY) === '1';} catch (e) {return false;}
  }
  function wsMarkUserClosed(on) {
    try {
      if (on) {sessionStorage.setItem(WS_USER_CLOSED_KEY, '1');}
      else {sessionStorage.removeItem(WS_USER_CLOSED_KEY);}
    } catch (e) {}
  }

  function isWSVisible() {
    const wsEl = document.getElementById('lis-ws');
    return !!(wsEl && wsEl.classList.contains('show'));
  }

  function keepWorkbenchOnTop(reason) {
    const wsEl = document.getElementById('lis-ws');
    if (!wsEl) {return;}
    // 8.16.11: 用户主动退出过工作台（在看原始 LIS）→ 不强行拉回来。
    // 自动审核走的是 iframe（ensureReportPageLoaded 点「报告处理」链接在子框架里审），
    // **不需要工作台可见**就能继续审，所以让路不影响审核本身。
    if (wsUserClosedWS()) {
      dbg('[WS] 用户已主动退出工作台，跳过保活重开：', reason || '');
      return;
    }
    if (!wsEl.classList.contains('show')) {
      applyWSState(loadWSState());
      invalidateCaches(); // 确保使用最新数据渲染
      // 8.9.2: 与 openWS 同款旗帜重置——renderWSHeader 会重建头部并清空分类栏 DOM，
      // 不重置 _catBarBuilt 会导致分类栏「看起来消失」（自动审核保活重开工作台路径的根因）
      _tabsBuilt = false;
      _catBarBuilt = false;
      wsEl.classList.add('show');
      resetWSSearch(); // 8.11.10: 头部 build-once 后搜索词不再随重建消失，重开时显式清空
      renderWSHeader();
      renderWSTabs();
      renderWSCategoryBar();
      renderWSTable();
      updateWSFooter();
      startWSRefresh();
      if (!wsData.length) {loadWSData();}
    }
    wsEl.style.cssText =
      'display:flex!important;flex-direction:column!important;height:100vh!important;overflow:hidden!important;position:fixed!important;inset:0!important;z-index:100000!important';
    document.body.style.overflow = 'hidden';
    dbg('[WS] 批审保持工作台置顶: ' + (reason || ''));
  }

  function startWSRefresh() {
    stopWSRefresh();
    wsTimer = setInterval(() => loadWSData(), REFRESH);
  }
  function stopWSRefresh() {
    if (wsTimer) {
      clearInterval(wsTimer);
      wsTimer = null;
    }
  }

  // --- 加载数据 ---
  async function loadWSData(options = {}) {
    const force = !!(options && options.force);
    if (wsLoading && !force) {return { skipped: true };}
    // 分类进行中时跳过自动刷新（force 仍可强制），避免 30s 刷新打断分类、
    // 整组重分类永远追不上刷新拖死批审（6456 行注释已意识的同类问题）
    if (wsClassifying && !force) {
      dbg('分类进行中，跳过自动刷新');
      return { skipped: true };
    }
    const seq = ++_wsLoadSeq;
    if (force) {
      wsLoading = false;
      wsClassifying = false;
      _classifyPendingRerun = false;
      _classifyRunSeq++; // 作废进行中的分类写回，避免强制刷新后被旧结果污染
      // 8.6.3: 分类缓存不再在此预清——若 force 加载失败/返回空（空数据保护保留了行数据），
      // 预清已把分类删光，所有标本落「不完整」桶，待审/异常计数全部归 0。
      // 改为 applyResults 成功应用新数据后再清（见下方 wipe-on-success）
      wsChecked.clear();
      wsAbnormalIndex = -1;
      wsMachineCounts = {};
      invalidateCaches();
    }
    try {
      wsLoading = true;
      setWSStatusNote(force ? '强制刷新中...' : '加载中...');
      // 8.16.1: 移除此处的 syncMildRuleOverrides 调用——sync 已有 startup+visibilitychange 两个触发点，
      // 放在 loadWSData 里会在 save→refresh→loadWSData 路径上造成竞态覆盖用户刚保存的数据。

      // 8.7.0: 本次加载的查询日期窗口（平时=选中单日；自动审核运行中=开启日~今天）
      const [qStart, qEnd] = getWSQueryRange();

      async function loadOneWG(w) {
        let machines;
        try {
          machines = await loadMachines(w.dr);
        } catch (e) {
          machines = [];
        }
        const ss = buildSS(w.dr);
        const wgData = [];
        const wgMachines = [];
        const machineResults = await Promise.all(
          machines
            .filter(m => m.RowID)
            .map(async m => {
              const result = { rows: [], pending: [], collected: [], machine: m, ok: true };
              try {
                result.rows = await loadWL(m.RowID, ss, qStart, qEnd); // 8.7.0: 按查询窗口取数
                // 8.8.10: 待排/采集是当天实时排队队列，仅查看今天时拉取；历史日期不混入当天实时待排/采集
                if (!wsActiveDate || wsActiveDate === today()) {
                  [result.pending, result.collected] = await Promise.all([
                    loadPendingForMachine(m.RowID, ss).catch(() => []),
                    loadCollectedForMachine(m.RowID, ss).catch(() => [])
                  ]);
                }
              } catch (e) {
                // 8.5.82: 单台仪器加载失败不再静默吞掉——汇总进健康状态，防该仪器标本从工作台悄悄消失
                result.ok = false;
              }
              return result;
            })
        );
        for (const mr of machineResults) {
          const m = mr.machine;
          mr.rows.forEach(r => {
            r._wg = w.dr;
            r._wgn = w.name;
            r._wgc = w.color;
            r._wgi = w.icon;
            r._mn = m.CName || m.Name || m.RowID;
            r._mdr = m.RowID;
          });
          mr.pending.forEach(r => {
            r._wg = w.dr;
            r._wgn = w.name;
            r._wgc = w.color;
            r._wgi = w.icon;
            r._mn = m.CName || m.Name || m.RowID;
            r._mdr = m.RowID;
          });
          mr.collected.forEach(r => {
            r._wg = w.dr;
            r._wgn = w.name;
            r._wgc = w.color;
            r._wgi = w.icon;
            r._mn = m.CName || m.Name || m.RowID;
            r._mdr = m.RowID;
          });
          wgData.push(...mr.rows, ...mr.pending, ...mr.collected);
          wgMachines.push({ ...m, _wg: w.dr, _wgn: w.name, _wgc: w.color, _wgi: w.icon });
        }
        // machinesOk：机器列表是否成功加载（瞬断返回空时不清理该组勾选，等下一轮再验）
        // 8.5.82: failedMachines 汇总本组加载失败的仪器，供 applyResults 计入数据健康
        const failedMachines = machineResults.filter(mr => !mr.ok).map(mr => mr.machine);
        return { data: wgData, machines: wgMachines, wg: w.dr, machinesOk: machines.length > 0, failedMachines };
      }

      function applyResults(results, partial) {
        let allData = [];
        const allMachines = [];
        const loadedWGs = new Set();
        const failedMachineNames = [];
        for (const r of results) {
          allData.push(...r.data);
          allMachines.push(...r.machines);
          if (r.machinesOk && r.wg) {loadedWGs.add(String(r.wg));}
          // 8.5.82: 组级机器列表失败（machinesOk=false）或单台仪器失败——汇总进健康状态：
          // 宁可让自动审核暂停，不可让该组/该仪器标本静默消失（漏看比慢更危险）。
          // 8.6.3: 去掉 !partial 门槛——partial 阶段 results 只含已加载组，不会把「未加载的组」
          // 误报成失败；保留该门槛反而让「跨天+优先组机器列表失败」绕过下方的空数据保护
          if (!r.machinesOk && r.wg) {failedMachineNames.push((WG_MAP[String(r.wg)] || {}).name + '组机器列表');}
          (r.failedMachines || []).forEach(m => failedMachineNames.push(m.CName || m.Name || String(m.RowID)));
        }

        // 8.8.10: 历史日期视图严格过滤：只保留登记日期与当前查看日期完全一致的标本，决不混入今天或其它日期
        const curTargetDate = wsActiveDate;
        if (curTargetDate && curTargetDate !== today()) {
          const beforeCnt = allData.length;
          allData = allData.filter(r => {
            const d = rowAcceptDateStr(r);
            return !d || d === curTargetDate;
          });
          if (allData.length !== beforeCnt) {
            dbg('[WS] 历史日期', curTargetDate, '过滤剔除非当日标本:', beforeCnt - allData.length, '条');
          }
        }
        // 8.5.40: 空数据保护扩展到 partial 阶段——长时间闲置/会话过期/网络瞬断时，
        // 阶段1(partial)返回空会直接把 wsData 清空、统计全变 0；阶段2 再空时 wsData 已为空
        // 导致保护条件失效。改为：只要「返回空 && 已有数据」就保留旧数据，等下一轮恢复。
        // 8.5.42: 跨天例外——工作台按当天查询（SttAccDate=今天），跨天后昨天的标本在
        // 原生列表已查不到（如 23:50 做的标本），保留旧数据只会显示「看得见审不了」的
        // 假数据。故日期变化时允许清空重载（自动归零到新一天），同一天内的瞬断仍保留。
        // 8.6.3: 跨天例外再加一道门——本次加载存在失败（仪器/组机器列表）时即使跨天也保留旧数据。
        // 否则「午夜跨天 + 会话过期」组合（午夜无人重登，最常见）会让 dateChanged 绕过保护
        // 直接清空归零；只有各组都加载成功、新一天确实没标本时才允许归零。
        // 8.7.0: 对比对象改为本次查询窗口结束日（自动审核跨午夜时窗口含昨天，昨晚标本不会被误清）
        const dateChanged = !!(_wsLoadedDate && _wsLoadedDate !== qEnd);
        if (allData.length === 0 && wsData.length > 0 && (!dateChanged || failedMachineNames.length > 0)) {
          _wsDataHealth.failed = true;
          _wsDataHealth.partial = !!partial;
          dbg('刷新返回空数据，保留原有', wsData.length, '条', partial ? '(partial)' : '', dateChanged ? '(跨天但有加载失败，暂不清空)' : '');
          setWSStatusNote(`刷新失败，保留 ${wsData.length} 条 | ${new Date().toLocaleTimeString()}`);
          // 8.5.40: 强制刷新的警告只在全量阶段判断（partial 阶段空可能是瞬断，阶段2会恢复）
          if (!partial && force) {showToast('工作台强制刷新仍返回空数据，可能需要重新登录或刷新浏览器页面', 'warning');}
          if (!partial) {_noteWSLoadFailure();} // 8.6.3: 连续失败升级提醒
          return false;
        }
        if (!partial) {_wsFullLoadFailStreak = 0;} // 8.6.3: 成功应用全量数据，清零失败计数
        // 8.5.42: 跨天后更新数据日期（无论清空重载还是正常更新，都归到新一天）
        if (dateChanged || allData.length > 0) {_wsLoadedDate = qEnd;}
        // 8.9.0: 剔除刷新期间本地已审核移除的标本，防 T0 旧快照把它们带回来。
        // 注意清除判定看「原始快照」：原始快照仍返回该标本 → 服务端尚未同步，条目保留；
        // 原始快照已没有 → 服务端已更新，条目清掉（避免集合无限增长）。
        if (_wsLocalRemoved.size) {
          // 8.10.0: 本轮存在加载失败的仪器/组时快照本身不完整——失败仪器上刚审完的
          // 标本不在 allData 里，会被「原始快照已没有」误判为服务端已确认而清掉；
          // 下一轮该仪器恢复、服务端状态尚未回写时，旧快照会把标本带回列表（幽灵卡），
          // 甚至可能被自动审核二次复审。此时跳过清理，条目留到下轮完整快照再判定
          if (!partial && failedMachineNames.length === 0) {
            const _serverDRs = new Set(allData.map(r => String(r.ReportDR)));
            for (const dr of _wsLocalRemoved) {
              if (!_serverDRs.has(dr)) {_wsLocalRemoved.delete(dr); continue;}
              // 8.9.4: 服务端快照里该行已是终审状态 → 本地隐藏使命完成，恢复展示（真实已审态，
              // 不会再进待审队列）；否则按日期全状态查询时该行会被隐藏一整天
              const _srow = allData.find(r => String(r.ReportDR) === dr);
              const _sst = String((_srow && (_srow.Status || _srow.ReportStatus)) || '');
              if (_sst === '3' || _sst === '4') {_wsLocalRemoved.delete(dr);}
            }
          }
          const _removedCnt = allData.length;
          allData = allData.filter(r => !_wsLocalRemoved.has(String(r.ReportDR)));
          if (allData.length !== _removedCnt) {dbg('[WS] 剔除刷新期间已本地审核的标本:', _removedCnt - allData.length, '条');}
        }
        // 8.17.0: 外送组入库过滤——只保留「待排/采集」，其余状态（已录入结果/已审/取消）直接丢弃。
        // 放在入库这一层而不是各视图里过滤：这样计数、分类、自动审核「在跑」判定、菜单栏推送
        // 全都天然看不到外送已出结果的标本，不必逐处打补丁。
        if (allData.some(r => isExternalWSWorkGroup(r._wg))) {
          const _extBefore = allData.length;
          allData = allData.filter(r => !isExternalWSWorkGroup(r._wg) || isExternalTrackableRow(r));
          const _extDrop = _extBefore - allData.length;
          if (_extDrop > 0) {dbg('[WS] 外送组剔除已出结果标本:', _extDrop, '条（外送只追踪待排/采集）');}
        }
        // 8.17.11: 顺手学「组合项目 → 应有项数」（观察模式的数据源；只认 IsComplete='0' 且 NoResRows 为正的行）
        try {expectedItemsLearn(allData);} catch (e) {}
        wsData = allData;
        // 8.5.82: 全量阶段存在失败仪器/组 → partial 置位（自动审核闸门暂停，防漏审）且不刷新 lastFullSuccessAt
        const _machinesUnhealthy = !partial && failedMachineNames.length > 0;
        _wsDataHealth.partial = !!partial || _machinesUnhealthy;
        if (!partial) {
          _wsDataHealth.failed = false;
          if (!_machinesUnhealthy) {_wsDataHealth.lastFullSuccessAt = Date.now();}
        }
        if (_machinesUnhealthy) {dbg('部分仪器/工作组加载失败:', failedMachineNames.join(', '));}
        // 8.5.33: 每次数据刷新后自动取消已核收标本的忽略（进入未审核/审核 → 恢复正常计数）
        wsIgnoreAutoRelease(allData);
        wsMachines = allMachines;
        if (wsData.length > 0) {_lastWSNonEmptyAt = Date.now();}
        // 阶段1（partial）只加载了当前工作组，机器列表不全：此时清理勾选会把其他工作组的
        // 多选仪器删掉（全部仪器跨组勾选在自动刷新后只剩一台的 bug）。等全部工作组加载完再清理。
        // 同理 pruneStaleClassificationCache 也不能在 partial 阶段跑：会把其他工作组的分类缓存
        // 当「已消失」删掉，每 30s 刷新就整组重分类，数据量大时分类永远追不上刷新（拖死批审）。
        if (!partial) {
          // 8.6.3: 强制刷新的分类缓存全清移到这里（wipe-on-success）——只有成功应用了新数据
          // 才清；force 加载失败/返回空时行数据被空数据保护保留，分类也一并保留，计数不归 0
          if (force) {
            wsClassifiedCache = {};
            _classifyVersion++;
          }
          normalizeWSMachineSelection(loadedWGs);
          pruneStaleClassificationCache(wsData);
          scheduleAutoAuditCycle(); // 8.5.58: 数据刷新完成后触发自动审核（防抖）
        }
        calcMachineCounts();
        const label = partial ? '优先' : '';
        const warnTag = _machinesUnhealthy ? `⚠${failedMachineNames.length}台加载失败 ` : '';
        setWSStatusNote(`${warnTag}${wsData.length} 条${label} | ${new Date().toLocaleTimeString()}`);
        invalidateCaches({ raw: true, detail: true });
        renderWSTabs();
        renderWSCategoryBar();
        // 8.11.8: 详情抽屉打开时不做整表重建——检验人员正在逐项核对结果决定是否审核，
        // 30s 自动刷新把列表与右栏在手下重建会打断审阅（也是抽屉卡「加载中」的放大因素）。
        // 数据照常更新，关闭抽屉时再补一次渲染（见 closeDetailPanel）。
        if (isDetailPanelVisible()) {
          _wsRenderDeferred = true;
          dbg('详情抽屉打开中，延迟整表重建');
        } else {
          renderWSTable();
        }
        updateWSFooter();
        return true;
      }

      // 8.10.10: 全工作组统一并行拉取，一次性原子渲染——彻底消除分阶段 partial 渲染造成的界面闪烁与跳动
      // 8.17.0: WS_WG = 自检组 + 外送（外送仅一台仪器，多 3 个请求：机器列表 + 工作列表 + 待排/采集）
      const wgResults = await Promise.all(WS_WG.map(w => loadOneWG(w)));
      if (seq !== _wsLoadSeq) {return;}
      if (!isWSVisible()) {return;}
      if (!applyResults(wgResults, false)) {
        return { ok: false, empty: true, preserved: wsData.length > 0 };
      }
      classifyAllSpecimens(seq).catch(e => dbg('分类启动异常:', e));

      if (wsCategory === 'audit') {prefetchAbnormalAuditContext();}
      return { ok: true, count: wsData.length, empty: wsData.length === 0 };
    } catch (e) {
      _wsDataHealth.failed = true;
      _wsDataHealth.partial = false;
      dbg('loadWSData 异常:', e);
      // 8.10.0: qi 是 try 块内的块级变量，catch 里裸引用会抛 ReferenceError，
      // 连带 _noteWSLoadFailure()（8.6.3 失败升级提醒）永远执行不到——改为独立状态写入
      setWSStatusNote('加载失败');
      _noteWSLoadFailure(); // 8.6.3: 连续失败升级提醒（wsData 未动，数字保持旧值）
      return { ok: false, error: e, empty: true };
    } finally {
      if (seq === _wsLoadSeq) {wsLoading = false;}
    }
  }

  // 整页刷新并在加载后自动重新打开工作台（锁屏会话失效时等同浏览器强刷）
  function hardReloadPageForWS(reason) {
    try {
      sessionStorage.setItem(WS_REOPEN_KEY, '1');
      // 记住工作台状态，刷新后恢复
      saveWSState();
    } catch (e) {}
    showToast(reason || '正在刷新页面以恢复会话…', 'warning');
    setTimeout(() => {
      try {
        // 优先强制从服务器重载，避免磁盘缓存的过期页面
        if (typeof location.reload === 'function') {location.reload();}
        else {location.href = location.href;}
      } catch (e) {
        try {
          location.href = location.href;
        } catch (e2) {}
      }
    }, 350);
  }

  // 8.9.2: 自动升级整页刷新的节流阀——LIS 彻底故障时若不限制，会陷入「刷新→断流→再刷新」循环。
  // 5 分钟内最多自动整页刷新一次（用户手点 ↻ 不受限流，那是明确意图）
  const WS_AUTO_RELOAD_KEY = 'LIS_WS_LastAutoReload';
  const WS_AUTO_RELOAD_MIN_MS = 5 * 60 * 1000;
  function autoHardReloadAllowed() {
    try {
      const last = Number(sessionStorage.getItem(WS_AUTO_RELOAD_KEY) || 0);
      if (Date.now() - last < WS_AUTO_RELOAD_MIN_MS) {return false;}
      sessionStorage.setItem(WS_AUTO_RELOAD_KEY, String(Date.now()));
      return true;
    } catch (e) {return true;}
  }

  function maybeReopenWSAfterReload() {
    try {
      if (sessionStorage.getItem(WS_REOPEN_KEY) !== '1') {return;}
      sessionStorage.removeItem(WS_REOPEN_KEY);
    } catch (e) {
      return;
    }
    // 等页面/会话就绪再开工作台
    const tryOpen = n => {
      if (n <= 0) {return;}
      try {
        if (!document.getElementById('lis-ws')) {
          setTimeout(() => tryOpen(n - 1), 400);
          return;
        }
        if (!isWSVisible()) {
          // 8.16.11: 用户主动退出过工作台就不自动重开（否则原始 LIS 里一点刷新就被拉回来）
          if (wsUserClosedWS()) {dbg('[WS] 用户已主动退出工作台，跳过刷新后自动重开');}
          else {openWS();}
        }
        else {loadWSData({ force: true }).catch(() => {});}
      } catch (e) {
        setTimeout(() => tryOpen(n - 1), 400);
      }
    };
    setTimeout(() => tryOpen(15), 600);
  }

  async function forceRefreshWS() {
    dbg('[WS] 强制刷新工作台状态');
    stopWSRefresh();
    clearMachineCache();
    // 8.10.0: 删除已死的 hadData/alreadyEmpty——二者只在被删除的恒真条件下使用
    wsLoading = false;
    wsClassifying = false;
    _classifyRunSeq++; // 先递增序号，确保正在运行的分类任务感知到并中止
    wsClassifiedCache = {};
    _classifyVersion++;
    wsChecked.clear();
    wsAbnormalIndex = -1;
    invalidateCaches({ detail: true, raw: true });
    // 界面立即反馈
    setWSStatusNote('强制刷新中...');
    renderWSTabs();
    renderWSCategoryBar();
    renderWSTable();
    updateWSFooter();
    try {
      const result = await loadWSData({ force: true });
      const err = result && result.error;
      const empty = !result || result.empty || result.count === 0 || wsData.length === 0;
      const errMsg = (err && (err.message || String(err))) || '';
      const sessionDead = /会话|过期|非JSON|HTTP 401|HTTP 403|登录/i.test(errMsg);

      // 软刷新成功拿到数据 → 正常继续
      if (result && result.ok && !empty && !err) {
        // 8.9.2: 「成功」但健康仍是 failed/partial → 拿到的数据不可信（部分仪器失败/数据过期），
        // 正是「点了刷新只报一串黄字警告、计数还是旧的」的场景——整页刷新兜底
        // 8.9.4: ↻ 是用户明确意图，不受自动整页刷新的 5 分钟节流限制
        if (_wsDataHealth.failed || _wsDataHealth.partial) {
          hardReloadPageForWS('刷新后仍有仪器/工作组加载失败，数据可能不是最新，正在整页刷新恢复…');
          return;
        }
        dbg('[WS] 强制刷新成功，条数=', wsData.length);
        showToast('工作台已刷新（' + wsData.length + ' 条）', 'success');
        return;
      }

      // 8.7.0: 历史视图例外——查看过去日期时「空/失败」不代表会话失效（该日本来就可能没标本），
      // 整页刷新兜底不适用，如实提示即可
      if (wsActiveDate) {
        showToast(
          sessionDead
            ? '会话可能已失效，请重新登录后再刷新历史视图'
            : '已刷新 ' + wsActiveDate + '：' + (empty && !err ? '该日期无标本数据' : '加载失败，请稍后重试'),
          empty && !err ? 'info' : 'warning'
        );
        return;
      }

      // 锁屏/会话失效常见：一直 0 或接口失败 → 整页刷新（与浏览器强刷同效果）
      // 8.10.0: 走到这里说明软刷新未拿到可用数据——原「恒真条件」已去除，直接整页刷新
      hardReloadPageForWS(
        sessionDead ? '会话可能已失效，正在刷新页面…' : '工作台数据异常（全 0 或加载失败），正在刷新页面…'
      );
      return;
    } catch (e) {
      dbg('[WS] forceRefreshWS 异常:', e);
      hardReloadPageForWS('刷新异常，正在刷新页面…');
      return;
    } finally {
      // 若即将整页刷新则不必再开定时器
      try {
        if (sessionStorage.getItem(WS_REOPEN_KEY) === '1') {return;}
      } catch (e) {}
      if (isWSVisible()) {startWSRefresh();}
    }
  }

  const _mcCache = {};
  function clearMachineCache() {
    for (const k in _mcCache) {delete _mcCache[k];}
  }
  async function loadMachines(dr) {
    if (dr in _mcCache) {return _mcCache[dr];}
    const data = await fetchJ(WGM + '?Method=FindWGMbyWorkGroup&WorkGroupDR=' + dr);
    const rows = data && data.rows ? data.rows : Array.isArray(data) ? data : [];
    // 不缓存空结果，避免网络异常后永久返回空
    if (rows.length > 0) {_mcCache[dr] = rows;}
    return rows;
  }

  async function loadWL(mdr, ss, dateStart, dateEnd) {
    const p = new URLSearchParams();
    p.set('ClassName', 'LIS.WS.BLL.DHCRPVisitNumberReportForCSP');
    p.set('QueryName', 'QryWorkList');
    p.set('FunModul', 'MTHD');
    // P0: ReportStatus (空=全部)
    // P1: SttAccDate (开始日期)
    // P2: EndAccDate (结束日期)
    // P10: WorkGroupMachineDR (仪器DR，空=全部)
    // P11: ReportType (N^^^^)
    // P14: SessionStr
    p.set('P0', ''); // 空=全部状态
    // 8.7.0: 查询日期窗口——平时=选中单日；自动审核运行中=开启日~今天（跨午夜续审昨晚标本）
    p.set('P1', dateStart || today());
    p.set('P2', dateEnd || dateStart || today());
    p.set('P10', mdr || '');
    p.set('P11', 'N^^^^');
    p.set('P14', ss);
    const data = await fetchJ(CSP + '?' + p.toString());
    return data && data.rows ? data.rows : Array.isArray(data) ? data : [];
  }

  async function loadPendingForMachine(wgmDR, ss) {
    const p = new URLSearchParams();
    p.set('ClassName', 'LIS.WS.BLL.OT.DHCOTMain');
    p.set('QueryName', 'QryStatVisitStatusDetail');
    p.set('FunModul', 'JSON');
    p.set('P0', wgmDR || '');
    p.set('P1', '0');
    p.set('P14', ss);
    const data = await fetchJ(CSP + '?' + p.toString());
    const rows = data && data.rows ? data.rows : Array.isArray(data) ? data : [];
    return rows.map(r => ({
      ...r,
      ReportDR: 'pending:' + String(wgmDR || '') + ':' + String(r.Labno || '') + ':' + String(r.RegNo || ''),
      Status: '0',
      ReportStatus: '0',
      IsComplete: '0',
      EpisodeNo: r.RegNo || '',
      AcceptDT: ((r.AcceptDate || '') + ' ' + (r.AcceptTime || '')).trim(),
      ReceiveDT: ((r.ReceiveDate || '') + ' ' + (r.ReceiveTime || '')).trim() || r.ReceiveDT || '',
      ReceiveDate: r.ReceiveDate || '',
      ReceiveTime: r.ReceiveTime || '',
      _pending: true
    }));
  }

  // 8.5.31: 「采集」状态（P1=9）= 病房采集中、尚未送到科室的标本
  // 与 loadPendingForMachine 复用 QryStatVisitStatusDetail，仅 P1 改为 9。
  // LIS 首页「标本状态汇总」面板的 resArr[9] 就是这个状态（见 cache/.../start.js:971）。
  async function loadCollectedForMachine(wgmDR, ss) {
    const p = new URLSearchParams();
    p.set('ClassName', 'LIS.WS.BLL.OT.DHCOTMain');
    p.set('QueryName', 'QryStatVisitStatusDetail');
    p.set('FunModul', 'JSON');
    p.set('P0', wgmDR || '');
    p.set('P1', '9');
    p.set('P14', ss);
    const data = await fetchJ(CSP + '?' + p.toString());
    const rows = data && data.rows ? data.rows : Array.isArray(data) ? data : [];
    return rows.map(r => ({
      ...r,
      ReportDR: 'collected:' + String(wgmDR || '') + ':' + String(r.Labno || '') + ':' + String(r.RegNo || ''),
      Status: '9',
      ReportStatus: '9',
      IsComplete: '0',
      EpisodeNo: r.RegNo || '',
      AcceptDT: '',
      CollectDT: ((r.CollectionDate || r.CollectDate || '') + ' ' + (r.CollectionTime || r.CollectTime || '')).trim() || r.CollectDT || '',
      CollectionDate: r.CollectionDate || r.CollectDate || '',
      CollectionTime: r.CollectionTime || r.CollectTime || '',
      // 病房采集尚未送到科室，没有接收/核收时间，留空避免误用 AcceptDT 当成核收
      _collected: true
    }));
  }
  function calcMachineCounts() {
    // 8.9.0: 委托统一计数（单遍遍历 + 缓存）——此前每次调用都全量重跑 getWSAuditBucket，
    // 而本函数在每次审核成功/数据刷新/忽略切换后都会被调用
    wsMachineCounts = calcUnifiedCounts().machCounts;
  }

  // 跨工作组切换：
  // LIS 原生切换流程：父框架 <select id="sl_changeworkgroup"> → changeLogin(this) → ChangeLogin API → 重载页面。
  // 本函数直接调用父框架的 changeLogin 完成切组。
  async function safeSwitchWG(dr) {
    const wgName = (WG_MAP[dr] || {}).name || dr;
    try {
      const topWin = window.top;
      const topDoc = topWin.document;
      const sel = topDoc.getElementById('sl_changeworkgroup');
      if (!sel) {
        showToast(`未找到工作组切换控件，请手动切到${wgName}`, 'warning');
        return false;
      }
      if (String(sel.value) === String(dr)) {return true;} // 已在目标组
      // 8.8.27: 切组时若工作台可见，标记重载后立即自动重开工作台并保持状态，避免漏出原始 LIS 页面
      try {
        if (isWSVisible()) {
          sessionStorage.setItem(WS_REOPEN_KEY, '1');
          saveWSState();
        }
      } catch (e) {}
      sel.value = String(dr);
      // 调用父框架原生 changeLogin，与用户手动选工作组完全一致
      if (typeof topWin.changeLogin === 'function') {
        topWin.changeLogin(sel);
        return true;
      }
      // 降级：派发 change 事件
      sel.dispatchEvent(new Event('change', { bubbles: true }));
      return true;
    } catch (e) {
      dbg('safeSwitchWG 异常: ' + e);
      showToast(`切组失败，请手动切到${wgName}`, 'warning');
      return false;
    }
  }

  // --- 异常审核跨组跳转：保存/恢复目标标本 ---
  const K_ABN_TGT = 'LIS_AbnormalAuditTarget';
  // 跨组审核的起始工作组 + 本次跨组来源（8.5.8）：
  // - wg：首次跨组时的工作组（审完全部自动切回这里）
  // - source：'detail'（详情面板跨组，审完目标条自动重开详情面板续审）/ 'list'（列表逐条）
  // - ts：时间戳，30 分钟内有效，避免陈旧 origin 误切回
  const K_AUDIT_ORIGIN = 'LIS_AuditOrigin';
  function saveAuditOrigin(source) {
    try {
      const old = JSON.parse(localStorage.getItem(K_AUDIT_ORIGIN) || '{}');
      const fresh = Date.now() - (old.ts || 0) < 30 * 60 * 1000;
      // 8.16.16: 起始组只记可信值——记不到就不记（loadAuditOrigin 返回 null），
      // 之后就不会拿着一个「视图过滤组/推测组」去切回（那是另一次整页重载）
      const origin = fresh && old.wg ? old.wg : resolveLoginWGReliable();
      localStorage.setItem(
        K_AUDIT_ORIGIN,
        JSON.stringify({ wg: origin, source: source || 'list', ts: Date.now() })
      );
    } catch (e) {}
  }
  function loadAuditOrigin() {
    try {
      const o = JSON.parse(localStorage.getItem(K_AUDIT_ORIGIN) || '{}');
      if (!o || !o.wg || Date.now() - (o.ts || 0) > 30 * 60 * 1000) {
        localStorage.removeItem(K_AUDIT_ORIGIN);
        return null;
      }
      return o;
    } catch (e) {
      return null;
    }
  }
  function clearAuditOrigin() {
    try {
      localStorage.removeItem(K_AUDIT_ORIGIN);
    } catch (e) {}
  }
  // 8.5.10: 不切组直接审跨组标本时，强制把 origin 记录为当前组——保证审完
  // trySwitchBackToOrigin 因 origin===当前组 直接 no-op，不会被陈旧 origin 误切回。
  function saveAuditOriginCurrent(source) {
    try {
      const cur = resolveLoginWGReliable();
      if (cur) {
        localStorage.setItem(K_AUDIT_ORIGIN, JSON.stringify({ wg: cur, source: source || 'list', ts: Date.now() }));
      }
    } catch (e) {}
  }
  // 跨组审核全部审完：切回起始工作组，并保证切回后工作台自动打开
  function switchBackToOriginWG(wgDR) {
    try {
      sessionStorage.setItem(WS_REOPEN_KEY, '1');
      saveWSState();
    } catch (e) {}
    safeSwitchWG(wgDR);
  }
  // 8.5.8: 审空自动切回起始组 —— 分类进行中（可能有尚未分类、即将进入待审的标本）或
  // 搜索框过滤时不算「审完」，延迟重试；确认待审视图真空才切回，避免提前切回遗留标本
  // 8.5.9: 用单 timer 管理重试 —— 原实现在分类中/搜索中每次调用都启 setTimeout，
  //   连续审核多条时多个并行 setTimeout 互相重置 _switchBackRetry=0，上限 10 永远到不了。
  //   改为：已有 timer 在跑则直接 return，不再重复启动；计数器在 timer 触发链路里递增。
  let _switchBackRetry = 0;
  let _switchBackTimer = null;
  function trySwitchBackToOrigin() {
    try {
      const origin = loadAuditOrigin();
      if (!origin || String(origin.wg) === String(resolveLoginWGReliable())) {
        _switchBackRetry = 0;
        if (_switchBackTimer) {clearTimeout(_switchBackTimer); _switchBackTimer = null;}
        return;
      }
      const searchQ = (($('#lis-ws-search') || {}).value || '').trim();
      if (wsClassifying || searchQ) {
        // 已有重试 timer 在跑则不重复启动（避免并行 setTimeout 互相重置计数器导致上限失效）
        if (_switchBackTimer) {return;}
        if (_switchBackRetry < 10) {
          _switchBackRetry++;
          _switchBackTimer = setTimeout(() => {
            _switchBackTimer = null;
            trySwitchBackToOrigin();
          }, 3000);
        } else {
          // 重试 10 次（约 30s）仍未分类完成，放弃切回避免无限重试；用户可手动切组
          _switchBackRetry = 0;
        }
        return;
      }
      // 分类完成、无搜索过滤：清掉待重试 timer + 计数器，落定切回判定
      if (_switchBackTimer) {clearTimeout(_switchBackTimer); _switchBackTimer = null;}
      _switchBackRetry = 0;
      if (filteredData().length === 0) {
        clearAuditOrigin();
        showToast(`已审完，切回${(WG_MAP[origin.wg] || {}).name || origin.wg}`, 'success');
        switchBackToOriginWG(origin.wg);
      }
    } catch (e) {}
  }
  function saveAbnormalTarget(specimen, extra) {
    try {
      // 8.8.27: 记住重开工作台
      sessionStorage.setItem(WS_REOPEN_KEY, '1');
      saveWSState();
      // 读取已有 cycle 计数，累加防循环
      let cycle = 0;
      try {
        const old = JSON.parse(localStorage.getItem(K_ABN_TGT) || '{}');
        cycle = (old.cycle || 0) + 1;
      } catch (_) {}
      localStorage.setItem(
        K_ABN_TGT,
        JSON.stringify({
          reportDR: String(specimen.ReportDR || ''),
          wg: specimen._wg || '',
          name: specimen.PatName || '',
          labno: specimen.Labno || '',
          ts: Date.now(),
          cycle
        })
      );
      // 记录跨组起始工作组（审完自动切回）+ 来源（详情续审用）
      saveAuditOrigin((extra && extra.source) || 'list');
    } catch (e) {}
  }
  function loadAbnormalTarget() {
    try {
      const raw = localStorage.getItem(K_ABN_TGT);
      if (!raw) {return null;}
      const t = JSON.parse(raw);
      if (!t || !t.reportDR || Date.now() - (t.ts || 0) > 5 * 60 * 1000) {
        localStorage.removeItem(K_ABN_TGT);
        return null;
      }
      // 防止无限循环：最多尝试 3 次切组
      if ((t.cycle || 0) > 3) {
        localStorage.removeItem(K_ABN_TGT);
        return null;
      }
      return t;
    } catch (e) {
      return null;
    }
  }
  function clearAbnormalTarget() {
    try {
      localStorage.removeItem(K_ABN_TGT);
    } catch (e) {}
  }
  function checkAbnormalTarget() {
    const tgt = loadAbnormalTarget();
    if (!tgt) {return;}
    // 不立即清空，找到标本后再清（防止页面重载导致丢失）
    // 跨组切组后页面已重载、工作台处于关闭状态：
    // 1) 先打开工作台（openWS 会从 localStorage 恢复上次的工作组 + 跨组仪器多选），
    //    并触发 loadWSData，否则 wsData 永远为空、找不到目标标本、工作台也不会自动打开；
    // 2) 恢复后再 saveWSState()，避免把空的多选状态覆盖回 localStorage 丢掉跨组勾选。
    if (!isWSVisible()) {openWS();}
    if (wsCategory !== 'audit') {
      wsCategory = 'audit';
      saveWSState();
      renderWSCategoryBar();
      renderWSTable();
    }
    let classifiedOnce = false; // 只主动补分类一次，避免每条轮询都发请求
    const tryFind = attempts => {
      const found = wsData.find(r => String(r.ReportDR) === tgt.reportDR);
      if (found) {
        // 直接按桶判断（不依赖分类队列整体进度），否则大工作组的分类批次可能跑不完，
        // 轮询窗口内目标标本一直进不了待审视图 → 误报「未找到标本」
        // 合并视图：正常/异常均可审，两个分支都恢复定位+审核（否则跨组审 normal 会漏审）
        const _bucket = getWSAuditBucket(found);
        const isAuditable = _bucket === 'normal' || _bucket === 'abnormal';
        if (!isAuditable && !classifiedOnce) {
          classifiedOnce = true;
          fetchAndClassifySpecimen(found)
            .then(live => {
              if (live && live.reportDR) {
                attachClassificationMeta(live, found);
                wsClassifiedCache[live.reportDR] = live;
                _classifyVersion++;
                invalidateCaches();
              }
            })
            .catch(() => {});
          // 本轮先不成功，等下一次轮询（已提交主动分类）
        } else if (isAuditable) {
          const data = filteredData();
          let idx = data.indexOf(found);
          if (idx < 0) {idx = data.length ? 0 : -1;} // 同桶必在列表，兜底取首条
          if (idx >= 0) {
            clearAbnormalTarget();
            // 8.5.8: 详情面板跨组审核时，审完目标条自动重开详情面板续审（连续审核跨组不断）
            const _origin = loadAuditOrigin();
            _resumeDetailAfterAudit = !!( _origin && _origin.source === 'detail');
            wsAbnormalIndex = idx;
            showToast(`继续审核: ${tgt.name || tgt.labno}`, 'warning');
            setTimeout(() => auditAbnormalSpecimen(found), 500);
            return;
          }
        }
      }
      if (attempts > 0) {
        // init 阶段会话可能未就绪、首次加载失败时，主动补一次强制加载
        if (attempts === 10 && !wsData.length) {loadWSData({ force: true }).catch(() => {});}
        setTimeout(() => tryFind(attempts - 1), 1000);
      }
      else {
        clearAbnormalTarget();
        showToast(`未找到标本 ${tgt.name || tgt.labno}，可能已审核`, 'warning');
      }
    };
    setTimeout(() => tryFind(10), 1500);
  }

  // ============================================================
  //  待排/采集标本忽略（8.5.33）：忽略后不计入任何统计；列表仍显示但灰显，可随时取消
  // ============================================================
  let _wsIgnored = null; // 懒加载 Map: rdr -> {labno,patName,testSet,ts}
  function wsIgnoreLoad() {
    if (_wsIgnored) {return;}
    try {
      _wsIgnored = new Map(Object.entries(JSON.parse(localStorage.getItem(K.wsIgnore) || '{}')));
    } catch (e) {_wsIgnored = new Map();}
  }
  function wsIgnoreSave() {
    if (!_wsIgnored) {return;}
    // 顺带清理过期项：待排/采集都是当天标本（接口按今日日期查），超过 7 天仍未核收/被自动取消
    // 说明早已离开待排列表，保留只会让 localStorage 无限增长。7 天远大于任何正常滞留时间，不会误删。
    const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;
    let expired = false;
    _wsIgnored.forEach((v, k) => {
      if (v && v.ts && v.ts < cutoff) {
        _wsIgnored.delete(k);
        expired = true;
      }
    });
    if (expired) {dbg('清理过期忽略项', _wsIgnored.size, '条');}
    const obj = {};
    _wsIgnored.forEach((v, k) => {obj[k] = v;});
    try {localStorage.setItem(K.wsIgnore, JSON.stringify(obj));} catch (e) {}
  }
  function isWSIgnored(rdr) {
    if (!rdr) {return false;}
    wsIgnoreLoad();
    return _wsIgnored.has(String(rdr));
  }
  function toggleWSIgnore(rdr, meta) {
    if (!rdr) {return;}
    wsIgnoreLoad();
    const key = String(rdr);
    if (_wsIgnored.has(key)) {_wsIgnored.delete(key);}
    else {
      _wsIgnored.set(key, {
        labno: (meta && meta.labno) || '',
        patName: (meta && meta.patName) || '',
        testSet: (meta && meta.testSet) || '',
        ts: Date.now()
      });
    }
    wsIgnoreSave();
    invalidateCaches(); // 8.9.0: 忽略状态影响计数，统一计数缓存须失效
  }
  function wsIgnoreBtnHTML(rdr) {
    if (!rdr) {return '';}
    const ignored = isWSIgnored(rdr);
    return '<button class="ws-ignore-btn' + (ignored ? ' on' : '') + '" data-rdr="' + escAttr(rdr) + '" title="' +
      (ignored ? '点击取消忽略（重新计入统计）' : '点击忽略（不再计入任何统计）') + '">' +
      (ignored ? '👁 取消' : '🙈 忽略') + '</button>';
  }

  // 8.5.33: 标本一旦核收进入未审核/审核流程（状态不再是待排 0 / 采集 9，即已在主列表出现），
  // 自动取消忽略、恢复正常计数。忽略项 key 是合成 DR（pending:/collected:），而核收后标本用的是
  // 真实 ReportDR，key 必然不同；此处以 Labno（检验号，院内唯一）匹配主列表标本，把对应忽略项删除。
  function wsIgnoreAutoRelease(rows) {
    wsIgnoreLoad();
    if (!_wsIgnored || _wsIgnored.size === 0) {return false;}
    const liveLabnos = new Set();
    (rows || []).forEach(r => {
      const st = String(r.Status || r.ReportStatus || '');
      if (st === '0' || st === '9') {return;} // 仍在待排/采集，不动
      const labno = String(r.Labno || '').trim();
      if (labno) {liveLabnos.add(labno);}
    });
    if (liveLabnos.size === 0) {return false;}
    let changed = false;
    _wsIgnored.forEach((meta, key) => {
      const k = String(key || '');
      if (!k.startsWith('pending:') && !k.startsWith('collected:')) {return;}
      const labno = String((meta && meta.labno) || '').trim();
      if (labno && liveLabnos.has(labno)) {
        _wsIgnored.delete(key);
        changed = true;
      }
    });
    if (changed) {
      wsIgnoreSave();
      dbg('自动取消忽略：标本已核收进入未审核/审核，恢复正常计数');
    }
    return changed;
  }

  function getWSAuditBucket(r) {
    const status = String(r.Status || r.ReportStatus || '');
    // 8.17.0: 外送组（dr=5，仅一台「外送标本」仪器）——只追踪待排/采集，不做审核。
    // 外送报告由第三方出具，本科室不审核：标本一旦录入结果即从工作台消失（返回 'audited'
    // 与已审同等隐藏，各分类视图均不显示；正常入库路径已在 applyResults 直接丢弃这些行，
    // 这里是兜底——详情/历史/导出等非工作台来源也可能把外送行喂进来）。
    if (isExternalWSWorkGroup(r._wg)) {
      if (status === '0') {return 'pending';}
      if (status === '9') {return 'collected';}
      return 'audited';
    }
    if (status === '5') {
      // 8.10.0: 已取消标本一律不可审——此前只挡 3/0/9，取消标本若 IsComplete='1'
      // 且分类 NORMAL 会混入待审视图/批审队列，存在误审已取消报告的风险
      return 'audited'; // 与已审同等隐藏（各分类视图不显示，「全部」视图仍可见）
    }
    if (status === '3') {
      // 8.5.50: 一审完成（审核）= 已审核，保持隐藏
      return 'audited';
    }
    if (status === '4') {
      // 8.5.50: 复审（复检/复查）标本：结果不完整 → 不完整；结果完整 → 待审显示
      // 8.5.52: 复检标本可正常审核（危急值除外），仅危急值由 validateAuditClassification 红线拦截
      // 只处理 status 4，status 3 保持隐藏——避免 8.5.44/8.5.45 误伤已审核标本的教训
      if (!isSpecimenActuallyComplete(r)) {return 'incomplete';}
      // 走下方分类判断：NORMAL/ABNORMAL → 待审；无缓存/待定 → 不完整
    }
    if (status === '0') {return 'pending';}
    if (status === '9') {return 'collected';} // 8.5.31: 病房采集中、未送到科室
    // 8.10.23: 结果完整性判定——自动化仪器以 IsComplete==='1' 为硬门槛；
    // 手工录入仪器（H900/手工杂项等）在所有项目录入完整后放行
    if (!isSpecimenActuallyComplete(r)) {return 'incomplete';}
    const cached = wsClassifiedCache[r.ReportDR];
    if (!cached) {return 'incomplete';} // 分类未完成时不进入正常可审，避免误批审
    if (isClassificationStale(r)) {return 'incomplete';}
    if (cached.status === 'NORMAL') {return 'normal';}
    if (cached.status === 'CRITICAL' || cached.status === 'ZERO') {return 'abnormal';}
    // 8.15.11: 含星号占位结果（形如 ***.**，各仪器星号个数不同）→ 一律归「不完整」。
    // **必须放在下面 8.10.25 那条之前**：LIS 对这类标本常仍置 IsComplete=1，
    // 于是走「实际已录入完整就放行进待审」被捞进待审，而待审视图的 Enter/F4 会连它一起审掉。
    // 危急值/堵孔仍保留在待审——它们本就不可被 Enter/F4 批审（F4 只收 NORMAL/轻微带内），
    // 留在待审更利于被发现，不该因占位符而下沉。
    if (cached.items && cached.items.some(it => isAsteriskPlaceholderResult(it.result))) {return 'incomplete';}
    if (cached.status === 'ABNORMAL') {return 'abnormal';}
    // 8.10.25: 若标本实际结果已经录入完整（手工录入无空项 或 IsComplete=1），即使含有待定项目（UNCERTAIN，如特殊符号/操作符/未配置参考范围）
    // 也应放行进入待审（需人工确认审核），绝不能作为不完整锁死在未录入列表中
    if (isSpecimenActuallyComplete(r, cached)) {return 'abnormal';}
    return 'incomplete';
  }

  // 8.9.0: 排序规则按 wg 缓存——此前每次调用都重建含 6+ 正则的数组，而本函数在排序
  // 比较器里被高频调用，重建纯属浪费
  const _machineSortRulesCache = {};
  function _machineSortRulesFor(wg) {
    if (!_machineSortRulesCache[wg]) {
      _machineSortRulesCache[wg] =
        wg === '1'
          ? [
            ['血细胞', /血细胞|血球|血常规|bc-|xn|xs|sysmex|mindray|迈瑞/],
            ['血凝', /血凝|凝血|coag|cs-|ca-|stago|acl/],
            ['尿液', /尿液|尿沉渣|尿干化|尿常规|uf|uc|urisys|ave/],
            ['粪便', /粪便|大便|便|fec|ob/],
            ['血流变', /血流变|流变|hemorheology/],
            ['手工杂项', /手工|杂项|manual/]
          ]
          : wg === '4'
            ? [
              ['800', /dxi\s*800|dxi800|化学发光仪800|800/],
              ['x8', /maglumi\s*x?8|maglumix8|x8/],
              ['1600', /1600|getein/],
              ['wan200', /wan\s*200|wan200/],
              ['手工杂项', /手工|杂项|manual/]
            ]
            : [];
    }
    return _machineSortRulesCache[wg];
  }

  function getMachineSortRank(machine) {
    const name = ((machine && (machine.CName || machine.Name || machine.RowID)) || '').toLowerCase();
    const wg = String((machine && machine._wg) || '');
    const rules = _machineSortRulesFor(wg);
    for (let i = 0; i < rules.length; i++) {
      if (rules[i][1].test(name)) {return i;}
    }
    return 100;
  }

  function sortWSMachines(machines) {
    return [...machines].sort((a, b) => {
      const ra = getMachineSortRank(a);
      const rb = getMachineSortRank(b);
      if (ra !== rb) {return ra - rb;}
      const na = a.CName || a.Name || a.RowID || '';
      const nb = b.CName || b.Name || b.RowID || '';
      return na.localeCompare(nb, 'zh');
    });
  }

  function specimenMachineRank(row) {
    const wg = String(row._wg || '');
    const mdr = prWorkGroupMachineDR(row);
    return getMachineSortRank({ CName: row._mn || '', Name: row._mn || '', RowID: mdr, _wg: wg });
  }

  function compareSpecimensByMachineGroup(a, b) {
    const wgA = String(a._wg || '');
    const wgB = String(b._wg || '');
    const wgCmp = wgA.localeCompare(wgB, 'zh');
    if (wgCmp) {return wgCmp;}

    const rankA = specimenMachineRank(a);
    const rankB = specimenMachineRank(b);
    if (rankA !== rankB) {return rankA - rankB;}

    const mdrA = prWorkGroupMachineDR(a);
    const mdrB = prWorkGroupMachineDR(b);
    const mdrCmp = String(mdrA).localeCompare(String(mdrB), 'zh');
    if (mdrCmp) {return mdrCmp;}

    return String(a._mn || '').localeCompare(String(b._mn || ''), 'zh');
  }

  function compareSpecimensForAudit(a, b) {
    const g = compareSpecimensByMachineGroup(a, b);
    if (g) {return g;}
    const va = String(a.AcceptDT || '');
    const vb = String(b.AcceptDT || '');
    const dtCmp = vb.localeCompare(va, 'zh');
    if (dtCmp) {return dtCmp;}
    return String(a.Labno || '').localeCompare(String(b.Labno || ''), 'zh');
  }

  // 确定用户实际登录工作组（多层回退）
  function resolveCurrentWG() {
    // 注意：跨组判定必须以「实际登录工作组」为准，不能用工作台视图过滤器 wsActiveWG——
    // 用户可能看的是临检 tab 而实际登录在生化；且切组重载后 wsActiveWG 是从 localStorage 恢复的
    // 旧视图组，若优先返回它会导致批审死循环 / F4 跨组静默不审。
    // 1. 父框架工作组下拉框（切组后页面重载，全局变量可能尚未就绪，但下拉框已更新）
    try {
      const sel = window.top.document.getElementById('sl_changeworkgroup');
      if (sel && sel.value) {return String(sel.value);}
    } catch (e) {}
    // 2. LIS 页面全局变量
    const dr = wgDR();
    if (dr) {return dr;}
    // 3. 工作台选中的工作组（仅视图过滤，不代表登录组；无登录组信息时才退回）
    if (wsActiveWG) {return wsActiveWG;}
    // 4. 从 wsData 推断：有标本的工作组中最常见的
    const counts = {};
    wsData.forEach(r => {
      const w = r._wg;
      if (w) {counts[w] = (counts[w] || 0) + 1;}
    });
    let best = '',
      bestN = 0;
    for (const [w, n] of Object.entries(counts)) {
      if (n > bestN) {
        best = w;
        bestN = n;
      }
    }
    return best;
  }

  // ==================== 8.16.16: 「可信登录工作组」 ====================
  // 只认原生界面给出的权威值：① 顶层 sl_changeworkgroup 下拉框 ② LIS 页面全局 WorkGroupDR。
  //
  // 为什么必须与 resolveCurrentWG() 分开：后者有 4 级回退，**后两级都不代表实际登录组**——
  //   ③ wsActiveWG 是工作台的**视图过滤**（用户可能在看临检 tab，实际登录在生化）；
  //   ④ 从 wsData 推断「标本最多的组」，会随数据变化**漂移**。
  // 拿它们做「跨组判定」会得出「非空但错误」的当前组 → 把本组标本误判成跨组 →
  // 触发切组（整页重载）→ 重载后若仍读不到权威值 → 又误判 → 再切，正是
  // 8.16.15 那个「工作台与原生 LIS 无限来回切、关掉自动审核也停不下来」死循环的入口。
  //
  // 约定：凡是**决定「要不要切组」**的地方一律用本函数；返回 '' 表示「当前组不可知」，
  // 调用方必须按「不确定 ⇒ 绝不切组」处理——因为免切组（按机台 DR 直接查工作列表）
  // 本来就不需要知道当前登录组，放行是安全且正确的默认。
  function resolveLoginWGReliable() {
    try {
      const sel = window.top.document.getElementById('sl_changeworkgroup');
      if (sel && sel.value) {return String(sel.value);}
    } catch (e) {}
    const dr = wgDR();
    if (dr) {return String(dr);}
    return '';
  }

  function compareAuditQueueItems(a, b) {
    const rowA = resolveQueueItemRow(a) || { _wg: a.wg, _mdr: a.mdr, AcceptDT: '', Labno: a.labno };
    const rowB = resolveQueueItemRow(b) || { _wg: b.wg, _mdr: b.mdr, AcceptDT: '', Labno: b.labno };
    // 当前工作组优先，减少切组次数
    const curWg = resolveLoginWGReliable() || resolveCurrentWG();
    const aIsCur = String(rowA._wg || a.wg) === curWg ? 0 : 1;
    const bIsCur = String(rowB._wg || b.wg) === curWg ? 0 : 1;
    if (aIsCur !== bIsCur) {return aIsCur - bIsCur;}
    const g = compareSpecimensByMachineGroup(rowA, rowB);
    if (g) {return g;}
    const va = String(rowA.AcceptDT || '');
    const vb = String(rowB.AcceptDT || '');
    const dtCmp = vb.localeCompare(va, 'zh');
    if (dtCmp) {return dtCmp;}
    return String(a.labno || '').localeCompare(String(b.labno || ''), 'zh');
  }

  function sortSpecimensForAudit(rows) {
    return [...rows].sort(compareSpecimensForAudit);
  }

  // --- 过滤 & 排序 ---
  function filteredData() {
    // 读取当前搜索框值（不能用旧的 wsSearchQuery）
    const _q = ($('#lis-ws-search') || {}).value || '';
    // 缓存检查
    let machineFilterKey;
    if (wsActiveWG) {
      machineFilterKey = [...wsMachineFilterSetForActiveWG()].sort().join(',');
    } else {
      // 全部工作组：汇总所有组的选中仪器（含外送）
      const allSel = [];
      WS_WG.forEach(w => {
        const s = getWSSelectedMachineSet(w.dr);
        if (s.size) {allSel.push(w.dr + ':' + [...s].sort().join(','));}
      });
      machineFilterKey = allSel.length ? allSel.sort().join('|') : wsActiveMachine;
    }
    const ck =
      wsActiveDate +
      '|' +
      wsActiveWG +
      '|' +
      machineFilterKey +
      '|' +
      wsCategory +
      '|' +
      _q +
      '|' +
      (wsSort.field + wsSort.asc) +
      '|' +
      _classifyVersion;
    if (_filteredCache && _filteredCacheKey === ck) {return _filteredCache;}
    let d = [...wsData];
    // 8.8.10: 历史日期视图严格兜底过滤：确保只展示目标日期的标本
    if (wsActiveDate && wsActiveDate !== today()) {
      d = d.filter(r => {
        const dStr = rowAcceptDateStr(r);
        return !dStr || dStr === wsActiveDate;
      });
    }
    // 工作组 + 仪器过滤
    if (wsActiveWG || wsActiveMachine || WS_WG.some(w => getWSSelectedMachineSet(w.dr).size > 0))
    {d = d.filter(rowPassWSMachineFilter);}
    // 分类过滤
    if (wsCategory === 'audit') {
      d = d.filter(r => {
        const b = getWSAuditBucket(r);
        return b === 'normal' || b === 'abnormal';
      });
    } else if (wsCategory === 'incomplete') {
      d = d.filter(r => {
        return getWSAuditBucket(r) === 'incomplete';
      });
    } else if (wsCategory === 'pending') {
      d = d.filter(r => {
        return getWSAuditBucket(r) === 'pending';
      });
    } else if (wsCategory === 'collected') {
      // 8.5.31: 病房采集中、尚未送到科室
      d = d.filter(r => {
        return getWSAuditBucket(r) === 'collected';
      });
    }
    // 'all' = 不过滤分类
    // 搜索
    if (_q) {
      const ql = _q.toLowerCase();
      d = d.filter(
        r =>
          (r.PatName || '').toLowerCase().includes(ql) ||
          (r.Labno || '').toLowerCase().includes(ql) ||
          (r.EpisodeNo || '').toLowerCase().includes(ql) ||
          (r.RegNo || '').toLowerCase().includes(ql) ||
          (r.TestSetDesc || '').toLowerCase().includes(ql) ||
          (r.Doctor || r.DoctorName || '').toLowerCase().includes(ql) ||
          (r.Location || r.LocationName || '').toLowerCase().includes(ql)
      );
    }
    wsSearchQuery = _q; // 保存搜索词用于高亮
    // 排序：批审/异常待审按仪器分组，同仪器内再按原排序字段
    const { field, asc } = wsSort;
    if (wsCategory === 'audit') {
      // 待审视图：当前登录工作组优先（减少跨组审核时的切组次数，先审完本组），
      // 组内按仪器分组，危急→异常→正常（正常放后面，供 F4 一键批审）
      // 8.9.0: decorate-sort——先为每行预计算全部排序键，比较器只比预计算值。
      // 原实现每次比较都调 getWSAuditBucket（内部做分类指纹 join）与
      // getMachineSortRank（重建正则数组），500 行 ≈ 9000 次比较全在重复计算
      const _curWGForSort = resolveCurrentWG();
      const _dec = d.map(r => {
        const b = getWSAuditBucket(r);
        const cached = wsClassifiedCache[r.ReportDR];
        return {
          r,
          isCur: String(r._wg || '') === _curWGForSort ? 0 : 1,
          wg: String(r._wg || ''),
          mRank: specimenMachineRank(r),
          mdr: String(prWorkGroupMachineDR(r)),
          mn: String(r._mn || ''),
          crit: b === 'normal' ? 2 : (cached && cached.status === 'CRITICAL' ? 0 : 1),
          // 8.14.0: 四色分层排序——危急(0)→超带异常(1)→轻微可批(2)→正常(3)，与卡片颜色同源，
          // 同色标本在仪器段内自然聚拢；不跨仪器全局聚色（那会让原生页在仪器间来回跳选行）
          clsRank: ({critical: 0, beyond: 1, mild: 2, normal: 3})[wsAuditCardClass(r)],
          fv: (r[field] || '').toString()
        };
      });
      _dec.sort((a, b) => {
        if (a.isCur !== b.isCur) {return a.isCur - b.isCur;}
        const wgCmp = a.wg.localeCompare(b.wg, 'zh');
        if (wgCmp) {return wgCmp;}
        if (a.mRank !== b.mRank) {return a.mRank - b.mRank;}
        const mdrCmp = a.mdr.localeCompare(b.mdr, 'zh');
        if (mdrCmp) {return mdrCmp;}
        const mnCmp = a.mn.localeCompare(b.mn, 'zh');
        if (mnCmp) {return mnCmp;}
        if (a.crit !== b.crit) {return a.crit - b.crit;}
        if (a.clsRank !== b.clsRank) {return a.clsRank - b.clsRank;}
        return asc ? a.fv.localeCompare(b.fv, 'zh') : b.fv.localeCompare(a.fv, 'zh');
      });
      d = _dec.map(x => x.r);
    } else {
      d.sort((a, b) => {
        const va = wsCategory === 'collected'
          ? (getSpecimenCollectTime(a) || a.CollectDT || a[field] || '').toString()
          : wsCategory === 'pending'
          ? (getSpecimenReceiveTime(a) || a.ReceiveDT || a[field] || '').toString()
          : (a[field] || '').toString();
        const vb = wsCategory === 'collected'
          ? (getSpecimenCollectTime(b) || b.CollectDT || b[field] || '').toString()
          : wsCategory === 'pending'
          ? (getSpecimenReceiveTime(b) || b.ReceiveDT || b[field] || '').toString()
          : (b[field] || '').toString();
        return asc ? va.localeCompare(vb, 'zh') : vb.localeCompare(va, 'zh');
      });
    }

    dbg('过滤后数据量:', d.length, '分类:', wsCategory);
    _filteredCache = d;
    _filteredCacheKey = ck;
    return d;
  }

  // --- 统一计数：一次遍历产出工作组计数 + 分类计数 ---
  function calcUnifiedCounts() {
    let machineFilterKey;
    if (wsActiveWG) {
      machineFilterKey = [...wsMachineFilterSetForActiveWG()].sort().join(',');
    } else {
      const allSel = [];
      WS_WG.forEach(w => {
        const s = getWSSelectedMachineSet(w.dr);
        if (s.size) {allSel.push(w.dr + ':' + [...s].sort().join(','));}
      });
      machineFilterKey = allSel.length ? allSel.sort().join('|') : wsActiveMachine;
    }
    const ck =
      _wsDataEpoch + '|' + _classifyVersion + '|' + Math.floor(Date.now() / 60000) + '|' +
      wsData.length + '|' + wsActiveWG + '|' + machineFilterKey;
    if (_countsCache && _countsCacheKey === ck) {return _countsCache;}

    // 工作组计数（含外送：其 total = 待排 + 采集，见 getWSAuditBucket 的外送分支）
    const wgCounts = {};
    WS_WG.forEach(w => {
      wgCounts[w.dr] = { total: 0, normalReady: 0, abnormalReady: 0, incomplete: 0 };
    });
    // 分类计数（基于当前过滤）
    let normalCount = 0,
      abnormalCount = 0,
      incompleteCount = 0,
      pendingCount = 0;
    // 8.9.0: 同一遍顺带产出「当前仪器过滤」范围的分类计数（分类栏/页脚/菜单栏用）——
    // 此前 renderWSCategoryBar 对全量 wsData 又单独跑一遍 getWSAuditBucket
    let fTotal = 0, fNormal = 0, fAbnormal = 0, fIncomplete = 0, fPending = 0, fCollected = 0;
    let fMild = 0; // 8.12.0: 当前过滤范围内可被 F4 一并批审的轻微异常条数
    const _machFilterActive = !!(wsActiveWG || wsActiveMachine || WS_WG.some(w => getWSSelectedMachineSet(w.dr).size > 0));
    // 全部仪器汇总
    const machCounts = {};
    machCounts['_all'] = { total: 0, normalReady: 0, abnormalReady: 0, incomplete: 0 };

    wsData.forEach(r => {
      // 8.5.33: 忽略的标本不计入工作组/仪器/分类任何统计
      if (isWSIgnored(r.ReportDR)) {return;}
      // 工作组计数
      const wg = r._wg;
      if (wgCounts[wg]) {
        wgCounts[wg].total++;
      }
      // 仪器计数
      const mdr = r._mdr || '_unknown';
      if (!machCounts[mdr]) {machCounts[mdr] = { total: 0, normalReady: 0, abnormalReady: 0, incomplete: 0 };}
      machCounts[mdr].total++;
      machCounts['_all'].total++;

      const bucket = getWSAuditBucket(r);
      const inScope = !_machFilterActive || rowPassWSMachineFilter(r);
      if (inScope) {fTotal++;}
      if (bucket === 'pending') {
        pendingCount++;
        if (inScope) {fPending++;}
        return;
      }
      if (bucket === 'audited') {return;}
      if (bucket === 'collected') {
        // 8.5.31: 病房采集中——只进分类栏计数，不进可审统计
        if (inScope) {fCollected++;}
        return;
      }

      if (bucket === 'incomplete') {
        if (wgCounts[wg]) {wgCounts[wg].incomplete++;}
        machCounts[mdr].incomplete++;
        machCounts['_all'].incomplete++;
        incompleteCount++;
        if (inScope) {fIncomplete++;}
        return;
      }
      if (bucket === 'abnormal') {
        if (wgCounts[wg]) {wgCounts[wg].abnormalReady++;}
        machCounts[mdr].abnormalReady++;
        machCounts['_all'].abnormalReady++;
        abnormalCount++;
        if (inScope) {
          fAbnormal++;
          // 8.12.0: 统计轻微异常可批审数（classifyMildAbnormal 带 _classifyVersion 记忆，无重复开销）
          const _mildCached = wsClassifiedCache[r.ReportDR];
          const _mildEval = _mildCached ? classifyMildAbnormal(_mildCached) : null;
          if (_mildEval && _mildEval.ok) {fMild++;}
        }
      } else if (bucket === 'normal') {
        if (wgCounts[wg]) {wgCounts[wg].normalReady++;}
        machCounts[mdr].normalReady++;
        machCounts['_all'].normalReady++;
        normalCount++;
        if (inScope) {fNormal++;}
      }
    });

    const result = {
      wgCounts, machCounts, normalCount, abnormalCount, incompleteCount, pendingCount,
      // 8.9.0: 当前仪器过滤范围（分类栏 renderWSCategoryBar 消费）
      fTotal, fNormal, fAbnormal, fIncomplete, fPending, fCollected, fMild
    };
    _countsCache = result;
    _countsCacheKey = ck;
    return result;
  }

  // --- 渲染：头部（精简全局顶栏 Row 1）---
  let _wsHeaderBuilt = false;
  function renderWSHeader() {
    const hd = $('#lis-ws-hd');
    if (!hd) {return;}
    hd.style.flexShrink = '0';
    // 8.11.10: 头部 DOM 只构建一次、事件只绑一次，之后只刷新日期控件与自动审核按钮状态。
    // 此前每次 openWS 全量重建头部并重绑全部监听；querySelector 校验兜底外部清空场景
    //（与分类栏 _catBarBuilt 同款自愈策略）。
    // 注意：搜索词不再随重建消失——重开工作台请调用 resetWSSearch()
    if (!_wsHeaderBuilt || !hd.querySelector('.ws-search')) {
      _wsHeaderBuilt = true;
      hd.innerHTML = `
            <div class="ws-title"><span class="ws-title-dot"></span><h3>标本审核工作台</h3></div>
            <div class="ws-date-pill" id="lis-ws-date-pill">
                <button class="ws-dp-zone" id="lis-ws-date-prev" title="前一天">◀</button>
                <button class="ws-dp-zone ws-dp-main" id="lis-ws-date-btn" title="点击弹出日历选择日期（可查看/审核历史标本）"><span id="lis-ws-date-label">今天</span><span class="ws-dp-caret">▾</span></button>
                <button class="ws-dp-zone" id="lis-ws-date-next" title="后一天">▶</button>
                <button type="button" class="ws-dp-zone ws-dp-now" id="lis-ws-date-today" title="回到今天" style="display:none">今</button>
            </div>
            <div class="ws-search-wrap">
                <input type="text" class="ws-search" id="lis-ws-search" placeholder="快速定位 姓名 / 检验号 / 流水号" />
            </div>
            <div class="ws-right-group">
                <span class="cat-stats cat-ca" title="当前 CA 认证账号（审核者）"></span>
                <div class="ws-acts">
                    <button class="ws-aa-btn" id="lis-ws-autoaudit" title="自动审核：按设定时长自动审核当前筛选范围的标本（正常批量 + 异常逐条按当前方案：白天仅轻微带内 / 夜间全放；危急值/堵孔0值/传染病阳性等留人工）">🤖 自动审核</button>
                    <button class="ws-icon-btn" id="lis-ws-aalog" title="查看自动审核记录（最近自动审核了哪些样本）">🕘</button>
                    <button class="ws-icon-btn" id="lis-ws-refresh" title="强制刷新（全0/会话失效时等同浏览器刷新，并自动重开工作台）">↻</button>
                    <button class="ws-icon-btn" id="lis-ws-pwd" title="CA密码">钥</button>
                    <button class="ws-icon-btn danger" id="lis-ws-close" title="关闭">×</button>
                </div>
            </div>`;
      _bindWSHeaderEvents();
    }
    updateWSDateControls();
    renderAutoAuditButtonState();
  }

  function _bindWSHeaderEvents() {
    document.getElementById('lis-ws-refresh').addEventListener('click', () => {
      dbg('刷新按钮被点击');
      const btn = document.getElementById('lis-ws-refresh');
      if (btn) {
        btn.classList.add('spinning');
        btn.title = '刷新中…';
      }
      forceRefreshWS().finally(() => {
        if (btn && document.body.contains(btn)) {
          btn.classList.remove('spinning');
          btn.title = '强制刷新（全0/会话失效时等同浏览器刷新，并自动重开工作台）';
        }
      });
    });
    document.getElementById('lis-ws-close').addEventListener('click', closeWS);
    document.getElementById('lis-ws-pwd').addEventListener('click', openPwdDlg);
    document.getElementById('lis-ws-autoaudit').addEventListener('click', () => openAutoAuditDialog());
    document.getElementById('lis-ws-aalog').addEventListener('click', () => openAutoAuditLogViewer());
    document.getElementById('lis-ws-date-prev').addEventListener('click', () => {
      setWSActiveDate(addDays(wsViewDate(), -1));
    });
    document.getElementById('lis-ws-date-next').addEventListener('click', () => {
      const td = today();
      const v = wsViewDate();
      if (v < td) {setWSActiveDate(addDays(v, 1));}
    });
    document.getElementById('lis-ws-date-btn').addEventListener('click', () => {
      if (document.getElementById('lis-ws-date-picker')) {wsCloseDatePicker();}
      else {wsOpenDatePicker();}
    });
    document.getElementById('lis-ws-date-today').addEventListener('click', () => {
      wsCloseDatePicker();
      setWSActiveDate('');
    });
    document.getElementById('lis-ws-search').addEventListener('input', () => {
      invalidateCaches();
      clearTimeout(_wsSearchTimer);
      _wsSearchTimer = setTimeout(() => { renderWSTable(); updateWSFooter(); }, 200);
    });
  }

  // 8.11.10: 重开工作台时清空搜索框——旧实现靠 renderWSHeader 全量重建顺带清空，
  // 头部改 build-once 后需显式调用（wsSearchQuery 由 filteredData() 读输入框实时值，无需单独清）
  function resetWSSearch() {
    const inp = document.getElementById('lis-ws-search');
    if (inp && inp.value) {inp.value = '';}
  }

  function renderWSHeaderWGTabs() {
    const root = $('#lis-ws-tabs') || $('#lis-ws-hd');
    if (!root) {return;}
    const wgCounts = calcWSTabCounts();
    root.querySelectorAll('.ws-wg-tab').forEach(b => {
      const wg = b.dataset.wg;
      const isOn = wg ? wsActiveWG === wg : !wsActiveWG;
      b.classList.toggle('on', isOn);
      const tEl = b.querySelector('.ws-cnt-total');
      if (wg) {
        const c = wgCounts[wg] || { total: 0 };
        if (tEl) {tEl.textContent = c.total;}
      } else {
        // 8.17.0: 「全部」标签合计 = 自检组 + 外送（外送计入其待排/采集数）
        const totalAll = WS_WG.reduce((s, w) => s + (wgCounts[w.dr]?.total || 0), 0);
        if (tEl) {tEl.textContent = totalAll;}
      }
    });
  }

  // --- 渲染：仪器标签栏（两级：工作组 + 仪器）---
  function calcWSTabCounts() {
    // 8.9.0: 委托统一计数（单遍遍历 + 缓存）。wgCounts 条目含额外 incomplete 字段，消费方只用 total/normalReady/abnormalReady
    return calcUnifiedCounts().wgCounts;
  }

  let _tabsBuilt = false;
  let _tabsLastActiveWG = undefined;
  let _tabsLastMachineSet = ''; // 上次构建时可见仪器 DR 集合签名
  let _wsMachPopGlobalBound = false;

  function closeWSMachPopovers() {
    document.querySelectorAll('.ws-mach-popover').forEach(p => {p.style.display = 'none';});
    document.querySelectorAll('.ws-mach-wg-btn').forEach(b => {b.classList.remove('active-open');});
  }

  // 8.5.69: 判断当前要显示的机器是否都已存在标签（以「是否有新增仪器」为重建条件，
  // 而非机器数量：刷新时部分/全量加载会造成机器列表数量短暂波动，数量变化重建会导致标签闪失（历史 acd7306 同类问题）；
  // 仅当出现 DOM 里尚无标签的新仪器时才重建加标签）
  function wsNeedTabRebuild(tabs) {
    if (!_tabsBuilt || _tabsLastActiveWG !== wsActiveWG) {return true;}
    const sig = wsMachines
      .filter(m => (wsActiveWG ? String(m._wg) === String(wsActiveWG) : true))
      .map(m => String(m.RowID))
      .sort()
      .join(',');
    if (sig !== _tabsLastMachineSet) {
      // 集合变化：仅当出现「列表里有但 DOM 无标签」的新 DR 才重建；纯减少（如瞬断列表变少）不重建，避免闪
      const has = new Set();
      tabs.querySelectorAll('[data-multi-m]').forEach(b => has.add(String(b.dataset.multiM)));
      for (const m of wsMachines) {
        if ((!wsActiveWG || String(m._wg) === String(wsActiveWG)) && !has.has(String(m.RowID))) {
          return true;
        }
      }
    }
    return false;
  }

  function renderWSTabs() {
    const tabs = $('#lis-ws-tabs');
    if (!tabs) {return;}
    tabs.style.flexShrink = '0';
    const mc = wsMachineCounts;
    const wgCounts = calcWSTabCounts();
    // 首次 / 切换工作组 / 出现新仪器时重建 DOM，其余只更新状态（避免刷新时闪烁）
    const needRebuild = wsNeedTabRebuild(tabs);
    if (needRebuild) {
      _tabsBuilt = true;
      _tabsLastActiveWG = wsActiveWG;
      _tabsLastMachineSet = wsMachines
        .filter(m => (wsActiveWG ? String(m._wg) === String(wsActiveWG) : true))
        .map(m => String(m.RowID))
        .sort()
        .join(',');
      buildWSTabsDOM(tabs, wgCounts, mc);
    } else {
      updateWSTabsState(tabs, wgCounts, mc);
    }
  }

  // ==================== 8.16.7: 仪器小标签简写 ====================
  // 需求：仪器名太长（「DXI800化学发光仪」「Getein1600荧光定量」…），一排标签占满整行。
  // ⚠️ **只在「已选中某个工作组」时的那排仪器小标签上生效**——
  //    「全部仪器」模式、工作组下拉菜单（.ws-mach-popover）、卡片、详情、导出、菜单栏、
  //    推送等一切其它位置**一律仍用全称**。简写标签都带 title 全称，悬停即可看全名。
  // 选名规则（按**同一工作组内所有仪器一起**算，保证组内唯一）：
  //   ① 类别名（血细胞 / 血凝 / 尿常规 / 发光…）在本组内唯一 → 用类别名（最短、最贴现场叫法）
  //   ② 类别名在本组内重复（如免疫组 4 台发光仪）→ 改用**型号**（名称开头的字母数字串）
  //   ③ 两者都拿不到 → 保留全称（不猜、不误伤）
  //   另：只在**确实更短**（至少省 2 个字）且**短名组内不重复**时才采用，否则保留全称。
  const MACH_CATEGORY_ALIASES = [
    [/血细胞|血球|血液细胞|血常规/, '血细胞'],
    [/凝血|血凝|coag/i, '血凝'],
    [/尿(液|常规|沉渣|有形成分|分析)/, '尿常规'],
    [/粪便|大便|便常规|便潜血/, '粪便'],
    [/核酸|pcr|基因扩增|扩增/i, '核酸'],          // 必须在「荧光/发光」之前：荧光定量PCR 属核酸
    [/糖化/, '糖化'],
    [/血沉/, '血沉'],
    [/血气/, '血气'],
    [/电解质/, '电解质'],
    [/血型|配血|交叉配血/, '血型'],
    [/培养|微生物|药敏|鉴定/, '微生物'],
    [/微量元素/, '微量元素'],
    [/过敏原|变应原/, '过敏原'],
    [/自身抗体|免疫印迹|印迹法/, '自身抗体'],
    [/特定蛋白|免疫比浊|比浊/, '特定蛋白'],
    [/血流变/, '血流变'],
    [/精液/, '精液'],
    [/白带|阴道分泌物/, '白带'],
    [/生化/, '生化'],
    [/化学发光|荧光|发光|酶免|免疫分析|时间分辨/, '发光']
  ];

  // 名称开头的「字母数字型号」：DXI800化学发光仪→DXI800、Wan200+化学发光仪→Wan200+、BS-2000生化仪→BS-2000
  function machModelOf(name) {
    const m = String(name || '').match(/^[A-Za-z][A-Za-z0-9+._/-]{1,19}/);
    if (!m) {return '';}
    // 去掉尾部分隔符（BC5390-血球仪 → BC5390），但**保留 `+`**——它是型号的一部分（Wan200+）
    const s = m[0].replace(/[._/-]+$/, '');
    if (!s) {return '';}
    // 无数字又非全大写 → 多半是普通英文单词（如「Sysmex血球仪」），不当型号，交给类别名
    if (!/\d/.test(s) && !/^[A-Z]{3,}/.test(s)) {return '';}
    return s;
  }
  function machCategoryOf(name) {
    const s = String(name || '');
    for (const [re, alias] of MACH_CATEGORY_ALIASES) {
      if (re.test(s)) {return alias;}
    }
    return '';
  }
  // 返回 Map(仪器DR → 短名)。算不出短名的机器不进 Map，调用方回退全称。
  function computeMachShortLabels(machines) {
    const out = new Map();
    const list = (machines || []).map(m => ({
      id: String((m && (m.RowID != null ? m.RowID : m.id)) || ''),
      name: String((m && (m.CName || m.Name || m.text)) || '')
    })).filter(m => m.id && m.name);
    if (!list.length) {return out;}

    const cat = new Map(), model = new Map(), catUse = new Map();
    list.forEach(m => {
      const c = machCategoryOf(m.name);
      cat.set(m.id, c);
      model.set(m.id, machModelOf(m.name));
      if (c) {catUse.set(c, (catUse.get(c) || 0) + 1);}
    });

    const cand = new Map();
    list.forEach(m => {
      const c = cat.get(m.id), md = model.get(m.id);
      let s = '';
      if (c && catUse.get(c) === 1) {s = c;}     // ① 类别名组内唯一
      else if (md) {s = md;}                     // ② 同类多台 → 型号
      if (s) {cand.set(m.id, s);}
    });

    // 短名之间也要唯一（如两台都叫 BC5390）；且必须真的更短，否则保留全称
    const used = new Map();
    cand.forEach(s => used.set(s, (used.get(s) || 0) + 1));
    list.forEach(m => {
      const s = cand.get(m.id);
      if (s && used.get(s) === 1 && s.length <= m.name.length - 2) {out.set(m.id, s);}
    });
    return out;
  }

  function buildWSTabsDOM(tabs, wgCounts, mc) {
    let wgHTML = '';
    // 8.17.0: 工作组标签含外送——外送只统计「待排 + 采集」，悬停有说明
    WS_WG.forEach(w => {
      const _tip = isExternalWSWorkGroup(w.dr)
        ? ' title="外送标本：只追踪「待排 / 采集」；录入结果后自动从工作台消失（第三方出报告，本科室不审核）"'
        : '';
      wgHTML += `<button class="ws-wg-tab" data-wg="${w.dr}"${_tip}><span class="ws-tab-name">${w.name}</span><span class="mach-cnt ws-cnt-total"></span></button>`;
    });
    wgHTML += '<button class="ws-wg-tab" data-wg=""><span class="ws-tab-name">全部</span><span class="mach-cnt ws-cnt-total"></span></button>';

    let h = '<div class="ws-filter-left">';
    h += `<div class="ws-wg-inline">${wgHTML}</div>`;
    h += '<div class="ws-filter-divider"></div>';

    h += `<div class="ws-mach-row${wsActiveWG ? '' : ' all-wg'}"><span class="ws-mach-filter-label">仪器:</span>`;
    if (wsActiveWG) {
      h += `<button class="ws-mach-tab ws-mach-all" data-action="all">
                <span class="ws-tab-name">全部仪器</span>
                <span class="mach-cnt ws-cnt-mach"></span>
            </button>`;
      const wgMach = sortWSMachines(wsMachines.filter(m => m._wg === wsActiveWG));
      // 8.16.7: 该工作组的仪器短名表（只在下面这排标签用；下拉菜单/其它地方仍用全称）
      const _shortMap = computeMachShortLabels(wgMach);
      wgMach.forEach(m => {
        const mdr = String(m.RowID || '');
        const _full = String(m.CName || m.Name || '');
        const _short = _shortMap.get(mdr) || _full;
        h += `<button class="ws-mach-tab ws-mach-multi" data-multi-m="${escAttr(mdr)}" data-wg="${escAttr(wsActiveWG)}" title="${escAttr(_full)}">
                    <span class="ws-mach-check"></span>
                    <span class="ws-tab-name">${esc(_short)}</span>
                    <span class="mach-cnt ws-cnt-mach"></span>
                </button>`;
      });
    } else {
      h += `<button class="ws-mach-tab ws-mach-all" data-action="all-global">
                <span class="ws-tab-name">全部仪器</span>
                <span class="mach-cnt ws-cnt-mach"></span>
            </button>`;
      // 全部工作组下：按工作组折叠为下拉菜单，支持跨组快速勾选仪器（含外送组）
      WS_WG.forEach(w => {
        const wgMachines = sortWSMachines(wsMachines.filter(m => m._wg === w.dr));
        if (!wgMachines.length) {return;}
        const selSet = getWSSelectedMachineSet(w.dr);
        const selCount = selSet.size;

        h += `<div class="ws-mach-wg-wrap" data-wg="${escAttr(w.dr)}">`;
        h += `<button type="button" class="ws-mach-tab ws-mach-wg-btn${selCount > 0 ? ' on' : ''}" data-wg="${escAttr(w.dr)}" title="点击展开${escAttr(w.name)}仪器列表">
                <span class="ws-tab-name">${esc(w.name)}${selCount > 0 ? ` · ${selCount}台` : ''} ▾</span>
              </button>`;
        h += `<div class="ws-mach-popover" id="lis-mach-pop-${escAttr(w.dr)}" style="display:none">`;
        h += `<div class="ws-mach-pop-hd">
                <span class="ws-mach-pop-title" style="color:${w.color || 'var(--lis-text)'}"><b>${esc(w.name)}</b> 仪器 (${wgMachines.length}台)</span>
                <div class="ws-mach-pop-actions">
                  <span class="ws-mach-pop-act" data-pop-act="all" data-wg="${escAttr(w.dr)}">全选</span>
                  <span class="ws-mach-pop-sep">|</span>
                  <span class="ws-mach-pop-act" data-pop-act="none" data-wg="${escAttr(w.dr)}">清空</span>
                </div>
              </div>`;
        h += '<div class="ws-mach-pop-list">';
        wgMachines.forEach(m => {
          const mdr = String(m.RowID || '');
          const count = (mc[mdr] || { total: 0 }).total;
          const isChecked = selSet.has(mdr);
          h += `<div class="ws-mach-pop-item ws-mach-multi${isChecked ? ' on' : ''}${count === 0 ? ' zero-count' : ''}" data-multi-m="${escAttr(mdr)}" data-wg="${escAttr(w.dr)}">
                  <span class="ws-mach-check">${isChecked ? '✓' : ''}</span>
                  <span class="ws-mach-pop-name" title="${escAttr(m.CName || m.Name)}">${esc(m.CName || m.Name)}</span>
                  <span class="mach-cnt ws-cnt-mach">${count}</span>
                </div>`;
        });
        h += '</div>'; // close .ws-mach-pop-list
        h += '</div>'; // close .ws-mach-popover
        h += '</div>'; // close .ws-mach-wg-wrap
      });
    }
    h += '</div>'; // close .ws-mach-row

    h += '</div>'; // close .ws-filter-left

    h += '<div class="ws-filter-right"><span class="ws-filter-divider ws-seam-divider"></span><div class="ws-cat-hd-inline" data-ws-cat-tabs></div></div>';
    tabs.innerHTML = h;

    // 工作组下拉展开/收起
    tabs.querySelectorAll('.ws-mach-wg-btn').forEach(btn => {
      btn.addEventListener('click', e => {
        e.stopPropagation();
        const wg = btn.dataset.wg;
        const pop = tabs.querySelector(`#lis-mach-pop-${wg}`);
        if (!pop) {return;}
        const isOpen = pop.style.display === 'flex';
        closeWSMachPopovers();
        if (!isOpen) {
          pop.style.display = 'flex';
          btn.classList.add('active-open');
          const rect = btn.getBoundingClientRect();
          const popWidth = pop.offsetWidth || 240;
          const maxLeft = window.innerWidth - popWidth - 12;
          pop.style.top = `${Math.round(rect.bottom + 4)}px`;
          pop.style.left = `${Math.max(8, Math.min(Math.round(rect.left), maxLeft))}px`;
        }
      });
    });

    // 阻止下拉浮层内点击冒泡关闭
    tabs.querySelectorAll('.ws-mach-popover').forEach(pop => {
      pop.addEventListener('click', e => e.stopPropagation());
    });

    // 下拉浮层内“全选 / 清空”操作
    tabs.querySelectorAll('.ws-mach-pop-act').forEach(act => {
      act.addEventListener('click', e => {
        e.stopPropagation();
        const wg = act.dataset.wg;
        const type = act.dataset.popAct;
        if (!wg) {return;}
        invalidateCaches();
        if (type === 'all') {
          const allM = wsMachines.filter(m => String(m._wg) === String(wg)).map(m => String(m.RowID));
          setWSSelectedMachineSet(wg, new Set(allM));
        } else {
          setWSSelectedMachineSet(wg, new Set());
        }
        wsActiveMachine = '';
        wsAbnormalIndex = -1;
        wsChecked.clear();
        saveWSState();
        renderWSTabs();
        renderWSCategoryBar();
        renderWSTable();
      });
    });

    // 点击外部或按 Esc 关闭浮层（全局绑定一次）
    if (!_wsMachPopGlobalBound) {
      _wsMachPopGlobalBound = true;
      document.addEventListener('click', e => {
        if (!e.target.closest('.ws-mach-wg-wrap') && !e.target.closest('.ws-mach-popover')) {
          closeWSMachPopovers();
        }
      });
      document.addEventListener('keydown', e => {
        if (e.key === 'Escape') {
          closeWSMachPopovers();
        }
      });
      window.addEventListener('resize', () => {
        closeWSMachPopovers();
      });
    }

    // 滚轮直接在仪器栏横向滚动
    const machRow = tabs.querySelector('.ws-mach-row');
    if (machRow) {
      machRow.addEventListener('wheel', e => {
        closeWSMachPopovers();
        if (e.deltaY !== 0 && machRow.scrollWidth > machRow.clientWidth) {
          e.preventDefault();
          machRow.scrollLeft += e.deltaY;
        }
      }, { passive: false });
    }

    // 工作组标签事件绑定
    tabs.querySelectorAll('.ws-wg-tab').forEach(b =>
      b.addEventListener('click', () => {
        closeWSMachPopovers();
        invalidateCaches();
        wsActiveWG = b.dataset.wg;
        wsActiveMachine = '';
        if (wsActiveWG) {
          WS_WG.forEach(w => {
            if (String(w.dr) !== String(wsActiveWG)) {delete wsSelectedMachinesByWG[String(w.dr)];}
          });
        }
        // 8.17.0: 切到外送组时，若当前停在「待审/不完整」（外送恒为空，看着像坏了）→ 自动落到「待排」，
        // 让用户一眼看到外送还有哪些没做。外送组只有待排/采集两种状态，其余分类视图对它永远是空的。
        if (isExternalWSWorkGroup(wsActiveWG) && (wsCategory === 'audit' || wsCategory === 'incomplete')) {
          wsCategory = 'pending';
        }
        wsAbnormalIndex = -1;
        wsChecked.clear();
        saveWSState();
        renderWSHeaderWGTabs();
        renderWSTabs();
        renderWSCategoryBar();
        renderWSTable();
      })
    );

    // 仪器标签事件绑定（全部仪器）
    tabs.querySelectorAll('.ws-mach-all').forEach(b =>
      b.addEventListener('click', () => {
        invalidateCaches();
        if (wsActiveWG) {setWSSelectedMachineSet(wsActiveWG, new Set());}
        else {WS_WG.forEach(w => setWSSelectedMachineSet(w.dr, new Set()));}
        wsActiveMachine = '';
        wsAbnormalIndex = -1;
        wsChecked.clear();
        saveWSState();
        closeWSMachPopovers();
        renderWSTabs();
        renderWSCategoryBar();
        renderWSTable();
      })
    );

    // 仪器多选事件绑定（单工作组下按钮 或 下拉浮层内选项）
    tabs.querySelectorAll('.ws-mach-multi').forEach(b =>
      b.addEventListener('click', e => {
        e.stopPropagation();
        invalidateCaches();
        const mdr = String(b.dataset.multiM || '');
        const wg = b.dataset.wg || wsActiveWG || '';
        if (!wg) {return;}
        const selected = getWSSelectedMachineSet(wg);
        if (selected.has(mdr)) {selected.delete(mdr);}
        else if (mdr) {selected.add(mdr);}
        setWSSelectedMachineSet(wg, selected);
        wsActiveMachine = '';
        wsAbnormalIndex = -1;
        wsChecked.clear();
        saveWSState();
        renderWSTabs();
        renderWSCategoryBar();
        renderWSTable();
      })
    );
    updateWSTabsState(tabs, wgCounts, mc);
    renderWSCategoryBar();
  }

  // 仅更新数字和选中态（不重建 DOM，不闪烁）
  function updateWSTabsState(tabs, wgCounts, mc) {
    // Workgroup tabs are in header — update via renderWSHeaderWGTabs
    renderWSHeaderWGTabs();

    // 更新全部仪器按钮
    const allBtn = tabs.querySelector('.ws-mach-all');
    if (allBtn) {
      const isOn = wsActiveWG
        ? getWSSelectedMachineSet(wsActiveWG).size === 0
        : !WS_WG.some(w => getWSSelectedMachineSet(w.dr).size > 0);
      allBtn.classList.toggle('on', isOn);
      const el = allBtn.querySelector('.ws-cnt-mach');
      if (el) {el.textContent = (mc['_all'] || { total: 0 }).total;}
    }

    // 全部工作组下更新工作组下拉按钮文字与高亮态（含外送组）
    if (!wsActiveWG) {
      WS_WG.forEach(w => {
        const btn = tabs.querySelector(`.ws-mach-wg-btn[data-wg="${w.dr}"]`);
        if (btn) {
          const selCount = getWSSelectedMachineSet(w.dr).size;
          btn.classList.toggle('on', selCount > 0);
          const nameSpan = btn.querySelector('.ws-tab-name');
          if (nameSpan) {
            nameSpan.textContent = `${w.name}${selCount > 0 ? ` · ${selCount}台` : ''} ▾`;
          }
        }
      });
    }

    // 更新各个仪器项（平铺药丸 或 下拉浮层内选项）
    tabs.querySelectorAll('.ws-mach-multi').forEach(b => {
      const mdr = b.dataset.multiM;
      const wg = b.dataset.wg || wsActiveWG || '';
      const checked = wg ? getWSSelectedMachineSet(wg).has(mdr) : false;
      b.classList.toggle('on', checked);
      const chk = b.querySelector('.ws-mach-check');
      if (chk) {chk.textContent = checked ? '✓' : '';}
      const el = b.querySelector('.ws-cnt-mach');
      const count = (mc[mdr] || { total: 0 }).total;
      if (el) {el.textContent = count;}
      if (b.classList.contains('ws-mach-pop-item')) {
        b.classList.toggle('zero-count', count === 0);
      }
    });
  }

  // 切换工作台分类（与点击分类标签行为一致：保留勾选、刷新渲染）
  function switchWSCategory(cat) {
    if (!cat) {return;}
    // 旧版 normal/abnormal 已合并为 audit（待审）
    if (cat === 'normal' || cat === 'abnormal') {cat = 'audit';}
    invalidateCaches();
    wsCategory = cat;
    wsAbnormalIndex = -1;
    saveWSState();
    renderWSCategoryBar();
    renderWSTable();
    updateAbnormalEnterBridge();
    if (wsCategory === 'audit') {prefetchAbnormalAuditContext();}
  }

  // 8.11.14: 数字键 1-5 快速切换工作台分类标签（1 待审 / 2 不完整 / 3 待排 / 4 采集 / 5 全部）。
  // 工作台未打开 / 详情面板或历史浮层打开 / 焦点在输入框（搜索框打数字）时不劫持；
  // 命中但与当前分类相同则吞掉按键不重复渲染。返回 true 表示按键已消费
  function handleWSCategoryHotkey(e) {
    if (!isWSVisible() || isDetailPanelVisible() || histIsOpen()) {return false;}
    if (e.ctrlKey || e.altKey || e.metaKey) {return false;}
    const t = e.target;
    // 8.15.3: SELECT 一并排除——日期选择器的年/月是原生 <select>，聚焦时按 1-5 会被
    // preventDefault + stopImmediatePropagation 吞掉，导致下拉选不中年月（误切分类）
    if (
      t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' ||
        t.isContentEditable || t.closest?.('textarea,[contenteditable]'))
    ) {return false;}
    // 日期选择器打开时不劫持数字键（下拉/日期按钮在上层，避免误切分类）
    if (document.getElementById('lis-ws-date-picker')) {return false;}
    const cat = { '1': 'audit', '2': 'incomplete', '3': 'pending', '4': 'collected', '5': 'all' }[e.key];
    if (!cat) {return false;}
    e.preventDefault();
    e.stopImmediatePropagation();
    if (cat !== wsCategory) {switchWSCategory(cat);}
    return true;
  }

  // 菜单栏跳转：工作台关闭时先打开，再显示目标分类。
  function gotoWSCategoryFromMenubar(cat) {
    if (!cat) {return;}
    if (cat === 'normal' || cat === 'abnormal') {cat = 'audit';} // 旧入口统一归入待审
    if (!isWSVisible()) {
      // 必须先 openWS()：它会 applyWSState(loadWSState()) 恢复跨组仪器多选。
      // 若先 set+saveWSState()（此时内存 multiMdr 还是空 {}），会把 localStorage
      // 里的跨组勾选覆盖清空（与 checkAbnormalTarget 同类 bug）。
      openWS();
      wsCategory = cat;
      wsAbnormalIndex = -1;
      saveWSState();
      renderWSCategoryBar();
      renderWSTable();
      updateAbnormalEnterBridge();
      if (wsCategory === 'audit') {prefetchAbnormalAuditContext();}
      return;
    }
    switchWSCategory(cat);
  }

  // 菜单栏指令轮询：SwiftBar 下拉点击 → 由本地桥原子认领，避免多标签重复执行。
  let _menubarCmdTimer = null;
  let _menubarCmdLastId = 0;
  function startMenubarCmdPoller() {
    if (_menubarCmdTimer) {return;}
    _menubarCmdTimer = setInterval(() => {
      try {
        fetch('http://127.0.0.1:8765/cmd', { cache: 'no-store' })
          .then(r => (r.ok ? r.json() : null))
          .then(cmd => {
            if (!cmd || cmd.consumed) {return;}
            if (cmd.id === _menubarCmdLastId) {return;}
            if (cmd.action === 'goto' && cmd.cat) {
              fetch('http://127.0.0.1:8765/cmd/claim', {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain' },
                body: JSON.stringify({ id: cmd.id })
              })
                .then(r => (r.ok ? r.json() : null))
                .then(result => {
                  if (!result) {return;}
                  _menubarCmdLastId = cmd.id;
                  if (result.claimed) {gotoWSCategoryFromMenubar(cmd.cat);}
                })
                .catch(() => {});
            } else {
              _menubarCmdLastId = cmd.id;
            }
          })
          .catch(() => {});
      } catch (e) {}
    }, 1500);
  }

  // 把「当前筛选范围」计数推给本地菜单栏桥（localhost:8765）。失败静默，绝不影响审核。
  let _menubarPushTimer = null;
  let _menubarLastStats = null; // 最后一次推送的 stats，用于 keep-alive
  function pushMenubarStats(counts) {
    clearTimeout(_menubarPushTimer);
    _menubarLastStats = counts;
    _menubarPushTimer = setTimeout(() => {
      try {
        fetch('http://127.0.0.1:8765/stats', {
          method: 'POST',
          headers: { 'Content-Type': 'text/plain' }, // text/plain 免 CORS 预检
          body: JSON.stringify(counts),
          keepalive: true
        }).catch(() => {});
      } catch (e) {}
    }, 300); // 去抖，避免频繁渲染刷爆
  }
  // keep-alive：每 30 秒重推最后已知 stats，防止菜单栏显示「已过期」
  let _menubarKeepAliveTimer = null;
  function startMenubarKeepAlive() {
    if (_menubarKeepAliveTimer) {return;}
    _menubarKeepAliveTimer = setInterval(() => {
      if (!_menubarLastStats) {return;}
      try {
        fetch('http://127.0.0.1:8765/stats', {
          method: 'POST',
          headers: { 'Content-Type': 'text/plain' },
          body: JSON.stringify(_menubarLastStats),
          keepalive: true
        }).catch(() => {});
      } catch (e) {}
    }, 30000);
  }

  // 推导「当前筛选范围」的可读名称：全部 / 某工作组全部 / 某工作组选N台 / 具体仪器名
  function describeWSScope() {
    if (!wsActiveWG && !wsActiveMachine) {
      const anyMulti = Object.values(wsSelectedMachinesByWG || {}).some(s => s && s.length);
      return anyMulti ? '多工作组(自定义)' : '全部仪器';
    }
    const wgName = wsActiveWG ? (WG_MAP[wsActiveWG] || {}).name || wsActiveWG : '';
    const sel = wsActiveWG ? [...wsMachineFilterSetForActiveWG()] : wsActiveMachine ? [wsActiveMachine] : [];
    if (!sel.length) {return wgName ? `${wgName}(全部仪器)` : '全部仪器';}
    if (sel.length === 1) {
      const m = wsMachines.find(x => String(x.RowID) === String(sel[0]));
      const mn = (m && (m.CName || m.Name)) || sel[0];
      return wgName ? `${wgName} · ${mn}` : mn;
    }
    return wgName ? `${wgName}(${sel.length}台)` : `${sel.length}台仪器`;
  }

  let _catBarBuilt = false; // 分类标签栏是否已构建 DOM

  // --- 渲染：分类标签栏 ---
  function renderWSCategoryBar() {
    // 8.11.8: 容器缺失时（筛选行被外部重建等）分类标签会渲染失败且无法自愈
    //（「待审/不完整小标签全没了」的历史同类故障）。8.11.10 起兜底一律就地重建容器，
    // 旧 #lis-ws-bar 隐藏兜底容器与 .ws-cat-row-inline 死类已删除。
    let bar = $('.ws-cat-hd-inline');
    if (!bar) {
      const host = $('.ws-filter-right') || $('#lis-ws-tabs');
      if (host) {
        bar = document.createElement('div');
        bar.className = 'ws-cat-hd-inline';
        bar.setAttribute('data-ws-cat-tabs', '');
        host.appendChild(bar);
        dbg('分类栏容器缺失，已就地重建');
      }
    }
    if (!bar) {return;}
    bar.style.flexShrink = '0';

    // 8.16.6: 接缝分隔线随容器一起兜底——外部重建筛选行时若把它弄丢了，这里补回来
    //（它与 .ws-cat-hd-inline 同属「仪器筛选 / 状态切换」两组的分界，缺了就又贴在一起）
    const _right = bar.closest('.ws-filter-right');
    if (_right && !_right.querySelector('.ws-seam-divider')) {
      const dv = document.createElement('span');
      dv.className = 'ws-filter-divider ws-seam-divider';
      _right.insertBefore(dv, bar);
    }

    // 统计各分类数量（基于当前工作组+仪器过滤）
    // 8.9.0: 计数来自统一单遍统计（含当前仪器过滤范围 f* 计数，已排除忽略行）——
    // 此前这里对全量 wsData 再单独跑一遍 getWSAuditBucket O(N)
    const _uc = calcUnifiedCounts();
    const normalCount = _uc.fNormal;
    const abnormalCount = _uc.fAbnormal;
    const incompleteCount = _uc.fIncomplete;
    const pendingCount = _uc.fPending;
    const collectedCount = _uc.fCollected;
    const totalCount = _uc.fTotal;
    const fd = filteredData();

    // 首次或切换分类时重建 DOM，其余只更新计数和状态
    // 8.9.2: 除旗帜外再校验 DOM 里是否真有标签——keepWorkbenchOnTop/renderWSHeader 重建头部会
    // 连带清空分类栏 DOM，旧逻辑只看 _catBarBuilt 旗帜导致清空后永不重建
    //（「待审/不完整小标签全没了、退出重进才恢复」的根因）。DOM 校验让任何路径清空后下一拍自愈
    if (!_catBarBuilt || !bar.querySelector('.cat-tab')) {
      _catBarBuilt = true;
      _buildCategoryBarDOM(bar);
    }
    _updateCategoryBarState(bar, normalCount, abnormalCount, incompleteCount, pendingCount, collectedCount, totalCount);

    updateWSFooter({
      // 8.5.34: visible 也排除忽略行，避免「可见 5 / 总 3条」倒挂
      visible: fd.filter(r => !isWSIgnored(r.ReportDR)).length,
      total: totalCount,
      normal: normalCount,
      abnormal: abnormalCount,
      incomplete: incompleteCount,
      pending: pendingCount,
      collected: collectedCount // 8.5.31
    });

    // 推菜单栏（当前筛选范围合计）
    pushMenubarStats({
      scope: describeWSScope(),
      url: location.href,
      viewDate: wsViewDate(), // 8.7.0: 当前查看日期——历史视图时菜单栏可据此标注，避免误读为当日待审
      normalReady: normalCount,
      abnormalReady: abnormalCount,
      auditReady: normalCount + abnormalCount,
      mildReady: _uc.fMild || 0, // 8.12.0: 轻微异常可批审数（F4 队列扩容部分）
      pending: pendingCount,
      incomplete: incompleteCount,
      collected: collectedCount, // 8.5.31
      total: totalCount
    });

    // 8.5.40: 更新「当前 CA 认证账号」徽标（异步取默认账号）
    updateCaUserBadge();
  }

  // 8.5.40: 工作台右侧显示当前 CA 认证账号（审核者），保证审核身份正确
  // 8.5.41: 只显示备注名（无备注则兜底用户名），完整信息放悬停提示，避免拥挤
  function updateCaUserBadge() {
    const el = document.querySelector('.cat-ca');
    if (!el) {return;}
    caDefaultAccount().then(acc => {
      const cur = _caAccountCurUser();
      const explicit = String(localStorage.getItem(K.caDefaultUser) || '');
      const id = acc ? acc.id : '';
      const note = acc && acc.note ? acc.note : '';
      const tag = cur && id === cur ? '当前登录' : explicit && id === explicit ? '默认' : '';
      el.title = id
        ? `CA认证账号：${id}${note ? ' · ' + note : ''}${tag ? '（' + tag + '）' : ''}`
        : '尚未配置 CA 账号';
      el.textContent = note || id || ''; // 有备注显示备注，无备注兜底用户名
    }).catch(() => {});
  }

  function _buildCategoryBarDOM(bar) {
    let h = '';

    // 8.10.12: 分类栏仅保留 5 个纯粹小标签，位置绝对固定、永不跳动
    // 8.16.6: 5 个标签包进 .cat-tabs-box —— 仪器多时它们会与左侧仪器小标签顶到一起，
    //         加一层浅底容器把「状态切换」和「仪器筛选」在视觉上分成两组。
    h += '<div class="cat-tabs-box">';
    h += '<button class="cat-tab cat-audit" data-cat="audit">\n            🔍待审 <span class="cat-cnt">0</span>\n        </button>';
    h += '<button class="cat-tab cat-incomplete" data-cat="incomplete">\n            📋不完整 <span class="cat-cnt">0</span>\n        </button>';
    h += '<button class="cat-tab cat-pending" data-cat="pending">\n            📝待排 <span class="cat-cnt">0</span>\n        </button>';
    h += '<button class="cat-tab cat-collected" data-cat="collected" title="病房已采未送到科室的标本（仅供追踪/催送）">\n            🩸采集 <span class="cat-cnt">0</span>\n        </button>';
    h += '<button class="cat-tab" data-cat="all">\n            📃全部 <span class="cat-cnt">0</span>\n        </button>';
    h += '</div>';

    // 8.10.12: 批审功能由下方醒目的「一键批审正常 N · F4」横幅及 F4 热键统一承载，顶部栏不再放置多余批审按钮
    h += '<div class="cat-right"><span class="cat-stats cat-ca" title="当前 CA 认证账号（审核者）"></span></div>';

    bar.innerHTML = h;

    // 分类标签事件
    bar.querySelectorAll('.cat-tab').forEach(b =>
      b.addEventListener('click', () => {
        switchWSCategory(b.dataset.cat);
      })
    );

    // 8.5.61: 自动审核按钮已移至头部（事件绑定在 renderWSHeader）
  }

  function _updateCategoryBarState(bar, normalCount, abnormalCount, incompleteCount, pendingCount, collectedCount, totalCount) {
    // 更新计数（不重建 DOM）
    const cntMap = {
      audit: normalCount + abnormalCount,
      incomplete: incompleteCount,
      pending: pendingCount,
      collected: collectedCount || 0,
      all: totalCount
    };
    bar.querySelectorAll('.cat-tab').forEach(b => {
      const cat = b.dataset.cat;
      b.classList.toggle('on', cat === wsCategory);
      const cnt = b.querySelector('.cat-cnt');
      if (cnt) {cnt.textContent = cntMap[cat] || 0;}
    });

    // 8.5.58: 自动审核按钮状态（开启时显示剩余时长）
    renderAutoAuditButtonState();
  }

  // 8.11.11: 批审前置安全校验（分类完成 / 无失效分类 / 全部可自动审核 / 非空）——
  // 直审路径（F4/横幅按钮）与确认弹窗路径共用，未过校验一律不启动批审
  function validateBatchAudit(normalData) {
    if (wsClassifying) {
      showToast('标本正在分类中，请等候分类完成后再批审', 'warning');
      return false;
    }
    // 8.12.0: MILD 条目用轻微带口径做失效校验（isLiveMildForBatch），NORMAL 口径不变
    const stale = normalData.filter(sp => {
      const dr = sp.reportDR || (sp.row && sp.row.ReportDR);
      if (String(sp.status) === 'MILD') {return !isLiveMildForBatch(dr);}
      return !isLiveNormalForBatch(dr);
    });
    if (stale.length > 0) {
      const first = stale[0].row || stale[0];
      showToast(`分类状态已变化或未完成：${first.PatName || first.Labno || ''}，请刷新工作台后重试`, 'error');
      return false;
    }
    const blocked = normalData.filter(
      r => !isAutoAuditableClassified(r) && !(String(r.status) === 'MILD' && r.mild && r.mild.ok)
    );
    if (blocked.length > 0) {
      const first = blocked[0];
      showToast(getAutoAuditBlockReason(first, first.row) || '包含不可自动审核的标本', 'error');
      return false;
    }
    if (normalData.length === 0) {
      showToast('没有可审核的标本', 'warning');
      return false;
    }
    return true;
  }

  // 工作台「正常可审」一键批审入口（按钮 / F4 共用）
  // 有勾选则只审勾选中的正常标本，否则审当前筛选下全部正常可审
  // 8.11.11: 免确认——F4/按钮校验通过后直接批审（危急值/异常/不可自动审核标本本就被排除，
  // 且批审中有进度条 + ⏹停止按钮兜底），不再要求「再按一次 F4 确认」
  function openWorkbenchBatchAudit() {
    try {
      if (_auditInProgress || _abnormalAuditInProgress || _detailAuditInProgress) {
        showToast('正在审核中，请稍候', 'warning');
        return false;
      }
      let currentFiltered = wsData;
      if (wsActiveWG || wsActiveMachine || WS_WG.some(w => getWSSelectedMachineSet(w.dr).size > 0))
      {currentFiltered = currentFiltered.filter(rowPassWSMachineFilter);}

      let sourceData;
      if (wsChecked.size > 0) {
        sourceData = currentFiltered.filter(r => wsChecked.has(r.ReportDR));
      } else {
        sourceData = currentFiltered;
      }
      // 与视图口径统一：用 getWSAuditBucket 判定（含 Status!=0 待排过滤），
      // 避免「全部视图勾选的待排标本」被批审而待审视图不显示（8.5.x 批审数与显示数不一致）
      // 8.12.0: 队列扩容——严格 NORMAL 之外，纳入「整管异常都在轻微带内且乙类 ≤8 项」的
      // ABNORMAL 标本（classifyMildAbnormal，带 _classifyVersion 记忆）。分类桶不动：
      // 这些标本在工作台仍显示为异常、夜里机器人照旧按异常逐条口径处理
      const mildEvalOf = r => {
        const c = wsClassifiedCache[r.ReportDR];
        const m = c ? classifyMildAbnormal(c) : null;
        return m && m.ok ? m : null;
      };
      const normalData = sourceData
        .filter(r => {
          const b = getWSAuditBucket(r);
          if (b === 'normal') {return true;}
          return b === 'abnormal' && !!mildEvalOf(r);
        })
        .map(r => {
          const cached = wsClassifiedCache[r.ReportDR];
          if (getWSAuditBucket(r) === 'normal') {
            return {
              status: 'NORMAL',
              items: (cached && cached.items) || [],
              row: r,
              reportDR: r.ReportDR
            };
          }
          return {
            status: 'MILD',
            mild: mildEvalOf(r),
            items: (cached && cached.items) || [],
            row: r,
            reportDR: r.ReportDR
          };
        });
      const nMildQ = normalData.filter(x => String(x.status) === 'MILD').length;
      const nNormQ = normalData.length - nMildQ;
      if (normalData.length === 0) {
        if (wsClassifying) {
          showToast('标本正在分类中，请稍候再试', 'warning');
        } else if (wsChecked.size > 0) {
          showToast('勾选中没有可审核的正常标本', 'warning');
        } else {
          showToast('没有可审核的正常标本', 'warning');
        }
        return false;
      }
      if (!validateBatchAudit(normalData)) {return false;}
      dbg('一键批审(直审):', normalData.length, '个标本（正常', nNormQ, '· 轻微异常', nMildQ, '）');
      showToast(
        `⚡ 开始批审 ${nNormQ} 个正常${nMildQ ? ` + ${nMildQ} 个轻微异常` : ''}（首条自动 CA 认证，进度条可停止）`,
        'success'
      );
      // 与旧确认弹窗路径同款排序：按审核视图顺序（仪器分组、危急→异常→正常）逐条审
      const sorted = [...normalData].sort((a, b) => compareSpecimensForAudit(a.row || a, b.row || b));
      // 8.15.3: 轻微异常留痕改到批审结束后、且只记真正审过的（queue.done）——此前在批审启动前
      // 就全量记账，中途点 ⏹ 停止或失败时日志里仍留下「已放行」，回溯会与实际审核结果不符
      const mildQueue = nMildQ > 0 ? normalData.filter(x => String(x.status) === 'MILD') : [];
      executeBatchAudit(sorted)
        .then(q => {
          if (!mildQueue.length || !q || !Array.isArray(q.done)) {return;}
          const doneSet = new Set(q.done.map(it => String(it.reportDR)));
          recordMildAuditLog(mildQueue.filter(sp => doneSet.has(String(sp.reportDR || (sp.row && sp.row.ReportDR)))));
        })
        .catch(e => {
          console.error('[LIS] 批审异常:', e);
          showToast('批审出错: ' + e.message, 'error');
        });
      return true;
    } catch (e) {
      dbg('一键批审错误:', e);
      showToast('批审出错: ' + e.message, 'error');
      return false;
    }
  }

  // --- 渲染：数据表 ---
  // --- 渲染：数据表（分发到各分类视图）---
  let _abnormalKeyHandler = null; // 异常视图键盘监听器
  let _abnormalKeyTargets = [];
  let _abnormalGridHijackHandler = null;
  let _abnormalEnterLastAt = 0;

  function isDetailPanelVisible() {
    return !!(detailPanel && detailPanel.classList.contains('show'));
  }

  function updateAbnormalEnterBridge() {
    const active = wsCategory === 'audit' && isWSVisible() && !isDetailPanelVisible();
    try {
      window.__lisAbnormalEnterActive = active;
      window.__lisAbnormalEnterToken = active
        ? Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 12)
        : '';
    } catch (e) {}
  }

  function isTrustedAbnormalEnterMessage(e) {
    if (!e || !e.data || e.data.type !== 'lis-enhancer-abnormal-enter') {return false;}
    const reportWin = getReportIframeWin();
    if (!reportWin || e.source !== reportWin) {return false;}
    if (e.origin !== window.location.origin) {return false;}
    const token = window.__lisAbnormalEnterToken;
    return !!(token && e.data.token === token);
  }

  function releaseNativeReportFocus(iframeWin) {
    iframeWin = iframeWin || getReportIframeWin();
    if (!iframeWin) {return;}
    try {
      if (typeof iframeWin.__lisEnhancerReleaseReportFocus === 'function') {
        iframeWin.__lisEnhancerReleaseReportFocus();
        return;
      }
    } catch (e) {}
    const jq = iframeWin.jQuery || iframeWin.$;
    if (!jq) {return;}
    try {
      jq('.datagrid-editable-input').blur();
      jq('#dgLeftReportItem, #dgRightReportItem').each(function () {
        const grid = jq(this);
        if (!grid.length || !grid.datagrid) {return;}
        try {
          grid.datagrid('endEdit');
        } catch (e) {}
        try {
          grid.datagrid('clearSelections');
        } catch (e) {}
        try {
          const panel = grid.datagrid('getPanel').panel('panel');
          if (panel && panel[0] && panel[0].blur) {panel[0].blur();}
        } catch (e) {}
      });
    } catch (e) {}
    try {
      if (iframeWin.editIndex !== undefined) {iframeWin.editIndex = undefined;}
      if (iframeWin.editDatagrid !== undefined) {iframeWin.editDatagrid = undefined;}
    } catch (e) {}
    try {
      const ae = iframeWin.document.activeElement;
      if (ae && ae !== iframeWin.document.body && typeof ae.blur === 'function') {ae.blur();}
    } catch (e) {}
  }

  function triggerAbnormalEnterAudit() {
    updateAbnormalEnterBridge();
    if (wsCategory !== 'audit' || !isWSVisible() || isDetailPanelVisible()) {return false;}
    const now = Date.now();
    if (_abnormalAuditInProgress) {
      if (!_abnormalAuditQueued) {
        _abnormalAuditQueued = true;
        const ft = document.getElementById('lis-ws-ft-stat');
        if (ft) {ft.textContent = '⏳ 当前条审完后自动审下一条（已排队）';}
        showToast('下一条已排队，当前条完成后自动继续', 'info');
      }
      return true;
    }
    if (now - _abnormalEnterLastAt < 140) {return true;}
    _abnormalEnterLastAt = now;
    const curData = filteredData();
    if (!curData.length) {return false;}
    if (wsAbnormalIndex < 0 || wsAbnormalIndex >= curData.length) {wsAbnormalIndex = 0;}
    const sp = getAbnormalFocusSpecimen(curData);
    if (!sp) {return false;}
    markAbnormalAuditUI(sp, 'start');
    void auditAbnormalSpecimen(sp);
    return true;
  }

  function handleAbnormalEnterAudit(e) {
    if (wsCategory !== 'audit' || isDetailPanelVisible()) {return false;}
    if (!e || e.key !== 'Enter' || e.shiftKey) {return false;}
    if (shouldIgnoreAbnormalKeyEvent(e)) {return false;}
    e.preventDefault();
    e.stopImmediatePropagation();
    return triggerAbnormalEnterAudit() || true;
  }

  function installPageContextAbnormalEnterHijack(iframeWin) {
    iframeWin = iframeWin || getReportIframeWin();
    if (!iframeWin) {return;}
    try {
      if (iframeWin.__lisPageEnterHijack) {return;}
      const doc = iframeWin.document;
      const s = doc.createElement('script');
      s.setAttribute('data-lis-enhancer', 'abnormal-enter');
      s.textContent = `(function(){
var KEY='__lisEnhancerAbnormalEnter';
if(window[KEY])return;
window[KEY]=true;
window.__lisEnhancerReleaseReportFocus=function(){
  try{
    var jq=window.jQuery||window.$;
    if(jq){
      jq('.datagrid-editable-input').blur();
      jq('#dgLeftReportItem,#dgRightReportItem').each(function(){
        try{jq(this).datagrid('endEdit');jq(this).datagrid('clearSelections');}catch(e){}
      });
    }
    if(typeof editIndex!=='undefined')editIndex=undefined;
    if(typeof editDatagrid!=='undefined')editDatagrid=undefined;
    var ae=document.activeElement;
    if(ae&&ae!==document.body&&ae.blur)ae.blur();
  }catch(e){}
};
window.addEventListener('keydown',function(e){
  if(e.key!=='Enter'||e.shiftKey)return;
  var active=false,token='',origin='';
  try{
    active=!!(window.parent&&window.parent.__lisAbnormalEnterActive);
    token=String(window.parent.__lisAbnormalEnterToken||'');
    origin=window.parent.location.origin;
  }catch(err){}
  if(!active||!token)return;
  try{window.parent.postMessage({type:'lis-enhancer-abnormal-enter',token:token},origin);}catch(err){}
  e.preventDefault();
  e.stopImmediatePropagation();
},true);
})();`;
      (doc.head || doc.documentElement).appendChild(s);
      s.remove();
      iframeWin.__lisPageEnterHijack = true;
      dbg('报告页页面上下文 Enter 劫持已注入');
    } catch (e) {
      dbg('注入报告页 Enter 劫持失败:', e.message);
    }
  }

  function installAbnormalResultGridEnterHijack(iframeWin) {
    installPageContextAbnormalEnterHijack(iframeWin);
    iframeWin = iframeWin || getReportIframeWin();
    if (!iframeWin) {return;}
    const jq = iframeWin.jQuery || iframeWin.$;
    if (!jq) {return;}
    if (!_abnormalGridHijackHandler) {
      _abnormalGridHijackHandler = e => {
        handleAbnormalEnterAudit(e);
      };
    }
    ['#dgLeftReportItem', '#dgRightReportItem'].forEach(sel => {
      try {
        const grid = jq(sel);
        if (!grid.length || !grid.datagrid) {return;}
        const panel = grid.datagrid('getPanel').panel('panel')[0];
        if (!panel) {return;}
        if (panel.__lisAbnormalEnterHandler) {
          panel.removeEventListener('keydown', panel.__lisAbnormalEnterHandler, true);
        }
        panel.__lisAbnormalEnterHandler = _abnormalGridHijackHandler;
        panel.addEventListener('keydown', _abnormalGridHijackHandler, true);
      } catch (e) {}
    });
  }


  // F4 统一入口优先级：
  // 2) 待审视图（正常+异常已合并 8.5.0）→ 直接批审正常标本（8.11.11 免确认）
  // 注：详情面板内 F4 已取消（8.5.1），由 _f4BridgeHandler 直接吞掉
  function triggerF4Audit() {
    // 8.11.14: 确认弹窗链路（Alt+B 旧通道）已随 Alt 快捷键一并移除，F4 一律直审
    if (isWSVisible() && wsCategory === 'audit') {
      openWorkbenchBatchAudit();
      return;
    }
    return;
  }

  // 常驻 Enter 桥：挂到报告页 iframe，不被 openDetailPanel 的 _removeAbnormalKeyHandler 影响。
  // 详情面板打开时异常视图处理器会被移除，故 Enter 在面板内（焦点常在原生 iframe）必须由本桥捕获。
  let _f4BridgeHandler = null;
  const _f4BridgeTargets = [];
  let _f4BridgeTimer = null;
  function _installF4Bridge() {
    if (_f4BridgeHandler) {
      _attachF4BridgeToIframe();
      return;
    }
    _f4BridgeHandler = e => {
      if (histIsOpen()) {return;} // 历史浮层打开时 F4/Enter 全部让位（避免隔层误审）
      if (shouldIgnoreAbnormalKeyEvent(e)) {return;}
      // 详情面板打开时：Enter 审当前详情（焦点常在原生 iframe，Enter 必须靠桥捕获）；
      // F4 在详情面板内已取消（8.5.1），只保留 Enter + 面板「审核」按钮
      if (isDetailPanelVisible() && currentDetailSpecimen) {
        if (e.key === 'Enter' && !e.shiftKey) {
          // 8.5.82: 焦点在任何可编辑元素时放行原生行为（含原生 LIS 报告页 iframe 的输入框/编辑单元格）——
          // 否则用户在原生页编辑结果/备注按回车提交输入，会被抢注为详情面板的真实审核
          if (isEditableEventTarget(e)) {return;}
          // 焦点在详情面板内的按钮上时，放行按钮默认行为（Enter=点「关闭」/「审核」），不抢为审核
          const inPanelBtn = e.target && e.target.closest ? e.target.closest('#lis-detail-panel button') : null;
          if (inPanelBtn) {return;}
          e.preventDefault();
          e.stopImmediatePropagation();
          void _auditFromDetailPanel();
        }
        return;
      }
      if (e.key !== 'F4') {return;}
      // 待审列表：F4 直接批审正常标本（8.11.11 免确认弹窗）
      if (isWSVisible() && wsCategory === 'audit') {
        e.preventDefault();
        e.stopImmediatePropagation();
        triggerF4Audit();
        return;
      }
      return;
    };
    document.addEventListener('keydown', _f4BridgeHandler, true);
    _f4BridgeTargets.push(document);
    _attachF4BridgeToIframe();
    // 定时巡检：报告 iframe 重载/重开后 document 会换新，桥必须跟上，否则 F4 静默失效；
    // 同时清掉已 detached 的旧目标，避免 _f4BridgeTargets 只增不减挂住旧 document
    if (!_f4BridgeTimer) {
      _f4BridgeTimer = setInterval(() => {
        try {
          _pruneF4BridgeTargets();
          _attachF4BridgeToIframe();
        } catch (e) {}
      }, 2000);
    }
  }
  function _pruneF4BridgeTargets() {
    for (let i = _f4BridgeTargets.length - 1; i >= 0; i--) {
      const t = _f4BridgeTargets[i];
      if (t === document || t === window) {continue;} // 主页面常驻，不清理
      try {
        const d = t.nodeType === 9 ? t : t.document; // document 或 iframe window
        if (!d || !d.documentElement || !d.defaultView) {
          try {t.removeEventListener('keydown', _f4BridgeHandler, true);} catch (e) {}
          _f4BridgeTargets.splice(i, 1);
        }
      } catch (e) {
        _f4BridgeTargets.splice(i, 1);
      }
    }
  }
  function _attachF4BridgeToIframe() {
    if (!_f4BridgeHandler) {return;}
    const iframeWin = getReportIframeWin();
    if (!iframeWin || !iframeWin.document || iframeWin.document === document) {return;}
    if (!_f4BridgeTargets.includes(iframeWin.document)) {
      try {
        iframeWin.document.addEventListener('keydown', _f4BridgeHandler, true);
        _f4BridgeTargets.push(iframeWin.document);
      } catch (e) {}
    }
    if (!_f4BridgeTargets.includes(iframeWin)) {
      try {
        iframeWin.addEventListener('keydown', _f4BridgeHandler, true);
        _f4BridgeTargets.push(iframeWin);
      } catch (e) {}
    }
  }
  function _removeF4BridgeHandler() {
    if (!_f4BridgeHandler) {return;}
    if (_f4BridgeTimer) {
      clearInterval(_f4BridgeTimer);
      _f4BridgeTimer = null;
    }
    for (const target of _f4BridgeTargets) {
      try {
        target.removeEventListener('keydown', _f4BridgeHandler, true);
      } catch (e) {}
    }
    _f4BridgeTargets.length = 0;
    _f4BridgeHandler = null;
  }

  function _attachAbnormalKeyToIframe() {
    if (!_abnormalKeyHandler) {return;}
    const iframeWin = getReportIframeWin();
    if (!iframeWin || !iframeWin.document || iframeWin.document === document) {return;}
    if (_abnormalKeyTargets.includes(iframeWin.document)) {return;}
    try {
      iframeWin.document.addEventListener('keydown', _abnormalKeyHandler, true);
      _abnormalKeyTargets.push(iframeWin.document);
    } catch (e) {}
    try {
      if (!_abnormalKeyTargets.includes(iframeWin)) {
        iframeWin.addEventListener('keydown', _abnormalKeyHandler, true);
        _abnormalKeyTargets.push(iframeWin);
      }
    } catch (e) {}
    installAbnormalResultGridEnterHijack(iframeWin);
    _attachF4BridgeToIframe();
  }

  function syncAbnormalFocusFromDOM() {
    // 8.9.0: 用本脚本文档查询——工作台元素挂在脚本所在文档，此前用 getUIDoc()（=top 文档），
    // 脚本一旦在子 iframe 运行会静默查不到元素
    const card = document.querySelector('.ws-abnormal-card.focused');
    if (!card) {return;}
    _abnormalFocusDR = String(card.dataset.rdr || '');
    const data = filteredData();
    const idx = data.findIndex(r => String(r.ReportDR) === _abnormalFocusDR);
    if (idx >= 0) {wsAbnormalIndex = idx;}
  }

  function refocusAbnormalWorkbench() {
    // 8.10.13: 用户正在输入框打字（如工作台搜索框）时不抢焦点
    const _ae = document.activeElement;
    if (_ae && /^(INPUT|TEXTAREA|SELECT)$/i.test(_ae.tagName)) {return;}
    releaseNativeReportFocus();
    try {
      (document.defaultView || window).focus(); // 8.9.0: 聚焦工作台所在窗口，而非固定 top
    } catch (e) {}
    const card = document.querySelector('.ws-abnormal-card.focused');
    if (card) {
      if (!card.hasAttribute('tabindex')) {card.setAttribute('tabindex', '-1');}
      try {
        card.focus({ preventScroll: true });
      } catch (e) {
        try {
          card.focus();
        } catch (e2) {}
      }
      syncAbnormalFocusFromDOM();
      return;
    }
    const wsEl = document.getElementById('lis-ws');
    if (wsEl) {
      if (!wsEl.hasAttribute('tabindex')) {wsEl.setAttribute('tabindex', '-1');}
      try {
        wsEl.focus({ preventScroll: true });
      } catch (e) {
        try {
          wsEl.focus();
        } catch (e2) {}
      }
    }
    syncAbnormalFocusFromDOM();
  }

  function scheduleAbnormalFocusRecovery() {
    // 详情面板打开时不恢复列表焦点：避免跨组续审重开详情后焦点被抢回列表卡片
    if (isDetailPanelVisible()) {return;}
    updateAbnormalEnterBridge();
    releaseNativeReportFocus();
    refocusAbnormalWorkbench();
    installAbnormalResultGridEnterHijack();
    [80, 200, 450, 900, 1800].forEach(ms => {
      setTimeout(() => {
        if (wsCategory !== 'audit' || _abnormalAuditInProgress || isDetailPanelVisible()) {return;}
        updateAbnormalEnterBridge();
        releaseNativeReportFocus();
        refocusAbnormalWorkbench();
        installAbnormalResultGridEnterHijack();
      }, ms);
    });
  }

  function _rebindAbnormalKeyHandler() {
    if (_abnormalKeyHandler) {
      _attachAbnormalKeyToIframe();
      return;
    }
    _abnormalKeyHandler = e => {
      if (shouldIgnoreAbnormalKeyEvent(e)) {return;}
      if (histIsOpen()) {return;} // 历史浮层打开时工作台按键全部让位
      if (wsCategory !== 'audit') {return;}
      // 8.11.14: 数字键 1-5 切分类（输入框聚焦时不劫持，见 handleWSCategoryHotkey）
      if (handleWSCategoryHotkey(e)) {return;}
      // F4：无论面板是否打开都处理（待审视图处理器已挂到 iframe，可捕获原生页焦点下的按键）
      // 面板打开时用 currentDetailSpecimen 调面板同款审核；面板未开时用列表焦点标本。
      if (e.key === 'F4') {
        e.preventDefault();
        e.stopImmediatePropagation();
        if (isDetailPanelVisible()) {return;} // 详情面板内 F4 已取消（8.5.1），防重装后误触发
        triggerF4Audit();
        return;
      }
      if (isDetailPanelVisible()) {return;}
      if (_abnormalAuditInProgress && e.key === 'Enter') {
        handleAbnormalEnterAudit(e);
        return;
      }
      if (e.defaultPrevented) {return;}
      const curData = filteredData();
      if (!curData.length) {return;}
      if (wsAbnormalIndex < 0 || wsAbnormalIndex >= curData.length) {wsAbnormalIndex = 0;}
      if (e.key === 'ArrowDown' || e.key === 'j') {
        e.preventDefault();
        moveAbnormalFocus(1, curData);
      } else if (e.key === 'ArrowUp' || e.key === 'k') {
        e.preventDefault();
        moveAbnormalFocus(-1, curData);
      } else if (e.key === 'Enter' && !e.shiftKey) {
        handleAbnormalEnterAudit(e);
      } else if (e.key === ' ' || e.code === 'Space') {
        e.preventDefault();
        e.stopImmediatePropagation();
        advanceAbnormalFocusAfterSkip(wsAbnormalIndex);
      } else if (e.key === 'm' || e.key === 'M') {
        // 8.17.4: M = 直达电子病历（与详情面板同一个键；Shift+M = 直接唤起原生 32 位 IE）
        e.preventDefault();
        e.stopImmediatePropagation();
        openEMRForWSRow(getAbnormalFocusSpecimen(curData), e.shiftKey);
      } else if (e.key === 'Enter' && e.shiftKey) {
        e.preventDefault();
        e.stopImmediatePropagation();
        const sp = getAbnormalFocusSpecimen(curData);
        if (sp) {openDetailPanel(sp, 'abnormal', wsAbnormalIndex);}
      } else if (e.key === 'Escape') {
        // 待审视图 Esc = 关闭工作台（与其它查看视图一致）
        e.preventDefault();
        closeWS();
      }
    };
    _abnormalKeyTargets = [document];
    try {
      document.addEventListener('keydown', _abnormalKeyHandler, true);
    } catch (e) {}
    try {
      window.addEventListener('keydown', _abnormalKeyHandler, true);
      _abnormalKeyTargets.push(window);
    } catch (e) {}
    _attachAbnormalKeyToIframe();
  }

  function _removeAbnormalKeyHandler() {
    if (!_abnormalKeyHandler) {return;}
    (_abnormalKeyTargets.length ? _abnormalKeyTargets : [document]).forEach(doc => {
      try {
        doc.removeEventListener('keydown', _abnormalKeyHandler, true);
      } catch (e) {}
    });
    _abnormalKeyTargets = [];
    _abnormalKeyHandler = null;
  }

  function renderWSTable() {
    const body = $('#lis-ws-body');
    if (!body) {return;}
    // 8.11.10: 本函数即将全量 innerHTML 重建视图区（含左栏列表/表格各自的滚动容器），
    // 30s 自动刷新会把用户浏览到中部的列表拉回顶部。先按分类找到当前滚动容器记下位置，
    // 同分类重建后还原；切分类/首次打开（_renderedCat 不同）则归零。
    // audit 视图滚动容器 = .ws-split-master 内的 .ws-abnormal-list；表格视图 = .ws-table-wrap
    const _sameCat = body._renderedCat === wsCategory;
    const _oldScroller = _sameCat ? (body.querySelector('.ws-abnormal-list') || body.querySelector('.ws-table-wrap')) : null;
    const _savedTop = _oldScroller ? _oldScroller.scrollTop : 0;
    const _savedLeft = _oldScroller ? _oldScroller.scrollLeft : 0;
    // 移除旧的异常视图键盘监听
    _removeAbnormalKeyHandler();
    if (_normalKeyHandler) {
      document.removeEventListener('keydown', _normalKeyHandler);
      _normalKeyHandler = null;
    }
    // 移除旧视图的 click/change/delegate handler，防止切换分类时累积
    if (body._delegatedHandler) {
      body.removeEventListener('click', body._delegatedHandler.click);
      body.removeEventListener('change', body._delegatedHandler.change);
      body.removeEventListener('dblclick', body._delegatedHandler.dblclick);
      body._delegatedHandler = null;
    }
    if (body._abnormalClickHandler) {
      body.removeEventListener('click', body._abnormalClickHandler);
      body._abnormalClickHandler = null;
    }
    if (body._incompleteClickHandler) {
      body.removeEventListener('click', body._incompleteClickHandler);
      body._incompleteClickHandler = null;
    }

    const data = filteredData();
    if (data.length === 0) {
      body.innerHTML = `
        <div class="ws-empty">
          <div class="ico">📭</div>
          <div style="font-size:15px;font-weight:700;color:var(--lis-text)">暂无标本数据</div>
          <div class="sub">当前筛选条件下没有匹配的项目</div>
        </div>`;
      body._renderedCat = wsCategory;
      // 即使无数据，仍需绑定 Escape 退出监听，避免空列表时无法按 Esc 关闭工作台
      if (!isDetailPanelVisible()) {
        _normalKeyHandler = e => {
          if (isPatientResultPanelEvent(e)) {return;}
          // 8.11.14: 数字键 1-5 切分类（空态下也可用）
          if (handleWSCategoryHotkey(e)) {return;}
          if (e.key === 'Escape') {
            e.preventDefault();
            closeWS();
          }
        };
        document.addEventListener('keydown', _normalKeyHandler);
      }
      return;
    }

    // 8.11.8: 本函数即将 body.innerHTML 清空整个视图区（含右栏检视器）。
    // 先清掉上一轮的承接内容，只有 renderAuditView 会在同一次渲染里重新写入，
    // 避免其它视图/空态残留旧的承接导致错误复用。
    _inspCarry = null;
    switch (wsCategory) {
    case 'audit':
      renderAuditView(data, body);
      break;
    case 'incomplete':
      renderIncompleteView(data, body);
      break;
    case 'pending':
      // 8.15.26: 待排样标本 — 独立只读表格视图，完整展示患者及申请信息
      renderPendingView(data, body);
      break;
    case 'collected':
      // 8.5.31: 病房采集 — 与不完整视图一致的只读模式
      renderCollectedView(data, body);
      break;
    default:
      renderAllView(data, body);
      break;
    }
    body._renderedCat = wsCategory;
    // 8.11.10: 同分类重建后还原滚动位置（内容变短时浏览器会自行钳到合法值）
    if (_savedTop || _savedLeft) {
      const _newScroller = body.querySelector('.ws-abnormal-list') || body.querySelector('.ws-table-wrap');
      if (_newScroller) {
        _newScroller.scrollTop = _savedTop;
        _newScroller.scrollLeft = _savedLeft;
      }
    }

    // 安全网：待审视图下确保键盘 handler 存在
    // 详情面板打开时不要重绑列表 handler，避免与详情 F4/Enter 双重触发
    if (wsCategory === 'audit' && !isDetailPanelVisible()) {
      if (!_abnormalKeyHandler) {_rebindAbnormalKeyHandler();}
    }
    // 其余查看视图：Escape 关闭工作台（详情打开时 Esc 由详情 handler 负责）
    if (wsCategory !== 'audit' && !isDetailPanelVisible()) {
      _normalKeyHandler = e => {
        if (isPatientResultPanelEvent(e)) {return;}
        // 8.11.14: 数字键 1-5 切分类
        if (handleWSCategoryHotkey(e)) {return;}
        if (e.key === 'Escape') {
          e.preventDefault();
          closeWS();
        }
      };
      document.addEventListener('keydown', _normalKeyHandler);
    }
  }

  // 8.11.8: 顶栏重构后原状态指示元素 #lis-qi 已不存在，加载/刷新进度提示静默丢失。
  // 恢复方案：临时占用底栏左侧状态位（默认「本地工作台」），超时自动还原，
  // 不与右侧 #lis-ws-ft-stat 统计（updateWSFooter 负责）互相覆盖。
  const WS_FOOTER_IDLE = '本地工作台';
  let _wsStatusNoteTimer = null;
  function setWSStatusNote(text, ttlMs) {
    const el = document.querySelector('#lis-ws-ft > span:first-child');
    if (!el) {return;}
    el.textContent = text ? String(text) : WS_FOOTER_IDLE;
    if (_wsStatusNoteTimer) {
      clearTimeout(_wsStatusNoteTimer);
      _wsStatusNoteTimer = null;
    }
    if (!text) {return;}
    _wsStatusNoteTimer = setTimeout(() => {
      _wsStatusNoteTimer = null;
      const cur = document.querySelector('#lis-ws-ft > span:first-child');
      if (cur) {cur.textContent = WS_FOOTER_IDLE;}
    }, typeof ttlMs === 'number' ? ttlMs : 12000);
  }

  function updateWSFooter(counts) {
    const ft = document.getElementById('lis-ws-ft-stat');
    if (!ft) {return;}
    if (!counts) {
      // 8.5.33: 忽略的标本不计入 footer 总数（可见行仍显示灰显，但统计数字排除）
      // 8.5.34: visible 同样排除忽略行，避免「可见 5 / 总 3条」倒挂
      // 8.5.82: total 同口径过工作组/仪器筛选——此前无参调用用全院总数，会覆盖
      // renderWSCategoryBar 传入的筛选范围总数，出现「footer 5/438 vs 分类栏 5/12」互相矛盾
      const _fdNoIgn = filteredData().filter(r => !isWSIgnored(r.ReportDR)).length;
      counts = {
        visible: _fdNoIgn,
        total: _fdNoIgn
      };
    }
    const groupName = wsActiveWG ? (WG_MAP[wsActiveWG] || {}).name || wsActiveWG : '全部工作组';
    let machineName = '全部仪器';
    if (wsActiveWG) {
      const selectedMachines = getWSSelectedMachineSet(wsActiveWG);
      if (selectedMachines.size > 0) {
        const names = wsMachines
          .filter(m => m._wg === wsActiveWG && selectedMachines.has(String(m.RowID)))
          .map(m => m.CName || m.Name || m.RowID)
          .filter(Boolean);
        machineName = names.length <= 2 ? names.join('、') : `已选${selectedMachines.size}台仪器`;
      }
    } else {
      // 全部工作组：汇总各组选中的仪器（含外送组）
      const allSel = [];
      WS_WG.forEach(w => {
        const s = getWSSelectedMachineSet(w.dr);
        if (s.size) {allSel.push({ wg: w.name, n: s.size });}
      });
      if (allSel.length) {
        machineName = allSel.map(s => `${s.wg}${s.n}台`).join('、');
      } else if (wsActiveMachine) {
        machineName = (wsMachines.find(m => String(m.RowID) === String(wsActiveMachine)) || {}).CName || '当前仪器';
      }
    }
    const parts = [`${groupName}`, `${machineName}`, `${counts.visible}/${counts.total || 0}条`];
    if (typeof counts.normal === 'number') {parts.push(`正常${counts.normal}`);}
    if (typeof counts.abnormal === 'number') {parts.push(`异常${counts.abnormal}`);}
    // 8.5.58: 自动审核状态（剩余时长，10s 级更新由引擎 ticker 负责）
    const _aaRemain = autoAuditRemainText();
    if (_aaRemain) {parts.push(_aaRemain);}
    if (wsLoading) {parts.push('刷新中');}
    ft.textContent = parts.join(' · ');
  }

  // --- 正常可审视图已并入 renderAuditView（待审）---
  function getAbnormalFocusSpecimen(data) {
    data = data || filteredData();
    if (!data.length) {return null;}
    const focused = document.querySelector('.ws-abnormal-card.focused');
    const focusDR = (focused && focused.dataset.rdr) || _abnormalFocusDR;
    if (focusDR) {
      const sp = findWSSpecimenByReportDR(focusDR);
      if (sp) {
        const idx = data.findIndex(r => String(r.ReportDR) === String(sp.ReportDR));
        if (idx >= 0) {wsAbnormalIndex = idx;}
        return sp;
      }
    }
    if (wsAbnormalIndex < 0 || wsAbnormalIndex >= data.length) {wsAbnormalIndex = 0;}
    return data[wsAbnormalIndex] || null;
  }

  // 就诊类型徽章：门诊/住院/体检，门诊蓝色醒目一眼可辨
  function admTypeBadgeHTML(r) {
    const t = String((r && r.AdmType) || '').trim();
    if (!t) {return '';}
    let cls = '', label = '';
    if (t.indexOf('门诊') !== -1) {cls = 'outpatient'; label = '门';}
    else if (t.indexOf('住院') !== -1 || t.indexOf('入院') !== -1) {cls = 'inpatient'; label = '住';}
    else if (t.indexOf('体检') !== -1) {cls = 'healthcheck'; label = '体';}
    else {return '';}
    return `<span class="ab-card-admtype ${cls}" title="${escAttr(t)}">${label}</span>`;
  }

  // 8.5.51: 复审（复检/复查）标本的小标识——各视图（待审/不完整/全部）均显示，
  // 便于识别；status 4 才显示。8.5.52: 复检标本可正常审核（危急值除外），仅作身份标识
  function recheckTagHTML(r) {
    const st = String((r && (r.Status || r.ReportStatus)) || '');
    return st === '4'
      ? '<span class="st-tag st-4t" title="复检/复查标本" style="margin-right:4px">复审</span>'
      : '';
  }

  // 8.5.54: 曾为复审（复检）状态的标本记录——脚本审核 status 4 标本成功时写入，
  // 供「全部」视图对审核后（status 3）的复检标本显示『审核+复审』双标识。
  // LIS 审核后状态 4→3，当前数据无法推断是否复检过，需本地记忆。
  const RECHECK_DONE_KEY = 'LIS_RecheckDone';
  function recheckDoneAdd(reportDR) {
    if (!reportDR) {return;}
    try {
      const o = JSON.parse(localStorage.getItem(RECHECK_DONE_KEY) || '{}');
      o[String(reportDR)] = Date.now();
      // 清理 7 天前的记录，防止无限增长
      const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;
      Object.keys(o).forEach(k => { if (o[k] < cutoff) {delete o[k];} });
      localStorage.setItem(RECHECK_DONE_KEY, JSON.stringify(o));
    } catch (e) {}
  }
  function isRecheckDone(reportDR) {
    if (!reportDR) {return false;}
    try {
      const o = JSON.parse(localStorage.getItem(RECHECK_DONE_KEY) || '{}');
      return !!o[String(reportDR)];
    } catch (e) {return false;}
  }

  // --- 右栏实时检验结果检视器 (Live Inspector) ---
  function renderLiveInspector(specimen) {
    const insp = document.getElementById('lis-ws-inspector');
    if (!insp) {return;}
    if (!specimen) {
      _abnormalFocusDR = '';
      insp.innerHTML = `
        <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;color:var(--lis-text-muted);font-size:13px;gap:8px">
          <div style="font-size:32px;opacity:.5">📋</div>
          <div>请在左侧列表选择标本查看结果</div>
        </div>`;
      return;
    }
    const rdr = specimen.ReportDR || '';
    _abnormalFocusDR = String(rdr);
    const cached = wsClassifiedCache[rdr];
    const bucket = getWSAuditBucket(specimen);
    const hasCritical = (cached && cached.status === 'CRITICAL') || (cached && cached.items && cached.items.some(it => it.status === 'CRITICAL' || it.critical));
    const hasZeroSuspect = cached && cached.status === 'ZERO';
    const hasInfectionWarning = cached && cached.infectionWarning;

    const _cr = (cached && cached.row) || specimen;
    // 8.13.1: 分类缓存带回的 LabInfo（GetReportInfoAll）——申请医生/标本类型等工作台行数据
    // 缺失的字段从这里补全（回退链与病人结果导出模块同源）
    const _labInfo = (cached && cached.labInfo) || {};
    const name = esc(specimen.PatName || '未知');
    const sex = esc(_cr.Sex || _cr.Species || specimen.Sex || specimen.Species || '');
    const age = esc((_cr.Age || specimen.Age || _labInfo.Age || '') + (_cr.AgeUnit || specimen.AgeUnit || ''));
    const labno = esc(specimen.Labno || '-');
    const regNo = esc(_cr.RegNo || specimen.RegNo || '-');
    const admNo = esc(_cr.AdmNo || specimen.AdmNo || _labInfo.AdmNo || _labInfo.InHospNo || '');
    const bed = esc(formatDetailBedNo(_cr.BedNo || specimen.BedNo || _labInfo.BedNo || _labInfo.Bed));
    const dept = esc(_cr.Location || _cr.LocationName || specimen.LocDesc || _labInfo.Location || _labInfo.LocationName || '');
    const doc = esc(
      _cr.Doctor || _cr.DoctorName || _cr.ReqDoctorName || _cr.ApplyDoctorName ||
      specimen.Doctor || specimen.DoctorName || specimen.ReqDoctorName || specimen.ApplyDoctorName ||
      _labInfo.Doctor || _labInfo.DoctorName || _labInfo.ReqDoctorName || _labInfo.ApplyDoctorName || ''
    );
    const specimenDesc = esc(_cr.Specimen || _cr.SpecimenDesc || specimen.Specimen || specimen.SpecimenDesc || _labInfo.Specimen || _labInfo.SpecimenDesc || '');
    const episodeNo = esc(specimen.EpisodeNo || _cr.EpisodeNo || _labInfo.EpisodeNo || '');
    const testSet = esc(specimen.TestSetDesc || '');
    const machine = esc(specimen._mn || prWorkGroupMachineDR(specimen) || '');
    const admBadge = admTypeBadgeHTML(specimen);
    const recheckTag = recheckTagHTML(specimen);
    const extraText = buildDetailExtraText(_cr, specimen, _labInfo);

    let hdHtml = `
      <div class="insp-hd-main">
        <div class="insp-hd-pat">
          <span class="insp-pat-name">${name}</span>
          ${sex || age ? `<span class="insp-pat-meta">${[sex, age].filter(Boolean).join(' · ')}</span>` : ''}
          ${admBadge}
          ${recheckTag}
        </div>
        <div class="insp-hd-sub">
          <span>检验号: <span class="insp-mono">${labno}</span></span>
          <span>登记号: <span class="insp-mono">${regNo}</span></span>
          ${admNo ? `<span>住院号: <span class="insp-mono">${admNo}</span></span>` : ''}
          ${bed ? `<span>${bed}</span>` : ''}
          ${dept ? `<span>${dept}</span>` : ''}
          ${doc ? `<span>申请医生: ${doc}</span>` : ''}
          ${specimenDesc ? `<span>标本: ${specimenDesc}</span>` : ''}
          ${episodeNo ? `<span>流水号: <span class="insp-mono">${episodeNo}</span></span>` : ''}
          <span>仪器: ${machine}</span>
        </div>
        ${extraText ? `<div class="insp-hd-extra" title="${escAttr(extraText)}">${esc(extraText)}</div>` : ''}
      </div>
      <div class="insp-hd-acts">
        <button class="insp-tool-btn" id="lis-insp-tool-native" type="button" title="在原生 LIS 界面打开此标本">📂 原生</button>
        <button class="insp-tool-btn" id="lis-insp-tool-drawer" type="button" title="打开完整历史抽屉">📋 抽屉</button>
      </div>
    `;

    let alertHtml = '';
    if (hasCritical) {
      alertHtml = `<div class="ws-insp-alert critical">🚨 <b>危急值警告</b>：此标本包含危急值指标，须在原始 LIS 复查登记后再审核！</div>`;
    } else if (hasInfectionWarning) {
      alertHtml = `<div class="ws-insp-alert warning">⚠️ <b>历史不一致</b>：${esc(cached.infectionWarning)}</div>`;
    } else if (hasZeroSuspect) {
      alertHtml = `<div class="ws-insp-alert warning">⚠️ <b>可疑 0 值（疑似堵孔）</b>：检测到 0 值或断崖式异常，请务必核实原始仪器吸样状态！</div>`;
    } else if (bucket === 'normal') {
      alertHtml = `<div class="ws-insp-alert normal">✅ <b>指标正常</b>：所有检验项目均在参考区间内，可安全审核。</div>`;
    }

    // 8.11.8: 必须精确到「正在审核的是不是这一条」——此前判定用 _abnormalFocusDR，
    // 而它在上方刚被赋值为本标本的 rdr，条件恒真，等价于「有任一审核在跑」。
    // 后果：审完一条后右栏下一条的「审核此标本」按钮显示「⏳ 审核中…」且被禁用，
    // clearAbnormalAuditingCard 又因焦点已移走而不复位，直到下一次整表重建才恢复。
    const isAuditing = _abnormalAuditInProgress && _abnormalAuditingDR === String(rdr);
    let ftHtml = `
      <div class="ws-insp-hint"><kbd>Enter</kbd> 审核当前 · <kbd>Space</kbd> 跳过 · <kbd>M</kbd> 病历 · <kbd>↑↓</kbd> 切换 · <kbd>F4</kbd> 批审正常 · <kbd>1-5</kbd> 切分类</div>
      <div class="ws-insp-ft-actions">
        <button class="ws-insp-btn-emr" id="lis-insp-btn-emr" type="button" title="查看该患者的电子病历 / HIS 信息（Shift+点击：直接唤起原生 32 位 IE，文书正文只有它渲染得了）· 快捷键 M">📄 病历 (M)</button>
        <button class="ws-insp-btn-skip" id="lis-insp-btn-skip" type="button" title="跳过当前标本 (Space)">↷ 跳过 (Space)</button>
        <button class="ws-insp-btn-audit${isAuditing ? ' disabled' : ''}" id="lis-insp-btn-audit" type="button" ${isAuditing ? 'disabled' : ''}>
          ${isAuditing ? '⏳ 审核中...' : '✓ 审核此标本 (Enter)'}
        </button>
      </div>
    `;

    let hd = document.getElementById('lis-insp-hd');
    let al = document.getElementById('lis-insp-alert');
    let bd = document.getElementById('lis-insp-body');
    let ft = document.getElementById('lis-insp-ft');

    if (!hd || !al || !bd || !ft) {
      insp.innerHTML = `
        <div class="ws-insp-hd" id="lis-insp-hd"></div>
        <div id="lis-insp-alert"></div>
        <div class="ws-insp-body" id="lis-insp-body"></div>
        <div class="ws-insp-ft" id="lis-insp-ft"></div>
      `;
      hd = document.getElementById('lis-insp-hd');
      al = document.getElementById('lis-insp-alert');
      bd = document.getElementById('lis-insp-body');
      ft = document.getElementById('lis-insp-ft');

      bd.addEventListener('click', e => {
        const btn = e.target && e.target.closest ? e.target.closest('.detail-hist-item') : null;
        if (!btn) { return; }
        e.preventDefault();
        e.stopPropagation();
        const curData = filteredData();
        const sp = getAbnormalFocusSpecimen(curData);
        if (!sp) { toast('当前没有选中的标本', 'warning'); return; }
        histOpenForTest(
          {
            RegNo: sp.RegNo || '',
            PatName: sp.PatName || '',
            Labno: sp.Labno || '',
            EpisodeNo: sp.EpisodeNo || '',
            _wg: sp._wg || '',
            _mdr: sp._mdr || '',
            ReportDR: sp.ReportDR || '',
            Status: sp.Status || sp.ReportStatus || '',
            AcceptDT: sp.AcceptDT || '',
            TransmitDate: sp.TransmitDate || '',
            MachineParameterDR: sp.MachineParameterDR || '',
            TestSetDesc: sp.TestSetDesc || ''
          },
          btn.dataset.key || '',
          btn.dataset.name || '',
          btn.dataset.syn || ''
        );
      });
      // 8.15.10: 右栏检视器同样支持项目名后的 ⚙ —— 保存后由 _refreshAfterMildRuleChange
      // 调 renderLiveInspector 重建（版本号已递增，其「跳过重建」判据会失效）
      _bindMildBtn(bd);
    }

    hd.innerHTML = hdHtml;
    al.innerHTML = alertHtml;
    ft.innerHTML = ftHtml;

    const nativeBtn = document.getElementById('lis-insp-tool-native');
    if (nativeBtn) {
      nativeBtn.addEventListener('click', () => {
        navigateToSpecimen(specimen);
      });
    }
    const drawerBtn = document.getElementById('lis-insp-tool-drawer');
    if (drawerBtn) {
      drawerBtn.addEventListener('click', () => {
        openDetailPanel(specimen, bucket === 'normal' ? 'normal' : 'abnormal', wsAbnormalIndex);
      });
    }
    // 8.17.5: 「📄 病历」——与「跳过 / 审核此标本」同一排；Shift+点击 = 直接唤起原生 32 位 IE
    const inspEmrBtn = document.getElementById('lis-insp-btn-emr');
    if (inspEmrBtn) {
      inspEmrBtn.addEventListener('click', e => {
        openEMRForWSRow(specimen, e.shiftKey);
      });
    }
    const skipBtn = document.getElementById('lis-insp-btn-skip');
    if (skipBtn) {
      skipBtn.addEventListener('click', () => {
        advanceAbnormalFocusAfterSkip(wsAbnormalIndex);
      });
    }
    const auditBtn = document.getElementById('lis-insp-btn-audit');
    if (auditBtn) {
      auditBtn.addEventListener('click', () => {
        triggerAbnormalEnterAudit();
      });
    }

    // 8.11.8: 整表重建前承接的同标本结果 → 直接放回（含滚动位置），不闪白也不重新请求。
    // 这是 30s 自动刷新路径的实际生效点（整表重建会销毁右栏 DOM，data-rdr 复用判定到不了）。
    if (_inspCarry) {
      const _carry = _inspCarry;
      _inspCarry = null;
      if (_carry.dr === String(rdr)) {
        bd.innerHTML = _carry.html;
        bd.setAttribute('data-rdr', _carry.dr);
        _inspShownVersion = _classifyVersion;
        try {bd.scrollTop = _carry.scrollTop;} catch (e) {}
        dbg('右栏检视器沿用重建前结果，保持滚动位置:', rdr);
        return;
      }
    }
    // 8.11.8: 同标本 + 同分类代数 + 结果区已就绪 → 只更新头/横幅/按钮，不重建结果区。
    // 覆盖非整表重建的局部刷新路径（↑↓ 切焦、跳过、点击卡片、审核后推进）。
    // 判定用 body 上的 data-rdr（DOM 自证已渲染），避免依赖可能过期的全局变量。
    if (bd.getAttribute('data-rdr') === String(rdr) && _inspShownVersion === _classifyVersion && !bd.querySelector('.ws-insp-loading')) {
      dbg('右栏检视器复用已有结果，跳过重建:', rdr);
      return;
    }
    bd.removeAttribute('data-rdr');
    bd.innerHTML = `
      <div class="ws-insp-loading">
        <div class="spinner"></div>
        <span>正在加载结果...</span>
      </div>
    `;
    loadDetailResults(specimen, bd);
  }

  // 8.11.10: 异常卡展示项提取（原内联在 renderAuditView 字符串拼接中，抽出复用/可读）
  // 优先取分类缓存中的异常项目；为空且非传染病提示时，从详情缓存 HTML 解析；
  // 仍为空则退回展示所有有结果的项目（可能 AbFlag 未标记）
  function getAbnormalDisplayItems(r, hasInfectionWarning) {
    const cached = wsClassifiedCache[r.ReportDR];
    const items = cached ? cached.items : [];
    let displayItems = items.filter(it => it.status !== 'NORMAL');
    if (displayItems.length === 0 && !hasInfectionWarning) {
      const detailCached = detailLRUGet(r.ReportDR);
      const _cacheEntry = cached;
      if (
        detailCached && detailCached.html &&
        _cacheEntry && _cacheEntry._displayItemsFrom === detailCached.html && Array.isArray(_cacheEntry._displayItems)
      ) {
        displayItems = _cacheEntry._displayItems;
      } else if (detailCached && detailCached.html) {
        const extracted = [];
        const _tmp = document.createElement('div');
        _tmp.innerHTML = detailCached.html;
        _tmp.querySelectorAll('tr').forEach(tr => {
          const cls = tr.querySelector('td.abnormal');
          if (cls) {
            const tds = tr.querySelectorAll('td');
            if (tds.length >= 4) {
              const name = (tds[0].textContent || '').trim();
              const result = (tds[1].textContent || '').trim();
              const status = (tds[3].textContent || '').trim();
              if (name && name !== '项目')
              {extracted.push({
                name,
                result,
                status: status.includes('高') ? 'HIGH' : status.includes('低') ? 'LOW' : 'ABNORMAL'
              });}
            }
          }
        });
        if (_cacheEntry) {_cacheEntry._displayItems = extracted; _cacheEntry._displayItemsFrom = detailCached.html;}
        displayItems = extracted;
      }
      if (displayItems.length === 0 && items.length > 0) {
        displayItems = items.filter(it => !isEmptyResultValue(it, it.result));
      }
    }
    return displayItems;
  }

  // 8.14.0: 待审卡片四色分层——critical(危急·红)/beyond(超带异常·橙)/mild(轻微可批·蓝)/normal(正常·绿)。
  // 与 filteredData 的 audit 排序共用同一口径：卡片颜色 = 排序分层 = 横幅计数，三处永远一致
  function wsAuditCardClass(r) {
    const b = getWSAuditBucket(r);
    if (b === 'normal') {return 'normal';}
    const cached = wsClassifiedCache[r.ReportDR];
    if (cached && cached.status === 'CRITICAL') {return 'critical';}
    const m = cached ? classifyMildAbnormal(cached) : null;
    return m && m.ok ? 'mild' : 'beyond';
  }

  // 8.17.4: 工作台标本 → 电子病历直达。与详情面板「📄 病历」按钮走同一个 openEnhancedEMR，
  // 所以取数口径（Labno/PatName/RegNo/EpisodeNo）与那里完全一致，不会出现「卡片能开、面板开不了」。
  // shiftKey=true → directNativeIE：直接唤起原生 32 位 IE（病历文书正文的 ActiveX 只有它渲染得了）。
  function openEMRForWSRow(r, shiftKey) {
    if (!r) {showToast('没有定位到标本，无法查看病历', 'info'); return;}
    const labno = r.Labno || '';
    if (!labno) {showToast('该标本没有检验号，无法查看病历', 'warning'); return;}
    openEnhancedEMR(labno, {
      labNo: labno,
      patName: r.PatName || '',
      regNo: r.RegNo || '',
      episodeNo: r.EpisodeNo || '',
      directNativeIE: !!shiftKey
    });
  }

  // --- 待审视图（融合正常 + 异常，单队列审核）---
  function renderAuditView(data, body) {
    if (_abnormalFocusDR) {
      const idx = data.findIndex(r => String(r.ReportDR) === String(_abnormalFocusDR));
      wsAbnormalIndex = idx >= 0 ? idx : data.length ? 0 : -1;
    } else if (wsAbnormalIndex < 0 || wsAbnormalIndex >= data.length) {
      wsAbnormalIndex = data.length ? 0 : -1;
    }
    if (wsAbnormalIndex >= 0 && data[wsAbnormalIndex]) {
      _abnormalFocusDR = String(data[wsAbnormalIndex].ReportDR || '');
    } else {
      _abnormalFocusDR = '';
    }

    // 分类汇总（基于当前视图数据）
    // 8.12.0: nMild = 异常中「整管在轻微带内、可被 F4 批审」的条数（classifyMildAbnormal 带版本记忆）
    let nNormal = 0,
      nAbnormal = 0,
      nCritical = 0,
      nMild = 0;
    data.forEach(r => {
      const b = getWSAuditBucket(r);
      if (b === 'normal') {nNormal++;}
      else {
        const cached = wsClassifiedCache[r.ReportDR];
        if (cached && cached.status === 'CRITICAL') {nCritical++;}
        else {
          nAbnormal++;
          const m = cached ? classifyMildAbnormal(cached) : null;
          if (m && m.ok) {nMild++;}
        }
      }
    });

    let h = '<div class="ws-split-wrap">';
    h += '<div class="ws-split-master">';
    const _batchBtnText =
      nNormal > 0 && nMild > 0
        ? `⚡ 一键批审正常 ${nNormal} · 轻微 ${nMild} · F4`
        : nNormal > 0
          ? `⚡ 一键批审正常 ${nNormal} · F4`
          : `⚡ 一键批审轻微异常 ${nMild} · F4`;
    h += `<div class="ws-audit-banner">
            <span class="ws-audit-summary">
                <span class="ws-audit-normal">✅ 正常 <b>${nNormal}</b></span>
                <span class="ws-audit-sep">·</span>
                <span class="ws-audit-beyond">⚠️ 异常 <b>${nAbnormal}</b></span>
                ${nMild ? `<span class="ws-audit-sep">·</span><span class="ws-audit-mild" title="整管异常都在轻微放行带内，F4 可一并批审">⚡ 轻微 <b>${nMild}</b></span>` : ''}
                ${nCritical ? `<span class="ws-audit-sep">·</span><span class="ws-audit-critical">🚨 危急 <b>${nCritical}</b></span>` : ''}
            </span>
            ${nNormal > 0 || nMild > 0 ? `<button class="nb-btn" id="lis-audit-batch" title="直接批审当前筛选范围全部正常标本 + 轻微异常标本（超出轻微带的异常/危急值/传染病/待定等仍留人工）· F4 同 · 批审中可点进度条 ⏹ 停止">${_batchBtnText}</button>` : ''}
        </div>`;

    h += `<div class="ws-abnormal-hint">
            <span><kbd>Enter</kbd> 审核 <kbd>Space</kbd> 跳过 <kbd>↑↓</kbd> 移动 <kbd>F4</kbd> 批审 <kbd>M</kbd> 病历 <kbd>1-5</kbd> 切分类</span>
            <span>按仪器分组</span>
        </div>`;
    h += '<div class="ws-abnormal-list">';

    let lastMachineKey = '';
    data.forEach((r, i) => {
      const machineKey = String(r._wg || '') + '|' + String(prWorkGroupMachineDR(r) || r._mn || '');
      if (machineKey !== lastMachineKey) {
        const machineLabel = r._mn || prWorkGroupMachineDR(r) || '未知仪器';
        h += `<div class="ws-abnormal-machine">🔬 ${esc(machineLabel)}</div>`;
        lastMachineKey = machineKey;
      }
      const cached = wsClassifiedCache[r.ReportDR];
      const bucket = getWSAuditBucket(r);
      if (bucket === 'normal') {
        // --- 正常行：信任分类结果，Enter 直接单条审核；F4 整批 ---
        const focused = i === wsAbnormalIndex ? ' focused' : '';
        h += `<div class="ws-abnormal-card is-normal${focused}" data-i="${i}" data-rdr="${escAttr(r.ReportDR || '')}">`;
        h += '<div class="ab-card-top">';
        h += '<div style="display:flex;align-items:center;gap:6px;min-width:0">';
        h += '<span class="ab-card-badge ok">✅</span>';
        h += `<span class="ab-card-name">${highlightText(r.PatName || '', wsSearchQuery)}</span>`;
        h += recheckTagHTML(r);
        h += admTypeBadgeHTML(r);
        h += '</div>';
        h += `<span class="ab-card-no">${highlightText(r.Labno || '', wsSearchQuery)}</span>`;
        h += '</div>';
        h += '<div style="display:flex;align-items:center;font-size:11px;color:var(--lis-text-secondary)">';
        h += `<span class="ab-card-test">${highlightText(r.TestSetDesc || '', wsSearchQuery)}</span>`;
        h += '</div>';
        h += '</div>';
        return;
      }

      const items = cached ? cached.items : [];
      const hasCritical =
        (cached && cached.status === 'CRITICAL') || items.some(it => it.status === 'CRITICAL' || it.critical);
      const hasInfectionWarning = cached && cached.infectionWarning;
      // 8.5.58: 堵孔 0 值可疑（ZERO）标本
      const hasZeroSuspect = cached && cached.status === 'ZERO';
      // 8.14.0: 四色分层——cls-* 类驱动色条/底色，轻微可批卡用 ⚡ 徽章与超带 ⚠️ 区分
      const _cardCls = wsAuditCardClass(r);
      const focused = i === wsAbnormalIndex ? ' focused' : '';

      h += `<div class="ws-abnormal-card cls-${_cardCls}${focused}${hasCritical ? ' has-critical' : ''}${hasInfectionWarning ? ' has-infection-warning' : ''}${hasZeroSuspect ? ' has-zero' : ''}" data-i="${i}" data-rdr="${escAttr(r.ReportDR || '')}">`;
      h += '<div class="ab-card-top">';
      h += '<div style="display:flex;align-items:center;gap:6px;min-width:0">';
      h += hasCritical
        ? '<span class="ab-card-badge critical">🚨</span>'
        : hasZeroSuspect
          ? '<span class="ab-card-badge zero" title="含 0 值结果，疑似堵孔，需人工确认">0?</span>'
          : _cardCls === 'mild'
            ? '<span class="ab-card-badge mild" title="整管异常都在轻微放行带内，F4 可批审">⚡</span>'
            : '<span class="ab-card-badge warn">⚠️</span>';
      h += `<span class="ab-card-name">${highlightText(r.PatName || '', wsSearchQuery)}</span>`;
      h += recheckTagHTML(r);
      h += admTypeBadgeHTML(r);
      // 8.16.11: 「已知晓」——只在**需要人工**的标本上给（危急 / 超带无法自动审核 / 堵孔0值 / 传染病提示）。
      // 点一次后该标本不再进自动审核推送（仍照旧留在待审、仍须人工审核）。可再点一次取消。
      const _ackEligible = _cardCls === 'critical' || _cardCls === 'beyond' || hasCritical || hasZeroSuspect || !!hasInfectionWarning;
      if (_ackEligible) {
        const _acked = aaAckHas(r.ReportDR);
        h += `<button type="button" class="ab-ack-btn${_acked ? ' on' : ''}" data-ack="${escAttr(r.ReportDR || '')}" title="${_acked ? '已标记「已知晓」：该标本不再进自动审核推送；点击可取消标记' : '标记「已知晓」：该标本不再进自动审核推送（仍留在待审、仍须人工审核）'}">${_acked ? '✓ 已知晓' : '已知晓'}</button>`;
      }
      h += '</div>';
      h += `<span class="ab-card-no">${highlightText(r.Labno || '', wsSearchQuery)}</span>`;
      h += '</div>';
      h += '<div style="display:flex;align-items:center;justify-content:space-between;font-size:11px;color:var(--lis-text-secondary)">';
      h += `<span class="ab-card-test">${highlightText(r.TestSetDesc || r._mn || '', wsSearchQuery)}</span>`;
      h += `<span class="ab-card-time" style="font-size:10.5px;color:var(--lis-text-muted)">${esc(r.AcceptDT || '')}</span>`;
      h += '</div>';
      h += '<div class="ab-card-items">';
      const displayItems = getAbnormalDisplayItems(r, hasInfectionWarning);
      // 8.11.13: 血常规次要异常按自动审核推送同款口径折叠——core 必显 / cond 超阈值才显 /
      // skip（比率、分布宽度、MPV 等衍生项）折叠为「+N 次要」；危急值永显、非血常规组合
      // 不受影响、参考范围解析失败时 fail-open 显示（与推送摘要 aaPushItemVisible 同一函数，
      // 卡片与推送看到的口径永远一致）。被折叠项在「+N 次要」悬停 title 里可看全量
      const _testKey = r.TestSetDesc || r._mn || '';
      const visibleItems = [];
      const hiddenMinor = [];
      displayItems.forEach(it => {
        if (aaPushItemVisible(_testKey, it)) {visibleItems.push(it);}
        else {hiddenMinor.push(it);}
      });
      visibleItems.forEach(it => {
        let cls = 'uncertain';
        const st = it.status || '';
        // 8.15.6: 高/低再分两档——在轻微放行带内＝浅色+虚线边（F4 可批审），超带/未配规则/判不出＝深色（不可批审）。
        // 判定复用审核期已算好的结果（mildItemVerdict），保证颜色与 F4 实际放行口径一致。
        let _mv = '';
        if (st === 'CRITICAL') {cls = 'critical';}
        else if (st === 'HIGH') {cls = 'high'; _mv = mildItemVerdict(it, cached);}
        else if (st === 'LOW') {cls = 'low'; _mv = mildItemVerdict(it, cached);}
        else if (st === 'ABNORMAL') {cls = 'abnormal';}
        else if (st === 'ZERO') {cls = 'zero';}
        if (_mv === 'pass') {cls += ' mild';}
        if (
          st === 'ABNORMAL' &&
          isX8InfectionPanel(r) &&
          isInfectionSpecialItem(it.name) &&
          isPositiveResult(it.result, it.preResult || it)
        ) {
          cls = 'inf-special';
        }
        const prefix = st === 'CRITICAL' ? '危急 ' : '';
        // 8.11.12: 长中文名压成规范缩写（MPV/NEU#…，复用推送侧字典），悬停 title 看全称；
        // 高/低贴 ↑/↓ 方向箭头，多异常项时一排短 chip 扫读更快
        const dirMark = st === 'HIGH' ? '↑' : st === 'LOW' ? '↓' : '';
        const abbrName = aaPushItemAbbr(it.name);
        const chipText = prefix + abbrName + ' ' + it.result + (it.unit || '') + dirMark;
        // 悬停解释浅/深含义，避免现场误读「浅色＝不重要」
        const _mvHint = _mv === 'pass' ? '（轻微带内，F4 可批审）' : (_mv === 'block' ? '（超出轻微带，需人工）' : '');
        h += `<span class="ab-card-item ${cls}" title="${escAttr(it.name + ' ' + it.result + (it.unit || '') + (dirMark ? '（' + (st === 'HIGH' ? '偏高' : '偏低') + '）' : '') + _mvHint)}">${esc(chipText)}</span>`;
      });
      if (hiddenMinor.length > 0) {
        const hiddenText = hiddenMinor
          .map(it => `${it.name || ''} ${it.result || ''}${it.unit || ''}`.trim())
          .join('；');
        h += `<span class="ab-card-item minor-more" title="${escAttr('次要异常已折叠（' + hiddenText + '）')}">+${hiddenMinor.length} 次要</span>`;
      }
      if (hasInfectionWarning) {
        h += `<span class="ab-card-item infection-warning">⚠ ${esc(cached.infectionWarning)}</span>`;
      }
      if (hasCritical && !visibleItems.some(it => it.status === 'CRITICAL' || it.critical)) {
        h += '<span class="ab-card-item critical">🚨 危急值</span>';
      }
      if (displayItems.length === 0 && !hasInfectionWarning) {
        h += '<span class="ab-card-item uncertain">⚠ 待确认</span>';
      }
      h += '</div>';
      // 8.5.52: 复检标本可审核（危急值除外）；危急值红线优先提示
      // 8.15.11: 去掉「Enter=审核」提示——它让每张无红线的卡片多出一整行，抬高卡片高度；
      // Enter 是常驻主操作，界面上不必反复提示（底部提示条已有说明）。红线类提示保留。
      if (hasCritical) {
        h += '<span class="ab-card-hint" style="color:#c62828;font-weight:600">🚨 危急值</span>';
      } else if (hasZeroSuspect) {
        h += '<span class="ab-card-hint" style="color:#8a6d3b;font-weight:600">0值? 疑似堵孔，需人工确认</span>';
      } else if (hasInfectionWarning) {
        h += '<span class="ab-card-hint" style="color:#e65100;font-weight:600">⚠ 历史不一致</span>';
      }
      h += '</div>';
    });
    h += '</div>'; // close ws-abnormal-list
    h += '</div>'; // close ws-split-master

    // 右栏实时检视器容器
    h += '<div class="ws-split-inspector" id="lis-ws-inspector"></div>';
    h += '</div>'; // close ws-split-wrap

    // 8.11.8: 清空前先承接右栏已渲染好的结果 HTML 与滚动位置——
    // 若重建后仍是同一条标本（30s 自动刷新的常态），直接放回，不再闪白也不重新拉接口。
    const _prevInspBody = document.getElementById('lis-insp-body');
    if (_prevInspBody && _prevInspBody.getAttribute('data-rdr') && _inspShownVersion === _classifyVersion) {
      _inspCarry = {
        dr: _prevInspBody.getAttribute('data-rdr'),
        html: _prevInspBody.innerHTML,
        scrollTop: _prevInspBody.scrollTop || 0
      };
    }
    body.innerHTML = h;

    const activeSpecimen = data[wsAbnormalIndex] || data[0] || null;
    renderLiveInspector(activeSpecimen);

    // 横幅一键批审按钮（与顶栏 / F4 共用 openWorkbenchBatchAudit）
    const auditBatchBtn = document.getElementById('lis-audit-batch');
    if (auditBatchBtn) {
      auditBatchBtn.addEventListener('click', () => {
        openWorkbenchBatchAudit();
      });
    }

    // 卡片点击 → 更新聚焦与实时检视器
    if (body._abnormalClickHandler) {
      body.removeEventListener('click', body._abnormalClickHandler);
    }
    body._abnormalClickHandler = e => {
      // 8.16.11: 「已知晓」按钮 —— 必须先拦下，否则会被下面的卡片点击当成选中卡片
      const ackBtn = e.target.closest ? e.target.closest('.ab-ack-btn') : null;
      if (ackBtn) {
        e.preventDefault();
        e.stopPropagation();
        const dr = String(ackBtn.dataset.ack || '');
        if (!dr) {return;}
        const on = !aaAckHas(dr);
        aaAckSet(dr, on);
        // 8.16.12: 取消标记时同时清掉「同标本同原因只记一次」的记忆——否则本页会话内该标本
        // 已被记为「跳过过」，下一轮不会再进 skipped，取消标记后要等刷新页面才恢复推送。
        if (!on) {try {delete _autoAuditSkipSeen[dr];} catch (e) {}}
        showToast(
          on
            ? '已标记「已知晓」 —— 该标本不再进自动审核推送（仍留在待审，仍须人工审核）'
            : '已取消「已知晓」标记 —— 该标本恢复进推送',
          on ? 'success' : 'info'
        );
        renderWSTable(); // 重渲染卡片，按钮状态立即跟上
        return;
      }
      const card = e.target.closest('.ws-abnormal-card');
      if (!card) {return;}
      const specimen = findWSSpecimenByReportDR(card.dataset.rdr);
      if (!specimen) {return;}
      _abnormalFocusDR = String(specimen.ReportDR || '');
      const cards = document.querySelectorAll('.ws-abnormal-card');
      cards.forEach(c => c.classList.remove('focused'));
      card.classList.add('focused');
      wsAbnormalIndex = Math.max(
        0,
        filteredData().findIndex(r => String(r.ReportDR) === String(specimen.ReportDR))
      );
      renderLiveInspector(specimen);
    };
    body.addEventListener('click', body._abnormalClickHandler);

    // 键盘导航
    if (!isDetailPanelVisible()) {_rebindAbnormalKeyHandler();}

    // 滚动到聚焦卡片
    _scrollAbnormalFocus();
    updateAbnormalEnterBridge();
    scheduleAbnormalAuditPrewarm();
    installAbnormalResultGridEnterHijack();
  }

  function moveAbnormalFocus(dir, data) {
    data = data || filteredData();
    if (!data.length) {return;}
    const cur = getAbnormalFocusSpecimen(data);
    let idx = cur ? data.findIndex(r => String(r.ReportDR) === String(cur.ReportDR)) : wsAbnormalIndex;
    if (idx < 0) {idx = 0;}
    idx = Math.max(0, Math.min(data.length - 1, idx + dir));
    wsAbnormalIndex = idx;
    _abnormalFocusDR = String(data[idx].ReportDR || '');
    document.querySelectorAll('.ws-abnormal-card').forEach(c => c.classList.remove('focused'));
    const card = [...document.querySelectorAll('.ws-abnormal-card')].find(
      c => String(c.dataset.rdr) === _abnormalFocusDR
    );
    if (card) {card.classList.add('focused');}
    _scrollAbnormalFocus();
    renderLiveInspector(data[idx]);
    scheduleAbnormalAuditPrewarm();
  }

  function _scrollAbnormalFocus() {
    const cards = document.querySelectorAll('.ws-abnormal-card');
    if (cards[wsAbnormalIndex]) {
      cards[wsAbnormalIndex].scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    }
  }

  function advanceAbnormalFocusAfterSkip(startIndex) {
    _abnormalNativeReadyDR = '';
    const data = filteredData();
    const cards = document.querySelectorAll('.ws-abnormal-card');
    if (!data.length || !cards.length) {return;}
    if (cards[wsAbnormalIndex]) {cards[wsAbnormalIndex].classList.remove('focused');}
    if (data.length === 1) {
      wsAbnormalIndex = 0;
    } else {
      wsAbnormalIndex = Math.min(Math.max(startIndex, 0), data.length - 1);
      wsAbnormalIndex = (wsAbnormalIndex + 1) % data.length;
    }
    if (cards[wsAbnormalIndex]) {cards[wsAbnormalIndex].classList.add('focused');}
    if (data[wsAbnormalIndex]) {
      _abnormalFocusDR = String(data[wsAbnormalIndex].ReportDR || '');
      renderLiveInspector(data[wsAbnormalIndex]);
    }
    _scrollAbnormalFocus();
  }

  function nextPaint() {
    return new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
  }

  function clearAbnormalAuditingCard(reportDR) {
    const card = [...document.querySelectorAll('.ws-abnormal-card[data-rdr]')].find(
      c => String(c.dataset.rdr || '') === String(reportDR || '')
    );
    if (card) {
      card.classList.remove('auditing');
      card.removeAttribute('aria-busy');
      const hint = card.querySelector('.ab-card-hint');
      if (hint && hint.textContent === '正在审核...') {
        // 8.11.8: 优先还原 markAbnormalAuditUI 记下的原文案，避免把「🚨 危急值」等提示覆盖掉
        hint.textContent = hint.dataset.lisHint || 'Enter=审核';
        delete hint.dataset.lisHint;
      }
    }
    // 8.11.8: 审核结束（finally 必经）后右栏按钮一律复位——此前要求 _abnormalFocusDR === reportDR，
    // 但审核成功后焦点已推进到下一条，条件不成立，导致下一条的按钮永远停在「⏳ 审核中…」且不可点。
    _abnormalAuditingDR = '';
    const inspBtn = document.getElementById('lis-insp-btn-audit');
    if (inspBtn) {
      inspBtn.disabled = false;
      inspBtn.classList.remove('disabled');
      inspBtn.textContent = '✓ 审核此标本 (Enter)';
    }
  }

  function auditTargetContext(iframeWin, reportDR) {
    if (!iframeWin || !reportDR) {
      return { rowPresent: false, detailReady: false, allowMissingSuccess: false };
    }
    const rowPresent = !!findNativeRowByReportDR(iframeWin, reportDR);
    const detailReady = isReportDetailLoaded(iframeWin, reportDR);
    // 详情已就绪即可认定「行消失=审核成功」；全部仪器列表里行可能找不到但详情仍有效
    return { rowPresent, detailReady, allowMissingSuccess: detailReady };
  }

  // 8.5.53: 审核上下文——当前正在审核的标本是否「审核前已是复审(status 4)」。
  // 复检标本审核前状态就是 4，静态 4 匹配/行消失不可信，成功判定只认状态变 3 或动态信号。
  // 由 executeNativeAudit / _auditFromDetailPanel / 批审主循环在审核期间设置。
  let _auditingPreStatus4 = false;
  // 8.16.25: 本次审核的标本是否属于「别的登录组」（免切组审核场景）。
  // 用途：跨组标本不在当前登录组的原生列表里，`findNativeRowByReportDR` 对它恒返回 null，
  // 于是「行消失 = 审核成功」这条对同组标本可靠的启发式，套在跨组标本上会**恒判成功**，
  // 把其实没审掉的标本记成已完成（现场：批审 2 条都提示成功，刷新后总留 1 条）。
  // 同组标本保持原有宽容（原生审核后行常从待审列表移出），因此不无条件收紧。
  let _auditingCrossGroup = false;

  // 8.5.53: opts.accept4=false 时，状态 4（复审）不算「已审核成功」——
  // 复检标本审核前状态就是 4，静态匹配会误判；必须等状态变 3 或动态信号
  function verifyAuditSucceededByReportDR(iframeWin, reportDR, opts = {}) {
    if (!reportDR) {return false;}
    const accept4 = !_autoAuditRunning && (opts.accept4 !== undefined ? opts.accept4 : !_auditingPreStatus4);
    const statuses = accept4 ? ['3', '4'] : ['3'];
    const latestWin = getReportIframeWin() || iframeWin;
    if (latestWin) {
      // 8.16.35: 原生 DeleteReportArr 包含该标本（原生 ReportSave 审核成功后 deleteRow 的显式记录）
      try {
        const me = latestWin.me;
        if (me && Array.isArray(me.DeleteReportArr) && me.DeleteReportArr.some(id => String(id) === String(reportDR))) {
          return true;
        }
      } catch (e) {}
      const found = findNativeRowByReportDR(latestWin, reportDR);
      if (found && isExpectedNativeStatus(found.row, statuses)) {return true;}
      try {
        const me = latestWin.me;
        if (me && String(me.curReportDR || '') === String(reportDR)) {
          const sel = me.selectedGrid ? me.selectedGrid.datagrid('getSelected') : null;
          if (sel && isExpectedNativeStatus(sel, statuses)) {return true;}
        }
      } catch (e) {}
    }
    const liveRow = wsData.find(r => String(r.ReportDR) === String(reportDR));
    if (liveRow && statuses.includes(String(liveRow.Status || liveRow.ReportStatus || ''))) {return true;}
    return false;
  }

  // CA 回调 ReportSave 后：状态回写前也能较快认成功的启发式
  // 8.5.53: opts.accept4=false 时内部静态匹配只认状态变 3（复检标本审核前就是 4）
  function softAuditSuccessHint(iframeWin, reportDR, opts = {}) {
    if (!iframeWin || !reportDR) {return false;}
    if (isNativeConfirmVisible(iframeWin)) {return false;} // 8.16.29: 确认弹窗仍在绝非审核成功
    const accept4 = opts.accept4 !== undefined ? opts.accept4 : !_auditingPreStatus4;
    if (verifyAuditSucceededByReportDR(iframeWin, reportDR, { accept4 })) {return true;}
    // 自动审核只接受明确状态确认，软提示不能直接记为成功
    if (_autoAuditRunning) {return false;}
    try {
      const me = iframeWin.me;
      if (!me) {return false;}
      // 已审核标志 + 焦点已离开本条（原生审后常自动下一条）
      if (me.IsAuthed === true && String(me.curReportDR || '') !== String(reportDR)) {
        const found = findNativeRowByReportDR(iframeWin, reportDR);
        // 8.16.25: 跨组标本的「列表里找不到该行」**不能单独作为成功证据**。
        // 免切组审核的跨组标本本来就不在当前登录组的原生列表里，`!found` 恒成立；
        // 再叠加「CA 已认证 + 焦点已移开」，这条启发式会**无条件判成功**，
        // 把**其实没审掉**的标本记成已完成（现场：批审 2 条都提示成功，刷新后总留 1 条）。
        // 跨组时必须要有原生「保存成功」标志佐证；同组标本保持原样（行消失对它是可靠信号）。
        if (!found) {
          if (!_auditingCrossGroup || me.IsSaveSuccess === true) {return true;}
        } else if (isExpectedNativeStatus(found.row, accept4 ? ['3', '4'] : ['3'])) {
          return true;
        }
      }
      if (me.IsSaveSuccess === true && String(me.curReportDR || '') === String(reportDR)) {return true;}
    } catch (e) {}
    return false;
  }

  async function confirmAuditEventually(iframeWin, reportDR, patientName, options = {}) {
    const batchMode = !!options.batchMode;
    // 8.5.53: 复检标本（审核前已是 4）——静态 4 与行消失都不可信，只认状态变 3 或动态信号
    const preStatus4 = !!options.preStatus4;
    const ft = document.getElementById('lis-ws-ft-stat');
    const label = patientName || reportDR;
    const tick = msg => {
      if (typeof options.onTick === 'function') {options.onTick(msg);}
      else if (ft) {ft.textContent = msg;}
    };
    tick(`确认中：${label}`);
    // 先做几次快速校验，避免「其实已成功却干等满超时」
    for (let i = 0; i < (batchMode ? 6 : 2); i++) {
      if (options.abortCheck && options.abortCheck()) {return false;}
      const _hc = handleNativeMessageConfirm(iframeWin);
      if (_hc === 'incomplete') {return 'incomplete';}
      if (verifyAuditSucceededByReportDR(iframeWin, reportDR, { accept4: !preStatus4 }) ||
          softAuditSuccessHint(iframeWin, reportDR, { accept4: !preStatus4 })) {return true;}
      await sleep(batchMode ? 80 : 200);
    }
    const ctx = auditTargetContext(iframeWin, reportDR);
    const targetWasPresent =
      options.targetWasPresent !== undefined ? !!options.targetWasPresent : ctx.rowPresent || ctx.detailReady;
    const detailWasReady = options.detailWasReady !== undefined ? !!options.detailWasReady : ctx.detailReady;
    // 8.5.53: 复检标本关闭「行消失=成功」
    const allowMissing = (detailWasReady || !!options.afterCA) && !preStatus4;
    // 批审 afterCA 确认必须短：首条 CA 后 FuncStr 往往已审完，长等只会卡在姓名上
    const confirmTimeout = batchMode ? (options.afterCA ? BATCH_CONFIRM_MS.afterCA : BATCH_CONFIRM_MS.normal) : 10000;
    const confirmed = await waitNativeActionResult(iframeWin, reportDR, ['3'], confirmTimeout, allowMissing, {
      targetWasPresent: targetWasPresent,
      missingStableMs: batchMode ? (options.afterCA ? 200 : 280) : 900,
      turbo: true,
      abortCheck: options.abortCheck,
      quickVerify: () =>
        verifyAuditSucceededByReportDR(iframeWin, reportDR, { accept4: !preStatus4 }) ||
        softAuditSuccessHint(iframeWin, reportDR, { accept4: !preStatus4 }),
      onTick: elapsed => {
        if (batchMode && elapsed > 1200) {tick(`确认中：${label}`);}
        else if (!batchMode) {tick(`确认结果中：${label}（${Math.round(elapsed / 1000)}s）`);}
      }
    });
    if (confirmed === 'incomplete') {return 'incomplete';}
    if (confirmed && confirmed !== 'incomplete') {return true;}
    await sleep(batchMode ? 80 : 800);
    if (verifyAuditSucceededByReportDR(iframeWin, reportDR, { accept4: !preStatus4 }) ||
        softAuditSuccessHint(iframeWin, reportDR, { accept4: !preStatus4 })) {return true;}
    const latestWin = getReportIframeWin() || iframeWin;
    const found = findNativeRowByReportDR(latestWin, reportDR);
    if (!found) {return allowMissing;}
    // 8.5.53: 复检标本只认状态变 3（审核前就是 4，静态 4 不算成功）
    return preStatus4
      ? isExpectedNativeStatus(found.row, ['3'])
      : isExpectedNativeStatus(found.row, ['3', '4']);
  }

  let _abnormalAuditInProgress = false;
  let _abnormalAuditQueued = false;
  let _abnormalLastMdr = '';
  let _abnormalNativeReadyDR = '';
  let _abnormalPrewarmTimer = null;
  let _abnormalPrewarmDR = '';
  let _abnormalPrewarmPromise = null;
  let _resumeDetailAfterAudit = false; // 8.5.8: 跨组恢复后审完目标条自动重开详情面板续审
  let _reportPageLoadPromise = null;
  let _nativeUserSelectDR = '';
  let _nativeUserSelectAt = 0;
  let _nativeGuardTimer = null;
  // 8.8.2: 原生日期框被切到非今天（跨午夜/历史审核）——会话结束时恢复今天，
  // 覆盖异常逐条 / 详情面板 / 预热路径（批审原来只有 continueAuditQueue 恢复）
  let _wsDateboxCustom = false;

  function markAbnormalAuditUI(specimen, phase) {
    if (!specimen) {return;}
    const targetDR = String(specimen.ReportDR || '');
    const ft = document.getElementById('lis-ws-ft-stat');
    const name = specimen.PatName || specimen.Labno || targetDR;
    const card = [...document.querySelectorAll('.ws-abnormal-card[data-rdr]')].find(c => c.dataset.rdr === targetDR);
    if (phase === 'start') {_abnormalAuditingDR = targetDR;} // 8.11.8: 精确标记正在审核的标本
    if (phase === 'start' && ft) {ft.textContent = `审核：准备 ${name}`;}
    if (card && phase === 'start') {
      card.classList.add('auditing');
      card.setAttribute('aria-busy', 'true');
      const hint = card.querySelector('.ab-card-hint');
      if (hint) {
        // 8.11.8: 记下原提示文案再改「正在审核...」，失败/跳过时能原样还原
        // （正常卡是「Enter 审核」、危急卡是「🚨 危急值」，此前一律被还原成「Enter=审核」）
        if (!hint.dataset.lisHint) {hint.dataset.lisHint = hint.textContent || '';}
        hint.textContent = '正在审核...';
      }
    }
    if (phase === 'start') {
      const inspBtn = document.getElementById('lis-insp-btn-audit');
      if (inspBtn && _abnormalFocusDR === targetDR) {
        inspBtn.disabled = true;
        inspBtn.classList.add('disabled');
        inspBtn.textContent = '⏳ 审核中...';
      }
    }
  }

  function prefetchReportPageForWS() {
    const existing = getReportIframeWin();
    if (existing) {
      installNativeDetailGuard(existing);
      installAbnormalResultGridEnterHijack(existing);
      return Promise.resolve(existing);
    }
    if (!_reportPageLoadPromise) {
      _reportPageLoadPromise = ensureReportPageLoaded({ keepWS: true, fast: true })
        .then(w => {
          if (w) {
            installNativeDetailGuard(w);
            installAbnormalResultGridEnterHijack(w);
          }
          scheduleNativeDetailGuardInstall();
          return w;
        })
        .finally(() => {
          _reportPageLoadPromise = null;
        });
    }
    return _reportPageLoadPromise;
  }

  function prefetchAbnormalAuditContext() {
    if (wsCategory !== 'audit' || _abnormalAuditInProgress) {return;}
    scheduleAbnormalAuditPrewarm(0);
  }

  function scheduleAbnormalAuditPrewarm(delayMs) {
    if (wsCategory !== 'audit' || _abnormalAuditInProgress || !isWSVisible()) {return;}
    clearTimeout(_abnormalPrewarmTimer);
    const delay = typeof delayMs === 'number' ? delayMs : 0;
    _abnormalPrewarmTimer = setTimeout(() => {
      // 详情面板/审核进行中不抢原生页（prewarm 内部有同款守卫，这里提前跳过避免白跑）
      if (isDetailPanelVisible() || _detailAuditInProgress || _abnormalAuditInProgress || _auditInProgress) {return;}
      const data = filteredData();
      if (!data.length) {return;}
      if (wsAbnormalIndex < 0 || wsAbnormalIndex >= data.length) {wsAbnormalIndex = 0;}
      const sp = data[wsAbnormalIndex];
      prewarmAbnormalAuditNative(sp).catch(() => {});
    }, delay);
  }

  function isAbnormalSpecimenReady(reportDR) {
    const iframeWin = getReportIframeWin();
    return !!(iframeWin && reportDR && isReportDetailLoaded(iframeWin, reportDR));
  }

  async function prewarmAbnormalAuditNative(specimen, options = {}) {
    // 详情审核进行中也不预热：避免列表焦点标本（详情内 ↑↓ 切换后可能与详情标本不一致）
    // 的预热与详情审核双线程驱动同一原生页（8.5.4+ 修复，详见 M1 竞态）
    // 8.10.13: 允许上一条审核已确认成功时，提前预热下一条（forceNext），消除断链
    const allowAuditInProgress = !!(options && options.forceNext);
    if (!specimen || (!allowAuditInProgress && _abnormalAuditInProgress) || _auditInProgress || _detailAuditInProgress || !isWSVisible()) {return;}
    const reportDR = String(specimen.ReportDR || '');
    if (isAbnormalSpecimenReady(reportDR)) {
      _abnormalNativeReadyDR = reportDR;
      _abnormalPrewarmDR = reportDR;
      return;
    }
    if (_abnormalPrewarmPromise && _abnormalPrewarmDR === reportDR) {
      return _abnormalPrewarmPromise;
    }
    _abnormalPrewarmDR = reportDR;
    _abnormalPrewarmPromise = (async () => {
      let iframeWin = await prefetchReportPageForWS();
      if (!iframeWin) {iframeWin = getReportIframeWin();}
      if (!iframeWin) {return;}
      installNativeDetailGuard(iframeWin);
      if (!canScriptSelectNativeRow(iframeWin, reportDR)) {
        dbg('预热跳过：用户正在原生列表查看其他标本');
        return;
      }
      const item = specimenToAuditItem(specimen);
      const mdrKey = String(item.mdr || '');
      if (mdrKey) {
        const mdrChanged = mdrKey !== String(_abnormalLastMdr || '');
        const nativeMismatch = !nativeMachineMatches(iframeWin, mdrKey);
        // 8.8.2: 同机器但登记日不同（跨午夜/历史标本）也要刷新原生列表——否则列表停在今天，
        // 昨天的行永远选不中（prewarm 白等 2.8s 超时）
        const dateDiff = nativeDateDiffers(iframeWin, item.accDate);
        if (mdrChanged || nativeMismatch || dateDiff) {
          iframeWin = await refreshNativeWorkListForItem(iframeWin, item, { force: true, fast: true });
          _abnormalLastMdr = mdrKey;
        } else {
          _abnormalLastMdr = mdrKey;
        }
      }
      iframeWin = getReportIframeWin() || iframeWin;
      if (!canScriptSelectNativeRow(iframeWin, reportDR)) {
        dbg('预热中止：刷新列表后用户已接管原生选择');
        return;
      }
      if (item.labno && typeof iframeWin.FindFast === 'function' && canScriptSelectNativeRow(iframeWin, reportDR)) {
        try {
          iframeWin.FindFast(item.labno);
          await sleep(60);
        } catch (e) {}
        iframeWin = getReportIframeWin() || iframeWin;
      }
      if (!selectNativeRowByReportDR(iframeWin, reportDR, { force: true })) {
        await waitAndSelectNativeRow(iframeWin, item, {
          timeoutMs: 2800,
          pollMs: 30,
          skipListRefresh: !!mdrKey,
          force: true
        });
        iframeWin = getReportIframeWin() || iframeWin;
      }
      // 8.8.1: FindFast/选行后立即把焦点拉回详情面板（若还开着），
      // 避免焦点滞留原生 iframe 可编辑控件（快速查找框/日期框/编辑格），
      // 导致下一次 Enter 被原生输入吃掉、详情审核不触发（连续 Enter 审第二条失效的根因）。
      // 仅详情面板场景需要；列表视图（无面板）不受影响。
      // 8.8.11: 用户正在输入框打字（如工作台搜索框）时不抢焦点
      if (isDetailPanelVisible()) {
        const _ae = document.activeElement;
        const _typing = _ae && /^(INPUT|TEXTAREA|SELECT)$/i.test(_ae.tagName);
        if (!_typing) {
          try {releaseNativeReportFocus();} catch (e) {}
          refocusDetailPanel();
        }
      }
      if (!isReportDetailLoaded(iframeWin, reportDR)) {
        // 8.5.35: 预热详情等待 4500 → 3500（后台预热，避免用户紧跟 Enter 时被 4.5s 拖住）
        await waitReportDetailReady(iframeWin, reportDR, 3500, { fastBatch: true });
      }
      iframeWin = getReportIframeWin() || iframeWin;
      if (isReportDetailLoaded(iframeWin, reportDR)) {
        _abnormalNativeReadyDR = reportDR;
      }
      return true; // 8.8.1: 驱动过原生页（FindFast/选行/等详情）才返回 true，供调用方决定是否回收焦点
    })().finally(() => {
      if (_abnormalPrewarmDR === reportDR) {_abnormalPrewarmPromise = null;}
    });
    return _abnormalPrewarmPromise;
  }

  async function awaitAbnormalPrewarm(specimen) {
    try {
      await prewarmAbnormalAuditNative(specimen);
    } catch (e) {}
  }

  function specimenToAuditItem(specimen) {
    return {
      reportDR: specimen.ReportDR,
      mdr: prWorkGroupMachineDR(specimen) || '',
      labno: specimen.Labno || '',
      accDate: rowAcceptDateStr(specimen) // 8.7.0: 异常逐条审核路径同样需要按登记日期对齐原生列表
    };
  }

  function nativeMachineMatches(iframeWin, mdrKey) {
    if (!mdrKey || !iframeWin || !iframeWin.me) {return false;}
    return String(iframeWin.me.WorkGroupMachineDR || '') === String(mdrKey);
  }

  // 8.8.2: 原生日期框当前值与标本登记日不一致（跨午夜/历史标本同机器时也要切日期）。
  // 日期框读不到值也视为「需要切」——保守刷新，避免停在错误的默认日期上选不中行
  function nativeDateDiffers(iframeWin, accDate) {
    if (!iframeWin || !accDate) {return false;}
    const jq = iframeWin.jQuery || iframeWin.$;
    if (!jq) {return false;}
    try {
      const cur = jq('#dt_wlReportDate').length
        ? jq('#dt_wlReportDate').datebox('getValue') || jq('#dt_wlReportDate').datebox('getText') || ''
        : '';
      return !cur || String(cur) !== String(accDate);
    } catch (e) {
      return false;
    }
  }

  async function ensureSpecimenReadyForAudit(iframeWin, specimen, ctx = {}) {
    const reportDR = specimen.ReportDR;
    const item = specimenToAuditItem(specimen);
    const mdrKey = String(item.mdr || '');
    const fast = !!ctx.abnormalFast;
    iframeWin = getReportIframeWin() || iframeWin;

    if (isReportDetailLoaded(iframeWin, reportDR)) {
      return { ok: true, iframeWin, lastMdr: ctx.lastMdr || mdrKey };
    }

    const mdrChanged = !!(mdrKey && mdrKey !== String(ctx.lastMdr || ''));
    const nativeMismatch = !!(mdrKey && !nativeMachineMatches(iframeWin, mdrKey));
    const selOpts = ctx.forceSelect ? { force: true } : {};
    if (!mdrChanged && !nativeMismatch && selectNativeRowByReportDR(iframeWin, reportDR, selOpts)) {
      if (isReportDetailLoaded(iframeWin, reportDR)) {
        return { ok: true, iframeWin, lastMdr: ctx.lastMdr || mdrKey };
      }
    }

    let listFresh = false;
    const dateChanged = nativeDateDiffers(iframeWin, item.accDate);
    if ((mdrKey && (mdrChanged || nativeMismatch)) || dateChanged) {
      // 8.8.2: 机器或登记日任一变化都刷新原生列表（跨午夜/历史标本同机器时日期也要切；无 mdr 标本也支持切日期）
      iframeWin = await refreshNativeWorkListForItem(iframeWin, item, { force: true, fast });
      ctx.lastMdr = mdrKey;
      listFresh = true;
    } else if (mdrKey) {
      ctx.lastMdr = mdrKey;
    }
    iframeWin = getReportIframeWin() || iframeWin;

    let selected = false;
    if (ctx.skipSelect) {
      selected = selectNativeRowByReportDR(iframeWin, reportDR, selOpts);
    }
    if (!selected && !selectNativeRowByReportDR(iframeWin, reportDR, selOpts)) {
      const selResult = await waitAndSelectNativeRow(iframeWin, item, {
        timeoutMs: fast ? (listFresh ? 2200 : 3000) : listFresh ? 3500 : 5000,
        pollMs: fast ? 30 : 40,
        skipListRefresh: listFresh,
        force: !!ctx.forceSelect
      });
      if (!selResult.ok) {return { ok: false, reason: 'select', iframeWin: selResult.iframeWin || iframeWin };}
      iframeWin = selResult.iframeWin || iframeWin;
    }
    if (!isReportDetailLoaded(iframeWin, reportDR)) {
      // 8.5.35: 异常路径详情等待 3000/1500 → 2500/1200（就绪即退，只影响真慢时长的尾部）
      const t1 = fast ? 2500 : 5000;
      const t2 = fast ? 1200 : 2500;
      let ready = await waitReportDetailReady(iframeWin, reportDR, t1, { fastBatch: true });
      if (!ready) {
        selectNativeRowByReportDR(iframeWin, reportDR, selOpts);
        ready = await waitReportDetailReady(iframeWin, reportDR, t2, { fastBatch: true });
      }
      if (!ready) {return { ok: false, reason: 'detail', iframeWin };}
    }
    return { ok: true, iframeWin, lastMdr: ctx.lastMdr || mdrKey };
  }

  function removeAuditedAbnormalCard(reportDR, startIndex) {
    const q = ($('#lis-ws-search') || {}).value || '';
    if (q) {
      renderWSCategoryBar();
      renderWSTable();
      return;
    }
    const escDR =
      typeof CSS !== 'undefined' && CSS.escape
        ? CSS.escape(String(reportDR || ''))
        : String(reportDR || '').replace(/"/g, '\\"');
    const card = document.querySelector(`.ws-abnormal-card[data-rdr="${escDR}"]`);
    const list = card && card.parentElement;
    if (card) {
      const prev = card.previousElementSibling;
      const next = card.nextElementSibling;
      card.remove();
      if (prev && prev.classList && prev.classList.contains('ws-abnormal-machine')) {
        const nextIsCard = next && next.classList && next.classList.contains('ws-abnormal-card');
        if (!nextIsCard) {prev.remove();}
      }
    }

    const newData = filteredData();
    if (newData.length === 0) {
      // 待审队列审空：保持待审视图，显示空态（不再自动切回正常分类）
      wsAbnormalIndex = -1;
      _abnormalFocusDR = '';
      renderWSCategoryBar();
      renderWSTable();
      return;
    }

    wsAbnormalIndex = Math.min(Math.max(startIndex, 0), newData.length - 1);
    const cards = list ? [...list.querySelectorAll('.ws-abnormal-card')] : [];
    cards.forEach((c, i) => {
      c.dataset.i = String(i);
      c.classList.remove('focused');
    });
    if (cards[wsAbnormalIndex]) {
      cards[wsAbnormalIndex].classList.add('focused');
      _abnormalFocusDR = String(cards[wsAbnormalIndex].dataset.rdr || '');
      _scrollAbnormalFocus();
      renderLiveInspector(newData[wsAbnormalIndex]);
    } else {
      renderWSTable();
      return;
    }
    renderWSCategoryBar();
    updateWSFooter();
    // 8.10.13: 去除此处的重复 scheduleAbnormalFocusRecovery，由 auditAbnormalSpecimen 的 finally 统一收口
  }

  function noteAbnormalNativeReadyAfterAudit(iframeWin, removedDR) {
    _abnormalNativeReadyDR = '';
    clearNativeUserSelectLock();
    const data = filteredData();
    if (!data.length) {return;}
    const targetIdx = Math.max(0, Math.min(wsAbnormalIndex, data.length - 1));
    const next = data[targetIdx];
    if (!next || String(next.ReportDR) === String(removedDR)) {return;}
    if (isReportDetailLoaded(iframeWin, next.ReportDR)) {
      _abnormalNativeReadyDR = String(next.ReportDR);
      dbg('异常审核: 原生已定位下一条', next.ReportDR);
    } else {
      // 8.10.13: 传入 forceNext 穿透当前条审核进行中守卫，使下一条预热无缝并行
      prewarmAbnormalAuditNative(next, { forceNext: true }).catch(() => {});
    }
  }

  async function _executeNativeAuditImpl(iframeWin, specimen, options = {}) {
    const fast = options.fast !== false;
    const reportDR = specimen.ReportDR;
    // 8.5.53: 审核前已是 status 4（复检/复审标本）——静态 4 匹配不可信，需等状态变 3 或动态信号
    const preStatus4 = String(specimen.Status || specimen.ReportStatus || '') === '4';
    _auditingPreStatus4 = preStatus4; // 8.5.53: 审核期间供内部 verify/soft 兜底
    // 8.16.25: 本条是否属于「别的登录组」（免切组审核场景）——用于关闭「行消失=成功」，
    // 原因见 softAuditSuccessHint 内的说明：跨组标本不在当前登录组的原生列表里，行消失不可信
    const _auditCrossGroup = !!(
      specimen._wg &&
      resolveLoginWGReliable() &&
      String(specimen._wg) !== String(resolveLoginWGReliable())
    );
    _auditingCrossGroup = _auditCrossGroup; // 8.16.25: 供 softAuditSuccessHint 收紧「行消失=成功」
    const auditCtx = auditTargetContext(iframeWin, reportDR);
    const caReady = isCASessionReady(iframeWin);
    const deadline = options.deadline || Date.now() + (fast ? (caReady ? 14000 : 40000) : 60000);
    const abortCheck = () => {
      if (typeof options.abortCheck === 'function' && options.abortCheck()) {return true;}
      return Date.now() > deadline;
    };
    const name = specimen.PatName || specimen.Labno || reportDR;
    const ft = document.getElementById('lis-ws-ft-stat');
    let result = await clickNativeAuditButton(iframeWin, 'btn_ReportAuth', {
      action: 'audit',
      expectedStatuses: ['3'],
      batchMode: fast,
      timeoutMs: fast ? (caReady ? 4500 : 7000) : 12000,
      keepWS: !!options.keepWS,
      caSessionReady: caReady,
      // 8.5.53: 复检标本关闭「行消失=成功」（审核前就是 4，行可能因 CA 流程暂时消失）
      // 8.16.25: 跨组标本同样关闭——免切组审核时它不在当前登录组的原生列表里，
      // 「行消失」恒成立，会把没审掉的标本误判成功（同批审路径的处理保持一致）
      missingAsSuccess: auditCtx.allowMissingSuccess && !preStatus4 && !_auditCrossGroup,
      preStatus4, // 8.5.53: 传审核前状态标记，内部成功判定排除静态 4
      targetReportDR: reportDR,
      abortCheck,
      onTick: (elapsed, phase) => {
        if (ft)
        {ft.textContent = `${phase || '审核中'}：${name}${elapsed ? ' ' + Math.round(elapsed / 1000) + 's' : ''}`;}
      }
    });
    if (result === 'incomplete') {
      dbg('单审被原生不完整弹窗拦截:', name);
      showToast(`⚠️ 原生弹窗拦截：${name} 必填项目未存数据，已自动按【取消】阻止审核！`, 'error', 6000);
      return false;
    }
    if (!result && !abortCheck()) {
      iframeWin = getReportIframeWin() || iframeWin;
      // 8.5.53: 复检标本（preStatus4）静态 4 不可信，跳过这里直接走长确认
      if (!preStatus4 && verifyAuditSucceededByReportDR(iframeWin, reportDR)) {return true;}
      result = await confirmAuditEventually(iframeWin, reportDR, name, {
        batchMode: fast,
        targetWasPresent: auditCtx.rowPresent,
        detailWasReady: auditCtx.detailReady,
        afterCA: !caReady,
        preStatus4, // 8.5.53
        abortCheck
      });
      if (result === 'incomplete') {
        dbg('单审 confirmAuditEventually 拦截到不完整弹窗:', name);
        showToast(`⚠️ 原生弹窗拦截：${name} 必填项目未存数据，已自动按【取消】阻止审核！`, 'error', 6000);
        return false;
      }
    }
    if (!preStatus4 && verifyAuditSucceededByReportDR(iframeWin, reportDR)) {return true;}
    // 延迟二次校验：原生状态回写可能有延迟，做短轮询早退；深层兜底由外层 confirmAuditEventuallyLive 处理
    if (!result && !abortCheck()) {
      // 8.17.6: 先校验再等待（原实现首轮盲等 120ms）；轮数 4→5 保证总窗口仍是 4×120ms
      for (let _dv = 0; _dv < 5 && !abortCheck(); _dv++) {
        iframeWin = getReportIframeWin() || iframeWin;
        const _dConf = handleNativeMessageConfirm(iframeWin);
        if (_dConf === 'incomplete') {
          dbg('单审延迟校验拦截到不完整弹窗:', name);
          return false;
        }
        if (verifyAuditSucceededByReportDR(iframeWin, reportDR, { accept4: !preStatus4 }) ||
            softAuditSuccessHint(iframeWin, reportDR, { accept4: !preStatus4 })) {
          dbg('延迟二次校验：标本已审核成功（原生状态）');
          closeNativeAuditSuccessMessage(iframeWin);
          return true;
        }
        await sleep(120);
      }
    }
    // 最终返回前也关闭可能残留的原生弹窗
    if (result === true) {closeNativeAuditSuccessMessage(iframeWin);}
    return result;
  }
  // 8.17.2: 「这次原生审核是不是自动审核机器人发起的」——**不能用 `_autoAuditRunning` 判断**：
  // 自动审核一轮可能持续几十秒到几分钟（整批 `await executeBatchAudit` 期间它一直是 true），
  // 用户在轮次进行中插入的手动审核会被误判成机器人 → 人工审核留痕打不上 → 手工审掉的标本
  // 继续留在「自动审核记录」里、也不折叠（8.17.1 现场反馈就是这个）。
  // 改为由机器人**显式包裹自己发起的那次审核**；批量队列那条路径由 `queue._autoMode` 判定
  // （批审主循环直接调 clickNativeAuditButton，压根不过 executeNativeAudit）。
  let _robotAuditDepth = 0;
  function robotAuditBegin() {_robotAuditDepth++;}
  function robotAuditEnd() {_robotAuditDepth = Math.max(0, _robotAuditDepth - 1);}
  function isRobotAuditCtx() {return _robotAuditDepth > 0;}

  // 8.5.82: 包装层——任何路径（提前 return / 异常）都复位 preStatus4 共享标记。
  // 原实现只有最后一条路径复位，复检标本审核成功的两条 early-return 会泄漏 true，
  // 把下一条标本的静态 status-4 成功匹配误拒（触发多余重试/误报）
  async function executeNativeAudit(iframeWin, specimen, options = {}) {
    let _ok = false;
    try {
      _ok = await _executeNativeAuditImpl(iframeWin, specimen, options);
      return _ok;
    } finally {
      _auditingPreStatus4 = false; // 8.5.53: 审核结束重置
      _auditingCrossGroup = false; // 8.16.25: 同上（不留残标记影响后续同组标本）
      // 8.17.1/8.17.2: 人工审核留痕——走 executeNativeAudit 的入口（详情面板 / 详情面板回车 /
      // 卡片回车 / F4 定位审核）都记在这里；批审队列那条路径由 continueAuditQueue 记（它直接调
      // clickNativeAuditButton）。判定用 isRobotAuditCtx()（机器人显式包裹），**不用 `_autoAuditRunning`**。
      try {
        if (_ok && !isRobotAuditCtx()) {
          humanAuditMark(specimen && (specimen.ReportDR || specimen.reportDR));
          // 8.17.10: 审核留痕（详情面板 / 面板内回车 / 卡片回车都走这里）
          const _snapN = auditTraceSnapshot(specimen);
          auditTraceAdd({
            dr: specimen && (specimen.ReportDR || specimen.reportDR),
            labno: specimen && specimen.Labno,
            pat: specimen && specimen.PatName,
            mn: specimen && (specimen._mn || specimen.MachineName),
            path: '详情面板/回车',
            ic: _snapN.ic,
            nrr: _snapN.nrr,
            verdict: _snapN.verdict
          });
        }
      } catch (e) {}
    }
  }

  // 8.17.12: 关闭原生 LIS 审核成功后的弹窗（严格只关成功提示，绝不误触确认窗/不完整弹窗）
  function closeNativeAuditSuccessMessage(iframeWin) {
    try {
      const win = iframeWin || getReportIframeWin();
      if (!win) {return;}
      const doc = win.document;
      const jq = win.jQuery || win.$;
      if (!doc || !jq) {return;}
      const allWins = doc.querySelectorAll('.messager-window:not([style*="display: none"]), .window:not([style*="display: none"])');
      for (const w of allWins) {
        if (w.offsetParent === null) {continue;}
        const body = w.querySelector('.messager-body, .panel-body');
        if (!body) {continue;}
        const text = (body.textContent || '').trim();
        const kind = classifyNativeMessage(text);
        if (kind === 'incomplete') {
          // 8.17.12: 绝不可按确定！若残存必填项目未存数据弹窗，主动按【取消】阻止审核
          const btns = w.querySelectorAll('a.l-btn, button');
          for (const b of btns) {
            const bText = (b.textContent || b.value || '').trim();
            if (bText === '取消' || bText === 'No' || bText === '否' || bText === '关闭') {
              try { jq && jq(b).click ? jq(b).click() : b.click(); } catch (e) { try { b.click(); } catch (e2) {} }
              dbg('closeNativeAuditSuccessMessage 拦截到不完整弹窗，已主动按【取消】阻止审核');
              break;
            }
          }
          continue;
        }
        // 必须严格属于 success 类别才允许按「确定/OK/关闭」
        if (kind === 'success') {
          const btns = w.querySelectorAll('a.l-btn, button');
          for (const b of btns) {
            const bText = (b.textContent || b.value || '').trim();
            if (bText === '确定' || bText === 'OK' || bText === '关闭') {
              try { jq && jq(b).click ? jq(b).click() : b.click(); } catch (e) { try { b.click(); } catch (e2) {} }
              dbg('已关闭原生审核成功弹窗');
              break;
            }
          }
        }
      }
    } catch (e) {}
  }

  // 8.9.0: 列表审核与详情审核共用的「延迟兜底校验」——executeNativeAudit 可能因竞态误判失败，
  // 此处多重确认：原生状态轮询（250ms×8，成功早退）→ 刷新 wsData（分类中会被跳过则重试 ×4）→ 本地状态判定。
  // 此前两处各维护一份几乎相同的块，改一处漏一处的风险已存在
  async function confirmAuditEventuallyLive(iframeWin, reportDR, specimen) {
    // 8.5.53: 复检标本（审核前 status 4）verify 只认状态变 3
    const pre4 = String(specimen.Status || specimen.ReportStatus || '') === '4';
    // 8.17.6: 先校验再等待（原实现首轮盲等 150ms）；轮数 6→7 保证总窗口仍是 6×150ms
    for (let _dv = 0; _dv < 7; _dv++) {
      iframeWin = getReportIframeWin() || iframeWin;
      const _cLRes = handleNativeMessageConfirm(iframeWin);
      if (_cLRes === 'incomplete') {
        dbg('confirmAuditEventuallyLive: 拦截到原生不完整弹窗，终止确认并返回 incomplete');
        return 'incomplete';
      }
      if (verifyAuditSucceededByReportDR(iframeWin, reportDR, { accept4: !pre4 }) ||
          softAuditSuccessHint(iframeWin, reportDR, { accept4: !pre4 })) {
        dbg('审核延迟确认成功（原生状态）:', specimen.PatName);
        return true;
      }
      await sleep(150);
    }
    // 刷新 wsData 后再检查状态（审核期间轮询已停止）。
    // 分类进行中 force:false 会被跳过（8.5.4），重试等分类完成，
    // 避免读到审核前旧状态把已成功误报为失败。
    try {
      for (let _rt = 0; _rt < 2; _rt++) {
        const loadResult = await loadWSData({ force: false });
        if (loadResult && !loadResult.skipped) {dbg('延迟校验前已刷新 wsData'); break;}
        await sleep(800);
      }
    } catch (e) {}
    const liveRow = wsData.find(r => String(r.ReportDR) === String(reportDR));
    const liveStatus = liveRow ? String(liveRow.Status || liveRow.ReportStatus || '') : '';
    // 复检标本（审核前 status 4）需状态变 3 才算成功（审核前就是 4）
    if (liveStatus === '3' || (liveStatus === '4' && !pre4)) {
      dbg('审核延迟确认成功（wsData 状态）:', specimen.PatName);
      return true;
    }
    return false;
  }

  async function auditAbnormalSpecimen(specimen, options = {}) {
    // 8.5.82: quiet=true（自动审核夜间调用）——静默全部 toast（含 error），结果走返回值+日志；
    // 手动路径不传 options，行为不变。此前调用方传 {quiet:true} 但函数根本不收这个参数
    const _quiet = !!options.quiet;
    const _toast = (msg, type) => {
      if (_quiet) {return;}
      showToast(msg, type);
    };
    // 8.5.8: 消费一次跨组详情续审标记（无论成功失败都只触发一次，避免失败后残留误开详情）
    const _resumeDetail = _resumeDetailAfterAudit;
    _resumeDetailAfterAudit = false;
    if (_abnormalAuditInProgress) {
      _abnormalAuditQueued = true;
      const ft = document.getElementById('lis-ws-ft-stat');
      if (ft) {ft.textContent = '审核进行中，下一条已排队...';}
      return;
    }
    if (_auditInProgress) {
      _toast('正在批量审核中，请稍候', 'warning');
      return;
    }
    // 8.5.82: 与 _auditFromDetailPanel 的互检对称——详情面板审核不持有 _auditInProgress，
    // 不查此项会出现两个审核流并发驱动原生页（选行互相覆盖）
    if (_detailAuditInProgress) {
      _toast('正在详情面板审核中，请稍候', 'warning');
      return;
    }
    if (!specimen) {
      const data = filteredData();
      if (data.length) {
        wsAbnormalIndex = Math.max(0, Math.min(wsAbnormalIndex, data.length - 1));
        specimen = data[wsAbnormalIndex];
      }
    }
    if (!specimen) {
      _toast('没有可审核的待审标本', 'warning');
      return;
    }

    // 预校验：在标记 UI/设锁之前检查，避免"正在审核..."瞬间变"已审/不完整"的两个弹窗
    // 待审视图：正常行走 normal 上下文（NORMAL 才放行），异常/危急行走 abnormal 上下文（危急仍拦截）
    const _bucket = getWSAuditBucket(specimen);
    const _preClassCheck = validateAuditClassification(specimen.ReportDR, _bucket === 'normal' ? 'normal' : 'abnormal');
    if (!_preClassCheck.ok) {
      _toast(_preClassCheck.msg, _preClassCheck.msg.indexOf('危急') !== -1 ? 'error' : 'warning');
      advanceAbnormalFocusAfterSkip(Math.max(0, wsAbnormalIndex));
      return;
    }
    if (!isSpecimenActuallyComplete(specimen)) {
      _toast(`跳过: ${specimen.PatName} 结果不完整`, 'warning');
      advanceAbnormalFocusAfterSkip(Math.max(0, wsAbnormalIndex));
      return;
    }
    const _preStatus = String(specimen.Status || specimen.ReportStatus || '');
    // 8.5.52: 复审（status 4）标本可正常审核（除危急值外）——移除 8.5.50 的全拦；
    // 危急值由下方 validateAuditClassification 的 CRITICAL 红线拦截
    // status 3（一审完成）仍拦截（已审核，不在待审视图）
    if (_preStatus === '3') {
      _toast(`跳过: ${specimen.PatName} 已审核`, 'warning');
      advanceAbnormalFocusAfterSkip(Math.max(0, wsAbnormalIndex));
      return;
    }

    let _auditSafetyTimer = null;
    const resumeWSRefresh = !!wsTimer;
    // 8.5.58: 审核结果标记（供自动审核统计成功/失败；手动 Enter 路径不受影响）
    let _auditOutcome = false;

    try {
      _abnormalAuditInProgress = true;
      _abnormalAuditQueued = false;
      clearNativeUserSelectLock();
      updateAbnormalEnterBridge();
      keepWorkbenchOnTop('审核');
      markAbnormalAuditUI(specimen, 'start');
      // 安全超时：60 秒后显示警告，但不释放锁（finally 块负责释放）
      _auditSafetyTimer = setTimeout(() => {
        if (_abnormalAuditInProgress) {
          dbg('异常审核安全超时：操作耗时超过 60 秒');
          _toast('审核操作耗时较长，请耐心等待', 'warning');
        }
      }, 60000);
      dbg('异常列表审核开始:', specimen.PatName);
      stopWSRefresh();
      const startIndex = Math.max(0, wsAbnormalIndex);
      const targetDR = String(specimen.ReportDR || '');
      const ft = document.getElementById('lis-ws-ft-stat');
      if (ft) {ft.textContent = `审核：${specimen.PatName || specimen.Labno || targetDR}`;}

      // 8.16.16: 跨组判定用可信登录组——取不到权威值时 _wsCrossGroupTry 为 false，
      // 即「不确定就不切组」，只走免切组尝试；避免误判把本组标本当成跨组去切。
      const curDR = resolveLoginWGReliable();
      const spDR = specimen._wg || '';
      // 8.5.10: 跨组先试不切组——原生报告页可按 WorkGroupMachineDR 直接跨组加载并审核
      // （实测：临检组下免疫组x8 标本可直接审），不再立即切组；仅当原生列表选不到标本
      // （prep.reason='select'）时才回退 safeSwitchWG 切组重试（见 prep 失败分支）。
      const _wsCrossGroupTry = !!(spDR && curDR && spDR !== curDR);
      // 不切组直接审：先把 origin 钉在当前组，避免审完被陈旧 origin 误切回
      if (_wsCrossGroupTry) {saveAuditOriginCurrent('list');}

      // 若后台预热正针对本标本进行（8.5.3 后正常行也预热），等它完成再定位，
      // 避免列表审核与预热双线程驱动同一原生页（awaitAbnormalPrewarm 此时因锁直接返回，不等待）
      if (_abnormalPrewarmPromise && String(_abnormalPrewarmDR || '') === String(targetDR)) {
        try { await _abnormalPrewarmPromise; } catch (e) {}
      }
      if (ft) {ft.textContent = `审核：准备原生页面 ${specimen.PatName || specimen.Labno || targetDR}`;}
      releaseNativeReportFocus(); // 先 blur 原生编辑焦点，避免审核按钮/回车被结果格吃掉

      let iframeWin = getReportIframeWin();
      if (!iframeWin) {
        if (ft) {ft.textContent = '审核：加载报告页...';}
        iframeWin = await ensureReportPageLoaded({ keepWS: true, fast: true });
      }
      if (!iframeWin) {
        await sleep(80);
        iframeWin = getReportIframeWin() || (await ensureReportPageLoaded({ keepWS: true, fast: true }));
      }
      if (!iframeWin) {
        _toast('报告页面加载失败', 'error');
        advanceAbnormalFocusAfterSkip(startIndex);
        return;
      }

      const detailReady = isReportDetailLoaded(iframeWin, targetDR);
      if (ft)
      {ft.textContent = detailReady
        ? `审核：审核中 ${specimen.PatName || specimen.Labno || targetDR}`
        : `审核：选中 ${specimen.PatName || specimen.Labno || targetDR}`;}
      const skipSelect = _abnormalNativeReadyDR === targetDR;
      let prep = { ok: false, iframeWin, lastMdr: _abnormalLastMdr };
      if (detailReady && skipSelect) {
        prep.ok = true;
      } else {
        prep = await ensureSpecimenReadyForAudit(iframeWin, specimen, {
          lastMdr: _abnormalLastMdr,
          skipSelect: detailReady || skipSelect,
          abnormalFast: true,
          forceSelect: true
        });
      }
      _abnormalNativeReadyDR = '';
      iframeWin = prep.iframeWin || iframeWin;
      if (prep.lastMdr) {_abnormalLastMdr = prep.lastMdr;}
      if (!prep.ok) {
        // 8.5.10: 跨组先试不切组失败（原生列表选不到 / 详情加载不出）→ 回退切组重试
        if (
          _wsCrossGroupTry &&
          (prep.reason === 'select' || prep.reason === 'detail') &&
          spDR &&
          resolveLoginWGReliable() &&
          spDR !== resolveLoginWGReliable()
        ) {
          const wgName = (WG_MAP[spDR] || {}).name || spDR;
          _toast(`未找到标本/详情未加载，切换到${wgName}重试`, 'warning');
          saveAbnormalTarget(specimen);
          _abnormalAuditQueued = false; // 切组续跑由 saveAbnormalTarget 机制处理，不用旧索引
          safeSwitchWG(spDR);
          return;
        }
        const msg = prep.reason === 'detail' ? '报告详情未加载完成' : '未在原生列表中找到该标本';
        _toast(msg, prep.reason === 'detail' ? 'warning' : 'error');
        advanceAbnormalFocusAfterSkip(startIndex);
        return;
      }

      if (ft) {ft.textContent = `审核：审核中 ${specimen.PatName || specimen.Labno || targetDR}`;}
      releaseNativeReportFocus();
      let auditResult = await executeNativeAudit(iframeWin, specimen, { keepWS: true, fast: true });
      if (auditResult === 'incomplete') {
        _toast(`跳过: ${specimen.PatName} 结果不完整`, 'warning');
        advanceAbnormalFocusAfterSkip(startIndex);
        return;
      }
      // 最终兜底：executeNativeAudit 可能因竞态误判失败，多重校验确认
      // 8.9.0: 延迟兜底校验抽为 confirmAuditEventuallyLive 共用（250ms 轮询早退）
      if (!auditResult) {
        if (ft) {ft.textContent = `确认审核结果: ${specimen.PatName || specimen.Labno || targetDR}`;}
        auditResult = await confirmAuditEventuallyLive(iframeWin, targetDR, specimen);
      }
      if (!auditResult) {
        _toast('未确认审核成功，已跳到下一条', 'warning');
        advanceAbnormalFocusAfterSkip(startIndex);
        return;
      }
      if (ft) {ft.textContent = `已审核: ${specimen.PatName || specimen.Labno || targetDR}`;}
      _toast(`已审核: ${specimen.PatName || specimen.Labno || ''}`, 'success');
      closeNativeAuditSuccessMessage(iframeWin);
      // 8.5.54: 复检标本审核成功 → 记录「曾复审」，供全部视图显示双标识
      if (String(specimen.Status || specimen.ReportStatus || '') === '4') {recheckDoneAdd(targetDR);}
      _auditOutcome = true; // 8.5.58

      // 8.8.27: 若当前开启了自动审核但处于跨组独立续审状态（!_autoAuditRunning），记录事件并主动触发推送
      if (autoAuditEnabled() && !_autoAuditRunning) {
        try {
          const _si = auditRecordSpecInfo(targetDR, specimen);
          const _entry = {
            n: specimen.PatName || '',
            l: specimen.Labno || '',
            labno: specimen.Labno || '',
            seq: specimen.EpisodeNo || specimen.episodeNo || '',
            mn: specimen._mn || specimen.MachineName || '',
            d: String(targetDR),
            t: 'abnormal',
            test: _si.test,
            abn: _si.abn,
            items: _si.items,
            acceptDT: specimen.AcceptDT || specimen.acceptDT || ''
          };
          aaRecordEvent('异常', _entry);
          // 8.8.30: 结算统一走 aaSettleAccum；优先用内存累积器（storage 可能落后 ≤1s 或为空，
          // 直接 _aaAccumLoad() 会覆盖/吞掉最新事件造成漏报）
          if (!_aaAccum) {_aaAccumLoad();}
          if (_aaAccum) {
            aaSettleAccum(_aaAccum);
            aaClear();
          }
        } catch (e) {dbg('跨组异常审核推送异常:', e);}
      }

      delete wsClassifiedCache[specimen.ReportDR];
      _wsLocalRemoved.add(String(specimen.ReportDR)); // 8.9.0: 防在途旧快照把该行带回列表
      wsData = wsData.filter(r => r.ReportDR !== specimen.ReportDR);
      invalidateCaches();
      calcMachineCounts();
      noteAbnormalNativeReadyAfterAudit(iframeWin, targetDR);
      removeAuditedAbnormalCard(targetDR, startIndex);

      // 8.5.8: 跨组审核续跑 ——
      // 1) 详情来源（详情面板跨组切组恢复）：审完目标条自动重开详情面板，连续审核跨组不断
      // 2) 待审队列全部审空：自动切回起始工作组（不用手动回 LIS 切组再回工作台）
      if (_resumeDetail) {
        _resumeDetailAfterAudit = false;
        try {
          const after = filteredData();
          if (after.length) {
            const idx = Math.max(0, Math.min(wsAbnormalIndex, after.length - 1));
            const nxt = after[idx];
            if (nxt && String(nxt.ReportDR) !== targetDR) {
              openDetailPanel(nxt, getWSAuditBucket(nxt) === 'normal' ? 'normal' : 'abnormal', idx);
            }
          }
        } catch (e) {}
      }
      // 审空（跨组待审队列已清）→ 自动切回起始工作组（分类中/搜索中会自动延迟重试）
      trySwitchBackToOrigin();
    } catch (e) {
      dbg('审核失败:', e);
      _toast('审核失败: ' + e.message, 'error');
    } finally {
      clearTimeout(_auditSafetyTimer);
      clearAbnormalAuditingCard(specimen && specimen.ReportDR);
      _abnormalAuditInProgress = false;
      if (resumeWSRefresh && isWSVisible()) {startWSRefresh();}
      updateWSFooter();
      dbg('异常列表审核结束');
      // 8.8.2: 手动单条审核跨午夜/历史标本后恢复原生日期框（自动审核一轮的恢复由 autoAuditTick finally 统一收口；
      // 有排队下一条时不恢复——连续 Enter 审历史标本时避免每条都切来切去，审完最后一条才恢复今天）
      if (!_autoAuditRunning && !_abnormalAuditQueued) {restoreNativeDateboxToday();}
      if (wsCategory === 'audit') {scheduleAbnormalFocusRecovery();}
      if (_abnormalAuditQueued) {
        _abnormalAuditQueued = false;
        // 用户在审核完成前切走了待审分类：不再续审（filteredData 已是别的分类）
        if (wsCategory !== 'audit') {
          dbg('F4 排队续审取消: 已离开待审分类');
        } else {
          const data = filteredData();
          if (data.length) {
            const idx = Math.max(0, Math.min(wsAbnormalIndex, data.length - 1));
            setTimeout(() => auditAbnormalSpecimen(data[idx]), 30);
          }
        }
      } else {
        prefetchAbnormalAuditContext();
      }
      return _auditOutcome; // 8.5.58: 返回审核结果（true=成功），供自动审核统计
    }
  }

  // --- 8.5.31: 病房采集视图（只读） — 标本已采未送，无核收、无审核 ---
  // 与 renderIncompleteView 共用样式（条纹 / 行点击 → 详情），仅 banner 文案与列定义不同。
  // 8.9.0: 只读视图（采集/不完整）共用的行点击委托——行点击开详情、空白处收回；
  // 沿用 _incompleteClickHandler 属性名，移除旧委托防止刷新累积多个处理器
  function bindReadOnlyRowClick(body) {
    if (body._incompleteClickHandler) {
      body.removeEventListener('click', body._incompleteClickHandler);
    }
    body._incompleteClickHandler = e => {
      const tr = e.target.closest('tr[data-rdr]');
      if (!tr) {
        if (isDetailPanelVisible()) {closeDetailPanel();}
        return;
      }
      const specimen = findWSSpecimenByReportDR(tr.dataset.rdr);
      if (specimen) {openDetailPanel(specimen);}
    };
    body.addEventListener('click', body._incompleteClickHandler);
  }

  // 8.15.26: 提取标本患者详细元信息（申请医生/性别年龄/科室床号等），支持多级字段回退与缓存联动
  function getWSPatientMeta(r) {
    if (!r) {return { doc: '—', sex: '', age: '', dept: '', ward: '', bed: '', locBed: '—', sexAge: '—' };}
    const cached = (typeof wsClassifiedCache !== 'undefined' && wsClassifiedCache && wsClassifiedCache[r.ReportDR]) || null;
    const cr = (cached && cached.row) || r;
    const li = (cached && cached.labInfo) || {};

    const rawDoc =
      cr.Doctor || cr.DoctorName || cr.ReqDoctorName || cr.ApplyDoctorName ||
      cr.OrderDoctor || cr.DocName || cr.RequestUser || cr.InDocName || cr.ReqDoc || cr.DoctorDesc ||
      cr.ApplyDoc || cr.ReqDoctor || cr.OrderDoc || cr.AppDoctor ||
      r.Doctor || r.DoctorName || r.ReqDoctorName || r.ApplyDoctorName ||
      r.OrderDoctor || r.DocName || r.RequestUser || r.InDocName || r.ReqDoc || r.DoctorDesc ||
      r.ApplyDoc || r.ReqDoctor || r.OrderDoc || r.AppDoctor ||
      li.Doctor || li.DoctorName || li.ReqDoctorName || li.ApplyDoctorName || '';
    const doc = String(rawDoc || '').trim();

    const sex = String(cr.Species || cr.Sex || cr.SexDesc || r.Species || r.Sex || r.SexDesc || li.Species || li.Sex || '').trim();
    const ageVal = String(cr.Age || r.Age || li.Age || '').trim();
    const ageUnit = String(cr.AgeUnit || r.AgeUnit || li.AgeUnit || '').trim();
    const age = ageVal ? (ageVal + ageUnit) : String(cr.PatAge || r.PatAge || '').trim();

    const dept = String(
      cr.Location || cr.LocationName || cr.LocDesc || cr.DeptName || cr.Department || cr.AdmLoc || cr.ReqDept || cr.LocName ||
      r.Location || r.LocationName || r.LocDesc || r.DeptName || r.Department || r.AdmLoc || r.ReqDept || r.LocName ||
      li.Location || li.LocationName || ''
    ).trim();

    const ward = String(
      cr.Ward || cr.WardName || cr.WardDesc || r.Ward || r.WardName || r.WardDesc || li.Ward || li.WardName || ''
    ).trim();

    const bedRaw = cr.BedNo || cr.Bed || cr.BedNum || r.BedNo || r.Bed || r.BedNum || li.BedNo || li.Bed || '';
    const bed = formatDetailBedNo(bedRaw);

    const sexAge = [sex, age].filter(Boolean).join('/') || '—';
    const loc = dept && ward && ward !== dept ? `${dept} (${ward})` : (dept || ward || '');
    const locBed = [loc, bed].filter(Boolean).join(' ') || '—';

    return {
      doc: doc || '—',
      sex,
      age,
      dept,
      ward,
      bed,
      locBed,
      sexAge
    };
  }

  // 8.15.28: 提取标本采集时间（用于采集列表及标本详情顶栏展示）
  function getSpecimenCollectTime(r) {
    if (!r) {return '';}
    const cached = (typeof wsClassifiedCache !== 'undefined' && wsClassifiedCache && wsClassifiedCache[r.ReportDR]) || null;
    const cr = (cached && cached.row) || r;
    const li = (cached && cached.labInfo) || {};
    const raw =
      r.CollectDT ||
      cr.CollectDT ||
      li.CollectDT ||
      r.CollectionDT ||
      cr.CollectionDT ||
      ((r.CollectionDate || r.CollectDate || cr.CollectionDate || cr.CollectDate || li.CollectionDate || li.CollectDate || '') + ' ' +
       (r.CollectionTime || r.CollectTime || cr.CollectionTime || cr.CollectTime || li.CollectionTime || li.CollectTime || '')).trim() ||
      r.CollectDate ||
      cr.CollectDate ||
      '';
    if (!raw) {return '';}
    const m = raw.match(/^(\d{4})-(\d{2})-(\d{2})\s+(\d{2}):(\d{2})(?::\d{2})?/);
    if (m) {return m[1] + '-' + m[2] + '-' + m[3] + ' ' + m[4] + ':' + m[5];}
    return raw;
  }

  // 8.15.30: 提取标本接收时间（用于待排列表及标本详情顶栏展示）
  function getSpecimenReceiveTime(r) {
    if (!r) {return '';}
    const cached = (typeof wsClassifiedCache !== 'undefined' && wsClassifiedCache && wsClassifiedCache[r.ReportDR]) || null;
    const cr = (cached && cached.row) || r;
    const li = (cached && cached.labInfo) || {};
    const raw =
      r.ReceiveDT ||
      cr.ReceiveDT ||
      li.ReceiveDT ||
      ((r.ReceiveDate || cr.ReceiveDate || li.ReceiveDate || '') + ' ' +
       (r.ReceiveTime || cr.ReceiveTime || li.ReceiveTime || '')).trim() ||
      r.ReceiveDate ||
      cr.ReceiveDate ||
      '';
    if (!raw) {return '';}
    const m = raw.match(/^(\d{4})-(\d{2})-(\d{2})\s+(\d{2}):(\d{2})(?::\d{2})?/);
    if (m) {return m[1] + '-' + m[2] + '-' + m[3] + ' ' + m[4] + ':' + m[5];}
    return raw;
  }

