  // --- 全部标本视图 ---
  function renderAllView(data, body) {
    const stMap = {
      0: { t: '待排样', cls: 'st-0t' },
      1: { t: '登记', cls: 'st-1t' },
      2: { t: '初审', cls: 'st-2t' },
      3: { t: '审核', cls: 'st-3t' },
      4: { t: '复审', cls: 'st-4t' }, // 8.5.50: 补配色（复检/复查标本在全部视图可辨）
      5: { t: '取消', cls: 'st-5t' },
      9: { t: '采集', cls: 'st-9t' } // 8.5.31: 病房采集中（全部视图）
    };

    let h = '<table><thead><tr>';
    h += '<th style="width:30px"><input type="checkbox" id="lis-ws-chka" /></th>';
    h +=
      '<th>仪器</th><th>状态</th><th>完整度</th><th>流水号</th><th>姓名</th><th>检验号</th><th>医嘱</th><th>核收时间</th><th style="width:84px">忽略</th>';
    h += '</tr></thead><tbody>';

    data.forEach((r, i) => {
      const statusVal = r.Status || r.ReportStatus || '';
      const st = stMap[statusVal] || { t: r.StatusDesc || '?', cls: '' };
      const ck = wsChecked.has(r.ReportDR) ? 'checked' : '';
      // 8.5.33: 仅待排(0)/采集(9)行可忽略；已忽略行灰显+删除线
      const ignorable = statusVal === '0' || statusVal === '9';
      const ignored = isWSIgnored(r.ReportDR);
      // 8.5.34: 忽略行 checkbox 禁用且不可被全选带上（忽略=不再管它）
      const ckAttr = ignored ? ' disabled' : ck ? ' checked' : '';
      h += `<tr class="st-${escAttr(statusVal)} ${wsChecked.has(r.ReportDR) && !ignored ? 'sel' : ''}${ignored ? ' ws-ignored' : ''}" data-i="${i}" data-rdr="${escAttr(r.ReportDR || '')}">`; // 8.9.0: statusVal 加固转义
      h += `<td><input type="checkbox" class="lis-ws-ck" data-rdr="${escAttr(r.ReportDR || '')}"${ckAttr} /></td>`;
      h += `<td>${highlightText(r._mn || '', wsSearchQuery)}</td>`;
      // 8.5.54: 审核后（status 3）且曾为复审的标本 → 显示『审核』+『复审』双标识
      let stHTML = `<span class="st-tag ${st.cls}">${esc(st.t)}</span>`;
      if (String(statusVal) === '3' && isRecheckDone(r.ReportDR)) {
        stHTML += ' <span class="st-tag st-4t" title="曾复检/复查">复审</span>';
      }
      // 8.5.66: 今日已由自动审核审核的标本 → 🤖 徽章（点击行即可查看结果详情）
      if (String(statusVal) === '3' && autoAuditedTodayHas(r.ReportDR)) {
        stHTML += ' <span class="ws-aa-mark" title="今日已由自动审核审核 · 点击行查看结果">🤖 自动</span>';
      }
      h += `<td>${stHTML}</td>`;
      const icHTML = completenessBadgeHTML(r, false);
      h += `<td>${icHTML}</td>`;
      h += `<td><b>${highlightText(r.EpisodeNo || '', wsSearchQuery)}</b></td>`;
      h += `<td>${admTypeBadgeHTML(r)}${highlightText(r.PatName || '', wsSearchQuery)}</td>`;
      h += `<td>${highlightText(r.Labno || '', wsSearchQuery)}</td>`;
      h += `<td>${highlightText(r.TestSetDesc || '', wsSearchQuery)}</td>`;
      h += `<td>${esc(r.AcceptDT || '')}</td>`;
      h += `<td style="text-align:center">${ignorable ? wsIgnoreBtnHTML(r.ReportDR) : ''}</td>`;
      h += '</tr>';
    });
    h += '</tbody></table>';
    body.innerHTML = '<div class="ws-table-wrap">' + h + '</div>';

    _bindTableEvents(body, data, 'all');
  }

  // --- 通用表格事件绑定 ---
  // 事件委托：在 body 上监听，减少逐元素绑定
  function _bindTableEvents(body, data, source) {
    // 移除旧的委托监听器
    if (body._delegatedHandler) {
      body.removeEventListener('click', body._delegatedHandler.click);
      body.removeEventListener('change', body._delegatedHandler.change);
      body.removeEventListener('dblclick', body._delegatedHandler.dblclick);
    }

    const handlers = {};

    // click 委托：行点击 → 详情；空白处点击 → 收回详情
    handlers.click = e => {
      const tr = e.target.closest('tr[data-rdr]');
      if (!tr) {
        // 点击空白处，收回详情面板
        if (isDetailPanelVisible()) {closeDetailPanel();}
        return;
      }
      if (e.target.closest('input[type="checkbox"]')) {return;}
      body.querySelectorAll('tr.active-row').forEach(r => r.classList.remove('active-row'));
      tr.classList.add('active-row');
      const specimen = findWSSpecimenByReportDR(tr.dataset.rdr);
      if (!specimen) {return;}
      const idx = filteredData().findIndex(r => String(r.ReportDR) === String(specimen.ReportDR));
      openDetailPanel(specimen, source || 'all', idx >= 0 ? idx : parseInt(tr.dataset.i));
    };

    // change 委托：checkbox 选中
    handlers.change = e => {
      if (e.target.id === 'lis-ws-chka') {
        body.querySelectorAll('.lis-ws-ck').forEach(c => {
          // 8.5.34: 全选跳过忽略行（忽略行 checkbox 已禁用，这里兜底）
          if (isWSIgnored(c.dataset.rdr)) {
            c.checked = false;
            c.closest('tr').classList.remove('sel');
            return;
          }
          if (e.target.checked) {wsChecked.add(c.dataset.rdr);}
          else {wsChecked.delete(c.dataset.rdr);}
          c.checked = e.target.checked;
          c.closest('tr').classList.toggle('sel', e.target.checked);
        });
        return;
      }
      if (e.target.classList.contains('lis-ws-ck')) {
        if (isWSIgnored(e.target.dataset.rdr)) {e.target.checked = false;return;} // 8.5.34: 忽略行不可勾选
        if (e.target.checked) {wsChecked.add(e.target.dataset.rdr);}
        else {wsChecked.delete(e.target.dataset.rdr);}
        e.target.closest('tr').classList.toggle('sel', e.target.checked);
      }
    };

    // dblclick 委托：双击 → 原生界面
    handlers.dblclick = e => {
      const tr = e.target.closest('tr[data-rdr]');
      if (!tr) {return;}
      if (e.target.closest('input[type="checkbox"]')) {return;}
      const specimen = findWSSpecimenByReportDR(tr.dataset.rdr);
      if (specimen) {navigateToSpecimen(specimen);}
    };

    body.addEventListener('click', handlers.click);
    body.addEventListener('change', handlers.change);
    body.addEventListener('dblclick', handlers.dblclick);
    body._delegatedHandler = handlers;
  }

  // --- 导航到原生界面 ---
  // 8.9.0: 延迟在原生工作列表中按 ReportDR/Labno 选中对应行——
  // navigateToSpecimen 与 checkNavigateTarget（跨组跳转恢复）各有一份相同逻辑，抽为共用
  function selectNativeRowAfterDelay(reportDR, labno, delayMs) {
    setTimeout(() => {
      try {
        const iframeWin = getReportIframeWin();
        if (!iframeWin) {return;}
        const jq = iframeWin.jQuery || iframeWin.$;
        if (!jq) {return;}
        const dg = jq('#dgWorkList');
        if (!dg.length) {return;}
        const rows = dg.datagrid('getRows');
        if (!rows || rows.length === 0) {return;}
        // 根据 ReportDR 或 Labno 选中对应行
        for (let i = 0; i < rows.length; i++) {
          if (String(rows[i].ReportDR) === String(reportDR) || String(rows[i].Labno) === String(labno)) {
            dg.datagrid('selectRow', i);
            dbg('导航: 已选中行', i, 'ReportDR:', reportDR);
            break;
          }
        }
      } catch (e) {
        dbg('导航选行失败:', e);
      }
    }, delayMs || 1500);
  }

  function navigateToSpecimen(row) {
    const curDR = wgDR();
    const targetDR = row._wg;
    const labno = row.Labno;
    const mdr = row._mdr;
    const reportDR = row.ReportDR;

    // 保存导航目标
    try {
      localStorage.setItem(
        K.tgt,
        JSON.stringify({
          wgDR: targetDR,
          machineDR: mdr,
          labno: labno,
          reportDR: reportDR,
          time: Date.now()
        })
      );
    } catch (e) {}

    if (targetDR !== curDR) {
      // 需要切换工作组
      toast('正在切换到 ' + (WG_MAP[targetDR] || {}).name + '...', 'w');
      safeSwitchWG(targetDR);
      return;
    }

    // 同工作组：直接操作原生界面
    closeWS();

    // 尝试设置仪器选择
    try {
      const w = uw();
      if (w.me) {
        w.me.WorkGroupMachineDR = mdr;
        // 尝试设置 combogrid
        if (typeof w.$ !== 'undefined') {
          try {
            w.$('#cmb_WorkGroupMachine').combogrid('setValue', mdr);
          } catch (e) {}
          // 设置快速搜索
          try {
            w.$('#txt_FindFast').val(labno);
          } catch (e) {}
        }
      }
      // 触发搜索
      if (typeof uw().FindFast === 'function') {
        uw().FindFast(labno);
      } else if (typeof uw().ShowWorkList === 'function') {
        const dateStr = today();
        const findStr = '&WorkGroupMachineDR=' + mdr + '&ReportStatus=&SttAccDate=' + dateStr;
        uw().ShowWorkList(findStr);
      }

      // 等待搜索结果加载并选中对应行
      selectNativeRowAfterDelay(reportDR, labno);
    } catch (e) {
      dbg('导航失败:', e);
    }
  }

  let _saveQueueTimer = null;
  // 批量写入节流：批审标本多时，避免每条都全量序列化整队写 localStorage（O(N²) 卡顿）
  const QUEUE_SAVE_THROTTLE = 10; // 每 N 条才全量落盘一次
  let _queueSaveMod = 0;
  function _writeFullQueue(queue) {
    if (_batchAbort || (queue && queue._aborted)) {return;}
    try {
      localStorage.setItem(K.auditQueue, JSON.stringify({ ...queue, time: Date.now() }));
    } catch (e) {
      dbg('_writeFullQueue 失败:', e.message);
    }
  }
  function _writeQueueProgress(queue) {
    if (_batchAbort || (queue && queue._aborted)) {return;}
    // 轻量写入：只保留 current 进度，断点续跑仍能继续（在下次全量写时补全其余字段）
    try {
      const raw = localStorage.getItem(K.auditQueue);
      let base = raw ? JSON.parse(raw) : null;
      // items 代际不一致（重试塞队尾导致变长）时合并写会让 current 指向错误位置，直接全量写
      if (!base || !base.items || !Array.isArray(base.items) || base.items.length !== queue.items.length) {
        _writeFullQueue(queue);
        return;
      }
      base.current = queue.current;
      base.time = Date.now();
      localStorage.setItem(K.auditQueue, JSON.stringify(base));
    } catch (e) {
      try {
        _writeFullQueue(queue);
      } catch (_) {}
    }
  }
  function saveAuditQueue(queue) {
    clearTimeout(_saveQueueTimer);
    _saveQueueTimer = setTimeout(() => {
      try {
        _writeFullQueue(queue);
      } catch (e) {}
    }, 200);
  }
  function saveAuditQueueNow(queue) {
    clearTimeout(_saveQueueTimer);
    // 全量写入（切换组/中止/结束前必须调用，保证 items 完整）
    try {
      _writeFullQueue(queue);
    } catch (e) {}
  }
  // 批审循环内每条调用：节流全量写入，其余只更新进度
  function saveAuditQueueTick(queue) {
    _queueSaveMod = (_queueSaveMod + 1) % QUEUE_SAVE_THROTTLE;
    if (_queueSaveMod === 0) {
      try {
        _writeFullQueue(queue);
      } catch (e) {}
    } else {
      try {
        _writeQueueProgress(queue);
      } catch (e) {
        try {
          _writeFullQueue(queue);
        } catch (_) {}
      }
    }
  }

  function loadAuditQueue() {
    try {
      const raw = localStorage.getItem(K.auditQueue);
      if (!raw) {return null;}
      const q = JSON.parse(raw);
      if (!q || !q.items || !q.time || Date.now() - q.time > 10 * 60 * 1000) {
        localStorage.removeItem(K.auditQueue);
        return null;
      }
      return q;
    } catch (e) {
      return null;
    }
  }

  function clearAuditQueue() {
    try {
      localStorage.removeItem(K.auditQueue);
    } catch (e) {}
  }

  function makeAuditQueue(specimens, mode) {
    const items = [];
    specimens.forEach(sp => {
      const row = sp.row || sp;
      const reportDR = sp.reportDR || row.ReportDR;
      if (!reportDR || !row) {return;}
      // 8.12.0: 放行两类——严格 NORMAL，或 F4 队列标记 MILD 且构建时轻微带校验通过；
      // 机器人路径只构造 NORMAL 条目，行为零变化
      if (!isAutoAuditableClassified(sp) && !(String(sp.status) === 'MILD' && sp.mild && sp.mild.ok)) {return;}
      items.push({
        reportDR: String(reportDR),
        wg: row._wg || resolveLoginWGReliable(),
        mdr: prWorkGroupMachineDR(row) || '',
        labno: row.Labno || '',
        name: row.PatName || '',
        testSet: row.TestSetDesc || '',
        accDate: rowAcceptDateStr(row), // 8.7.0: 登记日期——跨午夜/历史标本审核时切原生列表日期用
        fingerprint: specimenFingerprint(row),
        status: sp.status || '',
        retry: 0,
        // 8.16.31: 最小必要「原生查询上下文」。跨整页刷新/切组续跑后 wsData 尚为空时，
        // 队列条目是唯一能重建明细查询的东西——此前只存 reportDR(小写) 与精简字段，
        // 重建出的行查不到明细（fetchAndClassifySpecimen 只读 ReportDR/TodoReportDR）→
        // 恒返回 UNCERTAIN → 被当成「待定标本不可自动审核」静默留人工且补审正则不匹配 → 漏审。
        // ⚠️ 这些必须是**原生**字段：status 是分类结论（NORMAL/MILD），绝不能当原生状态用；
        //    IsComplete / _mn 是安全判定必需（完整性、堵孔仪器白名单、传染病 x8 比对），
        //    缺任何一个都会静默丢红线，故一并固化。
        q: {
          ReportDR: String(reportDR),
          MachineParameterDR: prMachineParameterDR(row) || '',
          WorkGroupMachineDR: prWorkGroupMachineDR(row) || '',
          ReportStatus: String(row.Status || row.ReportStatus || ''), // 原生状态（1 待审 / 3 已审 / 4 复检 / 5 取消）
          EpisodeNo: row.EpisodeNo || '',
          TransmitDate: row.TransmitDate || '',
          IsComplete: row.IsComplete !== undefined ? row.IsComplete : '',
          NoResRows: row.NoResRows !== undefined ? row.NoResRows : '',
          AcceptDT: row.AcceptDT || '',
          _pending: row._pending ? 1 : 0,
          _mn: row._mn || '',
          _mdr: prWorkGroupMachineDR(row) || '',
          _wg: row._wg || '',
          PatName: row.PatName || '',
          Labno: row.Labno || '',
          RegNo: row.RegNo || '',
          TestSetDesc: row.TestSetDesc || '',
          ItemDesc: row.ItemDesc || ''
        }
      });
    });
    items.sort(compareAuditQueueItems);
    // 8.5.8: 记录批审起始工作组，审完全部自动切回（跨组批审不用手动回 LIS 切组）
    return {
      mode: mode || 'batch',
      items,
      done: [],
      failed: [],
      skipped: [],
      current: 0,
      keepWS: isWSVisible(),
      // 8.16.16: 起始组也用可信值——取不到则不记录，批审结束就不会误切回一个错的组
      originWG: resolveLoginWGReliable()
    };
  }

  // 8.16.31: 由队列条目恢复「原生查询上下文」——wsData 里没有该行时（跨整页刷新/切组续跑、
  // 数据不完整）用它重建一份**只含原生字段**的行，交给 fetchAndClassifySpecimen 重新拉明细
  // 与最新标本状态。绝不把分类结论（NORMAL/MILD）当原生状态，也不凭空造成功。
  // 返回 null 表示条目里没有可用的 ReportDR —— 调用方必须按 fail-closed 处理。
  function queueItemNativeRow(item) {
    if (!item) {return null;}
    const q = item.q || {};
    const reportDR = String(item.reportDR || q.ReportDR || '');
    if (!reportDR) {return null;}
    const mdr = q.WorkGroupMachineDR || item.mdr || '';
    return {
      ReportDR: reportDR,
      MachineParameterDR: q.MachineParameterDR || '',
      WorkGroupMachineDR: mdr,
      Status: String(q.ReportStatus || ''),
      ReportStatus: String(q.ReportStatus || ''),
      EpisodeNo: q.EpisodeNo || '',
      TransmitDate: q.TransmitDate || '',
      IsComplete: q.IsComplete !== undefined ? q.IsComplete : '',
      NoResRows: q.NoResRows !== undefined ? q.NoResRows : '',
      AcceptDT: q.AcceptDT || '',
      _pending: q._pending ? 1 : 0,
      _mn: q._mn || '',
      _mdr: mdr,
      _wg: q._wg || item.wg || '',
      PatName: q.PatName || item.name || '',
      Labno: q.Labno || item.labno || '',
      RegNo: q.RegNo || '',
      TestSetDesc: q.TestSetDesc || item.testSet || '',
      ItemDesc: q.ItemDesc || ''
    };
  }

  function currentQueueItem(queue) {
    if (!queue || !queue.items) {return null;}
    while (queue.current < queue.items.length) {
      const it = queue.items[queue.current];
      if (it && !it.done) {return it;}
      queue.current++;
    }
    return null;
  }

  // ==================== 8.16.15: 批审切组守卫 —— 防「切组死循环」 ====================
  // 现场 bug：开自动审核时，工作台在「原生 LIS ↔ 工作台」之间不停来回切，反复提示
  // 「切换工作组后继续批审」，伴随审核失败，**手动关掉自动审核也停不下来**，持续很久。
  // 根因是三条缺陷叠加（缺任何一条都构不成死循环）：
  //   ① 切组没成功也要重试：跨组标本在当前组选不到 → pausedForSwitch=true + safeSwitchWG + 2.5s 后续跑。
  //      若该账号对目标工作组无权限 / 原生 changeLogin 未生效 / sel.value 设不进去，
  //      切组后 resolveCurrentWG() 仍等于旧组 → 下一轮又判「还是跨组」→ 再切 → 无限。
  //   ② 自动审核关闭检查被绕过：while 循环开头的「queue._autoMode && !autoAuditEnabled() 就 break」
  //      （22909）在 ensureAuditQueueWorkGroup（22743）**之后**，而后者在需要切组时直接
  //      `return false` 让 continueAuditQueue 提前返回 —— 于是关掉自动审核也照样一轮轮切下去。
  //   ③ 全链路没有切组次数上限：loadAbnormalTarget 有 cycle>3、trySwitchBackToOrigin 有 10 次，
  //      唯独批审这条路径没有；且 _writeFullQueue 每次都刷新 time，loadAuditQueue 的 10 分钟
  //      过期守卫（按创建时间本可兜底）也永不触发，所以能一直转下去。
  // 本守卫在三处切组点统一调用：超限或自动审核已关 → 不再切组，清队列并明确告知原因。
  const AA_QUEUE_MAX_SWITCH = 3; // 单个队列内最多尝试切组 3 次（防同一队列内空转）
  const AA_STUCK_SWITCH_MAX = 3; // 同一条标本跨队列/跨页面的切组尝试上限
  const AA_STUCK_TTL_MS = 10 * 60 * 1000; // 「卡住」记录的 10 分钟窗口
  const K_AA_STUCK_SWITCH = 'LIS_AA_StuckSwitch'; // {key,n,ts} —— 必须落盘，否则自动审核每轮
  // 新建队列会重新从 0 计数（新队列对象不含 switchCycles），单队列内的上限会被绕过去
  const K_AA_SWITCH_FUSE = 'LIS_AA_SwitchFuse'; // 切组熔断时间戳：熔断期内自动审核不再尝试跨组批审

  function aaStuckSwitchRead() {
    try {
      const o = JSON.parse(localStorage.getItem(K_AA_STUCK_SWITCH) || 'null');
      if (!o || !o.ts || Date.now() - o.ts > AA_STUCK_TTL_MS) {return null;}
      return o;
    } catch (e) {return null;}
  }
  function aaStuckSwitchClear() {
    try {localStorage.removeItem(K_AA_STUCK_SWITCH);} catch (e) {}
  }
  // 同一条标本反复切组 → 累加；换标本（说明切组成功推进了）→ 重新计 1
  function aaStuckSwitchBump(key) {
    const o = aaStuckSwitchRead();
    const n = (o && o.key === key) ? ((o.n || 0) + 1) : 1;
    try {localStorage.setItem(K_AA_STUCK_SWITCH, JSON.stringify({key, n, ts: Date.now()}));} catch (e) {}
    return n;
  }
  function aaSwitchFuseActive() {
    try {
      const t = Number(localStorage.getItem(K_AA_SWITCH_FUSE) || 0);
      return t > 0 && Date.now() - t < AA_STUCK_TTL_MS;
    } catch (e) {return false;}
  }
  function aaSwitchFuseSet() {
    try {localStorage.setItem(K_AA_SWITCH_FUSE, String(Date.now()));} catch (e) {}
  }
  function aaSwitchFuseClear() {
    try {localStorage.removeItem(K_AA_SWITCH_FUSE);} catch (e) {}
  }

  // 中止整批并落盘清理。返回 false 便于调用方 `if (!aaQueueGuardSwitch(q)) {...}` 直接短路。
  function aaQueueForceStop(queue, reason, opts) {
    const remain = Math.max(0, ((queue && queue.items) || []).length - ((queue && queue.current) || 0));
    try {_batchAbort = true;} catch (e) {}
    if (queue) {queue._aborted = true;}
    try {delete queue.pausedForSwitch;} catch (e) {}
    try {saveAuditQueueNow(queue);} catch (e) {} // 顺带取消未落盘的节流写入
    try {clearAuditQueue();} catch (e) {} // 掐掉落盘队列：否则整页刷新后 checkAuditQueueResume 会让它复活
    const prog = document.getElementById('lis-audit-progress');
    if (prog) {prog.remove();}
    // 无论因何中止都清掉「卡住」记录：否则 10 分钟窗口内用户手动重试会立刻被再拦一次。
    // 真正的防复发由熔断（fuse）负责——它拦住自动审核「每 30 秒重建队列再来一轮」的节奏。
    aaStuckSwitchClear();
    // 因「切不过去」而中止 → 置熔断，让自动审核在窗口期内**只审当前工作组**，
    // 不再每 30 秒重建一次队列、重来一轮 3 次切组（那样只是把死循环的节奏放慢，并未终止）。
    // 只对自动模式的队列置熔断，手动 F4 批审不影响自动审核的跨组能力。
    if (opts && opts.fuse && queue && queue._autoMode) {
      aaSwitchFuseSet();
    }
    const tail = remain > 0 ? ('，剩余 ' + remain + ' 例请人工处理') : '';
    showToast('⛔ 批审已中止：' + reason + tail, 'error');
    try {aaStateEventAdd('pause', '批审中止：' + reason + tail);} catch (e) {}
    dbg('[批审] 切组守卫中止：' + reason);
    return false;
  }

  // 返回 true = 允许继续切组/等待续跑；false = 已中止（调用方必须立刻停止本轮）
  // targetKey：本次要切过去的目标（标本 DR），用于识别「同一条反复卡住」
  // opts.waiting：不是真要切组，只是在等页面就绪（curDR 尚为空）——**完全不计入**任何切组计数，
  //               否则页面重载后的「等待」会把正常的 A→B→C 多组批审也顶到上限。
  // 8.16.31: waiting 此前仍会累加「同一条标本卡住」的落盘计数（aaStuckSwitchBump），
  // 属于「额外增加真实切组计数」；真正的切组动作（非 waiting）照旧两重计数，两个上限都保留。
  function aaQueueGuardSwitch(queue, targetKey, opts) {
    if (!queue) {return false;}
    // ① 自动审核已关闭/已取消 → 自动模式的队列没有理由再往下跑
    if (queue._autoMode && (_autoAuditCancelRequested || !autoAuditEnabled())) {
      return aaQueueForceStop(queue, '自动审核已关闭');
    }
    // 等待页面就绪：不是切组动作，不计数（上限由真实切组路径兜住）
    if (opts && opts.waiting) {return true;}
    // ② **连续**切组失败上限：切组一旦成功，调用方会把 queue.switchCycles 归零，
    //    所以这里累加的自然就是「连着几次切不过去」（正常的跨组批审每次都是 1，不会误伤）
    queue.switchCycles = (queue.switchCycles || 0) + 1;
    if (queue.switchCycles > AA_QUEUE_MAX_SWITCH) {
      return aaQueueForceStop(
        queue,
        '已连续尝试切换工作组 ' + queue.switchCycles + ' 次仍未成功（可能当前账号无该工作组权限，或原生切组失败）',
        {fuse: true}
      );
    }
    // ③ 跨队列/跨页面：同一条标本反复切组（自动审核每轮新建队列会重置队列内计数，故必须落盘另计）
    const key = String(targetKey || '');
    if (key) {
      const n = aaStuckSwitchBump(key);
      if (n > AA_STUCK_SWITCH_MAX) {
        return aaQueueForceStop(
          queue,
          '同一条标本已尝试切换工作组 ' + n + ' 次仍未成功（可能该账号无目标工作组权限，或原生切组失败）',
          {fuse: true}
        );
      }
      dbg('[批审] 切组尝试 ' + (queue.switchCycles || 0) + '/' + AA_QUEUE_MAX_SWITCH + '（该标本累计 ' + n + '/' + AA_STUCK_SWITCH_MAX + '）');
    }
    return true;
  }

  // 切组确认推进（无需切组）→ 清零「连续失败」计数
  function aaQueueSwitchSucceeded(queue) {
    if (queue) {queue.switchCycles = 0;}
    aaStuckSwitchClear();
  }

  async function ensureAuditQueueWorkGroup(queue) {
    const item = currentQueueItem(queue);
    if (!item) {return true;}
    // ==================== 8.16.24: 本函数不再切组 ====================
    // 恢复 8.5.10 的「跨组先试不切组」：原生报告页支持按 WorkGroupMachineDR 直接查
    // 别的工作列表（现场实测可行），所以批审**起始点不需要预先切组**。
    //
    // 回归始末（现场原话：「14 号及之前的标本审报告是不切组的，就这两天出的问题」）：
    //   8.15.27（09-14 15:34）为消除「跨组选行 4.5s 超时死等」，把这里原本的
    //     `// 8.5.10 ... 不再预先切组；主循环内选不到标本时才回退切组` + `return true`
    //   改成「不在当前原生列表 → 立即切组」；同一提交还把主循环的「完整选行」换成
    //   「快速探测失败 → 立即切组」。两处合起来把跨组批审从「先试免切组」退化成
    //   「必切组」——而两个判据都过于苛刻：
    //     · 起始点只看**一次** selectNativeRowByReportDR，而批审刚启动时原生列表通常
    //       还停在默认日期/上一个机台，这一步几乎必然落空；
    //     · 主循环的探测用 fast:true（只等 70ms），而 ShowWorkList 是异步查询，
    //       70ms 远未返回，所以探测也几乎必然落空。
    //   结果就是每次都白切一趟：整页重载 + 重新 CA 认证（现场那个「是否记住密码」弹窗）
    //   + 工作台重建。
    //
    // 现在起始点一律放行，把「要不要切组」完全交给批审主循环 ——
    // 主循环会先按机台 DR 免切组探测，再走**完整选行**（waitAndSelectNativeRow：
    // 轮询等待工作列表返回 + FindFast 条码兜底 + 按机台/日期刷新列表），
    // 真的选不到才会切组（那里仍保留 aaQueueGuardSwitch 守卫与次数上限，不会死循环）。
    const curDR = String(resolveLoginWGReliable());
    const itemWg = String(item.wg || '');
    // ==================== 8.16.31: 只有「确认推进」才允许清零守卫计数 ====================
    // 现场缺陷：这里原本无条件 `aaQueueSwitchSucceeded(queue)`，而本函数**不做任何切组**、
    // 每轮 continueAuditQueue 都会走到 —— 于是它把 aaQueueGuardSwitch 累加的
    // queue.switchCycles 与落盘的「同一条标本卡住」记录**每轮清零**，
    // 守卫的「连续失败上限 3 次」「同一条标本上限 3 次」永远到不了，
    // 跨组死循环（切组 → 整页重载 → 续跑 → 再切组）无法被兜住。
    // 现在：只有**确实已到目标组**（本轮真的推进到位）才清零；组信息不可信时保守不动。
    if (curDR && itemWg && itemWg === curDR) {
      aaQueueSwitchSucceeded(queue);
    } else if (curDR && itemWg) {
      dbg('[批审] 起始点不切组（跨组先试免切组）: 标本wg=' + itemWg + ' 登录组=' + curDR + ' DR=' + item.reportDR);
      // 未到目标组 → 本函数没有推进任何东西，**不得**清零计数（清零 = 守卫失效）
    } else {
      dbg('[批审] 起始点工作组不可信（登录组/标本组取不到），保留守卫计数不作清零');
    }
    return true;
  }

  function runAuditQueueResume(delayMs) {
    setTimeout(() => {
      // 审核进行中：延迟重试，不弹误导 toast
      if (_auditInProgress || _abnormalAuditInProgress || _detailAuditInProgress) {
        // 队列已过期/完成就不再每 3s 空转（防止标志卡死时无限重调度）
        const q = loadAuditQueue();
        if (!q || !q.items || q.items.length - (q.current || 0) <= 0) {
          dbg('续跑批审: 队列已过期或完成，停止重试');
          clearAuditQueue();
          return;
        }
        dbg('续跑批审: 审核进行中，延迟 3s 重试');
        runAuditQueueResume(3000);
        return;
      }
      const freshQueue = loadAuditQueue();
      if (!freshQueue || !freshQueue.items || freshQueue.items.length - (freshQueue.current || 0) <= 0) {
        const prog = document.getElementById('lis-audit-progress');
        if (prog && prog.classList.contains('show')) {
          const text = document.getElementById('lis-prog-text');
          if (text) {text.textContent = '批审队列已过期或已完成，已自动清理';}
          showToast('批审队列已过期或已完成', 'info');
          setTimeout(() => prog.remove(), 2000);
        }
        clearAuditQueue();
        return;
      }
      // 8.9.4: 跨整页刷新后 CA 会话必然失效，清掉工作组 CA 缓存——否则恢复的首条走秒审快路径
      // 必失败一次（requeue 浪费一轮），下一条才回退慢路径弹 CA 重登
      freshQueue.caReadyByWg = {};
      // 8.16.30: 跨整页刷新或切组续跑时，清空剩余标本在旧组可能积累的重试次数，确保在正确工作组拥有完整尝试机会
      (freshQueue.items || []).forEach(it => {
        if (it) {it.retry = 0;}
      });
      // 8.9.4: pausedForSwitch 由 continueAuditQueue 在拿到队列锁后才清（见其开头）——拿锁失败
      //（如刷新后残留锁未过期）时标记仍在，据此自动重试直到接手成功（60s > 锁 TTL 45s）
      continueAuditQueue(freshQueue).catch(e => {
        dbg('续跑批审队列失败:', e);
        showToast('续跑批审失败: ' + e.message, 'error');
      });
      const _recheckResume = n => {
        if (n <= 0) {return;}
        setTimeout(() => {
          // 有别的审核在进行：不打断也不弹「正在审核中」，静默延后重试
          if (_auditInProgress || _abnormalAuditInProgress || _detailAuditInProgress) {_recheckResume(n - 1); return;}
          const q2 = loadAuditQueue();
          if (q2 && q2.pausedForSwitch && q2.items && q2.items.length - (q2.current || 0) > 0) {
            dbg('续跑批审: 队列锁未就绪，3s 后重试');
            continueAuditQueue(q2).catch(() => {});
            _recheckResume(n - 1);
          }
        }, 3000);
      };
      _recheckResume(20);
    }, delayMs);
  }

  function checkAuditQueueResume() {
    const queue = loadAuditQueue();
    if (!queue || !queue.items || queue.items.length === 0) {return;}
    const remaining = queue.items.length - (queue.current || 0);
    if (remaining <= 0) {
      clearAuditQueue();
      return;
    }
    // 仅在切组后自动续跑，不弹确认框
    if (queue.pausedForSwitch) {
      // 8.16.15: 这里是**跨整页重载**的续跑入口，也是「关掉自动审核后仍在切」的关键一环——
      // 此前只看 pausedForSwitch，不看自动审核开关，于是队列一落盘，之后每次页面重载都会
      // 自动续跑 → 切组 → 再重载，循环停不下来。现在先过守卫（自动审核已关 / 切组次数超限即中止）。
      const _curItem = (queue.items && queue.items[queue.current || 0]) || {};
      // waiting=true：这里只是决定「要不要续跑」，还不是切组动作本身，
      // 不计入「连续切组失败」——否则会和 ensureAuditQueueWorkGroup 里的判断重复计数
      if (!aaQueueGuardSwitch(queue, 'dr:' + String(_curItem.reportDR || ''), {waiting: true})) {return;}
      showToast(`切换工作组后继续批审（${remaining} 个标本）...`, 'warning');
      runAuditQueueResume(500);
      return;
    }
    // 非切组场景（如页面刷新），静默清理过期队列，不弹窗打扰
    clearAuditQueue();
  }

  // 8.9.0: auditSelectedSpecimens（F5 审核选中）已删除——仅被已删除的 updateBatchBar 调用，
  // 且 F5 快捷键从未注册；勾选批量审核入口由「一键批审 F4」承担


  // ============================================================
  //  标本详情面板
  // ============================================================
  let detailPanel = null;
  let currentDetailSpecimen = null;
  let detailSource = null; // 'abnormal' | 'normal' | null
  let detailSourceIndex = -1;
  let _detailKeyHandler = null; // 详情面板键盘监听器
  let _detailLoadSeq = 0; // 详情加载序号，防止旧请求覆盖当前标本

  function createDetailPanel() {
    if (detailPanel) {return detailPanel;}
    detailPanel = document.createElement('div');
    detailPanel.id = 'lis-detail-panel';
    detailPanel.innerHTML = `
            <div id="lis-detail-hd">
                <div style="flex:1;min-width:0;padding-right:10px">
                    <h4 id="lis-detail-title" style="margin:0;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">📋 标本详情</h4>
                    <div id="lis-detail-subtitle" style="font-size:11px;color:var(--lis-text-secondary);margin-top:3px"></div>
                    <div id="lis-detail-extra" style="font-size:11px;color:var(--lis-text-muted);margin-top:2px"></div>
                </div>
                <button class="detail-close" id="lis-detail-close">✕</button>
            </div>
            <div id="lis-detail-info"></div>
            <div id="lis-detail-body" style="flex:1;overflow-y:scroll;overflow-x:hidden;padding:16px 20px;min-height:0">
                <div id="lis-detail-loading">
                    <div class="spinner"></div>
                    <p>正在加载结果...</p>
                </div>
            </div>
            <div id="lis-detail-footer">
                <div id="lis-detail-left-actions"></div>
                <span class="detail-footer-hint">↑↓ 切换 | Enter 审核 | M 病历 | H 历史 | Esc 关闭</span>
                <div class="detail-footer-actions">
                    <button class="btn-emr" id="lis-detail-emr-btn" title="查看该患者的电子病历/HIS信息（Shift+点击：直接唤起原生 32 位 IE）">📄 病历</button>
                    <button class="btn-audit" id="lis-detail-audit" title="Enter 或点击：审核当前详情标本，成功后自动跳下一条">✅ 审核</button>
                    <button class="btn-close" id="lis-detail-close-btn">关闭</button>
                </div>
            </div>
        `;
    document.body.appendChild(detailPanel);

    // 透明层只保留占位，不拦截工作台列表点击；关闭请用按钮或 Esc。
    const overlay = document.createElement('div');
    overlay.id = 'lis-detail-overlay';
    overlay.style.cssText =
      'position:fixed;top:0;left:0;width:35vw;height:100vh;z-index:100004;display:none;pointer-events:none';
    document.body.appendChild(overlay);

    // 事件绑定（审核钮与 Enter 共用 _auditFromDetailPanel，非互斥）
    document.getElementById('lis-detail-close').addEventListener('click', closeDetailPanel);
    document.getElementById('lis-detail-close-btn').addEventListener('click', closeDetailPanel);
    const emrBtn = document.getElementById('lis-detail-emr-btn');
    if (emrBtn) {
      emrBtn.addEventListener('click', e => {
        e.preventDefault();
        e.stopPropagation();
        const sp = currentDetailSpecimen;
        if (!sp || !sp.Labno) {
          toast('当前没有选中的标本详情', 'w');
          return;
        }
        openEnhancedEMR(sp.Labno, {
          labNo: sp.Labno,
          patName: sp.PatName || '',
          regNo: sp.RegNo || '',
          episodeNo: sp.EpisodeNo || '',
          directNativeIE: !!e.shiftKey
        });
      });
    }
    _bindDetailAuditButton();
    // 详情结果表每行「🔎」：打开单项目历史（事件委托，兼容 LRU 缓存 HTML）
    const dBody = document.getElementById('lis-detail-body');
    if (dBody) {
      dBody.addEventListener('click', e => {
        const btn = e.target && e.target.closest ? e.target.closest('.detail-hist-item') : null;
        if (!btn) { return; }
        e.preventDefault();
        e.stopPropagation();
        const sp = currentDetailSpecimen;
        if (!sp) { toast('当前没有打开的标本详情', 'warning'); return; }
        histOpenForTest(
          {
            RegNo: sp.RegNo || '',
            PatName: sp.PatName || '',
            Labno: sp.Labno || '',
            EpisodeNo: sp.EpisodeNo || '',
            _wg: sp._wg || '',
            _mdr: sp._mdr || '',
            ReportDR: sp.ReportDR || '',
            Status: sp.Status || sp.ReportStatus || '',
            AcceptDT: sp.AcceptDT || '',
            TransmitDate: sp.TransmitDate || '',
            MachineParameterDR: sp.MachineParameterDR || '',
            TestSetDesc: sp.TestSetDesc || ''
          },
          {
            key: btn.getAttribute('data-key') || '',
            name: btn.getAttribute('data-name') || '',
            syn: btn.getAttribute('data-syn') || ''
          }
        );
      });
      // 8.15.9/8.15.10: 项目名后的 ⚙ —— 打开「轻微放行范围」设置（事件委托，兼容 LRU 缓存 HTML）
      _bindMildBtn(dBody);
    }

    return detailPanel;
  }

  // 详情「审核」按钮：每次打开/切换时重绑，避免监听丢失；与 Enter 同一入口
  function _bindDetailAuditButton() {
    const btn = document.getElementById('lis-detail-audit');
    if (!btn) {return;}
    btn.onclick = e => {
      if (e) {
        e.preventDefault();
        e.stopPropagation();
      }
      dbg(
        '详情面板审核按钮点击, specimen=',
        !!(currentDetailSpecimen && currentDetailSpecimen.PatName),
        currentDetailSpecimen && currentDetailSpecimen.PatName
      );
      if (!currentDetailSpecimen) {
        showToast('当前没有打开的标本详情', 'warning');
        return;
      }
      void _auditFromDetailPanel();
    };
  }

  function _setDetailAuditBusy(busy, text) {
    const btn = document.getElementById('lis-detail-audit');
    if (!btn) {return;}
    btn.disabled = !!busy;
    btn.classList.toggle('busy', !!busy);
    btn.textContent = text || (busy ? '⏳ 审核中…' : '✅ 审核');
  }

  function openDetailPanel(specimen, source, sourceIndex) {
    dbg('openDetailPanel', specimen.ReportDR, specimen.PatName, source);
    createDetailPanel();
    // 清理异常视图键盘监听，防止与详情面板冲突
    _removeAbnormalKeyHandler();
    // 详情打开后 iframe 内 Enter 不再走列表审核桥：立即置桥 inactive，
    // 否则第一个 Enter（焦点在原生 iframe 内）会被旧 active 劫持吞掉（8.5.1 主推 Enter 驱动后更明显）
    updateAbnormalEnterBridge();

    // 面板已打开时直接换内容，避免点击其它样本时先收回再二次点击。
    if (detailPanel.classList.contains('show')) {
      _switchDetailInPlace(specimen, source, sourceIndex);
      return;
    }

    currentDetailSpecimen = specimen;
    // 按标本实时分类桶校准 source：异常从「全部/不完整」视图打开详情也能审（原为 null→normal 会被拦）
    detailSource = specimen && getWSAuditBucket(specimen) === 'normal' ? 'normal' : 'abnormal';
    detailSourceIndex = sourceIndex !== undefined ? sourceIndex : -1;

    // 更新标题
    const titleEl = document.getElementById('lis-detail-title');
    if (titleEl) {
      titleEl.textContent = `📋 ${specimen.PatName || '未知'}`;
    }
    const subtitleEl = document.getElementById('lis-detail-subtitle');
    if (subtitleEl) {
      subtitleEl.innerHTML = buildDetailSubtitle(specimen);
    }
    const detailExtra = document.getElementById('lis-detail-extra');
    // 立即填充患者信息（优先缓存，回退到 specimen 本身）
    const _cr = (wsClassifiedCache[specimen.ReportDR] || {}).row || specimen;
    if (detailExtra) {detailExtra.textContent = buildDetailExtraText(_cr, specimen) || '加载中...';}

    // 信息栏（紧凑状态条）
    const info = document.getElementById('lis-detail-info');
    if (info) {
      info.innerHTML = '<div style="height:1px"></div>';
    }

    // 显示加载中
    const body = document.getElementById('lis-detail-body');
    if (body) {
      body.innerHTML = `
                <div id="lis-detail-loading">
                    <div class="spinner"></div>
                    <p>正在加载结果...</p>
                </div>
            `;
    }

    // 显示面板和遮罩层
    detailPanel.classList.add('show');
    const overlay = document.getElementById('lis-detail-overlay');
    if (overlay) {overlay.style.display = 'none';}

    // 加载详细结果
    loadDetailResults(specimen);

    // 更新底部按钮（8.9.0: 共用工厂）
    _installDetailNativeButton(specimen);
    _bindDetailAuditButton();
    _setDetailAuditBusy(false);

    // 注册详情面板键盘监听（Enter 与审核钮同一路径）
    _installDetailKeyHandler();
    dbg('详情面板键盘监听已注册, specimen:', specimen.PatName);
    // 确保 F4 桥在原生 iframe 上挂着（面板打开时异常处理器已被移除，Enter 靠桥捕获）
    _attachF4BridgeToIframe();
    refocusDetailPanel();
    scheduleDetailPrewarm(specimen, 120);
  }

  function _removeDetailKeyHandler() {
    if (_detailKeyHandler) {
      document.removeEventListener('keydown', _detailKeyHandler, true);
      _detailKeyHandler = null;
    }
  }

  // 8.9.0: 详情键盘监听与「原生界面」按钮在 openDetailPanel / _switchDetailInPlace 原各有一份
  // 逐字相同的实现（改一处漏一处的风险已存在），抽为共用工厂
  function _installDetailKeyHandler() {
    _removeDetailKeyHandler();
    _detailKeyHandler = e => {
      if (isPatientResultPanelEvent(e)) {return;}
      if (!detailPanel || !detailPanel.classList.contains('show')) {return;}
      // 焦点在搜索框/面板内输入框时 Enter 不触发审核（与 _f4BridgeHandler 的 shouldIgnore 对齐）
      if (shouldIgnoreAbnormalKeyEvent(e)) {return;}
      // 历史浮层打开时：详情键全部让位（避免 Enter 误审），Esc 由历史层处理
      if (histIsOpen()) {return;}
      // 8.17.4: M = 直达电子病历（与工作台待审视图同键，Shift+M = 原生 32 位 IE）
      if (e.key === 'm' || e.key === 'M') {
        e.preventDefault();
        e.stopImmediatePropagation();
        if (currentDetailSpecimen) {openEMRForWSRow(currentDetailSpecimen, e.shiftKey);}
        return;
      }
      if (e.key === 'H' || e.key === 'h') {
        e.preventDefault();
        e.stopImmediatePropagation();
        histOpen();
        return;
      }
      if (e.key === 'Escape') {
        e.preventDefault();
        e.stopImmediatePropagation();
        closeDetailPanel();
      } else if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        e.stopImmediatePropagation();
        dbg('Enter 键捕获 (详情面板), inProgress=', _detailAuditInProgress);
        void _auditFromDetailPanel();
      } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        if (_detailAuditInProgress) {return;} // 审核中禁止切换标本
        e.preventDefault();
        e.stopImmediatePropagation();
        // 方向键切换：原地更新内容，不关闭面板
        const data = filteredData();
        if (data.length === 0) {return;}
        const curIdx = data.findIndex(r => r.ReportDR === (currentDetailSpecimen && currentDetailSpecimen.ReportDR));
        let newIdx = curIdx + (e.key === 'ArrowDown' ? 1 : -1);
        if (newIdx < 0) {newIdx = data.length - 1;}
        if (newIdx >= data.length) {newIdx = 0;}
        _switchDetailInPlace(data[newIdx], detailSource, newIdx);
      }
    };
    document.addEventListener('keydown', _detailKeyHandler, true);
  }

  function _installDetailNativeButton(specimen) {
    const container = document.getElementById('lis-detail-left-actions') || document.getElementById('lis-detail-footer');
    if (!container) {return;}
    // 移除旧的"原生界面"按钮再重建
    const oldNative = document.getElementById('lis-detail-native');
    if (oldNative) {oldNative.remove();}
    const nativeBtn = document.createElement('button');
    nativeBtn.id = 'lis-detail-native';
    nativeBtn.type = 'button';
    nativeBtn.textContent = '📂 原生界面';
    nativeBtn.addEventListener('click', () => {
      navigateToSpecimen(specimen);
      closeDetailPanel();
    });
    container.appendChild(nativeBtn);
  }

  function formatDetailTimeText(value) {
    const raw = String(value || '').trim();
    if (!raw) {return '';}
    const m = raw.match(/^(\d{4})-(\d{2})-(\d{2})\s+(\d{2}):(\d{2})(?::\d{2})?/);
    if (m) {return m[2] + '-' + m[3] + ' ' + m[4] + ':' + m[5];}
    const mt = raw.match(/^(\d{2}):(\d{2})(?::\d{2})?/);
    if (mt) {return mt[1] + ':' + mt[2];}
    return raw;
  }

  function detailTimeFrom(info, dtKey, dateKey, timeKey, fallback) {
    const dt = info && info[dtKey] ? info[dtKey] : '';
    const date = info && info[dateKey] ? info[dateKey] : '';
    const time = info && info[timeKey] ? info[timeKey] : '';
    return formatDetailTimeText(dt || [date, time].filter(Boolean).join(' ') || fallback || '');
  }

  function formatDetailBedNo(bedNo) {
    const bed = String(bedNo || '').trim();
    if (!bed) {return '';}
    return /^床/.test(bed) || /床$/.test(bed) ? bed : '床' + bed;
  }

  // 8.13.1: 第三参 labInfo 为可选回退（检视器传入分类缓存带回的 GetReportInfoAll LabInfo）——
  // 申请医生/标本类型等工作台行数据常缺的字段从这层兜底
  function buildDetailExtraText(info, fallback, labInfo) {
    const r = info || {};
    const fb = fallback || {};
    const li = labInfo || {};
    const parts = [];
    const isCollected = !!(
      r._collected ||
      fb._collected ||
      String(r.Status || fb.Status || r.ReportStatus || fb.ReportStatus || '') === '9' ||
      getWSAuditBucket(r) === 'collected' ||
      getWSAuditBucket(fb) === 'collected'
    );
    const sex = r.Sex || r.Species || fb.Sex || fb.Species;
    const age = r.Age || fb.Age;
    const ageUnit = r.AgeUnit || fb.AgeUnit || '';
    const location = r.Location || r.LocationName || fb.Location || fb.LocationName;
    const ward = r.Ward || r.WardName || fb.Ward || fb.WardName;
    const admNo = r.AdmNo || fb.AdmNo;
    const recordNo = r.RecordNo || fb.RecordNo;
    const regNo = r.RegNo || fb.RegNo;
    const bed = formatDetailBedNo(r.BedNo || fb.BedNo);
    const specimen = r.Specimen || r.SpecimenDesc || fb.Specimen || fb.SpecimenDesc || li.Specimen || li.SpecimenDesc;
    const doctor = r.Doctor || r.DoctorName || r.ReqDoctorName || r.ApplyDoctorName ||
      fb.Doctor || fb.DoctorName || fb.ReqDoctorName || fb.ApplyDoctorName ||
      li.Doctor || li.DoctorName || li.ReqDoctorName || li.ApplyDoctorName;
    const diagnose = r.Diagnose || fb.Diagnose;
    const collectTime =
      getSpecimenCollectTime(r) ||
      getSpecimenCollectTime(fb) ||
      getSpecimenCollectTime(li) ||
      detailTimeFrom(r, 'CollectDT', 'CollectDate', 'CollectTime', fb.CollectDT);
    const receiveTime =
      getSpecimenReceiveTime(r) ||
      getSpecimenReceiveTime(fb) ||
      getSpecimenReceiveTime(li) ||
      detailTimeFrom(r, 'ReceiveDT', 'ReceiveDate', 'ReceiveTime', fb.ReceiveDT);
    const acceptTime = detailTimeFrom(r, 'AcceptDT', 'AcceptDate', 'AcceptTime', fb.AcceptDT);
    const authTime = detailTimeFrom(r, 'AuthDT', 'AuthDate', 'AuthTime', fb.AuthDT);

    if (sex) {parts.push(sex);}
    if (age) {parts.push(age + ageUnit);}
    if (location) {parts.push(location);}
    if (ward) {parts.push(ward);}
    if (admNo) {parts.push('住院号 ' + admNo);}
    else if (recordNo) {parts.push('病案号 ' + recordNo);}
    else if (regNo) {parts.push('登记号 ' + regNo);}
    if (bed) {parts.push(bed);}
    if (specimen) {parts.push(specimen);}
    if (doctor) {parts.push(doctor);}
    // 8.15.28: 采集时间只在采集列表标本详情顶栏展示，已到科室的其它标本重点关注核收/审核
    if (isCollected && collectTime) {parts.push('采集时间 ' + collectTime);}
    if (receiveTime) {parts.push('接收 ' + receiveTime);}
    if (acceptTime) {parts.push('核收 ' + acceptTime);}
    if (authTime) {parts.push('审核 ' + authTime);}
    if (diagnose) {parts.push('🏥 ' + diagnose);}
    return parts.join(' · ');
  }

  function buildDetailSubtitle(specimen) {
    return `<span>${getStatusText(specimen.Status || specimen.ReportStatus)}</span> · 检验号: ${esc(specimen.Labno || '-')} · 流水号: ${esc(specimen.EpisodeNo || '-')} · ${esc(specimen.TestSetDesc || '')} · 仪器: ${esc(specimen._mn || '-')}`;
  }

  // 原地切换详情面板内容（不关闭面板，避免闪烁）
  // options.force：审核成功后切下一条时绕过「审核中」锁
  function _switchDetailInPlace(specimen, source, sourceIndex, options) {
    if (!detailPanel || !specimen) {return;}
    if (_detailAuditInProgress && !(options && options.force)) {
      dbg('审核进行中，忽略详情切换');
      return;
    }
    currentDetailSpecimen = specimen;
    // 8.10.13: 同步工作台底层聚焦卡片与索引，Esc 退出面板后焦点与列表严格对齐
    _abnormalFocusDR = String(specimen.ReportDR || '');
    if (sourceIndex !== undefined && sourceIndex >= 0) {
      wsAbnormalIndex = sourceIndex;
    }
    const cards = document.querySelectorAll('.ws-abnormal-card');
    cards.forEach(c => {
      if (String(c.dataset.rdr || '') === _abnormalFocusDR) {
        c.classList.add('focused');
      } else {
        c.classList.remove('focused');
      }
    });
    // 始终按标本实时分类桶校准 source，避免详情内自动跳转/方向键切换后沿用旧桶
    // （8.5.1 误拦正常标本的根因：跳转后 detailSource 仍是异常的）
    detailSource = getWSAuditBucket(specimen) === 'normal' ? 'normal' : 'abnormal';
    detailSourceIndex = sourceIndex !== undefined ? sourceIndex : -1;
    // 切换时清危急标记，避免沿用上一条 dataset 误拦/误放
    try {
      detailPanel.dataset.rdr = String(specimen.ReportDR || '');
      detailPanel.dataset.hasCritical = '';
    } catch (e) {}

    // 更新标题
    const titleEl = document.getElementById('lis-detail-title');
    if (titleEl) {titleEl.textContent = `📋 ${specimen.PatName || '未知'}`;}
    const subtitleEl = document.getElementById('lis-detail-subtitle');
    if (subtitleEl) {subtitleEl.innerHTML = buildDetailSubtitle(specimen);}
    const detailExtra = document.getElementById('lis-detail-extra');
    const _cr = (wsClassifiedCache[specimen.ReportDR] || {}).row || specimen;
    if (detailExtra) {detailExtra.textContent = buildDetailExtraText(_cr, specimen) || '加载中...';}

    // 信息栏
    const info = document.getElementById('lis-detail-info');
    if (info) {info.innerHTML = '<div style="height:1px"></div>';}

    // 显示加载中
    const body = document.getElementById('lis-detail-body');
    if (body) {
      body.innerHTML = '<div id="lis-detail-loading"><div class="spinner"></div><p>正在加载结果...</p></div>';
    }

    // 更新底部按钮（8.9.0: 共用工厂）
    _installDetailNativeButton(specimen);
    _bindDetailAuditButton();
    _setDetailAuditBusy(false);

    // 加载详情（LRU 缓存命中时极快）
    loadDetailResults(specimen);

    // 重新注册键盘监听（8.9.0: 共用工厂）
    _installDetailKeyHandler();
    _attachF4BridgeToIframe();
    refocusDetailPanel();
    scheduleDetailPrewarm(specimen, 120);
  }

  // 焦点放回详情面板自身：确保 Enter 由 _detailKeyHandler 直接捕获（不依赖 iframe 桥），
  // 避免焦点滞留在原生 iframe 内导致 Enter 被原生 datagrid 吃掉（用户历史痛点）
  function refocusDetailPanel() {
    try {
      const dEl = document.getElementById('lis-detail-panel');
      if (dEl) {
        if (!dEl.hasAttribute('tabindex')) {dEl.setAttribute('tabindex', '-1');}
        dEl.focus({ preventScroll: true });
      }
    } catch (e) {}
  }

  // 详情面板当前标本后台预热：定位原生页并加载详情，保证 Enter 审核秒审（needPrep=false 跳过定位）
  // 审核成功跳下一条后也会触发，连续 Enter 全程不卡
  let _detailPrewarmTimer = null;
  function scheduleDetailPrewarm(specimen, delayMs) {
    if (!specimen || !isWSVisible()) {return;}
    clearTimeout(_detailPrewarmTimer);
    const delay = typeof delayMs === 'number' ? delayMs : 250;
    _detailPrewarmTimer = setTimeout(() => {
      // 审核进行中不抢原生页（详情审完由 finally 里的 scheduleDetailPrewarm 补触发）；
      // 列表审核（auditAbnormalSpecimen）进行中同样不抢；标本已切走则放弃本次预热
      if (_detailAuditInProgress || _auditInProgress || _abnormalAuditInProgress) {return;}
      if (!isDetailPanelVisible() || !currentDetailSpecimen) {return;}
      if (String(currentDetailSpecimen.ReportDR) !== String(specimen.ReportDR)) {return;}
      prewarmAbnormalAuditNative(specimen)
        .catch(() => false)
        .then(drove => {
          // 8.8.1: 预热驱动原生页后（FindFast/日期框 setValue/选行）焦点常落在 iframe 内的
          // 可编辑控件（快速查找框/日期框/网格编辑格）。此时再按 Enter 会被 _f4BridgeHandler
          // 的 isEditableEventTarget 放行给原生输入、不触发详情审核（用户反馈：审完第一条自动跳
          // 第二条后 Enter 失效，须点列表该标本才能继续）。预热完把焦点拉回详情面板，
          // 保证连续 Enter 直接审下一条（与 scheduleAbnormalFocusRecovery 同款收尾）。
          // 仅当预热真正驱动过原生页（drove=true）才回收焦点；用户正看其它标本的跳过路径不抢。
          if (!drove) {return;}
          if (_detailAuditInProgress || _auditInProgress || _abnormalAuditInProgress) {return;}
          if (!isDetailPanelVisible() || !currentDetailSpecimen) {return;}
          if (String(currentDetailSpecimen.ReportDR) !== String(specimen.ReportDR)) {return;}
          // 8.8.11: 用户正在输入框打字（如工作台搜索框）时不抢焦点
          const _ae = document.activeElement;
          if (_ae && /^(INPUT|TEXTAREA|SELECT)$/i.test(_ae.tagName)) {return;}
          releaseNativeReportFocus();
          refocusDetailPanel();
        });
    }, delay);
  }

  let _detailAuditInProgress = false;
  let _detailAuditQueued = false; // 8.10.13: 详情面板 Enter 排队标记，连续按 Enter 不再吃键

  // 从详情面板审核当前标本并自动跳转下一个
  // 入口：详情「审核」按钮 / Enter —— 同一函数，可同时保留（F4 在详情内已取消，8.5.1）
  async function _auditFromDetailPanel() {
    if (!currentDetailSpecimen) {
      dbg('详情审核跳过: 无当前标本');
      showToast('当前没有打开的标本详情', 'warning');
      return;
    }
    // 8.5.31: 采集标本（病房已采未送）不可审核，仅追踪/催送
    if (getWSAuditBucket(currentDetailSpecimen) === 'collected') {
      dbg('详情审核跳过: 采集标本不可审核');
      showToast('采集标本未送检，不可审核（仅供追踪/催送）', 'warning');
      return;
    }
    // 8.5.34: 待排标本（未核收）同样不可审核 — 与采集守卫对称，避免拿合成 DR 去原生找标本
    if (getWSAuditBucket(currentDetailSpecimen) === 'pending') {
      dbg('详情审核跳过: 待排标本未核收');
      showToast('待排标本未核收，不可审核（核收后进入待审）', 'warning');
      return;
    }
    if (_detailAuditInProgress) {
      // 8.10.13: 详情审核进行中再次按 Enter，自动排队下一条，不丢弃按键
      if (!_detailAuditQueued) {
        _detailAuditQueued = true;
        _setDetailAuditBusy(true, '⏳ 已排队下一条…');
        showToast('下一条已排队，当前条完成后自动继续', 'info');
      }
      return;
    }
    if (_auditInProgress) {
      showToast('正在批量审核中，请稍候', 'warning');
      return;
    }
    if (_abnormalAuditInProgress) {
      showToast('正在审核异常标本中，请稍候', 'warning');
      return;
    }
    let _detailSafetyTimer = null;
    const resumeWSRefresh = !!wsTimer;

    try {
      _detailAuditInProgress = true;
      _setDetailAuditBusy(true, '⏳ 审核中…');
      // 安全超时：60 秒后显示警告，但不释放锁（finally 块负责释放）
      _detailSafetyTimer = setTimeout(() => {
        if (_detailAuditInProgress) {
          dbg('详情审核安全超时：操作耗时超过 60 秒');
          showToast('详情审核操作耗时较长，请耐心等待', 'warning');
        }
      }, 60000);
      dbg('详情审核开始:', currentDetailSpecimen.PatName, 'source=', detailSource);
      // 不弹「正在审核」toast：按钮已显示 ⏳ 审核中…，结束后只弹 审核成功/审核失败 一个窗，避免双窗叠加
      stopWSRefresh();
      const specimen = currentDetailSpecimen;
      const source = detailSource;
      const idx = detailSourceIndex;
      // 8.5.53: 详情审核期间设置复检上下文（内部 verify/soft 兜底用）
      _auditingPreStatus4 = String(specimen.Status || specimen.ReportStatus || '') === '4';

      let nextReportDR = null;
      if (source) {
        // 8.10.13: 按 ReportDR 现场精准查找下一条，避免下标偏移漏审或越界
        const data = filteredData();
        const curIdx = data.findIndex(r => String(r.ReportDR) === String(specimen.ReportDR));
        if (curIdx >= 0 && curIdx + 1 < data.length) {
          nextReportDR = data[curIdx + 1].ReportDR;
        } else if (idx >= 0 && idx + 1 < data.length) {
          nextReportDR = data[idx + 1].ReportDR;
        }
      }

      let iframeWin = getReportIframeWin();
      if (!iframeWin) {iframeWin = await ensureReportPageLoaded({ keepWS: true });}
      if (!iframeWin) {
        showToast('报告页面未加载', 'error');
        return;
      }

      const reportDR = specimen.ReportDR;
      // 详情里人工点审：按当前标本实时分类桶选上下文（不能依赖 detailSource——
      // 详情内自动跳转后 source 仍是旧标本的，会误拦正常标本为「已分类为正常」）
      // 8.17.9: 详情面板「审核」按钮 / 面板内回车此前**完全没有完整度检查**（只有 collected/pending
      // 早退和分类校验）。这里**不硬拦**——从详情面板手动点审核是「确需人工审核」的有意通道
      // （见 HANDTEST §22：星号占位标本挪到不完整后仍可从详情手动审），硬拦会把这条通道锁死。
      // 但要**明确提示 + 留痕**：现场「缺了三个项目竟然审掉了」就是缺这一句提醒。
      try {
        const _cmpD = specimenCompleteness(specimen, wsClassifiedCache[specimen.ReportDR]);
        if (!_cmpD.ok) {
          showToast('⚠️ 该标本' + _cmpD.reason + '，仍按人工判断审核', 'warning');
          dbg('详情面板审核：完整度提示', specimen.Labno || reportDR, _cmpD.reason);
        }
      } catch (e) {}

      const classCtx = specimen && getWSAuditBucket(specimen) === 'normal' ? 'normal' : 'abnormal';
      const classCheck = validateAuditClassification(reportDR, classCtx);
      if (!classCheck.ok) {
        showToast(classCheck.msg || '当前标本不可审核', classCtx === 'abnormal' ? 'warning' : 'error');
        return;
      }
      if (detailPanel && detailPanel.dataset.rdr === String(reportDR) && detailPanel.dataset.hasCritical === '1') {
        showToast(`🚨 ${specimen.PatName || specimen.Labno || ''} 有危急值，必须在原始LIS中审核`, 'error');
        return;
      }

      if (!isSpecimenActuallyComplete(specimen)) {
        showToast(`跳过: ${specimen.PatName} 结果不完整`, 'warning');
        return;
      }

      const status = String(specimen.Status || specimen.ReportStatus || '');
      // 8.5.52: 复审（status 4）可正常审核（除危急值外，危急值由 validateAuditClassification 拦）
      // status 3（一审完成）仍拦截
      if (status === '3') {
        showToast(`跳过: ${specimen.PatName} 已审核`, 'warning');
        return;
      }
      // 8.10.0: status 5（已取消）拦截——已取消报告不可审核
      if (status === '5') {
        showToast(`跳过: ${specimen.PatName} 标本已取消，不可审核`, 'warning');
        return;
      }

      // 8.16.16: 同列表路径——跨组判定一律用可信登录组，不确定则不切组
      const curDR = resolveLoginWGReliable();
      const spDR = specimen._wg || '';
      // 8.5.10: 跨组先试不切组（同列表路径）；原生列表选不到时才回退切组重试
      const _wsCrossGroupTry = !!(spDR && curDR && spDR !== curDR);
      // 不切组直接审：先把 origin 钉在当前组，避免审完被陈旧 origin 误切回
      if (_wsCrossGroupTry) {saveAuditOriginCurrent('detail');}

      // 若后台预热正在运行，等它结束再现场判定（避免双线程同时驱动原生页竞态）。
      // 预热针对本标本时原生页已定位（needPrep 可直接跳过）；针对其他标本
      // （详情内 ↑↓ 切换后列表焦点未同步）也等它结束，防止并发 select 同一 iframe。
      if (_abnormalPrewarmPromise) {
        const prewarmDR = String(_abnormalPrewarmDR || '');
        try { await _abnormalPrewarmPromise; } catch (e) {}
        if (prewarmDR === String(reportDR)) {iframeWin = getReportIframeWin() || iframeWin;}
      }

      let needPrep = true;
      try {
        const me = iframeWin.me;
        if (me && me.selectedGrid && isReportDetailLoaded(iframeWin, reportDR)) {needPrep = false;}
      } catch (e) {}
      if (needPrep) {
        _setDetailAuditBusy(true, '⏳ 定位标本…');
        const prep = await ensureSpecimenReadyForAudit(iframeWin, specimen, { lastMdr: _abnormalLastMdr });
        iframeWin = prep.iframeWin || iframeWin;
        if (prep.lastMdr) {_abnormalLastMdr = prep.lastMdr;}
        if (!prep.ok) {
          // 8.5.10: 跨组先试不切组失败（原生列表选不到 / 详情加载不出）→ 回退切组重试
          if (
            _wsCrossGroupTry &&
            (prep.reason === 'select' || prep.reason === 'detail') &&
            spDR &&
            resolveLoginWGReliable() &&
            spDR !== resolveLoginWGReliable()
          ) {
            const wgName = (WG_MAP[spDR] || {}).name || spDR;
            showToast(`未找到标本/详情未加载，切换到${wgName}重试`, 'warning');
            saveAbnormalTarget(specimen, { source: 'detail' }); // 8.5.8: 标记详情来源，跨组恢复后重开详情面板续审
            safeSwitchWG(spDR);
            return;
          }
          const msg = prep.reason === 'detail' ? '报告详情未加载完成' : '未在原生列表中找到该标本';
          showToast(msg, prep.reason === 'detail' ? 'warning' : 'error');
          return;
        }
      }

      _setDetailAuditBusy(true, '⏳ 提交审核…');
      let auditResult = await executeNativeAudit(iframeWin, specimen, { keepWS: true, fast: true });
      if (auditResult === 'incomplete') {
        showToast(`跳过: ${specimen.PatName} 结果不完整`, 'warning');
        return;
      }
      // 最终兜底：多重校验（原生状态轮询 + wsData + softHint）
      // 8.9.0: 延迟兜底校验抽为 confirmAuditEventuallyLive 共用
      if (!auditResult) {
        _setDetailAuditBusy(true, '⏳ 确认审核结果…');
        auditResult = await confirmAuditEventuallyLive(iframeWin, reportDR, specimen);
      }
      if (!auditResult) {
        showToast(`审核失败: ${specimen.PatName || ''}，未能确认审核结果，请核对原生列表状态`, 'error');
        return;
      }
      showToast(`审核成功: ${specimen.PatName}`, 'success');
      closeNativeAuditSuccessMessage(iframeWin);
      // 8.5.54: 复检标本审核成功 → 记录「曾复审」
      if (String(specimen.Status || specimen.ReportStatus || '') === '4') {recheckDoneAdd(reportDR);}
      dbg('详情审核成功:', specimen.PatName, 'ReportDR:', reportDR);

      // 确保焦点在主页面（审核操作后焦点可能留在 iframe 中）
      try {
        window.focus();
      } catch (e) {}

      // 从数据中移除
      delete wsClassifiedCache[specimen.ReportDR];
      _wsLocalRemoved.add(String(specimen.ReportDR)); // 8.9.0: 防在途旧快照把该行带回列表
      wsData = wsData.filter(r => r.ReportDR !== specimen.ReportDR);
      invalidateCaches();
      calcMachineCounts();

      // 自动切换到下一个标本（原地更新，不关闭面板）
      // 须 force：此时 _detailAuditInProgress 仍为 true，否则会被「审中禁切换」误拦
      if (nextReportDR) {
        const newData = filteredData();
        const nextSpecimen = newData.find(r => r.ReportDR === nextReportDR);
        dbg('下一个标本: 数据量=', newData.length, 'ReportDR=', nextReportDR, 'found=', !!nextSpecimen);
        if (nextSpecimen) {
          const nextIdx = newData.indexOf(nextSpecimen);
          // 延迟更新工作台视图，先切换详情
          requestAnimationFrame(() => {
            renderWSCategoryBar();
            renderWSTable();
          });
          _switchDetailInPlace(nextSpecimen, source, nextIdx, { force: true });
        } else {
          closeDetailPanel(true); // force: 审核已完成，绕过 _detailAuditInProgress 守卫
          // 待审视图详情审核完成：保持当前视图（正常/异常已合并，无需再切分类）
          renderWSCategoryBar();
          renderWSTable();
        }
      } else {
        closeDetailPanel(true); // force: 审核已完成，绕过 _detailAuditInProgress 守卫
        renderWSCategoryBar();
        renderWSTable();
        // 8.5.8: 详情连续审核审完最后一条（跨组单向推进到达队尾）→ 自动切回起始工作组
        trySwitchBackToOrigin();
      }
    } catch (e) {
      dbg('详情面板审核失败:', e);
      showToast('审核失败: ' + e.message, 'error');
    } finally {
      _auditingPreStatus4 = false; // 8.5.53
      clearTimeout(_detailSafetyTimer);
      _detailAuditInProgress = false;
      _setDetailAuditBusy(false);
      if (resumeWSRefresh && isWSVisible()) {startWSRefresh();}
      // 详情审核结束：后台预热当前（下一条）标本，保证连续 Enter 秒审
      if (isDetailPanelVisible() && currentDetailSpecimen) {
        scheduleDetailPrewarm(currentDetailSpecimen, 20); // 8.10.13: 缩短预热延时至 20ms
      }
      dbg('详情审核结束, inProgress 重置为 false');
      // 8.10.13: 处理排队的 Enter，实现无缝连续审核
      if (_detailAuditQueued) {
        _detailAuditQueued = false;
        if (isDetailPanelVisible() && currentDetailSpecimen) {
          setTimeout(() => {
            if (isDetailPanelVisible() && currentDetailSpecimen && !_detailAuditInProgress) {
              void _auditFromDetailPanel();
            }
          }, 30);
        }
      }
    }
  }

  // F4 列表路径已收敛到 auditAbnormalSpecimen（见 triggerF4Audit）；保留薄封装兼容旧调用
  function auditFocusedSpecimenAsDetail() {
    triggerF4Audit();
  }

  function closeDetailPanel(force) {
    if (_detailAuditInProgress && !force) {
      dbg('审核进行中，忽略关闭详情面板');
      return;
    }
    _detailAuditQueued = false; // 8.10.13: 关闭面板清空排队
    _removeDetailKeyHandler();
    if (detailPanel) {
      detailPanel.classList.remove('show');
      currentDetailSpecimen = null;
      detailSource = null;
      detailSourceIndex = -1;
    }
    // 隐藏遮罩层
    const overlay = document.getElementById('lis-detail-overlay');
    if (overlay) {overlay.style.display = 'none';}
    // 8.8.2: 详情面板会话结束（审过跨午夜/历史标本）——原生日期框恢复今天
    restoreNativeDateboxToday();
    // 详情已关闭：恢复 iframe Enter 桥（若在待审视图则重新激活，否则置 inactive）
    updateAbnormalEnterBridge();
    // 如果当前是待审视图，恢复键盘监听
    if (wsCategory === 'audit') {
      _rebindAbnormalKeyHandler();
    }
    // 8.11.8: 抽屉打开期间被推迟的整表重建在此补上，避免列表长期停留在旧快照
    if (_wsRenderDeferred) {
      _wsRenderDeferred = false;
      renderWSTable();
      renderWSCategoryBar();
    }
  }

  function getStatusText(status) {
    const map = {
      0: '📦 待排样',
      1: '📋 登记',
      2: '🔍 初审',
      3: '✅ 审核',
      4: '🔄 复审',
      5: '❌ 取消',
      9: '🩸 采集中'
    };
    return map[String(status)] || '未知';
  }

  // 解析并渲染单个检验项目的历次结果，返回 {cells:[], dates:[]}
  function renderHistoryItems(r, live) {
    const historyItems = parsePreResult(r);
    if (historyItems.length === 0) {return { cells: ['', '', ''], dates: [] };}

    // 按日期降序排列（最新的在前），无日期的排最后
    const sorted = [...historyItems].sort((a, b) => {
      if (!a.date && !b.date) {return 0;}
      if (!a.date) {return 1;}
      if (!b.date) {return -1;}
      return b.date.localeCompare(a.date);
    });
    const recent = sorted.slice(0, 3);
    const cells = [];
    const dates = [];
    for (let i = 0; i < 3; i++) {
      if (i < recent.length) {
        const h = recent[i];
        let cls = 'normal';
        let st = ''; // 8.15.17: 供「能否批审」判定用的状态（只对高/低有意义）
        // 优先用 AbFlag 判断档位（从 PreResult 中提取）
        const ab = (h.abFlag || '').toUpperCase();
        if (ab === 'HH' || ab === 'LL') {cls = 'critical';}
        else if (ab === 'H') {cls = 'high'; st = 'HIGH';}
        else if (ab === 'L') {cls = 'low'; st = 'LOW';}
        else if (ab === 'A') {cls = 'abnormal';}
        else {
          // 回退：用参考范围数值比较
          const histStatus = compareResultToRange(h.result, r.ValueLow, r.ValueHigh);
          if (histStatus === 'HIGH') {cls = 'high'; st = 'HIGH';}
          else if (histStatus === 'LOW') {cls = 'low'; st = 'LOW';}
        }
        // 8.16.10: 历史值也必须判**危急**。LIS 的历史快照（PreResult）只带 H/L 级别标志，
        // 历史那次是否达到危急不会体现在 abFlag 里 —— 实测低钠 113.8 / 112.5（参考 135-155）
        // 只标 L，历史列就渲染成普通蓝色低值，与本次 119.7 的深红「危急」自相矛盾，
        // 现场直接质疑「明明是危急值为什么不是红的」。
        // 用**当前标本该项的危急范围**复核（同一患者同一项目的危急线一致；PreResult 不带危急范围），
        // 判不出（LIS 未配危急值）时保持原样，不会误染红。
        if (cls !== 'critical') {
          const _ps = compareResultToPanicRange(h.result, r);
          if (_ps === 'HIGH' || _ps === 'LOW') {cls = 'critical'; st = '';}
        }
        // 8.15.17: 历史小列不再只按 LIS 的 AbFlag 上色，而是与主结果共用同一套「可批审 / 须人工」判定，
        // 且用**当前生效的放行规则**（含 ⚙ 人工覆盖）现算 —— 所以上调/下调上下限后，
        // 历史列的颜色与形式（白底虚线 vs 满色实线）会跟着一起变，不需要重新打开历史。
        // 判定借当前标本该项的参考范围（PreResult 不带范围字段，同一患者同一项目范围一般一致）；
        // 判不出（缺范围 / 分段文本 / 未配规则）一律按「须人工」显示，方向保守。
        if (st && mildItemVerdict(mildItemFromRaw(r, st, h.result), live) === 'pass') {cls += ' mild';}
        if (!h.date && cls === 'normal') {cls = 'nodate';}
        const dateStr = h.date ? h.date.split(' ')[0].replace(/^\d{2}(\d{2})/, '$1') : '';
        dates.push(dateStr);
        cells.push(`<span class="hist-tag ${cls}">${esc(h.result)}</span>`);
      } else {
        dates.push('');
        cells.push('<span style="color:#ddd">-</span>');
      }
    }
    return { cells, dates };
  }

  // 健壮解析 PreResult 字段（支持多种格式）
  function parsePreResult(r) {
    const items = [];

    // 尝试所有可能的 PreResult 来源
    const sources = [r.PreResult, r.PreResult1, r.PreResult2, r.PreResult3, r.LabResult, r.HistoryResult];

    for (const src of sources) {
      if (!src) {continue;}

      // 格式1: 已经是数组
      if (Array.isArray(src)) {
        for (const p of src) {
          const res = p.Result || p.TCResult || p.result || p.PreResult || '';
          const dt = p.AcceptDT || p.AcceptDate || p.date || p.Date || '';
          const ab = (p.AbFlag || p.abFlag || p.Flag || '').toString().toUpperCase().trim();
          if (res) {items.push({ result: String(res).trim(), date: String(dt).trim(), abFlag: ab });}
        }
        continue;
      }

      // 格式2: JSON 字符串
      if (typeof src === 'string') {
        const trimmed = src.trim();
        if (!trimmed) {continue;}

        // 尝试 JSON 解析
        if (trimmed.startsWith('[') || trimmed.startsWith('{')) {
          try {
            const parsed = JSON.parse(trimmed);
            const arr = Array.isArray(parsed) ? parsed : [parsed];
            for (const p of arr) {
              const res = p.Result || p.TCResult || p.result || p.PreResult || '';
              const dt = p.AcceptDT || p.AcceptDate || p.date || p.Date || '';
              const ab = (p.AbFlag || p.abFlag || p.Flag || '').toString().toUpperCase().trim();
              if (res) {items.push({ result: String(res).trim(), date: String(dt).trim(), abFlag: ab });}
            }
            continue;
          } catch (e) {}
        }

        // 格式3: "值(日期), 值(日期)" 格式
        const matches = trimmed.match(/([^(),]+)\(([^)]+)\)/g);
        if (matches) {
          for (const m of matches) {
            const parts = m.match(/(.+)\((.+)\)/);
            if (parts) {items.push({ result: parts[1].trim(), date: parts[2].trim(), abFlag: '' });}
          }
          continue;
        }

        // 格式4: "值^标志^ID^日期" 格式（iMedicalLIS 历史结果格式）
        // 可能是单条 "5.57^H^10197009^20260607" 或逗号分隔多条
        if (trimmed.includes('^')) {
          // 先按逗号拆分多条记录
          const records = trimmed
            .split(',')
            .map(r => r.trim())
            .filter(Boolean);
          for (const rec of records) {
            if (rec.includes('^')) {
              const parts = rec.split('^');
              const res = parts[0] || '';
              const ab = (parts[1] || '').toString().toUpperCase().trim();
              // parts[1] = 异常标志(H/L/A等), parts[2] = ID, parts[3] = 日期(YYYYMMDD)
              let date = '';
              if (parts[3]) {
                const d = parts[3].trim();
                if (d.length === 8) {
                  date = d.slice(0, 4) + '-' + d.slice(4, 6) + '-' + d.slice(6, 8);
                } else {
                  date = d;
                }
              }
              if (res) {items.push({ result: res.trim(), date: date, abFlag: ab });}
            } else {
              if (rec) {items.push({ result: rec, date: '', abFlag: '' });}
            }
          }
          continue;
        }

        // 格式5: 用分隔符隔开的纯值（逗号、分号、竖线）
        if (trimmed.includes(',') || trimmed.includes(';') || trimmed.includes('|')) {
          const sep = trimmed.includes(',') ? ',' : trimmed.includes(';') ? ';' : '|';
          const vals = trimmed
            .split(sep)
            .map(v => v.trim())
            .filter(Boolean);
          for (const v of vals) {
            items.push({ result: v, date: '', abFlag: '' });
          }
          continue;
        }

        // 格式6: 单个值
        items.push({ result: trimmed, date: '', abFlag: '' });
      }
    }

    return items;
  }

  async function loadDetailResults(specimen, targetBody) {
    const isInspector = !!targetBody;
    const body = targetBody || document.getElementById('lis-detail-body');
    if (!body) {return;}
    const rdr = specimen.ReportDR || '';
    // 8.11.8: 检视器与详情抽屉各用独立序号——此前共用 _detailLoadSeq，右栏检视器每次渲染
    // （含每 30s 自动刷新、列表点击切焦）都会自增该序号，使正在加载的详情抽屉
    // isCurrentDetail() 判假并提前 return，抽屉永久停在「正在加载结果...」；
    // 检验人员在看不到结果明细的情况下仍可按 Enter 审核 → 盲审风险。
    const seq = isInspector ? ++_inspLoadSeq : ++_detailLoadSeq;
    const getDestBody = () => (isInspector ? (document.getElementById('lis-insp-body') || body) : body);
    const isCurrentDetail = () => {
      if (isInspector) {
        const insp = document.getElementById('lis-ws-inspector');
        if (!insp) {return false;}
        if (seq !== _inspLoadSeq) {return false;}
        return String(_abnormalFocusDR || '') === String(rdr);
      }
      if (seq !== _detailLoadSeq) {return false;}
      return (
        detailPanel &&
        detailPanel.classList.contains('show') &&
        currentDetailSpecimen &&
        String(currentDetailSpecimen.ReportDR || '') === String(rdr)
      );
    };

    // LRU 缓存命中
    const cached = detailLRUGet(rdr);
    if (cached) {
      dbg('详情缓存命中:', rdr);
      if (!isCurrentDetail()) {return;}
      const dBody = getDestBody();
      if (dBody) {
        dBody.innerHTML = cached.html;
        if (isInspector) {dBody.setAttribute('data-rdr', String(rdr));}
      }
      if (isInspector) {_inspShownVersion = _classifyVersion;}
      return;
    }

    try {
      // 优先使用分类时缓存的原始数据（同一 API 调用）
      let data, itemInfo, labInfo;
      const ss = buildSS(specimen._wg || wgDR());
      const classifyCached = _classifyRawCache[rdr];
      if (classifyCached && Date.now() - classifyCached.ts < 60000) {
        dbg('详情命中分类缓存:', rdr);
        data = classifyCached.data;
        itemInfo = data && data.ItemInfo ? data.ItemInfo : [];
        labInfo = data && data.LabInfo ? data.LabInfo : [];
        delete _classifyRawCache[rdr]; // 用完即删
      } else {
        const statusVal = specimen.Status || specimen.ReportStatus || '';

        const p = new URLSearchParams();
        p.set('ClassName', 'LIS.WS.BLL.DHCRPVisitNumberReportForCSP');
        p.set('QueryName', 'GetReportInfoAll');
        p.set('FunModul', 'MTHD');
        p.set('P0', specimen.ReportDR || '');
        p.set('P1', specimen.MachineParameterDR || '');
        p.set('P2', specimen.WorkGroupMachineDR || '');
        p.set('P3', statusVal);
        p.set('P4', specimen.EpisodeNo || '');
        p.set('P5', specimen.TransmitDate || '');
        p.set('P14', ss);

        dbg('加载标本详情:', specimen.ReportDR, statusVal);
        data = await fetchJ(CSP + '?' + p.toString());
        itemInfo = data && data.ItemInfo ? data.ItemInfo : [];
        labInfo = data && data.LabInfo ? data.LabInfo : [];

        if (itemInfo.length === 0 && statusVal) {
          dbg('状态', statusVal, '返回空结果，用空状态重试');
          p.set('P3', '');
          data = await fetchJ(CSP + '?' + p.toString());
          itemInfo = data && data.ItemInfo ? data.ItemInfo : [];
          if (!labInfo.length) {labInfo = data && data.LabInfo ? data.LabInfo : [];}
        }
      }

      // 调试：打印所有项目的字段和 PreResult
      if (DEBUG && itemInfo.length > 0) {
        dbg('=== PreResult 诊断 ===');
        dbg('Item0 字段:', Object.keys(itemInfo[0]).join(', '));
        itemInfo.forEach((item, i) => {
          const pr = item.PreResult;
          const prType = Array.isArray(pr) ? 'array[' + pr.length + ']' : typeof pr;
          dbg(
            `  ${i + 1}. ${item.CName}: PreResult(${prType})=`,
            pr === null ? 'null' : pr === undefined ? 'undefined' : JSON.stringify(pr).slice(0, 200)
          );
          // 检查其他可能的历史字段
          ['PreResult1', 'PreResult2', 'PreResult3', 'LabResult', 'HistoryResult', 'OldResult'].forEach(k => {
            if (item[k] !== undefined && item[k] !== null && item[k] !== '') {
              dbg(`    ${k}=`, JSON.stringify(item[k]).slice(0, 200));
            }
          });
        });
        dbg('=== 诊断结束 ===');
      }

      // 并行 fallback: 检查历史结果是否为空，同时发起备用查询
      const allPreEmpty = itemInfo.every(item => parsePreResult(item).length === 0);
      if (allPreEmpty && itemInfo.length > 0) {
        dbg('所有 PreResult 为空，并行尝试备用查询...');
        const fallbackPromises = [];
        // 备用查询1: 空状态参数
        const p2 = new URLSearchParams();
        p2.set('ClassName', 'LIS.WS.BLL.DHCRPVisitNumberReportForCSP');
        p2.set('QueryName', 'GetReportInfoAll');
        p2.set('FunModul', 'MTHD');
        p2.set('P0', specimen.ReportDR || '');
        p2.set('P1', specimen.MachineParameterDR || '');
        p2.set('P2', specimen.WorkGroupMachineDR || '');
        p2.set('P3', '');
        p2.set('P4', specimen.EpisodeNo || '');
        p2.set('P5', specimen.TransmitDate || '');
        p2.set('P14', ss);
        fallbackPromises.push(fetchJ(CSP + '?' + p2.toString()).catch(() => null));
        // 备用查询2: GetPatientPreResult
        const episodeNo = specimen.EpisodeNo || (labInfo.length > 0 ? labInfo[0].EpisodeNo : '');
        const regNo = specimen.RegNo || (labInfo.length > 0 ? labInfo[0].RegNo : '');
        if (episodeNo || regNo) {
          const pH = new URLSearchParams();
          pH.set('ClassName', 'LIS.WS.BLL.DHCRPVisitNumberReportForCSP');
          pH.set('QueryName', 'GetPatientPreResult');
          pH.set('FunModul', 'MTHD');
          pH.set('P0', specimen.ReportDR || '');
          pH.set('P1', episodeNo);
          pH.set('P2', regNo);
          pH.set('P14', ss);
          fallbackPromises.push(fetchJ(CSP + '?' + pH.toString()).catch(() => null));
        } else {
          fallbackPromises.push(Promise.resolve(null));
        }
        // 并行执行
        const [data2, histData] = await Promise.all(fallbackPromises);
        // 合并备用查询1结果
        if (data2) {
          const itemInfo2 = data2 && data2.ItemInfo ? data2.ItemInfo : [];
          if (itemInfo2.length > 0 && parsePreResult(itemInfo2[0]).length > 0) {
            itemInfo = itemInfo2;
          }
        }
        // 合并备用查询2结果
        if (histData && histData.length > 0) {
          const histMap = {};
          for (const h of histData) {
            const key = h.TestCodeDR || h.TCCode || h.CName;
            if (key) {
              if (!histMap[key]) {histMap[key] = [];}
              histMap[key].push(h);
            }
          }
          for (const item of itemInfo) {
            const key = item.TestCodeDR || item.TCCode || item.CName;
            if (histMap[key] && histMap[key].length > 0) {
              item.PreResult = histMap[key];
            }
          }
        }
      }

      if (itemInfo.length === 0) {
        if (!isCurrentDetail()) {return;}
        const isColl = specimen && (
          specimen._collected ||
          String(specimen.Status || specimen.ReportStatus || '') === '9' ||
          getWSAuditBucket(specimen) === 'collected'
        );
        const emptyMsg = isColl ? '🩸 标本处于病房采集中，尚未送到检验科上机测试' : '未找到结果数据';
        body.innerHTML = `<div style="text-align:center;padding:40px;color:#999">${emptyMsg}</div>`;
        return;
      }
      // 渲染结果
      let html = '';

      // 统计摘要栏
      const totalItems = itemInfo.length;
      const doneItems = itemInfo.filter(r => {
        const v = (r.TextRes && String(r.TextRes).trim() ? r.TextRes : r.Result || '').trim();
        return !isEmptyResultValue(r, v);
      }).length;
      const abnItems = itemInfo.filter(
        r => classifyResultItem(r) !== 'NORMAL' && classifyResultItem(r) !== 'UNCERTAIN'
      ).length;
      const critItems = itemInfo.filter(r => isCriticalResultItem(r)).length;
      const pendItems = totalItems - doneItems;

      html += '<div style="display:flex;align-items:center;gap:16px;padding:8px 0;font-size:12px;flex-wrap:wrap">';
      html += `<span style="font-weight:600">✅ 已检: ${doneItems}/${totalItems}</span>`;
      if (pendItems > 0) {html += `<span style="color:#ff9800;font-weight:600">⏳ 待检: ${pendItems}</span>`;}
      if (abnItems > 0) {html += `<span style="color:#e74c3c;font-weight:600">⚠ 异常: ${abnItems}</span>`;}
      if (critItems > 0) {html += `<span style="color:#b71c1c;font-weight:700">🚨 危急: ${critItems}</span>`;}
      html += '</div>';

      // x8 传染病面板：梅毒/丙肝/HIV 阳性高亮图例（区别于乙肝两对半）
      const isX8Inf = isX8InfectionPanel(specimen);
      const hasInfSpecialPos =
        isX8Inf &&
        itemInfo.some(r => {
          const res = r.TextRes && r.TextRes.trim() ? r.TextRes.trim() : r.Result || '';
          return isInfectionSpecialItem(r.CName) && isPositiveResult(res, r);
        });
      if (hasInfSpecialPos) {
        const c = INFECTION_SPECIAL_STYLE;
        html +=
          '<div style="display:flex;gap:12px;align-items:center;padding:4px 0 8px;font-size:11px;flex-wrap:wrap">';
        html += '<span style="color:#555;font-weight:700">⚠ 传染病阳性高亮：</span>';
        html += `<span style="display:inline-flex;align-items:center;gap:5px;font-weight:800;color:#5d3a00"><span style="width:11px;height:11px;border-radius:2px;background:${c.bg};border:1px solid ${c.border};display:inline-block"></span>${INFECTION_SPECIAL_LABEL}</span>`;
        html += '</div>';
      }

      // 结果表格（紧凑布局）
      // 8.5.17: 项目多时分栏（2 栏并排）——生化几十项一屏看全，历史日期列完整保留，
      // 避免单列长表必须滚动才能看完所有项目。
      const _detailCols = itemInfo.length > 16 ? 2 : 1;
      const _detailColSize = Math.ceil(itemInfo.length / _detailCols);
      html += '<div style="display:flex;gap:14px;align-items:flex-start">';

      // 收集历史日期（基于全量项目，仅算一次）
      const allDates = [[], [], []];
      itemInfo.forEach(r => {
        const hi = parsePreResult(r);
        const sorted = [...hi].sort((a, b) => {
          if (!a.date && !b.date) {return 0;}
          if (!a.date) {return 1;}
          if (!b.date) {return -1;}
          return b.date.localeCompare(a.date);
        });
        const recent = sorted.slice(0, 3);
        for (let i = 0; i < 3; i++) {
          if (i < recent.length && recent[i].date) {
            const d = recent[i].date.split(' ')[0].replace(/^\d{2}(\d{2})/, '$1');
            if (d) {allDates[i].push(d);}
          }
        }
      });
      const hdrDates = allDates.map(arr => {
        if (arr.length === 0) {return '';}
        const freq = {};
        arr.forEach(d => {
          freq[d] = (freq[d] || 0) + 1;
        });
        return Object.keys(freq).sort((a, b) => freq[b] - freq[a])[0];
      });
      const thDates = hdrDates
        .map(d => (d ? `<th style="font-size:11.5px">${esc(d)}</th>` : '<th style="font-size:11.5px">-</th>'))
        .join('');

      // 8.15.6: 本标本的分类缓存（供「轻微带内＝浅色」判定；拿不到时退化为按项目现算）
      const _liveForMild = getLiveClassification(specimen && (specimen.ReportDR || specimen.reportDR));
      for (let _ci = 0; _ci < _detailCols; _ci++) {
        const _colItems = itemInfo.slice(_ci * _detailColSize, Math.min((_ci + 1) * _detailColSize, itemInfo.length));
        html += `<table class="result-table${_detailCols > 1 ? ' compact' : ''}" style="flex:1;min-width:0">`;

      html += `<thead><tr><th style='width:20px'>QC</th><th>项目${_detailCols > 1 ? ' / 参考' : ''}</th><th>结果</th>${_detailCols > 1 ? '' : '<th>参考范围</th>'}${thDates}<th style="width:34px" title="查看该项目历史（跨组）">🔎</th></tr></thead>`;
      html += '<tbody>';

      _colItems.forEach(r => {
        const result = r.TextRes && r.TextRes.trim() ? r.TextRes.trim() : r.Result || '-';
        const unit = r.Unit || r.Units || '';
        const refRange = r.RefRanges || '-';
        const abnormalFlag = (r.AbFlag || '').toUpperCase().trim();

        const rawResult = (r.TextRes && String(r.TextRes).trim() ? r.TextRes : r.Result || '').trim();
        const isEmpty = isEmptyResultValue(r, rawResult);
        let isAbnormal = false,
          isCritical = false;
        let statusText = isEmpty ? '⏳ 待检' : '✓';

        const itemStatus = classifyResultItem(r);
        const criticalByRange = itemStatus === 'CRITICAL';
        const panicStatus = compareResultToPanicRange(result, r);

        if (criticalByRange) {
          isAbnormal = true;
          isCritical = true;
          statusText = abnormalFlag === 'LL' || panicStatus === 'LOW' ? '↓↓ 危急' : '↑↑ 危急';
        } else if (abnormalFlag === 'H' || itemStatus === 'HIGH') {
          isAbnormal = true;
          statusText = '↑ 高';
        } else if (abnormalFlag === 'L' || itemStatus === 'LOW') {
          isAbnormal = true;
          statusText = '↓ 低';
        } else if (abnormalFlag === 'A' || itemStatus === 'ABNORMAL') {
          isAbnormal = true;
          statusText = '⚠ 异常';
        } else if (r.ValueLow && r.ValueHigh) {
          const rangeStatus = compareResultToRange(result, r.ValueLow, r.ValueHigh);
          if (rangeStatus === 'HIGH') {
            isAbnormal = true;
            statusText = '↑ 高';
          } else if (rangeStatus === 'LOW') {
            isAbnormal = true;
            statusText = '↓ 低';
          }
        }

        // 8.15.21: 堵孔 0 值检测（生化分析仪特有误报）
        const _matchedCachedItem = _liveForMild && _liveForMild.items && _liveForMild.items.find(it => (it.code && it.code === (r.TestCodeDR || r.TCCode)) || (it.name && it.name === r.CName));
        const isZeroSuspect = (_matchedCachedItem && _matchedCachedItem.status === 'ZERO') ||
          (ZERO_BLOCK_MACHINE_NAMES.test(String(specimen && (specimen._mn || specimen.MachineName || '') || '')) &&
           parseComparableNumber(result) && parseComparableNumber(result).value === 0 && parseComparableNumber(result).op === '' &&
           (() => {
             const rg = getItemRangeValues({ low: r.ValueLow, high: r.ValueHigh, ref: refRange });
             const lo = parseComparableNumber(rg.low);
             const hi = parseComparableNumber(rg.high);
             if ((lo && !isNaN(lo.value)) || (hi && !isNaN(hi.value))) {
               const lowLe0 = !lo || isNaN(lo.value) || lo.value <= 0;
               const highGe0 = hi && !isNaN(hi.value) ? hi.value >= 0 : (!lo || isNaN(lo.value));
               return !(lowLe0 && highGe0);
             }
             return false;
           })());

        // 8.15.21 方案 A：行底色彻底去除普通高/低满行色块，仅危急值/堵孔/待检保留极浅提示底色
        let rowStyle = '';
        if (isEmpty) {
          rowStyle = 'background:#fafafa;color:#94a3b8';
        } else if (isCritical) {
          rowStyle = 'background:#fef2f2;border-left:3px solid #ef4444';
        } else if (isZeroSuspect) {
          rowStyle = 'background:#faf5ff;border-left:3px solid #8b5cf6';
        }

        // 8.15.21 方案 A：微胶囊标签流分类（数值+形态双重区分：轻微项镂空淡底细箭头 / 显著项实色徽章实心三角）
        let tagClass = 'normal';
        let arrowIcon = '';
        let arrowDesc = '';

        if (isEmpty) {
          tagClass = 'empty';
          arrowDesc = '⏳ 待检';
        } else if (isCritical) {
          tagClass = 'critical';
          const isLow = abnormalFlag === 'LL' || panicStatus === 'LOW';
          arrowIcon = isLow ? '↓↓ 危急' : '↑↑ 危急';
          arrowDesc = isLow ? '↓↓ 危急（极低）' : '↑↑ 危急（极高）';
        } else if (isZeroSuspect) {
          tagClass = 'zero';
          arrowIcon = '⚠️ 堵孔';
          arrowDesc = '疑似生化堵孔0值，须人工核实';
        } else if (isX8Inf && !isCritical && isInfectionSpecialItem(r.CName) && isPositiveResult(result, r)) {
          tagClass = 'inf-special';
          arrowIcon = '+ 阳性';
          arrowDesc = '传染病特殊阳性';
          rowStyle = 'background:' + INFECTION_SPECIAL_STYLE.bg + ';border-left:3px solid ' + INFECTION_SPECIAL_STYLE.border + ';font-weight:700';
        } else if (statusText.includes('高')) {
          const _mvIt = mildItemFromRaw(r, itemStatus, result);
          const isMild = mildItemVerdict(_mvIt, _liveForMild, mildSexOf({ row: specimen })) === 'pass';
          if (isMild) {
            tagClass = 'mild-high';
            arrowIcon = '↑';
            arrowDesc = '↑ 高（轻微带内，F4 可批审）';
          } else {
            tagClass = 'high';
            arrowIcon = '▲';
            arrowDesc = '▲ 显著偏高（超带，须人工审核）';
          }
        } else if (statusText.includes('低')) {
          const _mvIt = mildItemFromRaw(r, itemStatus, result);
          const isMild = mildItemVerdict(_mvIt, _liveForMild, mildSexOf({ row: specimen })) === 'pass';
          if (isMild) {
            tagClass = 'mild-low';
            arrowIcon = '↓';
            arrowDesc = '↓ 低（轻微带内，F4 可批审）';
          } else {
            tagClass = 'low';
            arrowIcon = '▼';
            arrowDesc = '▼ 显著偏低（超带，须人工审核）';
          }
        } else if (isAbnormal) {
          tagClass = 'abnormal';
          arrowIcon = '⚠';
          arrowDesc = '⚠ 异常';
        } else {
          tagClass = 'normal';
          arrowIcon = '';
          arrowDesc = '';
        }

        // 参考范围带单位
        const refWithUnit = unit ? refRange + ' ' + unit : refRange;

        // 8.15.21 方案 A：微胶囊标签 + 外部柔和灰色单位
        let tagInner = esc(result);
        if (arrowIcon) {
          tagInner += ` <span class="res-arrow">${esc(arrowIcon)}</span>`;
        }
        const resTagHTML = `<span class="res-tag ${tagClass}">${tagInner}</span>`;
        const resUnitHTML = unit ? `<span class="res-unit">${esc(unit)}</span>` : '';
        const resTitle = arrowDesc ? ' title="' + escAttr(arrowDesc) + '"' : '';

        // 历史结果
        const hist = renderHistoryItems(r, _liveForMild);

        // QC 状态图标
        let qcHtml = '';
        const qcf = (r.QcFlag || '').split('^');
        const qcs = qcf[0] || '0';
        if (qcs === '0') {
          qcHtml =
            '<span style="display:inline-block;width:14px;height:14px;border-radius:50%;border:2px solid #bbb;background:#f5f5f5" title="未做质控"></span>';
        } else if (qcs === '1') {
          qcHtml =
            '<span style="display:inline-block;width:14px;height:14px;border-radius:50%;background:#4caf50;box-shadow:0 0 4px rgba(76,175,80,.5)" title="质控正常"></span>';
        } else if (qcs === '2') {
          qcHtml =
            '<span style="display:inline-block;width:14px;height:14px;border-radius:50%;background:#ff9800;box-shadow:0 0 4px rgba(255,152,0,.5)" title="质控正常·警告未处理"></span>';
        } else if (qcs === '3') {
          qcHtml =
            '<span style="display:inline-block;width:14px;height:14px;border-radius:50%;background:#e74c3c;box-shadow:0 0 4px rgba(231,76,60,.5)" title="质控正常·失控未处理"></span>';
        } else if (qcs === '4') {
          qcHtml =
            '<span style="display:inline-block;width:14px;height:14px;border-radius:50%;background:#2196f3;box-shadow:0 0 4px rgba(33,150,243,.5)" title="质控正常·警告/失控已处理"></span>';
        } else if (qcs === '5') {
          qcHtml =
            '<span style="display:inline-block;width:14px;height:14px;border-radius:50%;background:#e74c3c;box-shadow:0 0 6px rgba(231,76,60,.7)" title="质控失控"></span>';
        } else if (qcs === '6') {
          qcHtml =
            '<span style="display:inline-block;width:14px;height:14px;border-radius:50%;background:#9e9e9e;box-shadow:0 0 4px rgba(158,158,158,.5)" title="批次过期"></span>';
        } else {
          qcHtml =
            '<span style="display:inline-block;width:14px;height:14px;border-radius:50%;border:2px solid #bbb;background:#f5f5f5" title="未知"></span>';
        }

        // 8.15.9: 项目名后的 ⚙ —— 调整该项目的轻微放行范围（人工改过的用醒目色，一眼能看出规则被动过）
        const _mildIt = mildItemFromRaw(r, itemStatus, result);
        const _mildRule = matchMildRule(_mildIt);
        const _mildOvd = isMildRuleOverridden(_mildRule);
        const _mildBtnTitle = _mildRule
          ? ('调整「' + (r.CName || '') + '」的 F4/自动审核放行范围'
            + (_mildOvd ? '（已人工修改）' : '') + (_mildRule._off ? '（当前已停用）' : ''))
          : '该项目未配放行规则 —— 点此新增';
        const _mildSvg = '<svg width="10" height="10" viewBox="0 0 16 16" fill="currentColor" style="display:block;pointer-events:none"><path d="M8 4.754a3.246 3.246 0 1 0 0 6.492 3.246 3.246 0 0 0 0-6.492zM5.754 8a2.246 2.246 0 1 1 4.492 0 2.246 2.246 0 0 1-4.492 0z"/><path d="M9.796 1.343c-.527-1.79-3.065-1.79-3.592 0l-.094.319a.873.873 0 0 1-1.255.52l-.292-.16c-1.64-.892-3.433.902-2.54 2.541l.159.292a.873.873 0 0 1-.52 1.255l-.319.094c-1.79.527-1.79 3.065 0 3.592l.319.094a.873.873 0 0 1 .52 1.255l-.16.292c-.892 1.64.901 3.434 2.541 2.54l.292-.159a.873.873 0 0 1 1.255.52l.094.319c.527 1.79 3.065 1.79 3.592 0l.094-.319a.873.873 0 0 1 1.255-.52l.292.16c1.64.893 3.434-.902 2.54-2.541l-.159-.292a.873.873 0 0 1 .52-1.255l.319-.094c1.79-.527 1.79-3.065 0-3.592l-.319-.094a.873.873 0 0 1-.52-1.255l.16-.292c.893-1.64-.902-3.433-2.541-2.54l-.292.159a.873.873 0 0 1-1.255-.52l-.094-.319z"/></svg>';
        const mildBtn = '<button class="detail-mild-btn' + (_mildOvd ? ' ovd' : '') + '"' +
          ' data-name="' + escAttr(r.CName || '') + '"' +
          ' data-syn="' + escAttr(r.Synonym || r.Code || '') + '"' +
          ' data-code="' + escAttr(r.TestCodeDR || r.TCCode || '') + '"' +
          ' data-res="' + escAttr(String(result)) + '"' +
          ' data-unit="' + escAttr(String(r.Unit || r.Units || '')) + '"' +
          ' data-ref="' + escAttr(r.RefRanges || r.RefRange || r.ReferenceRange || '') + '"' +
          ' data-vlow="' + escAttr(String(r.ValueLow || r.LowValue || r.RefLow || '')) + '"' +
          ' data-vhigh="' + escAttr(String(r.ValueHigh || r.HighValue || r.RefHigh || '')) + '"' +
          ' data-sex="' + escAttr(mildSexOf({ row: specimen })) + '"' +
          ' title="' + escAttr(_mildBtnTitle) + '">' + _mildSvg + '</button>';

        html += `<tr style="${rowStyle}">
                    <td style="text-align:center">${qcHtml}</td>
                    <td style="font-weight:500;white-space:nowrap"><div style="display:inline-flex;align-items:center;vertical-align:middle"><span style="display:inline-block;max-width:${_detailCols > 1 ? '112px' : '140px'};overflow:hidden;text-overflow:ellipsis;white-space:nowrap;vertical-align:middle" title="${esc(r.CName || '')}${_detailCols > 1 ? '  ' + esc(refWithUnit) : ''}">${esc(r.CName || '-')}</span>${mildBtn}</div>${_detailCols > 1 ? '<span style="font-size:11px;color:#888;font-weight:400;margin-left:3px"> ' + esc(refRange) + '</span>' : ''}</td>
                    <td class="${tagClass}" style="white-space:nowrap"${resTitle}>${resTagHTML}${resUnitHTML}</td>
                    ${_detailCols > 1 ? '' : '<td style="color:#888;font-size:12px;white-space:nowrap">' + esc(refWithUnit) + '</td>'}
                    <td style="font-size:11.5px">${hist.cells[0]}</td>
                    <td style="font-size:11.5px">${hist.cells[1]}</td>
                    <td style="font-size:11.5px">${hist.cells[2]}</td>
                    <td style="text-align:center"><button class="detail-hist-item" data-key="${esc(r.TestCodeDR || r.TCCode || '')}" data-name="${esc(r.CName || '')}" data-syn="${esc(r.Synonym || r.Code || '')}" title="查看该项目历史（跨组）">🔎</button></td>
                </tr>`;
      });

        html += '</tbody></table>';
      }
      html += '</div>';

      // 患者信息（可折叠）
      // 8.5.82: 头部文本先计算、待 isCurrentDetail 守卫通过后再写 DOM（防旧标本慢请求覆盖新标本头部）
      let _extraText = null;
      if (labInfo.length > 0) {
        const info = labInfo[0];
        let timeDelta = '';
        if (info.CollectDT && info.ReceiveDT) {
          try {
            const diffMs = new Date(String(info.ReceiveDT).replace(/-/g, '/')) - new Date(String(info.CollectDT).replace(/-/g, '/'));
            if (isNaN(diffMs)) {throw new Error('invalid date');}
            const diffH = Math.floor(diffMs / 3600000);
            const diffM = Math.floor((diffMs % 3600000) / 60000);
            timeDelta = diffH > 0 ? diffH + '小时' + diffM + '分' : diffM + '分钟';
          } catch (e) {}
        }

        _extraText = buildDetailExtraText(info, specimen);

        // 异常警告（内联）
        if (critItems > 0) {
          html +=
            '<div style="margin-top:6px;padding:6px 10px;background:#fff5f5;border-radius:4px;font-size:11px;border:1px solid #ffcdd2">';
          html += '<span style="color:#e74c3c;font-weight:700">🚨 危急值 ' + critItems + ' 项</span>';
          html += '<span style="margin-left:12px;color:#c62828;font-size:10px">须在原始LIS中审核</span>';
          html += '</div>';
        } else if (abnItems > 0) {
          // 列出具体异常项目名称
          const abnNames = itemInfo
            .filter(r => classifyResultItem(r) !== 'NORMAL' && classifyResultItem(r) !== 'UNCERTAIN')
            .map(r => {
              const st = classifyResultItem(r);
              const arrow =
                st === 'CRITICAL'
                  ? compareResultToPanicRange(r.TextRes && r.TextRes.trim() ? r.TextRes : r.Result, r) === 'LOW' ||
                    String(r.AbFlag || '').toUpperCase() === 'LL'
                    ? '↓↓危急'
                    : '↑↑危急'
                  : st === 'HIGH'
                    ? '↑'
                    : st === 'LOW'
                      ? '↓'
                      : '⚠';
              return esc((r.CName || '') + ' ' + (r.TextRes || r.Result || '') + ' ' + arrow);
            });
          html +=
            '<div style="margin-top:6px;padding:6px 10px;background:#fff8e1;border-radius:4px;font-size:11px;border:1px solid #ffecb3">';
          html += '<span style="color:#ff9800;font-weight:600">⚠ 异常项目 ' + abnItems + ' 项</span>';
          if (abnNames.length > 0)
          {html += '<span style="margin-left:8px;color:#e65100;font-size:10px">' + abnNames.join('、') + '</span>';}
          html += '</div>';
        }

        // 传染病历史比对
        const cached = wsClassifiedCache[specimen.ReportDR];
        if (cached && cached.infectionWarning) {
          html +=
            '<div style="margin-top:6px;padding:6px 10px;background:#fff3e0;border-radius:4px;font-size:11px;border:1px solid #ffcc80">';
          html += '<span style="color:#e65100;font-weight:700">⚠️ 与历史结果不一致</span>';
          html += '<div style="color:#bf360c;font-size:10px;margin-top:2px">' + esc(cached.infectionWarning) + '</div>';
          html += '</div>';
        }
      }

      if (!isCurrentDetail()) {return;}
      if (_extraText !== null && !isInspector) {
        const extraEl = document.getElementById('lis-detail-extra');
        if (extraEl) {extraEl.textContent = _extraText;}
      }
      const dBody = getDestBody();
      if (dBody) {
        dBody.innerHTML = html;
        if (isInspector) {dBody.setAttribute('data-rdr', String(rdr));}
      }
      const _dp = document.getElementById('lis-detail-panel');
      if (_dp && !isInspector) {
        _dp.dataset.rdr = String(rdr);
        _dp.dataset.hasCritical = critItems > 0 ? '1' : '0';
      }
      if (isInspector) {
        const al = document.getElementById('lis-insp-alert');
        if (al) {
          if (critItems > 0) {
            al.innerHTML = `<div class="ws-insp-alert critical">🚨 <b>危急值警告</b>：此标本包含危急值指标 (${critItems} 项)，须在原始 LIS 复查登记后再审核！</div>`;
          } else if (hasInfSpecialPos) {
            al.innerHTML = `<div class="ws-insp-alert warning">⚠️ <b>传染病阳性高亮</b>：包含梅毒/丙肝/HIV等特殊阳性指标，请仔细复核！</div>`;
          }
        }
        // 8.11.8: 标记「右栏已完整渲染该标本结果」，供 renderLiveInspector 刷新时跳过重建
        _inspShownVersion = _classifyVersion;
      }
      // 存入 LRU 缓存
      detailLRUSet(rdr, { html, ts: Date.now() });

      // 8.10.23: 若为手工录入标本且详情结果已完整录入，就地计算并补全分类缓存
      if (isManualEntrySpecimen(specimen)) {
        const _cached = wsClassifiedCache[rdr];
        if (!_cached || !_cached.isManualComplete) {
          const fresh = buildClassificationFromItems(specimen, itemInfo, labInfo);
          if (fresh.isManualComplete) {
            wsClassifiedCache[rdr] = fresh;
            _classifyVersion++;
            invalidateCaches();
            calcMachineCounts();
            renderWSTabs();
            renderWSCategoryBar();
          }
        }
      }
    } catch (e) {
      dbg('加载详细结果失败:', e);
      if (!isCurrentDetail()) {return;}
      const dBody = getDestBody();
      if (dBody) {
        dBody.innerHTML = `
                  <div style="text-align:center;padding:40px;color:#e74c3c">
                      <p>❌ 加载失败</p>
                      <p style="font-size:12px">${esc(e.message)}</p>
                  </div>
              `;
      }
    }
  }

  // 检查是否有待导航目标（页面加载后）
  function checkNavigateTarget() {
    try {
      const raw = localStorage.getItem(K.tgt);
      if (!raw) {return;}
      const tgt = JSON.parse(raw);
      if (!tgt || Date.now() - tgt.time > 30000) {
        localStorage.removeItem(K.tgt);
        return;
      }
      localStorage.removeItem(K.tgt);

      const curDR = wgDR();
      if (tgt.wgDR !== curDR) {return;} // 工作组不匹配，可能还在切换中

      // 延迟执行，等待页面完全加载
      setTimeout(() => {
        try {
          const w = uw();
          if (tgt.machineDR && w.me) {
            w.me.WorkGroupMachineDR = tgt.machineDR;
            if (typeof w.$ !== 'undefined') {
              try {
                w.$('#cmb_WorkGroupMachine').combogrid('setValue', tgt.machineDR);
              } catch (e) {}
            }
          }
          if (tgt.labno) {
            if (typeof w.$ !== 'undefined') {
              try {
                w.$('#txt_FindFast').val(tgt.labno);
              } catch (e) {}
            }
            if (typeof w.FindFast === 'function') {
              w.FindFast(tgt.labno);
            }
          }
          // 等待搜索结果加载并选中对应行
          selectNativeRowAfterDelay(tgt.reportDR, tgt.labno);
        } catch (e) {}
      }, 1500);
    } catch (e) {}
  }

  // --- 创建工作台 UI ---
  function createWS() {
    if (document.getElementById('lis-ws')) {return;} // 防止重复创建
    // 工作台容器
    const ws = document.createElement('div');
    ws.id = 'lis-ws';
    ws.innerHTML = `
            <div id="lis-ws-hd"></div>
            <div id="lis-ws-tabs"></div>
            <div id="lis-ws-body"></div>
            <div id="lis-ws-ft">
                <span>本地工作台</span>
                <span id="lis-ws-ft-stat"></span>
            </div>`;
    document.body.appendChild(ws);

    // 8.5.33: 待排/采集「忽略」按钮 — capture 阶段拦截，先于视图行点击处理器，避免误开详情
    const wsBody = document.getElementById('lis-ws-body');
    if (wsBody) {
      // 8.11.10: 强制 flex 纵向与自顶向下排列（LIS 系统 CSS 会覆盖）——从 renderWSTable
      // 移来只设一次，内联样式常驻，无需每轮渲染重写
      wsBody.style.cssText = 'flex:1!important;overflow:hidden!important;min-height:0!important;position:relative;display:flex!important;flex-direction:column!important;align-items:stretch!important;justify-content:flex-start!important;';
      wsBody.addEventListener('click', e => {
        const btn = e.target && e.target.closest ? e.target.closest('.ws-ignore-btn') : null;
        if (!btn) {return;}
        e.preventDefault();
        e.stopImmediatePropagation();
        const rdr = btn.getAttribute('data-rdr') || '';
        const row = wsData.find(r => String(r.ReportDR || '') === rdr);
        toggleWSIgnore(rdr, row ? { labno: row.Labno, patName: row.PatName, testSet: row.TestSetDesc } : null);
        // 8.5.34: 忽略后同步取消勾选（避免 F5/全选带上已忽略标本）
        if (isWSIgnored(rdr)) {wsChecked.delete(rdr);}
        // 立即刷新分类栏 + 仪器/工作组 tab 计数 + 表格（不用等 30s 自动刷新）
        calcMachineCounts();
        renderWSTabs();
        renderWSTable();
        renderWSCategoryBar();
      }, true);
    }

    // 监控工作台属性变化（检测是否有外部代码修改 class 或 style）
    const wsAttrObserver = new MutationObserver(muts => {
      for (const m of muts) {
        if (m.type === 'attributes' && m.target.id === 'lis-ws') {
          dbg('[WS] #lis-ws 属性变化:', m.attributeName, 'class=', ws.className, 'style=', ws.style.cssText);
        }
      }
    });
    wsAttrObserver.observe(ws, { attributes: true, attributeFilter: ['class', 'style'] });

    // 浮动按钮（可拖动，记忆位置）
    const fab = document.createElement('button');
    fab.id = 'lis-fab';
    fab.innerHTML = '🔬';
    fab.title = '拖动移动 | 点击打开工作台';
    // 恢复上次位置
    try {
      const wp = JSON.parse(localStorage.getItem('lis-fab-pos') || '');
      if (wp && typeof wp.l === 'number') {
        fab.style.left = wp.l + 'px';
        fab.style.top = wp.t + 'px';
        fab.style.right = 'auto';
        fab.style.bottom = 'auto';
      }
    } catch (e) {}
    document.body.appendChild(fab);

    const tip = document.createElement('div');
    tip.id = 'lis-fab-tip';
    tip.textContent = '点击打开审核工作台';
    document.body.appendChild(tip);

    // 拖动功能（pointer events）
    let fabDragging = false,
      fabMoved = false,
      fabStartX,
      fabStartY,
      fabOrigX,
      fabOrigY;
    fab.addEventListener('pointerdown', e => {
      fabDragging = true;
      fabMoved = false;
      fabStartX = e.clientX;
      fabStartY = e.clientY;
      fabOrigX = fab.offsetLeft;
      fabOrigY = fab.offsetTop;
      fab.setPointerCapture(e.pointerId);
      fab.style.transition = 'none';
      e.preventDefault();
    });
    fab.addEventListener('pointermove', e => {
      if (!fabDragging) {return;}
      const dx = e.clientX - fabStartX,
        dy = e.clientY - fabStartY;
      if (Math.abs(dx) > 3 || Math.abs(dy) > 3) {fabMoved = true;}
      if (fabMoved) {
        fab.style.left = Math.max(0, fabOrigX + dx) + 'px';
        fab.style.top = Math.max(0, fabOrigY + dy) + 'px';
        fab.style.right = 'auto';
        fab.style.bottom = 'auto';
      }
    });
    fab.addEventListener('pointerup', () => {
      fabDragging = false;
      fab.style.transition = '';
      if (fabMoved) {
        try {
          localStorage.setItem('lis-fab-pos', JSON.stringify({ l: fab.offsetLeft, t: fab.offsetTop }));
        } catch (e) {}
      }
    });
    // 点击（拖动后不触发）
    fab.addEventListener('click', e => {
      if (!fabMoved) {openWS();}
    });
    fab.addEventListener('mouseenter', () => tip.classList.add('show'));
    fab.addEventListener('mouseleave', () => tip.classList.remove('show'));

    // 键盘快捷键
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape') {
        // 8.9.0: 密码弹窗打开时 Esc 只关弹窗——此前 closeWS()/closePwdDlg() 同时执行，
        // 在弹窗输入框里按 Esc 会把整个工作台连带关掉
        const pwdO = document.getElementById('lis-pwdo');
        if (pwdO && pwdO.classList.contains('show')) {closePwdDlg(); return;}
        closeWS();
      }
    });
  }

  function toggleWS() {
    if ($('#lis-ws').classList.contains('show')) {closeWS();}
    else {openWS();}
  }

  // --- 密码设置弹窗 ---
  async function openPwdDlg() {
    let o = document.getElementById('lis-pwdo');
    if (!o) {
      o = document.createElement('div');
      o.id = 'lis-pwdo';
      o.innerHTML = `<div id="lis-pwdp">
                <h4>🔐 密码管理</h4>
                <label style="font-size:13px;color:#555;display:block;margin-bottom:6px">审核密码（与登录密码一致）</label>
                <input type="password" id="lis-pwdi" placeholder="输入审核密码" autocomplete="off" data-lpignore="true" />
                <div class="sts" id="lis-pwds"></div>
                <label style="font-size:13px;color:#555;display:block;margin-bottom:6px;margin-top:16px">CA 认证账号（capping 多账号）</label>
                <div id="lis-caaccts" style="max-height:200px;overflow-y:auto;border:1px solid #e3e8ef;border-radius:6px;padding:6px;margin-bottom:10px"></div>
                <div id="lis-caedit-tip" style="display:none;align-items:center;gap:8px;padding:6px 10px;background:#eef2ff;border:1px solid #c7d2fe;border-radius:6px;margin-bottom:8px;font-size:12px;color:#4f46e5">
                    <span style="flex:1">正在编辑账号：<b style="color:#3730a3"></b>（密码留空 = 不改）</span>
                    <button id="lis-caedit-cx" style="background:none;border:none;color:#4f46e5;font-size:14px;cursor:pointer;line-height:1">✕</button>
                </div>
                <div style="display:flex;gap:6px;align-items:center;margin-bottom:6px">
                    <input type="text" id="lis-caui" placeholder="用户名" autocomplete="off" data-lpignore="true" style="flex:1;height:28px;border:1px solid #cfd8e0;border-radius:5px;padding:0 8px;font-size:12px" />
                    <input type="text" id="lis-cawdi" placeholder="CA 密码" autocomplete="off" data-lpignore="true" style="flex:1;height:28px;border:1px solid #cfd8e0;border-radius:5px;padding:0 8px;font-size:12px;-webkit-text-security:disc;" />
                </div>
                <div style="display:flex;gap:6px;align-items:center;margin-bottom:8px">
                    <input type="text" id="lis-canote" placeholder="备注（如：A班 / 免疫）" style="flex:1;height:28px;border:1px solid #cfd8e0;border-radius:5px;padding:0 8px;font-size:12px" />
                    <button id="lis-caadd" style="height:28px;padding:0 14px;background:#0f766e;color:#fff;border:none;border-radius:5px;font-size:12px;font-weight:700;cursor:pointer">新增/更新</button>
                </div>
                <div class="sts" id="lis-cawds"></div>
                <div class="pa">
                    <button class="b-clr" id="lis-pwdc">清除全部</button>
                    <button class="b-can" id="lis-pwdca">取消</button>
                    <button class="b-save" id="lis-pwdsave">保存</button>
                </div>
                <div class="tip">💡 CA 账号按用户名区分，可存多组；认证时优先用当前登录用户名匹配到的账号（或用你设为默认的那个）。密码保存在本地 localStorage，仅本机可用。</div>
            </div>`;
      document.body.appendChild(o);

      // 保存：审核密码 + 让当前多账号区落盘
      document.getElementById('lis-pwdsave').addEventListener('click', async () => {
        const auditPwd = document.getElementById('lis-pwdi').value;
        if (auditPwd) {
          await savePwdAsync(auditPwd);
        } else {
          try { localStorage.removeItem(K.pwd); } catch (e) {}
        }
        // 若有未提交的账号表单，先落盘再提示
        await _maybeCommitCaForm();
        document.getElementById('lis-pwds').innerHTML = '<span style="color:#27ae60">✓ 已保存</span>';
        document.getElementById('lis-cawds').innerHTML = '<span style="color:#27ae60">✓ 已保存</span>';
        toast('密码已保存');
        setTimeout(closePwdDlg, 600);
      });
      document.getElementById('lis-cawdi') && document.getElementById('lis-caadd').addEventListener('click', _maybeCommitCaForm);
      // 取消账号编辑
      const _cx = document.getElementById('lis-caedit-cx');
      if (_cx) {_cx.addEventListener('click', () => _caExitEdit());}
      // Enter 快捷新增账号
      document.getElementById('lis-caadd').addEventListener('keydown', e => {
        if (e.key === 'Enter') {e.preventDefault();_maybeCommitCaForm();}
      });
      document.getElementById('lis-caui').addEventListener('keydown', e => {
        if (e.key === 'Enter') {e.preventDefault();_maybeCommitCaForm();}
      });
      document.getElementById('lis-cawdi').addEventListener('keydown', e => {
        if (e.key === 'Enter') {e.preventDefault();_maybeCommitCaForm();}
      });
      document.getElementById('lis-pwdc').addEventListener('click', () => {
        try {
          localStorage.removeItem(K.pwd);
          localStorage.removeItem(K.caPwd);
          localStorage.removeItem(K.caDefaultUser); // 8.5.36: 同时清默认账号标记
          caAccountsClear();
        } catch (e) {}
        document.getElementById('lis-pwdi').value = '';
        document.getElementById('lis-caui').value = '';
        document.getElementById('lis-cawdi').value = '';
        document.getElementById('lis-canote').value = '';
        _caEditUser = ''; // 8.5.37: 清除时退出编辑态
        const _tip = document.getElementById('lis-caedit-tip');
        if (_tip) {_tip.style.display = 'none';}
        document.getElementById('lis-pwds').innerHTML = '<span style="color:#e74c3c">✓ 已清除</span>';
        document.getElementById('lis-cawds').innerHTML = '<span style="color:#e74c3c">✓ 已清除</span>';
        _renderCaAccountList(document.getElementById('lis-caaccts'));
        toast('密码已清除', 'w');
      });
      document.getElementById('lis-pwdca').addEventListener('click', closePwdDlg);
      o.addEventListener('click', e => {
        if (e.target === o) {closePwdDlg();}
      });
    }
    const pwd = await loadPwdAsync();
    document.getElementById('lis-pwdi').value = pwd;
    document.getElementById('lis-pwds').textContent = pwd ? '当前已保存审核密码' : '尚未保存审核密码';
    document.getElementById('lis-cawds').textContent = '';
    // 渲染多账号列表
    _renderCaAccountList(document.getElementById('lis-caaccts'));
    o.classList.add('show');
    document.getElementById('lis-pwdi').focus();
  }

  // 当前正在编辑的账号用户名（''=新增模式）。8.5.37 支持编辑已存账号。
  let _caEditUser = '';

  // 编辑态下退出（还原表单为新增模式）
  function _caExitEdit() {
    _caEditUser = '';
    document.getElementById('lis-caui').value = '';
    document.getElementById('lis-cawdi').value = '';
    document.getElementById('lis-canote').value = '';
    const tip = document.getElementById('lis-caedit-tip');
    if (tip) {tip.style.display = 'none';}
  }

  // 把当前表单里的用户名+密码+备注作为账号落盘并刷新列表
  async function _maybeCommitCaForm() {
    const u = (document.getElementById('lis-caui').value || '').trim();
    const pw = document.getElementById('lis-cawdi').value;
    const note = (document.getElementById('lis-canote').value || '').trim();
    if (!u) {return false;}
    // 新增时必须有密码；编辑时可留空（不改密码）
    if (!pw && !_caEditUser) {
      toast('请输入 CA 密码', 'w');
      return false;
    }
    if (_caEditUser) {
      // 编辑模式：更新备注；密码留空保留原密码，填了则覆盖
      const all = await caAccountsAll();
      const orig = all[_caEditUser] || {};
      const newPwd = pw ? pw : (orig.pwd || '');
      await caAccountSet(u, { user: u, pwd: newPwd, note, ts: orig.ts });
      // 若改了用户名：清掉旧键；默认标记跟随新用户名
      if (u !== _caEditUser) {
        caAccountDelete(_caEditUser);
        if (String(localStorage.getItem(K.caDefaultUser) || '') === _caEditUser) {
          localStorage.setItem(K.caDefaultUser, u);
        }
      }
      _caExitEdit();
      document.getElementById('lis-cawds').innerHTML = '<span style="color:#27ae60">✓ 账号已更新</span>';
      toast(`已更新账号 ${u}`);
    } else {
      await caAccountSet(u, { user: u, pwd: pw, note });
      document.getElementById('lis-cawds').innerHTML = '<span style="color:#27ae60">✓ 账号已保存</span>';
    }
    document.getElementById('lis-caui').value = '';
    document.getElementById('lis-cawdi').value = '';
    document.getElementById('lis-canote').value = '';
    _renderCaAccountList(document.getElementById('lis-caaccts'));
    return true;
  }

  // 渲染多账号列表
  async function _renderCaAccountList(box) {
    if (!box) {return;}
    const all = await caAccountsAll();
    const cur = _caAccountCurUser();
    const explicit = String(localStorage.getItem(K.caDefaultUser) || '');
    const keys = Object.keys(all);
    if (keys.length === 0) {
      box.innerHTML = '<div style="font-size:12px;color:#9aa5b1;padding:6px 4px">尚无 CA 账号，下方输入用户名+密码新增。</div>';
      return;
    }
    let h = '';
    keys.sort().forEach(u => {
      const a = all[u];
      const isCur = u === cur;
      const isDefault = u === explicit;
      h += `<div style="display:flex;align-items:center;gap:6px;padding:5px 6px;border-bottom:1px solid #f0f3f7">
                <div style="flex:1;min-width:0">
                    <b style="font-size:13px;color:#ef4444">${esc(u)}</b>
                    ${isCur ? '<span style="font-size:10px;color:#0f766e;background:#ecfdf5;border:1px solid #99f6e4;border-radius:4px;padding:0 4px;margin-left:4px">当前登录</span>' : ''}
                    ${isDefault ? '<span style="font-size:10px;color:#7c3aed;background:#f3e8ff;border:1px solid #ddd6fe;border-radius:4px;padding:0 4px;margin-left:4px">CA默认</span>' : ''}
                    ${a.note ? ' <span style="font-size:11px;color:#9aa5b1">· ' + esc(a.note) + '</span>' : ''}
                    <div style="font-size:10px;color:#9aa5b1">${a.pwd ? '已存密码' : '无密码'}</div>
                </div>
                <button class="lis-ca-edit" data-u="${escAttr(u)}" style="height:24px;padding:0 8px;font-size:11px;border:1px solid #c7d2fe;border-radius:4px;background:#fff;color:#4f46e5;cursor:pointer">编辑</button>
                <button class="lis-ca-def" data-u="${escAttr(u)}" style="height:24px;padding:0 8px;font-size:11px;border:1px solid #cfd8e0;border-radius:4px;background:#fff;color:#475569;cursor:pointer">${isDefault ? '✓默认' : '设默认'}</button>
                <button class="lis-ca-del" data-u="${escAttr(u)}" style="height:24px;padding:0 8px;font-size:11px;border:1px solid #fecaca;border-radius:4px;background:#fff;color:#dc2626;cursor:pointer">删除</button>
            </div>`;
    });
    box.innerHTML = h;
    box.querySelectorAll('.lis-ca-edit').forEach(b => {
      b.addEventListener('click', async () => {
        const u = b.getAttribute('data-u');
        const all = await caAccountsAll();
        const a = all[u];
        if (!a) {return;}
        // 回填到表单进入编辑态；密码留空表示「不改」
        _caEditUser = u;
        document.getElementById('lis-caui').value = a.user || u;
        document.getElementById('lis-cawdi').value = '';
        document.getElementById('lis-canote').value = a.note || '';
        const tip = document.getElementById('lis-caedit-tip');
        if (tip) {tip.style.display = 'flex';tip.querySelector('b').textContent = u;}
        document.getElementById('lis-cawdi').focus();
      });
    });
    box.querySelectorAll('.lis-ca-def').forEach(b => {
      b.addEventListener('click', () => {
        const u = b.getAttribute('data-u');
        localStorage.setItem(K.caDefaultUser, u);
        _renderCaAccountList(box);
        toast(`已设 ${u} 为默认 CA 认证账号`);
      });
    });
    box.querySelectorAll('.lis-ca-del').forEach(b => {
      b.addEventListener('click', async () => {
        const u = b.getAttribute('data-u');
        caAccountDelete(u);
        if (String(localStorage.getItem(K.caDefaultUser) || '') === u) {localStorage.removeItem(K.caDefaultUser);}
        _renderCaAccountList(box);
        toast(`已删除 ${u}`);
      });
    });
  }

